@Composable
fun PremiumOrganizedMenu(
    expanded: Boolean,
    onDismiss: () -> Unit,
    isAdmin: Boolean,
    viewModel: MainViewModel,
    loggedInUserVal: User?,
    activeStyle: DesignStyle
