    if (expanded) {
        val isDark = isSystemInDarkTheme()
        val currentTheme by viewModel.themeMode.collectAsState()
        
        Box(
            modifier = Modifier
                .fillMaxSize()
                .background(Color.Black.copy(alpha = 0.55f))
                .clickable(
                    interactionSource = remember { androidx.compose.foundation.interaction.MutableInteractionSource() },
                    indication = null
                ) { onDismiss() },
            contentAlignment = Alignment.CenterEnd
        ) {
            var isVisible by remember { mutableStateOf(false) }
            LaunchedEffect(expanded) {
                isVisible = true
            }
            
            AnimatedVisibility(
                visible = isVisible,
                enter = slideInHorizontally(initialOffsetX = { it }, animationSpec = tween(300, easing = EaseOutCubic)) + fadeIn(),
                exit = slideOutHorizontally(targetOffsetX = { it }, animationSpec = tween(250, easing = EaseInCubic)) + fadeOut(),
                modifier = Modifier
                    .fillMaxHeight()
                    .fillMaxWidth(0.85f)
            ) {
                val gradientBorder = Brush.linearGradient(
                    colors = listOf(
                        MaterialTheme.colorScheme.primary.copy(alpha = 0.5f),
                        MaterialTheme.colorScheme.secondary.copy(alpha = 0.3f)
                    )
                )
                
                Surface(
                    modifier = Modifier
                        .fillMaxSize()
                        .clickable(enabled = false) {}
                        .border(
                            width = if (activeStyle == DesignStyle.NEO_BRUTALIST) 3.dp else 1.2.dp,
                            brush = if (activeStyle == DesignStyle.NEO_BRUTALIST) Brush.linearGradient(listOf(Color.Black, Color.Black)) else gradientBorder,
                            shape = if (activeStyle == DesignStyle.NEO_BRUTALIST) RoundedCornerShape(0.dp) else RoundedCornerShape(topStart = 24.dp, bottomStart = 24.dp)
                        ),
                    shape = if (activeStyle == DesignStyle.NEO_BRUTALIST) RoundedCornerShape(0.dp) else RoundedCornerShape(topStart = 24.dp, bottomStart = 24.dp),
                    color = when (activeStyle) {
                        DesignStyle.GRADIENT_GLASS -> MaterialTheme.colorScheme.surface.copy(alpha = 0.94f)
                        DesignStyle.NEO_BRUTALIST -> if (isDark) Color(0xFF1E1E2E) else Color.White
