@Composable
fun MenuCategory(
    title: String,
    content: @Composable ColumnScope.() -> Unit
) {
    Column(
        verticalArrangement = Arrangement.spacedBy(8.dp)
    ) {
        Text(
            text = title,
            fontSize = 10.sp,
            fontWeight = FontWeight.Black,
            color = MaterialTheme.colorScheme.primary.copy(alpha = 0.8f),
            letterSpacing = 1.sp
        )
        Column(
            verticalArrangement = Arrangement.spacedBy(4.dp)
        ) {
            content()
        }
    }
}

@Composable
fun MenuOptionItem(
    title: String,
    subtitle: String,
    icon: ImageVector,
    iconColor: Color,
    onClick: () -> Unit
) {
    Row(
        modifier = Modifier
            .fillMaxWidth()
            .clip(RoundedCornerShape(14.dp))
            .clickable { onClick() }
            .padding(10.dp),
        verticalAlignment = Alignment.CenterVertically,
        horizontalArrangement = Arrangement.spacedBy(14.dp)
    ) {
        Box(
            modifier = Modifier
                .size(38.dp)
                .clip(RoundedCornerShape(10.dp))
                .background(iconColor.copy(alpha = 0.12f)),
            contentAlignment = Alignment.Center
        ) {
            Icon(
                imageVector = icon,
                contentDescription = title,
                tint = iconColor,
                modifier = Modifier.size(20.dp)
            )
        }
        Column(modifier = Modifier.weight(1f)) {
            Text(
                text = title,
                fontSize = 13.sp,
                fontWeight = FontWeight.Bold,
                color = MaterialTheme.colorScheme.onSurface
            )
            Text(
                text = subtitle,
                fontSize = 10.sp,
                color = MaterialTheme.colorScheme.onSurfaceVariant.copy(alpha = 0.75f)
            )
        }
        Icon(
            imageVector = Icons.Filled.ChevronRight,
            contentDescription = "Navigate",
            tint = MaterialTheme.colorScheme.onSurfaceVariant.copy(alpha = 0.4f),
            modifier = Modifier.size(16.dp)
        )
    }
}

@Composable
fun PremiumStyleContainer(
    style: DesignStyle,
    onClick: (() -> Unit)? = null,
    modifier: Modifier = Modifier,
    containerColor: Color? = null,
    borderStrokeColor: Color? = null,
    isDark: Boolean = isSystemInDarkTheme(),
    content: @Composable ColumnScope.() -> Unit
) {
    val defaultBg = containerColor ?: if (isDark) Color(0xFF1E1E2E) else Color.White
    
    when (style) {
        DesignStyle.CLASSIC_CLEAN -> {
            Card(
                onClick = onClick ?: {},
                enabled = onClick != null,
                shape = RoundedCornerShape(16.dp),
                colors = CardDefaults.cardColors(containerColor = defaultBg),
                border = BorderStroke(1.dp, borderStrokeColor ?: if (isDark) Color(0xFF2D2D44) else Color(0xFFE2E8F0)),
                elevation = CardDefaults.cardElevation(defaultElevation = 2.dp),
                modifier = modifier
            ) {
                Column(modifier = Modifier.fillMaxWidth()) {
                    content()
                }
            }
        }
        DesignStyle.GRADIENT_GLASS -> {
            // Glassmorphic with subtle primary/secondary gradient border and soft shadows
            val glassBg = defaultBg.copy(alpha = if (isDark) 0.85f else 0.92f)
            val gradientBorder = Brush.linearGradient(
                colors = listOf(
                    MaterialTheme.colorScheme.primary.copy(alpha = 0.5f),
                    MaterialTheme.colorScheme.secondary.copy(alpha = 0.3f)
                )
            )
            
            Card(
                onClick = onClick ?: {},
                enabled = onClick != null,
                shape = RoundedCornerShape(28.dp),
                colors = CardDefaults.cardColors(containerColor = glassBg),
                elevation = CardDefaults.cardElevation(defaultElevation = 6.dp),
                modifier = modifier
                    .graphicsLayer {
                        shadowElevation = 8f
                        shape = RoundedCornerShape(28.dp)
                        clip = true
                    }
                    .border(BorderStroke(1.5.dp, gradientBorder), RoundedCornerShape(28.dp))
            ) {
                Column(modifier = Modifier.fillMaxWidth()) {
                    content()
                }
            }
        }
        DesignStyle.NEO_BRUTALIST -> {
            // Brutalist card with thick black borders and flat offset solid shadow
            val shadowOffset = 6.dp
            Box(modifier = modifier.padding(bottom = shadowOffset, end = shadowOffset)) {
                // The solid black shadow behind
                Box(
                    modifier = Modifier
                        .matchParentSize()
                        .offset(x = shadowOffset, y = shadowOffset)
                        .clip(RoundedCornerShape(8.dp))
                        .background(if (isDark) Color.White else Color.Black)
                )
                
                Card(
                    onClick = onClick ?: {},
                    enabled = onClick != null,
                    shape = RoundedCornerShape(8.dp),
                    colors = CardDefaults.cardColors(containerColor = defaultBg),
                    border = BorderStroke(2.5.dp, if (isDark) Color.White else Color.Black),
                    elevation = CardDefaults.cardElevation(defaultElevation = 0.dp),
                    modifier = Modifier.fillMaxWidth()
                ) {
                    Column(modifier = Modifier.fillMaxWidth()) {
                        content()
                    }
                }
            }
        }
    }
}

@Composable
fun DesignStyleSelectorCard(viewModel: MainViewModel) {
    val activeStyle by viewModel.activeDesignStyle.collectAsState()
    val isDark = isSystemInDarkTheme()
    
    PremiumStyleContainer(
        style = activeStyle,
        modifier = Modifier.fillMaxWidth().testTag("design_style_selector_card")
    ) {
        Column(
            modifier = Modifier.padding(18.dp),
            verticalArrangement = Arrangement.spacedBy(14.dp)
        ) {
            Row(
                verticalAlignment = Alignment.CenterVertically,
                horizontalArrangement = Arrangement.spacedBy(8.dp)
            ) {
                Icon(
                    imageVector = Icons.Filled.Palette,
                    contentDescription = "Design Presets",
                    tint = MaterialTheme.colorScheme.secondary,
                    modifier = Modifier.size(22.dp)
                )
                Text(
                    text = "SELECT LAYOUT DESIGN STYLE",
                    fontSize = 12.sp,
                    fontWeight = FontWeight.Black,
                    color = MaterialTheme.colorScheme.primary,
                    letterSpacing = 1.sp
                )
            }
            
            Text(
                text = "Personalize your portal with real-time dynamic layouts. Switch instantly to match your study aesthetic.",
                fontSize = 11.sp,
                color = if (isDark) Color.White.copy(alpha = 0.7f) else Color(0xFF555555),
                lineHeight = 15.sp
            )
            
            Row(
                modifier = Modifier.fillMaxWidth(),
                horizontalArrangement = Arrangement.spacedBy(8.dp)
            ) {
                val styles = listOf(
                    Triple(DesignStyle.CLASSIC_CLEAN, "Classic", "Minimalist"),
                    Triple(DesignStyle.GRADIENT_GLASS, "Gradient", "Luxury Glass"),
                    Triple(DesignStyle.NEO_BRUTALIST, "Brutalist", "High Contrast")
                )
                
                styles.forEach { (style, name, sub) ->
                    val isSelected = activeStyle == style
                    
                    val bg = if (isSelected) {
                        MaterialTheme.colorScheme.secondary
                    } else {
                        if (isDark) Color(0xFF2C2C3E) else Color(0xFFF1F5F9)
                    }
                    
                    val textColor = if (isSelected) {
                        Color.White
                    } else {
                        if (isDark) Color.White else Color(0xFF1E1E2E)
                    }
                    
                    val border = if (style == DesignStyle.NEO_BRUTALIST && isSelected) {
                        BorderStroke(2.dp, if (isDark) Color.White else Color.Black)
                    } else if (isSelected) {
                        BorderStroke(1.5.dp, MaterialTheme.colorScheme.primary)
                    } else {
                        BorderStroke(1.dp, if (isDark) Color(0xFF3D3D56) else Color(0xFFCBD5E1))
                    }
                    
                    val shape = when (style) {
                        DesignStyle.CLASSIC_CLEAN -> RoundedCornerShape(10.dp)
                        DesignStyle.GRADIENT_GLASS -> RoundedCornerShape(16.dp)
                        DesignStyle.NEO_BRUTALIST -> RoundedCornerShape(4.dp)
                    }
                    
                    Surface(
                        onClick = { viewModel.activeDesignStyle.value = style },
                        shape = shape,
                        color = bg,
                        border = border,
                        modifier = Modifier
                            .weight(1f)
                            .height(52.dp)
                            .testTag("style_button_${name.lowercase()}")
                    ) {
                        Column(
                            horizontalAlignment = Alignment.CenterHorizontally,
                            verticalArrangement = Arrangement.Center,
                            modifier = Modifier.padding(2.dp)
                        ) {
                            Text(
                                text = name,
                                fontSize = 11.sp,
                                fontWeight = FontWeight.Bold,
                                color = textColor
                            )
                            Text(
                                text = sub,
                                fontSize = 8.sp,
                                color = if (isSelected) Color.White.copy(alpha = 0.8f) else Color.Gray,
                                fontWeight = FontWeight.Medium
                            )
                        }
                    }
                }
            }
        }
    }
}

@OptIn(ExperimentalMaterial3Api::class)
@Composable
fun AppContent(viewModel: MainViewModel) {
    val currentScreen by viewModel.currentScreen.collectAsState()
    val loggedInUser by viewModel.loggedInUser.collectAsState()
    val feedbackMessage by viewModel.feedbackMessage.collectAsState()
    val snackbarHostState = remember { SnackbarHostState() }

    var userMenuExpanded by remember { mutableStateOf(false) }
    var adminMenuExpanded by remember { mutableStateOf(false) }

    val suspendedUser by viewModel.suspendedUser.collectAsState()
    val activeReportTask by viewModel.activeReportTask.collectAsState()
    val activeStyle by viewModel.activeDesignStyle.collectAsState()
    val context = androidx.compose.ui.platform.LocalContext.current

    // Observe suspendedUser and show suspended blocking action dialog
    if (suspendedUser != null) {
        AlertDialog(
            onDismissRequest = { viewModel.suspendedUser.value = null },
            title = {
                Row(verticalAlignment = Alignment.CenterVertically) {
                    Icon(
                        imageVector = Icons.Default.Warning,
                        contentDescription = "Suspended",
                        tint = MaterialTheme.colorScheme.error,
                        modifier = Modifier.size(28.dp)
                    )
                    Spacer(modifier = Modifier.width(8.dp))
                    Text(
                        text = "Account Suspended",
                        style = MaterialTheme.typography.titleMedium,
                        color = MaterialTheme.colorScheme.error,
                        fontWeight = FontWeight.Bold
                    )
                }
            },
            text = {
                Text(
                    text = "Hello $suspendedUser,\n\nYour NayaRasta Academy account is temporarily suspended because it is marked as unpaid.\n\nPlease contact our administration team via WhatsApp to activate your full books access or resolve any queries.",
                    fontSize = 15.sp,
                    lineHeight = 22.sp
                )
            },
            confirmButton = {
                Button(
                    onClick = {
                        try {
                            val whatsappNumber = viewModel.getHelplineNumberInternational()
                            val message = "Assalam-o-Alaikum, My name is $suspendedUser. I am trying to login to ${viewModel.getAppName()} app but my account is marked suspended/unpaid. Please assist me in activating my account."
                            val intent = Intent(Intent.ACTION_VIEW).apply {
                                data = Uri.parse("https://api.whatsapp.com/send?phone=$whatsappNumber&text=${Uri.encode(message)}")
                            }
                            context.startActivity(intent)
                        } catch (e: Exception) {
                            viewModel.feedbackMessage.value = "Unable to launch WhatsApp. Please manual message to +${viewModel.getHelplineNumberInternational()}"
                        }
                    },
                    colors = ButtonDefaults.buttonColors(containerColor = Color(0xFF25D366))
                ) {
                    Row(verticalAlignment = Alignment.CenterVertically) {
                        Icon(
                            imageVector = Icons.Default.Call,
                            contentDescription = "WhatsApp"
                        )
                        Spacer(modifier = Modifier.width(8.dp))
                        Text("Contact via WhatsApp", color = Color.White)
                    }
                }
            },
            dismissButton = {
                TextButton(onClick = { viewModel.suspendedUser.value = null }) {
                    Text("Close")
                }
            }
        )
    }

    // Observe activeReportTask and show dual export dialog
    if (activeReportTask != null) {
        val task = activeReportTask!!
        AlertDialog(
            onDismissRequest = { viewModel.activeReportTask.value = null },
            title = {
                Text(
                    text = "Select Download Format",
                    style = MaterialTheme.typography.titleMedium,
                    fontWeight = FontWeight.Bold
                )
            },
            text = {
                Column {
                    Text(
                        text = "How would you like to save this academic report? You can download it as a print-ready PDF document or a high-resolution PNG image card.",
                        fontSize = 14.sp,
                        color = Color.Gray,
                        modifier = Modifier.padding(bottom = 16.dp)
                    )
                    
                    // --- PDF Card Option ---
                    Row(
                        modifier = Modifier
                            .fillMaxWidth()
                            .clickable {
                                viewModel.activeReportTask.value = null
                                when (task) {
                                    is ReportTask.StudentProgress -> viewModel.generateAndSavePdfReport(context, task.user, task.results, asImage = false)
                                    is ReportTask.AcademyAnalysis -> viewModel.generateAndSaveAcademyPdfReport(context, task.users, task.results, asImage = false)
                                    is ReportTask.LeadershipRankings -> viewModel.generateAndSaveLeadershipPdfReport(context, task.users, task.results, asImage = false)
                                    is ReportTask.SingleTestCard -> viewModel.generateAndSaveSingleTestPdfReport(context, task.user, task.result, asImage = false)
                                    is ReportTask.FinancialLedger -> viewModel.generateAndSaveFinancialLedgerPdf(context, task.transactions, asImage = false)
                                }
                            }
                            .border(1.dp, MaterialTheme.colorScheme.outline.copy(alpha = 0.3f), RoundedCornerShape(8.dp))
                            .padding(12.dp),
                        verticalAlignment = Alignment.CenterVertically
                    ) {
                        Icon(
                            imageVector = Icons.Filled.PictureAsPdf,
                            contentDescription = "PDF Document",
                            tint = Color(0xFFC62828),
                            modifier = Modifier.size(24.dp)
                        )
                        Spacer(modifier = Modifier.width(12.dp))
                        Column {
                            Text("PDF Document", fontWeight = FontWeight.SemiBold, fontSize = 15.sp)
                            Text("Optimized for printing, standard documents & sharing", fontSize = 12.sp, color = Color.Gray)
                        }
                    }

                    Spacer(modifier = Modifier.height(10.dp))

                    // --- Image Card Option ---
                    Row(
                        modifier = Modifier
                            .fillMaxWidth()
                            .clickable {
                                viewModel.activeReportTask.value = null
                                when (task) {
                                    is ReportTask.StudentProgress -> viewModel.generateAndSavePdfReport(context, task.user, task.results, asImage = true)
                                    is ReportTask.AcademyAnalysis -> viewModel.generateAndSaveAcademyPdfReport(context, task.users, task.results, asImage = true)
                                    is ReportTask.LeadershipRankings -> viewModel.generateAndSaveLeadershipPdfReport(context, task.users, task.results, asImage = true)
                                    is ReportTask.SingleTestCard -> viewModel.generateAndSaveSingleTestPdfReport(context, task.user, task.result, asImage = true)
                                    is ReportTask.FinancialLedger -> viewModel.generateAndSaveFinancialLedgerPdf(context, task.transactions, asImage = true)
                                }
                            }
                            .border(1.dp, MaterialTheme.colorScheme.outline.copy(alpha = 0.3f), RoundedCornerShape(8.dp))
                            .padding(12.dp),
                        verticalAlignment = Alignment.CenterVertically
                    ) {
                        Icon(
                            imageVector = Icons.Filled.Image,
                            contentDescription = "Image Format",
                            tint = MaterialTheme.colorScheme.primary,
                            modifier = Modifier.size(24.dp)
                        )
                        Spacer(modifier = Modifier.width(12.dp))
                        Column {
                            Text("High-Quality Image", fontWeight = FontWeight.SemiBold, fontSize = 15.sp)
                            Text("Optimized for gallery storage, mobile viewing & backup", fontSize = 12.sp, color = Color.Gray)
                        }
                    }
                }
            },
            confirmButton = {},
            dismissButton = {
                TextButton(onClick = { viewModel.activeReportTask.value = null }) {
                    Text("Cancel")
                }
            }
        )
    }

    val quizStartPending by viewModel.quizStartPending.collectAsState()
    if (quizStartPending != null) {
        val pending = quizStartPending!!
        AlertDialog(
            onDismissRequest = { viewModel.cancelStartQuiz() },
            title = {
                Row(verticalAlignment = Alignment.CenterVertically) {
                    Icon(
                        imageVector = Icons.Default.Timer,
                        contentDescription = "Timer Settings",
                        tint = MaterialTheme.colorScheme.primary,
                        modifier = Modifier.size(24.dp)
                    )
                    Spacer(modifier = Modifier.width(8.dp))
                    Text(
                        "Enable Test Timer?",
                        fontWeight = FontWeight.Bold,
                        style = MaterialTheme.typography.titleMedium
                    )
                }
            },
            text = {
                val totalQuestions = pending.count
                val totalMinutes = totalQuestions // 1 minute per question
                val textMessage = if (pending.isPmdc) {
                    "This is the PMDC Mock MDCAT Exam consisting of 180 questions.\n\n" +
                    "Would you like to enable a countdown timer for this exam? " +
                    "The time limit will be 1 minute per question (180 minutes total).\n\n" +
                    "If disabled, you can solve the questions without a time limit (" +
                    "solve freely)."
                } else {
                    "Would you like to enable a countdown timer for this test of $totalQuestions questions?\n\n" +
                    "The time limit will be 1 minute per question ($totalMinutes minutes total).\n\n" +
                    "If disabled, you can solve the questions without a time limit (solve freely)."
                }
                Text(
                    textMessage,
                    fontSize = 14.sp,
                    lineHeight = 20.sp,
                    color = MaterialTheme.colorScheme.onSurfaceVariant
                )
            },
            confirmButton = {
                Button(
                    onClick = { viewModel.confirmStartQuiz(enableTimer = true) },
                    colors = ButtonDefaults.buttonColors(containerColor = MaterialTheme.colorScheme.primary)
                ) {
                    Text("Yes, Enable Timer")
                }
            },
            dismissButton = {
                Row {
                    TextButton(
                        onClick = { viewModel.confirmStartQuiz(enableTimer = false) }
                    ) {
                        Text("No, Solve Freely")
                    }
                    Spacer(modifier = Modifier.width(8.dp))
                    TextButton(
                        onClick = { viewModel.cancelStartQuiz() }
                    ) {
                        Text("Cancel", color = MaterialTheme.colorScheme.onSurfaceVariant.copy(alpha = 0.6f))
                    }
                }
            }
        )
    }

    val focusManager = androidx.compose.ui.platform.LocalFocusManager.current
    val keyboardController = androidx.compose.ui.platform.LocalSoftwareKeyboardController.current
    @OptIn(androidx.compose.foundation.layout.ExperimentalLayoutApi::class)
    val isKeyboardOpen = androidx.compose.foundation.layout.WindowInsets.Companion.isImeVisible

    // Intercept standard hardware back clicks
    val canGoBack = viewModel.canNavigateBack()
    BackHandler(enabled = canGoBack || isKeyboardOpen) {
        if (isKeyboardOpen) {
            focusManager.clearFocus()
            keyboardController?.hide()
        } else {
            viewModel.navigateBack()
        }
    }

    // Observe feedback toast triggers
    LaunchedEffect(feedbackMessage) {
        feedbackMessage?.let { msg ->
            snackbarHostState.showSnackbar(msg)
            viewModel.clearFeedback()
        }
    }

    Scaffold(
        snackbarHostStatus = snackbarHostState,
        topBar = {
            val loggedInUserVal = loggedInUser
            if (loggedInUserVal != null && loggedInUserVal.role == "USER" &&
                currentScreen !is Screen.UserQuizPlay && currentScreen !is Screen.UserQuizReview
            ) {
                Row(
                    modifier = Modifier
                        .fillMaxWidth()
                        .statusBarsPadding()
                        .height(64.dp)
                        .background(MaterialTheme.colorScheme.background)
                        .padding(horizontal = 20.dp),
                    horizontalArrangement = Arrangement.SpaceBetween,
                    verticalAlignment = Alignment.CenterVertically
                ) {
                    Row(
                        verticalAlignment = Alignment.CenterVertically,
                        horizontalArrangement = Arrangement.spacedBy(12.dp)
                    ) {
                        val initial = loggedInUserVal.fullName.firstOrNull()?.uppercase() ?: loggedInUserVal.username.firstOrNull()?.uppercase() ?: "A"
                        Box(
                            modifier = Modifier
                                .size(40.dp)
                                .clip(RoundedCornerShape(20.dp))
                                .background(Color(if (loggedInUserVal.avatarColor != 0) loggedInUserVal.avatarColor else 0xFFD6E3FF.toInt())),
                            contentAlignment = Alignment.Center
                        ) {
                            if (!loggedInUserVal.profileImageUri.isNullOrEmpty()) {
                                androidx.compose.foundation.Image(
                                    painter = coil.compose.rememberAsyncImagePainter(model = loggedInUserVal.profileImageUri),
                                    contentDescription = "User profile picture",
                                    modifier = Modifier.fillMaxSize(),
                                    contentScale = androidx.compose.ui.layout.ContentScale.Crop
                                )
                            } else {
                                Text(
                                    text = initial,
                                    color = Color.White,
                                    fontWeight = FontWeight.Bold,
                                    fontSize = 16.sp
                                )
                            }
                        }

                        Column {
                            Text(
                                text = "Good Morning,",
                                fontSize = 11.sp,
                                color = Color(0xFF44474E),
                                fontWeight = FontWeight.Medium
                            )
                            Text(
                                text = if (loggedInUserVal.fullName.isNotEmpty()) loggedInUserVal.fullName else loggedInUserVal.username,
                                fontSize = 16.sp,
                                fontWeight = FontWeight.Bold,
                                color = Color(0xFF1B1B1F)
                            )
                        }
                    }

                    Row(
                        horizontalArrangement = Arrangement.spacedBy(8.dp),
                        verticalAlignment = Alignment.CenterVertically
                    ) {
                        IconButton(
                            onClick = { viewModel.navigateTo(Screen.UserSearch) },
                            modifier = Modifier
                                .size(44.dp)
                                .clip(RoundedCornerShape(22.dp))
                                .background(MaterialTheme.colorScheme.surfaceVariant)
                        ) {
                            Icon(
                                imageVector = Icons.Filled.Search,
                                contentDescription = "Search Students",
                                tint = MaterialTheme.colorScheme.onSurfaceVariant
                            )
                        }

                        IconButton(
                            onClick = { userMenuExpanded = true },
                            modifier = Modifier
                                .size(44.dp)
                                .clip(RoundedCornerShape(22.dp))
                                .background(MaterialTheme.colorScheme.surfaceVariant)
                        ) {
                            Icon(
                                imageVector = Icons.Filled.Menu,
                                contentDescription = "Settings Menu",
                                tint = MaterialTheme.colorScheme.onSurfaceVariant
                            )
                        }
                    }
                }
            } else {
                TopAppBar(
                    title = {
                        Row(
                            verticalAlignment = Alignment.CenterVertically,
                            horizontalArrangement = Arrangement.spacedBy(8.dp)
                        ) {
                            androidx.compose.foundation.layout.Box(
                                modifier = Modifier
                                    .size(32.dp)
                                    .clip(androidx.compose.foundation.shape.CircleShape)
                                    .background(androidx.compose.ui.graphics.Color.White),
                                contentAlignment = androidx.compose.ui.Alignment.Center
                            ) {
                                val logoUrl = viewModel.getAppLogoUrl()
                                if (logoUrl != null) {
                                    androidx.compose.foundation.Image(
                                        painter = coil.compose.rememberAsyncImagePainter(model = logoUrl),
                                        contentDescription = "App Icon",
                                        modifier = Modifier.size(24.dp),
                                        contentScale = androidx.compose.ui.layout.ContentScale.Fit
                                    )
                                } else {
                                    androidx.compose.foundation.Image(
                                        painter = androidx.compose.ui.res.painterResource(id = com.example.R.drawable.logo),
                                        contentDescription = "App Icon",
                                        modifier = Modifier.size(24.dp),
                                        contentScale = androidx.compose.ui.layout.ContentScale.Fit
                                    )
                                }
                            }
                            Text(
                                text = if (loggedInUserVal?.role == "ADMIN") "${viewModel.getAppName()} Admin" else viewModel.getAppName(),
                                fontWeight = FontWeight.Bold,
                                fontFamily = FontFamily.SansSerif,
                                letterSpacing = 0.5.sp
                            )
                        }
                    },
                    actions = {
                        if (loggedInUserVal != null && loggedInUserVal.role == "ADMIN") {
                            IconButton(onClick = { viewModel.navigateTo(Screen.UserSearch) }) {
                                Icon(
                                    imageVector = Icons.Filled.Search,
                                    contentDescription = "Search Students"
                                )
                            }
                            IconButton(onClick = { adminMenuExpanded = true }) {
                                Icon(
                                    imageVector = Icons.Filled.Menu,
                                    contentDescription = "Settings Menu"
                                )
                            }
                        } else {
                            val isConnected by viewModel.isSupabaseConnected.collectAsState()

                            IconButton(onClick = {
                                viewModel.checkSupabaseConnection()
                                val msg = when (isConnected) {
                                    true -> "Successfully connected to Supabase backend!"
                                    false -> "Connection failed. Please check your Supabase credentials in the Secrets panel."
                                    null -> "Testing connectivity to Supabase backend..."
                                }
                                viewModel.feedbackMessage.value = msg
                            }) {
                                Icon(
                                    imageVector = Icons.Filled.Cloud,
                                    contentDescription = "Supabase Connection Status",
                                    tint = when (isConnected) {
                                        true -> Color(0xFF2E7D32) // Nice green!
                                        false -> Color.Red
                                        null -> Color.Gray
                                    }
                                )
                            }

                            // Strictly Light Mode only, no toggles per user request
                        }
                    },
                    colors = TopAppBarDefaults.topAppBarColors(
                        containerColor = MaterialTheme.colorScheme.surface
                    )
                )
            }
        },
        bottomBar = {
            if (loggedInUser != null &&
                currentScreen !is Screen.UserQuizPlay && currentScreen !is Screen.UserQuizReview
            ) {
                val isUser = loggedInUser?.role == "USER"
                val items = if (isUser) {
                    listOf(
                        Triple(Screen.UserDashboard, Icons.Filled.Home, "Home"),
                        Triple(Screen.StudyFeed, Icons.Filled.Forum, "Feed"),
                        Triple(Screen.UserNotes, Icons.Filled.Description, "Notes")
                    )
                } else {
                    listOf(
                        Triple(Screen.AdminDashboard, Icons.Filled.Dashboard, "Home"),
                        Triple(Screen.AdminNotes, Icons.Filled.LibraryBooks, "Notes"),
                        Triple(Screen.AdminManageUsers, Icons.Filled.Group, "Users")
                    )
                }

                val isDark = isSystemInDarkTheme()

                Box(
                    modifier = Modifier
                        .fillMaxWidth()
                        .navigationBarsPadding()
                        .padding(horizontal = 16.dp, vertical = 2.dp),
                    contentAlignment = Alignment.Center
                ) {
                    when (activeStyle) {
                        DesignStyle.GRADIENT_GLASS -> {
                            val gradientBorder = Brush.linearGradient(
                                colors = listOf(
                                    MaterialTheme.colorScheme.primary.copy(alpha = 0.4f),
                                    MaterialTheme.colorScheme.secondary.copy(alpha = 0.2f)
                                )
                            )
                            Card(
                                shape = RoundedCornerShape(24.dp),
                                colors = CardDefaults.cardColors(
                                    containerColor = MaterialTheme.colorScheme.surface.copy(alpha = 0.85f)
                                ),
                                elevation = CardDefaults.cardElevation(defaultElevation = 8.dp),
                                modifier = Modifier
                                    .fillMaxWidth()
                                    .border(BorderStroke(1.2.dp, gradientBorder), RoundedCornerShape(24.dp))
                            ) {
                                Row(
                                    modifier = Modifier
                                        .fillMaxWidth()
                                        .height(58.dp)
                                        .padding(horizontal = 8.dp),
                                    horizontalArrangement = Arrangement.SpaceEvenly,
                                    verticalAlignment = Alignment.CenterVertically
                                ) {
                                    items.forEach { (screen, icon, label) ->
                                        val isSelected = when (screen) {
                                            is Screen.UserDashboard -> currentScreen is Screen.UserDashboard
                                            is Screen.StudyFeed -> currentScreen is Screen.StudyFeed
                                            is Screen.UserNotes -> currentScreen is Screen.UserNotes
                                            is Screen.AdminDashboard -> currentScreen is Screen.AdminDashboard
                                            is Screen.AdminNotes -> currentScreen is Screen.AdminNotes
                                            is Screen.AdminManageUsers -> currentScreen is Screen.AdminManageUsers
                                            else -> false
                                        }

                                        Box(
                                            modifier = Modifier
                                                .weight(1f)
                                                .clip(RoundedCornerShape(16.dp))
                                                .clickable { viewModel.navigateTo(screen) }
                                                .padding(vertical = 8.dp),
                                            contentAlignment = Alignment.Center
                                        ) {
                                            Column(
                                                horizontalAlignment = Alignment.CenterHorizontally,
                                                verticalArrangement = Arrangement.spacedBy(4.dp)
                                            ) {
                                                Box(
                                                    modifier = Modifier
                                                        .clip(RoundedCornerShape(12.dp))
                                                        .background(
                                                            if (isSelected) MaterialTheme.colorScheme.primaryContainer.copy(alpha = 0.6f)
                                                            else Color.Transparent
                                                        )
                                                        .padding(horizontal = 16.dp, vertical = 4.dp)
                                                ) {
                                                    Icon(
                                                        imageVector = icon,
                                                        contentDescription = label,
                                                        tint = if (isSelected) MaterialTheme.colorScheme.primary
                                                               else MaterialTheme.colorScheme.onSurfaceVariant.copy(alpha = 0.7f),
                                                        modifier = Modifier.size(24.dp)
                                                    )
                                                }
                                                Text(
                                                    text = label,
                                                    fontSize = 11.sp,
                                                    fontWeight = if (isSelected) FontWeight.Bold else FontWeight.Medium,
                                                    color = if (isSelected) MaterialTheme.colorScheme.primary
                                                            else MaterialTheme.colorScheme.onSurfaceVariant.copy(alpha = 0.7f)
                                                )
                                            }
                                        }
                                    }
                                }
                            }
                        }
                        DesignStyle.NEO_BRUTALIST -> {
                            Card(
                                shape = RoundedCornerShape(8.dp),
                                colors = CardDefaults.cardColors(
                                    containerColor = if (isDark) Color(0xFF1E1E2E) else Color.White
                                ),
                                border = BorderStroke(2.5.dp, if (isDark) Color.White else Color.Black),
                                modifier = Modifier.fillMaxWidth()
                            ) {
                                Row(
                                    modifier = Modifier
                                        .fillMaxWidth()
                                        .height(58.dp),
                                    horizontalArrangement = Arrangement.SpaceEvenly,
                                    verticalAlignment = Alignment.CenterVertically
                                ) {
                                    items.forEach { (screen, icon, label) ->
                                        val isSelected = when (screen) {
                                            is Screen.UserDashboard -> currentScreen is Screen.UserDashboard
                                            is Screen.StudyFeed -> currentScreen is Screen.StudyFeed
                                            is Screen.UserNotes -> currentScreen is Screen.UserNotes
                                            is Screen.AdminDashboard -> currentScreen is Screen.AdminDashboard
                                            is Screen.AdminNotes -> currentScreen is Screen.AdminNotes
                                            is Screen.AdminManageUsers -> currentScreen is Screen.AdminManageUsers
                                            else -> false
                                        }

                                        Box(
                                            modifier = Modifier
                                                .weight(1f)
                                                .fillMaxHeight()
                                                .background(
                                                    if (isSelected) {
                                                        if (isDark) MaterialTheme.colorScheme.primary.copy(alpha = 0.3f)
                                                        else MaterialTheme.colorScheme.primaryContainer
                                                    } else Color.Transparent
                                                )
                                                .clickable { viewModel.navigateTo(screen) },
                                            contentAlignment = Alignment.Center
                                        ) {
                                            Column(
                                                horizontalAlignment = Alignment.CenterHorizontally,
                                                verticalArrangement = Arrangement.spacedBy(4.dp)
                                            ) {
                                                Icon(
                                                    imageVector = icon,
                                                    contentDescription = label,
                                                    tint = if (isDark) Color.White else Color.Black,
                                                    modifier = Modifier.size(24.dp)
                                                )
                                                Text(
                                                    text = label,
                                                    fontSize = 11.sp,
                                                    fontWeight = FontWeight.Black,
                                                    color = if (isDark) Color.White else Color.Black
                                                )
                                            }
                                        }
                                    }
                                }
                            }
                        }
                        DesignStyle.CLASSIC_CLEAN -> {
                            Card(
                                shape = RoundedCornerShape(16.dp),
                                colors = CardDefaults.cardColors(
                                    containerColor = MaterialTheme.colorScheme.surface
                                ),
                                border = BorderStroke(1.dp, if (isDark) Color(0xFF2D2D44) else Color(0xFFE2E8F0)),
                                modifier = Modifier.fillMaxWidth(),
                                elevation = CardDefaults.cardElevation(defaultElevation = 2.dp)
                            ) {
                                Row(
                                    modifier = Modifier
                                        .fillMaxWidth()
                                        .height(58.dp),
                                    horizontalArrangement = Arrangement.SpaceEvenly,
                                    verticalAlignment = Alignment.CenterVertically
                                ) {
                                    items.forEach { (screen, icon, label) ->
                                        val isSelected = when (screen) {
                                            is Screen.UserDashboard -> currentScreen is Screen.UserDashboard
                                            is Screen.StudyFeed -> currentScreen is Screen.StudyFeed
                                            is Screen.UserNotes -> currentScreen is Screen.UserNotes
                                            is Screen.AdminDashboard -> currentScreen is Screen.AdminDashboard
                                            is Screen.AdminNotes -> currentScreen is Screen.AdminNotes
                                            is Screen.AdminManageUsers -> currentScreen is Screen.AdminManageUsers
                                            else -> false
                                        }

                                        Box(
                                            modifier = Modifier
                                                .weight(1f)
                                                .clip(RoundedCornerShape(12.dp))
                                                .clickable { viewModel.navigateTo(screen) }
                                                .padding(vertical = 8.dp),
                                            contentAlignment = Alignment.Center
                                        ) {
                                            Column(
                                                horizontalAlignment = Alignment.CenterHorizontally,
                                                verticalArrangement = Arrangement.spacedBy(4.dp)
                                            ) {
                                                Box(
                                                    modifier = Modifier
                                                        .clip(RoundedCornerShape(10.dp))
                                                        .background(
                                                            if (isSelected) MaterialTheme.colorScheme.primaryContainer
                                                            else Color.Transparent
                                                        )
                                                        .padding(horizontal = 14.dp, vertical = 2.dp)
                                                ) {
                                                    Icon(
                                                        imageVector = icon,
                                                        contentDescription = label,
                                                        tint = if (isSelected) MaterialTheme.colorScheme.onPrimaryContainer
                                                               else MaterialTheme.colorScheme.onSurfaceVariant,
                                                        modifier = Modifier.size(24.dp)
                                                    )
                                                }
                                                Text(
                                                    text = label,
                                                    fontSize = 11.sp,
                                                    fontWeight = if (isSelected) FontWeight.Bold else FontWeight.Medium,
                                                    color = if (isSelected) MaterialTheme.colorScheme.primary
                                                            else MaterialTheme.colorScheme.onSurfaceVariant
                                                )
                                            }
                                        }
                                    }
                                }
                            }
                        }
                    }
                }
            }
        },
        contentWindowInsets = WindowInsets.safeDrawing
    ) { padding ->
        val isDark = isSystemInDarkTheme()
        val primaryColor = MaterialTheme.colorScheme.primary
        val secondaryColor = MaterialTheme.colorScheme.secondary
        val tertiaryColor = MaterialTheme.colorScheme.tertiary

        Box(
            modifier = Modifier
                .fillMaxSize()
                .drawBehind {
                    // Draw premium background gradient
                    val bgColors = if (isDark) {
                        listOf(Color(0xFF0F172A), Color(0xFF020617), Color(0xFF1E1B4B))
                    } else {
                        listOf(Color(0xFFF8FAFC), Color(0xFFEEF2F6), Color(0xFFE2E8F0))
                    }
                    val brush = Brush.verticalGradient(bgColors)
                    drawRect(brush)

                    // Draw glowing ambient light circles (glowing blobs) to give Luxury Glass feel
                    if (isDark) {
                        // Top-left soft blue-violet glow
                        drawCircle(
                            color = primaryColor.copy(alpha = 0.12f),
                            radius = size.width * 0.6f,
                            center = androidx.compose.ui.geometry.Offset(0f, 0f)
                        )
                        // Middle-right soft pinkish-orange glow
                        drawCircle(
                            color = secondaryColor.copy(alpha = 0.08f),
                            radius = size.width * 0.5f,
                            center = androidx.compose.ui.geometry.Offset(size.width, size.height * 0.4f)
                        )
                        // Bottom-left soft cyan-blue glow
                        drawCircle(
                            color = tertiaryColor.copy(alpha = 0.08f),
                            radius = size.width * 0.6f,
                            center = androidx.compose.ui.geometry.Offset(0f, size.height)
                        )
                    } else {
                        // Soft elegant light glows
                        drawCircle(
                            color = primaryColor.copy(alpha = 0.06f),
                            radius = size.width * 0.5f,
                            center = androidx.compose.ui.geometry.Offset(0f, 0f)
                        )
                        drawCircle(
                            color = secondaryColor.copy(alpha = 0.04f),
                            radius = size.width * 0.4f,
                            center = androidx.compose.ui.geometry.Offset(size.width, size.height * 0.3f)
                        )
                    }
                }
                .padding(
                    top = if (currentScreen is Screen.UserDashboard || currentScreen is Screen.AdminDashboard) {
                        maxOf(0.dp, padding.calculateTopPadding() - 10.dp)
                    } else {
                        padding.calculateTopPadding()
                    },
                    bottom = if (currentScreen is Screen.UserDashboard || currentScreen is Screen.AdminDashboard) {
                        maxOf(0.dp, padding.calculateBottomPadding() - 10.dp)
                    } else {
                        padding.calculateBottomPadding()
                    },
                    start = padding.calculateLeftPadding(androidx.compose.ui.unit.LayoutDirection.Ltr),
                    end = padding.calculateRightPadding(androidx.compose.ui.unit.LayoutDirection.Ltr)
                )
        ) {
            AnimatedContent(
                targetState = currentScreen,
                modifier = Modifier
                    .fillMaxSize()
                    .widthIn(max = 850.dp)
                    .align(Alignment.TopCenter),
                transitionSpec = {
                    val isEnteringRight = targetState.hashCode() > initialState.hashCode()
                    if (isEnteringRight) {
                        (slideInHorizontally { width -> width / 4 } + fadeIn(animationSpec = tween(300))).togetherWith(
                            slideOutHorizontally { width -> -width / 4 } + fadeOut(animationSpec = tween(300))
                        )
                    } else {
                        (slideInHorizontally { width -> -width / 4 } + fadeIn(animationSpec = tween(300))).togetherWith(
                            slideOutHorizontally { width -> width / 4 } + fadeOut(animationSpec = tween(300))
                        )
                    }
                },
                label = "Screen Transition"
                ) { screen ->
                    when (screen) {
                        is Screen.Splash -> SplashScreen(viewModel)
                        is Screen.Tutorial -> TutorialScreen(viewModel)
                        is Screen.Leaderboard -> LeaderboardScreen(viewModel)
                        is Screen.Reports -> ReportsScreen(viewModel)
                        is Screen.Login -> LoginScreen(viewModel)
                        is Screen.LoginBuffer -> LoginBufferScreen(viewModel)
                        is Screen.Register -> RegisterScreen(viewModel)
                        is Screen.UserDashboard -> UserDashboardScreen(viewModel)
                        is Screen.UserQuizSetup -> UserQuizSetupScreen(viewModel, screen.subjectId, screen.topicId)
                        is Screen.UserQuizPlay -> UserQuizPlayScreen(viewModel, screen.subjectId, screen.topicId, screen.enableTimer)
                        is Screen.UserQuizReview -> UserQuizReviewScreen(viewModel, screen.testResultId)
                        is Screen.UserProgressAnalytics -> UserProgressScreen(viewModel)
                        is Screen.AdminDashboard -> AdminDashboardScreen(viewModel)
                        is Screen.AdminManageSubjects -> AdminManageSubjectsScreen(viewModel)
                        is Screen.AdminManageTopics -> AdminManageTopicsScreen(viewModel)
                        is Screen.AdminManageMcqs -> AdminManageMcqsScreen(viewModel)
                        is Screen.AdminEditMcq -> AdminEditMcqScreen(viewModel, screen.mcqId)
                        is Screen.AdminImportMcqs -> AdminImportMcqsScreen(viewModel)
                        is Screen.AdminStatsDetails -> AdminStatsDetailsScreen(viewModel)
                        is Screen.AdminManageUsers -> AdminManageUsersScreen(viewModel)
                        is Screen.AdminFeeManagement -> AdminFeeManagementScreen(viewModel)
                        is Screen.AdminViewUserProfile -> AdminViewUserProfileScreen(viewModel, screen.userId)
                        is Screen.UserNotes -> UserNotesScreen(viewModel)
                        is Screen.AdminNotes -> AdminNotesScreen(viewModel)
                        is Screen.StudyFeed -> StudyFeedScreen(viewModel)
                        is Screen.UserProfile -> UserProfileScreen(viewModel)
                        is Screen.AdminPushNotifications -> AdminPushNotificationsScreen(viewModel)
                        is Screen.AdminContributedMcqs -> AdminContributedMcqsScreen(viewModel)
                        is Screen.AdminAnnouncements -> AdminAnnouncementsScreen(viewModel)
                        is Screen.AdminAppSettings -> AdminAppSettingsScreen(viewModel)
                        is Screen.AboutUs -> AboutUsScreen(viewModel, screen.customizeMode)
                        is Screen.UserAddMcq -> UserAddMcqScreen(viewModel)
                        is Screen.AskAi -> AskAiScreen(viewModel)
                        is Screen.AdminAskAiSettings -> AdminAskAiSettingsScreen(viewModel)
                        is Screen.MdcatCountdownDetail -> MdcatCountdownDetailScreen(viewModel)
                        is Screen.GetReward -> GetRewardScreen(viewModel)
                        is Screen.TargetTracker -> TargetTrackerScreen(viewModel)
                        is Screen.UserSearch -> UserSearchScreen(viewModel)
                        is Screen.ViewUserProfile -> ViewUserProfileScreen(viewModel, screen.userId)
                        is Screen.UserSubscription -> UserSubscriptionScreen(viewModel)
                    }
                }

                // SUSPENSION OVERLAY BARRIER
                val loggedInUserVal by viewModel.loggedInUser.collectAsState()
                val isSuspended = viewModel.isCurrentUserSuspended()
                val currentScreenVal by viewModel.currentScreen.collectAsState()
                
                if (loggedInUserVal != null && isSuspended && 
                    currentScreenVal !is Screen.Splash && 
                    currentScreenVal !is Screen.Login && 
                    currentScreenVal !is Screen.Register && 
                    currentScreenVal !is Screen.Tutorial && 
                    currentScreenVal !is Screen.LoginBuffer
                ) {
                    Box(
                        modifier = Modifier
                            .fillMaxSize()
                            .background(Color.Black.copy(alpha = 0.96f))
                            .clickable(enabled = true, onClick = {}),
                        contentAlignment = Alignment.Center
                    ) {
                        Card(
                            modifier = Modifier
                                .fillMaxWidth(0.92f)
                                .padding(16.dp),
                            colors = CardDefaults.cardColors(containerColor = MaterialTheme.colorScheme.surface),
                            border = BorderStroke(2.dp, MaterialTheme.colorScheme.error)
                        ) {
                            Column(
                                modifier = Modifier.padding(24.dp),
                                horizontalAlignment = Alignment.CenterHorizontally,
                                verticalArrangement = Arrangement.spacedBy(16.dp)
                            ) {
                                Box(
                                    modifier = Modifier
                                        .size(64.dp)
                                        .clip(CircleShape)
                                        .background(Color(0xFFFFEBEE)),
                                    contentAlignment = Alignment.Center
                                ) {
                                    Icon(
                                        imageVector = Icons.Filled.Error,
                                        contentDescription = null,
                                        tint = Color(0xFFC62828),
                                        modifier = Modifier.size(36.dp)
                                    )
                                }
                                
                                Text(
                                    text = "Subscription Required",
                                    fontWeight = FontWeight.ExtraBold,
                                    fontSize = 20.sp,
                                    color = Color(0xFFC62828),
                                    textAlign = TextAlign.Center
                                )
                                
                                Text(
                                    text = "Your free trial or premium subscription plan has expired / has been suspended. Please contact the NayaRasta Academy administrator to active your account.",
                                    fontSize = 13.sp,
                                    textAlign = TextAlign.Center,
                                    lineHeight = 19.sp,
                                    color = MaterialTheme.colorScheme.onSurfaceVariant
                                )
                                
                                Card(
                                    modifier = Modifier.fillMaxWidth(),
                                    colors = CardDefaults.cardColors(containerColor = MaterialTheme.colorScheme.surfaceVariant.copy(alpha = 0.5f))
                                ) {
                                    Column(
                                        modifier = Modifier.padding(12.dp),
                                        verticalArrangement = Arrangement.spacedBy(4.dp)
                                    ) {
                                        Text(
                                            text = "Username: @${loggedInUserVal?.username}",
                                            fontSize = 12.sp,
                                            fontWeight = FontWeight.Bold
                                        )
                                        Text(
                                            text = "Status: ${viewModel.getSubscriptionDetails(loggedInUserVal)}",
                                            fontSize = 12.sp,
                                            color = Color(0xFFC62828),
                                            fontWeight = FontWeight.Black
                                        )
                                    }
                                }
                                
                                Button(
                                    onClick = {
                                        try {
                                            val msg = "Assalam-o-Alaikum Admin! I am blocked by the subscription wall on NayaRasta App.\n\nMy Details:\nUsername: @${loggedInUserVal?.username}\nFull Name: ${loggedInUserVal?.fullName}\nPlease active/renew my subscription."
                                            val intent = android.content.Intent(
                                                android.content.Intent.ACTION_VIEW,
                                                android.net.Uri.parse("https://api.whatsapp.com/send?phone=${viewModel.getHelplineNumberInternational()}&text=${java.net.URLEncoder.encode(msg, "UTF-8")}")
                                            )
                                            context.startActivity(intent)
                                        } catch (e: Exception) {
                                            viewModel.feedbackMessage.value = "Failed to launch WhatsApp: ${e.localizedMessage}"
                                        }
                                    },
                                    modifier = Modifier.fillMaxWidth(),
                                    colors = ButtonDefaults.buttonColors(containerColor = Color(0xFF2E7D32))
                                ) {
                                    Icon(Icons.Filled.AccountBalanceWallet, null, modifier = Modifier.size(16.dp))
                                    Spacer(modifier = Modifier.width(8.dp))
                                    Text("Contact Admin to Active", fontWeight = FontWeight.Bold)
                                }
                                
                                OutlinedButton(
                                    onClick = {
                                        viewModel.triggerLogout()
                                    },
                                    modifier = Modifier.fillMaxWidth(),
                                    colors = ButtonDefaults.outlinedButtonColors(contentColor = MaterialTheme.colorScheme.primary),
                                    border = BorderStroke(1.2.dp, MaterialTheme.colorScheme.primary)
                                ) {
                                    Icon(Icons.Filled.ExitToApp, null, modifier = Modifier.size(16.dp))
                                    Spacer(modifier = Modifier.width(8.dp))
                                    Text("Sign Out / Log In to Another Account")
                                }
                            }
                        }
                    }
                }

                val activeNotification by viewModel.activeNotificationPopupFlow.collectAsState()
                
                // Heads-Up Slide-Down Notification Prompt
                androidx.compose.animation.AnimatedVisibility(
                    visible = activeNotification != null,
                    enter = androidx.compose.animation.slideInVertically(initialOffsetY = { -it }) + androidx.compose.animation.fadeIn(),
                    exit = androidx.compose.animation.slideOutVertically(targetOffsetY = { -it }) + androidx.compose.animation.fadeOut(),
                    modifier = Modifier
                        .align(Alignment.TopCenter)
                        .padding(16.dp)
                ) {
                    activeNotification?.let { notif ->
                        Card(
                            modifier = Modifier
                                .fillMaxWidth()
                                .clickable { viewModel.dismissActiveNotificationPopup() },
                            colors = CardDefaults.cardColors(
                                containerColor = MaterialTheme.colorScheme.surfaceVariant
                            ),
                            elevation = CardDefaults.cardElevation(defaultElevation = 12.dp),
                            shape = RoundedCornerShape(16.dp),
                            border = BorderStroke(1.dp, MaterialTheme.colorScheme.primary.copy(alpha = 0.5f))
                        ) {
                            Row(
                                modifier = Modifier
                                    .fillMaxWidth()
                                    .padding(12.dp),
                                verticalAlignment = Alignment.CenterVertically,
                                horizontalArrangement = Arrangement.spacedBy(12.dp)
                            ) {
                                Box(
                                    modifier = Modifier
                                        .size(40.dp)
                                        .clip(RoundedCornerShape(20.dp))
                                        .background(MaterialTheme.colorScheme.primary.copy(alpha = 0.1f)),
                                    contentAlignment = Alignment.Center
                                ) {
                                    Icon(
                                        imageVector = Icons.Filled.NotificationsActive,
                                        contentDescription = "Alert",
                                        tint = MaterialTheme.colorScheme.primary,
                                        modifier = Modifier.size(24.dp)
                                    )
                                }
                                
                                Column(modifier = Modifier.weight(1f)) {
                                    Text(
                                        text = notif.title,
                                        color = MaterialTheme.colorScheme.onSurfaceVariant,
                                        fontWeight = FontWeight.Bold,
                                        fontSize = 13.sp
                                    )
                                    Text(
                                        text = notif.message,
                                        color = MaterialTheme.colorScheme.onSurfaceVariant.copy(alpha = 0.8f),
                                        fontSize = 11.sp,
                                        maxLines = 2,
                                        overflow = TextOverflow.Ellipsis
                                    )
                                    if (!notif.imageUrl.isNullOrBlank()) {
                                        Spacer(modifier = Modifier.height(4.dp))
                                        val painter = coil.compose.rememberAsyncImagePainter(model = notif.imageUrl)
                                        androidx.compose.foundation.Image(
                                            painter = painter,
                                            contentDescription = "Notification Image",
                                            modifier = Modifier
                                                .fillMaxWidth()
                                                .height(100.dp)
                                                .clip(RoundedCornerShape(8.dp)),
                                            contentScale = androidx.compose.ui.layout.ContentScale.Crop
                                        )
                                    }
                                }
                                
                                IconButton(
                                    onClick = { viewModel.dismissActiveNotificationPopup() }
                                ) {
                                    Icon(
                                        imageVector = Icons.Filled.Close,
                                        contentDescription = "Dismiss",
                                        tint = MaterialTheme.colorScheme.outline,
                                        modifier = Modifier.size(16.dp)
                                    )
                                }
                            }
                        }
                    }
                }

                // Custom Premium Organized Glass Drawer Menus
                PremiumOrganizedMenu(
                    expanded = userMenuExpanded,
                    onDismiss = { userMenuExpanded = false },
                    isAdmin = false,
                    viewModel = viewModel,
                    loggedInUserVal = loggedInUser,
                    activeStyle = activeStyle
                )

                PremiumOrganizedMenu(
                    expanded = adminMenuExpanded,
                    onDismiss = { adminMenuExpanded = false },
                    isAdmin = true,
                    viewModel = viewModel,
                    loggedInUserVal = loggedInUser,
                    activeStyle = activeStyle
                )
        }
    }
}

@Composable
fun SimpleSnackbarHost(snackbarHostState: SnackbarHostState) {
    SnackbarHost(hostState = snackbarHostState)
}

@OptIn(ExperimentalMaterial3Api::class)
@Composable
fun Scaffold(
    snackbarHostStatus: SnackbarHostState,
    topBar: @Composable () -> Unit,
    bottomBar: @Composable () -> Unit,
    contentWindowInsets: WindowInsets,
    content: @Composable (PaddingValues) -> Unit
) {
    Scaffold(
        topBar = topBar,
        bottomBar = bottomBar,
        snackbarHost = { SimpleSnackbarHost(snackbarHostStatus) },
        contentWindowInsets = contentWindowInsets,
        content = content
    )
}

fun mapIconNameToVector(iconName: String): ImageVector {
    return when (iconName.lowercase()) {
        "computer" -> Icons.Filled.Computer
        "calculate" -> Icons.Filled.Calculate
        "menu_book" -> Icons.Filled.Book
        else -> Icons.Filled.School
    }
}

@Composable
fun NayaRastaDropdown(
    label: String,
    options: List<String>,
    selectedOption: String,
    onOptionSelected: (String) -> Unit
) {
    var expanded by remember { mutableStateOf(false) }
    
    Box(
        modifier = Modifier
            .fillMaxWidth()
            .padding(vertical = 4.dp)
    ) {
        OutlinedTextField(
            value = selectedOption,
            onValueChange = {},
            readOnly = true,
            label = { Text(label, fontWeight = FontWeight.Bold, fontSize = 12.sp) },
            trailingIcon = {
                IconButton(onClick = { expanded = !expanded }) {
                    Icon(
                        imageVector = if (expanded) Icons.Filled.ArrowDropUp else Icons.Filled.ArrowDropDown,
                        contentDescription = "Toggle Dropdown",
                        tint = MaterialTheme.colorScheme.primary
                    )
                }
            },
            modifier = Modifier
                .fillMaxWidth()
                .clickable { expanded = !expanded },
            shape = RoundedCornerShape(12.dp)
        )
        
        DropdownMenu(
            expanded = expanded,
            onDismissRequest = { expanded = false },
            modifier = Modifier
                .fillMaxWidth(0.85f)
                .background(MaterialTheme.colorScheme.surface)
        ) {
            options.forEach { option ->
                DropdownMenuItem(
                    text = { 
                        Text(
                            text = option,
                            fontWeight = if (option == selectedOption) FontWeight.Bold else FontWeight.Normal,
                            color = if (option == selectedOption) MaterialTheme.colorScheme.primary else MaterialTheme.colorScheme.onSurface,
                            fontSize = 14.sp
                        )
                    },
                    onClick = {
                        onOptionSelected(option)
                        expanded = false
                    },
                    modifier = Modifier.fillMaxWidth()
                )
            }
        }
    }
}

// ==================== SCREEN 1: LOGIN ====================
@Composable
fun LoginScreen(viewModel: MainViewModel) {
    var username by remember { mutableStateOf("") }
    var password by remember { mutableStateOf("") }
    var passwordVisible by remember { mutableStateOf(false) }

    var showRecoveryDialog by remember { mutableStateOf(false) }
    var recoveryMode by remember { mutableStateOf("USERNAME") } // "USERNAME" or "PASSWORD"
    var recoveryPhone by remember { mutableStateOf("") }
    var recoveredUser by remember { mutableStateOf<User?>(null) }
    var recoveryError by remember { mutableStateOf<String?>(null) }
    var requiresAdminPin by remember { mutableStateOf(false) }
    var adminPinInput by remember { mutableStateOf("") }

    val debugStatus by viewModel.loginDebugStatus.collectAsState()

    val isDark = isSystemInDarkTheme()
    val gradientBrush = if (isDark) {
        Brush.linearGradient(
            colors = listOf(Color(0xFF0C0E14), Color(0xFF1B1E2E))
        )
    } else {
        Brush.linearGradient(
            colors = listOf(Color(0xFFF3F7FA), Color(0xFFE2E9F0))
        )
    }

    Box(
        modifier = Modifier
            .fillMaxSize()
            .background(gradientBrush),
        contentAlignment = Alignment.Center
    ) {
        val configuration = androidx.compose.ui.platform.LocalConfiguration.current
        val isCompact = configuration.screenWidthDp < 360
        val isSmallHeight = configuration.screenHeightDp < 640
        val outerPadding = if (isCompact) 10.dp else 16.dp
        val innerPaddingHorizontal = if (isCompact) 12.dp else 20.dp
        val innerPaddingVertical = if (isSmallHeight) 16.dp else 28.dp

        PremiumStyleContainer(
            style = DesignStyle.GRADIENT_GLASS,
            modifier = Modifier
                .fillMaxWidth()
                .widthIn(max = 480.dp)
                .padding(outerPadding),
            containerColor = MaterialTheme.colorScheme.surface.copy(alpha = 0.88f)
        ) {
            Column(
                modifier = Modifier
                    .fillMaxWidth()
                    .verticalScroll(rememberScrollState())
                    .padding(vertical = innerPaddingVertical, horizontal = innerPaddingHorizontal),
                horizontalAlignment = Alignment.CenterHorizontally,
                verticalArrangement = Arrangement.spacedBy(16.dp)
            ) {
                // Header Group with Glowing NayaRasta Logo
                Box(
                    modifier = Modifier
                        .size(92.dp)
                        .clip(CircleShape)
                        .background(Color.White)
                        .border(
                            width = 2.dp,
                            color = MaterialTheme.colorScheme.primary.copy(alpha = 0.35f),
                            shape = CircleShape
                        )
                        .padding(14.dp),
                    contentAlignment = Alignment.Center
                ) {
                    val logoUrl = viewModel.getAppLogoUrl()
                    if (logoUrl != null) {
                        androidx.compose.foundation.Image(
                            painter = coil.compose.rememberAsyncImagePainter(model = logoUrl),
                            contentDescription = "App Logo",
                            modifier = Modifier.fillMaxSize(),
                            contentScale = androidx.compose.ui.layout.ContentScale.Fit
                        )
                    } else {
                        androidx.compose.foundation.Image(
                            painter = androidx.compose.ui.res.painterResource(id = com.example.R.drawable.logo),
                            contentDescription = "App Logo",
                            modifier = Modifier.fillMaxSize(),
                            contentScale = androidx.compose.ui.layout.ContentScale.Fit
                        )
                    }
                }

                Column(
                    horizontalAlignment = Alignment.CenterHorizontally,
                    verticalArrangement = Arrangement.spacedBy(4.dp)
                ) {
                    Text(
                        text = "${viewModel.getAppName()} Portal",
                        fontSize = 26.sp,
                        fontWeight = FontWeight.ExtraBold,
                        color = MaterialTheme.colorScheme.primary,
                        textAlign = TextAlign.Center
                    )
                    Text(
                        text = "Securely sign in to access subjects, practice tests, study feed, and academic paid notes.",
                        fontSize = 12.sp,
                        color = MaterialTheme.colorScheme.onSurfaceVariant,
                        textAlign = TextAlign.Center,
                        modifier = Modifier.padding(horizontal = 8.dp)
                    )
                }

                // Streamlined unified Input fields
                OutlinedTextField(
                    value = username,
                    onValueChange = { username = it },
                    label = { Text("Username") },
                    leadingIcon = { Icon(Icons.Filled.Person, "Username", tint = MaterialTheme.colorScheme.primary) },
                    singleLine = true,
                    modifier = Modifier.fillMaxWidth(),
                    shape = RoundedCornerShape(12.dp)
                )

                OutlinedTextField(
                    value = password,
                    onValueChange = { password = it },
                    label = { Text("Password") },
                    leadingIcon = { Icon(Icons.Filled.Lock, "Password", tint = MaterialTheme.colorScheme.primary) },
                    trailingIcon = {
                        IconButton(onClick = { passwordVisible = !passwordVisible }) {
                            Icon(
                                imageVector = if (passwordVisible) Icons.Filled.Visibility else Icons.Filled.VisibilityOff,
                                contentDescription = if (passwordVisible) "Hide password" else "Show password",
                                tint = MaterialTheme.colorScheme.outline
                            )
                        }
                    },
                    singleLine = true,
                    visualTransformation = if (passwordVisible) androidx.compose.ui.text.input.VisualTransformation.None else PasswordVisualTransformation(),
                    modifier = Modifier.fillMaxWidth(),
                    shape = RoundedCornerShape(12.dp)
                )

                val isConnected by viewModel.isSupabaseConnected.collectAsState()

                Row(
                    modifier = Modifier.fillMaxWidth(),
                    verticalAlignment = Alignment.CenterVertically,
                    horizontalArrangement = Arrangement.SpaceBetween
                ) {
                    Row(
                        verticalAlignment = Alignment.CenterVertically
                    ) {
                        Icon(
                            imageVector = Icons.Filled.LockPerson,
                            contentDescription = "Session security info",
                            tint = MaterialTheme.colorScheme.primary,
                            modifier = Modifier.size(16.dp)
                        )
                        Spacer(modifier = Modifier.width(6.dp))
                        Text("Persistent Session Active", fontSize = 11.sp, fontWeight = FontWeight.SemiBold)
                    }

                    // Clickable Connection status icon & label
                    Row(
                        verticalAlignment = Alignment.CenterVertically,
                        modifier = Modifier
                            .clip(RoundedCornerShape(8.dp))
                            .background(
                                when (isConnected) {
                                    true -> Color(0xFFE8F5E9)
                                    false -> Color(0xFFFFEBEE)
                                    null -> Color(0xFFF5F5F5)
                                }
                            )
                            .clickable { viewModel.checkSupabaseConnection() }
                            .padding(horizontal = 10.dp, vertical = 6.dp),
                        horizontalArrangement = Arrangement.spacedBy(4.dp)
                    ) {
                        Icon(
                            imageVector = Icons.Filled.Cloud,
                            contentDescription = "Connection indicator",
                            tint = when (isConnected) {
                                true -> Color(0xFF2E7D32)
                                false -> Color.Red
                                null -> Color.Gray
                            },
                            modifier = Modifier.size(14.dp)
                        )
                        Text(
                            text = when (isConnected) {
                                true -> "Connected"
                                false -> "Offline"
                                null -> "Checking..."
                            },
                            fontSize = 11.sp,
                            fontWeight = FontWeight.Bold,
                            color = when (isConnected) {
                                true -> Color(0xFF2E7D32)
                                false -> Color.Red
                                null -> Color.Gray
                            }
                        )
                    }
                }

                Button(
                    onClick = {
                        viewModel.authenticateUser(username, password) { success ->
                            if (success) {
                                viewModel.saveStayLoggedIn(username)
                                username = ""
                                password = ""
                            }
                        }
                    },
                    modifier = Modifier
                        .fillMaxWidth()
                        .height(52.dp),
                    shape = RoundedCornerShape(14.dp)
                ) {
                    Text("Login Now", fontSize = 15.sp, fontWeight = FontWeight.Bold)
                }

                Row(
                    modifier = Modifier.fillMaxWidth(),
                    horizontalArrangement = Arrangement.SpaceBetween,
                    verticalAlignment = Alignment.CenterVertically
                ) {
                    Text(
                        text = "Forgot Username?",
                        fontSize = 12.sp,
                        fontWeight = FontWeight.Bold,
                        color = MaterialTheme.colorScheme.primary,
                        modifier = Modifier.clickable {
                            recoveryMode = "USERNAME"
                            recoveryPhone = ""
                            recoveredUser = null
                            recoveryError = null
                            requiresAdminPin = false
                            adminPinInput = ""
                            showRecoveryDialog = true
                        }
                    )
                    Text(
                        text = "Forgot Password?",
                        fontSize = 12.sp,
                        fontWeight = FontWeight.Bold,
                        color = MaterialTheme.colorScheme.primary,
                        modifier = Modifier.clickable {
                            recoveryMode = "PASSWORD"
                            recoveryPhone = ""
                            recoveredUser = null
                            recoveryError = null
                            requiresAdminPin = false
                            adminPinInput = ""
                            showRecoveryDialog = true
                        }
                    )
                }

                Row(
                    modifier = Modifier.fillMaxWidth(),
                    horizontalArrangement = Arrangement.Center,
                    verticalAlignment = Alignment.CenterVertically
                ) {
                    Text("New student? ", fontSize = 13.sp)
                    Text(
                        text = "Register profile",
                        fontSize = 13.sp,
                        fontWeight = FontWeight.ExtraBold,
                        color = MaterialTheme.colorScheme.primary,
                        modifier = Modifier.clickable { viewModel.navigateTo(Screen.Register) }
                    )
                }

                if (showRecoveryDialog) {
                    AlertDialog(
                        onDismissRequest = { showRecoveryDialog = false },
                        shape = RoundedCornerShape(28.dp),
                        containerColor = MaterialTheme.colorScheme.surface,
                        tonalElevation = 6.dp,
                        title = {
                            Row(
                                verticalAlignment = Alignment.CenterVertically,
                                horizontalArrangement = Arrangement.spacedBy(8.dp)
                            ) {
                                Icon(
                                    imageVector = if (requiresAdminPin) Icons.Filled.Lock else Icons.Filled.Person,
                                    contentDescription = null,
                                    tint = MaterialTheme.colorScheme.primary,
                                    modifier = Modifier.size(28.dp)
                                )
                                Text(
                                    text = if (recoveredUser != null) "Credentials Found" else if (requiresAdminPin) "Security Verification" else "Recover Account",
                                    fontWeight = FontWeight.Bold,
                                    fontSize = 20.sp,
                                    color = MaterialTheme.colorScheme.onSurface
                                )
                            }
                        },
                        text = {
                            Column(
                                verticalArrangement = Arrangement.spacedBy(16.dp),
                                modifier = Modifier.fillMaxWidth().padding(vertical = 8.dp)
                            ) {
                                if (recoveredUser == null) {
                                    if (requiresAdminPin) {
                                        Text(
                                            text = "This phone number is associated with the Admin account. Please enter the Admin Protection Pin to reveal credentials.",
                                            fontSize = 13.sp,
                                            color = MaterialTheme.colorScheme.onSurfaceVariant
                                        )
                                        OutlinedTextField(
                                            value = adminPinInput,
                                            onValueChange = { adminPinInput = it },
                                            label = { Text("Admin Protection Pin") },
                                            leadingIcon = { Icon(Icons.Filled.Lock, contentDescription = "Lock") },
                                            placeholder = { Text("Enter Pin") },
                                            singleLine = true,
                                            keyboardOptions = androidx.compose.foundation.text.KeyboardOptions(
                                                keyboardType = androidx.compose.ui.text.input.KeyboardType.Number
                                            ),
                                            modifier = Modifier.fillMaxWidth().testTag("admin_pin_input"),
                                            shape = RoundedCornerShape(12.dp)
                                        )
                                    } else {
                                        Text(
                                            text = "Please enter your registered phone number below to confirm your identity and recover your login information.",
                                            fontSize = 13.sp,
                                            color = MaterialTheme.colorScheme.onSurfaceVariant
                                        )
                                        OutlinedTextField(
                                            value = recoveryPhone,
                                            onValueChange = { recoveryPhone = it },
                                            label = { Text("Phone Number") },
                                            leadingIcon = { Icon(Icons.Filled.Phone, contentDescription = "Phone") },
                                            placeholder = { Text("e.g. 03001234567") },
                                            singleLine = true,
                                            keyboardOptions = androidx.compose.foundation.text.KeyboardOptions(
                                                keyboardType = androidx.compose.ui.text.input.KeyboardType.Phone
                                            ),
                                            modifier = Modifier.fillMaxWidth().testTag("recovery_phone_input"),
                                            shape = RoundedCornerShape(12.dp)
                                        )
                                    }

                                    if (recoveryError != null) {
                                        Text(
                                            text = recoveryError!!,
                                            color = MaterialTheme.colorScheme.error,
                                            fontSize = 12.sp,
                                            fontWeight = FontWeight.Bold
                                        )
                                    }
                                } else {
                                    Column(
                                        modifier = Modifier
                                            .fillMaxWidth()
                                            .clip(RoundedCornerShape(16.dp))
                                            .background(MaterialTheme.colorScheme.primaryContainer.copy(alpha = 0.3f))
                                            .padding(16.dp),
                                        horizontalAlignment = Alignment.CenterHorizontally,
                                        verticalArrangement = Arrangement.spacedBy(12.dp)
                                    ) {
                                        Text(
                                            text = "YOUR CREDENTIALS FOUND:",
                                            fontSize = 11.sp,
                                            fontWeight = FontWeight.Bold,
                                            color = MaterialTheme.colorScheme.primary,
                                            letterSpacing = 1.sp
                                        )

                                        Column(
                                            verticalArrangement = Arrangement.spacedBy(8.dp),
                                            modifier = Modifier.fillMaxWidth()
                                        ) {
                                            Row(
                                                modifier = Modifier.fillMaxWidth(),
                                                horizontalArrangement = Arrangement.SpaceBetween,
                                                verticalAlignment = Alignment.CenterVertically
                                            ) {
                                                Text(
                                                    text = "Username:",
                                                    fontSize = 13.sp,
                                                    fontWeight = FontWeight.Medium,
                                                    color = MaterialTheme.colorScheme.onSurfaceVariant
                                                )
                                                Text(
                                                    text = recoveredUser!!.username,
                                                    fontSize = 16.sp,
                                                    fontWeight = FontWeight.Bold,
                                                    color = MaterialTheme.colorScheme.onPrimaryContainer,
                                                    modifier = Modifier.testTag("recovered_username_display")
                                                )
                                            }

                                            Row(
                                                modifier = Modifier.fillMaxWidth(),
                                                horizontalArrangement = Arrangement.SpaceBetween,
                                                verticalAlignment = Alignment.CenterVertically
                                            ) {
                                                Text(
                                                    text = "Password:",
                                                    fontSize = 13.sp,
                                                    fontWeight = FontWeight.Medium,
                                                    color = MaterialTheme.colorScheme.onSurfaceVariant
                                                )
                                                Text(
                                                    text = recoveredUser!!.passwordHash,
                                                    fontSize = 16.sp,
                                                    fontWeight = FontWeight.Bold,
                                                    color = MaterialTheme.colorScheme.onPrimaryContainer,
                                                    modifier = Modifier.testTag("recovered_password_display")
                                                )
                                            }
                                        }
                                    }
                                    Text(
                                        text = "Note: Please keep your login credentials secure. You can now use these details to login.",
                                        fontSize = 11.sp,
                                        color = MaterialTheme.colorScheme.onSurfaceVariant
                                    )
                                }
                            }
                        },
                        confirmButton = {
                            if (recoveredUser == null) {
                                Button(
                                    onClick = {
                                        if (requiresAdminPin) {
                                            if (adminPinInput.trim() == "35332") {
                                                recoveryError = null
                                                viewModel.getUserByPhoneNumber(viewModel.getHelplineNumber()) { user ->
                                                    if (user != null) {
                                                        recoveredUser = user
                                                    } else {
                                                        recoveryError = "No Admin account found in the database."
                                                    }
                                                }
                                            } else {
                                                recoveryError = "Incorrect Admin Protection Pin. Please try again."
                                            }
                                        } else {
                                            val targetPhone = recoveryPhone.trim()
                                            if (targetPhone.isEmpty()) {
                                                recoveryError = "Phone number cannot be empty."
                                            } else if (targetPhone == viewModel.getHelplineNumber()) {
                                                requiresAdminPin = true
                                                recoveryError = null
                                                adminPinInput = ""
                                            } else {
                                                recoveryError = null
                                                viewModel.getUserByPhoneNumber(targetPhone) { user ->
                                                    if (user != null) {
                                                        recoveredUser = user
                                                    } else {
                                                        recoveryError = "No account found with this phone number."
                                                    }
                                                }
                                            }
                                        }
                                    },
                                    shape = RoundedCornerShape(12.dp),
                                    modifier = Modifier.testTag("recovery_confirm_button")
                                ) {
                                    Text(if (requiresAdminPin) "Verify Pin" else "Confirm Phone")
                                }
                            } else {
                                Button(
                                    onClick = { showRecoveryDialog = false },
                                    shape = RoundedCornerShape(12.dp)
                                ) {
                                    Text("Done")
                                }
                            }
                        },
                        dismissButton = {
                            if (recoveredUser == null) {
                                TextButton(
                                    onClick = { showRecoveryDialog = false }
                                ) {
                                    Text("Cancel")
                                }
                            }
                        }
                    )
                }

                // Support & Academic Help Resource Card (Replacing old Demo Credentials)
                Card(
                    colors = CardDefaults.cardColors(
                        containerColor = if (isDark) Color(0xFF1E1E2E) else MaterialTheme.colorScheme.primaryContainer.copy(alpha = 0.1f)
                    ),
                    border = BorderStroke(1.dp, if (isDark) Color(0xFF2D2D44) else MaterialTheme.colorScheme.primaryContainer.copy(alpha = 0.2f)),
                    shape = RoundedCornerShape(14.dp),
                    modifier = Modifier.padding(top = 8.dp)
                ) {
                    Column(
                        modifier = Modifier.padding(14.dp),
                        verticalArrangement = Arrangement.spacedBy(6.dp)
                    ) {
                        Text(
                            text = "Official Academic Entrance Portal",
                            fontSize = 12.sp,
                            fontWeight = FontWeight.Bold,
                            color = MaterialTheme.colorScheme.primary
                        )
                        Text(
                            text = "• Practice from hundreds of verified MDCAT and NUMS MCQs with detailed explanations.",
                            fontSize = 11.sp,
                            color = MaterialTheme.colorScheme.onSurfaceVariant
                        )
                        Text(
                            text = "• Download free or premium PDF resources, view peer posts inside Study Feed, and monitor live ranks.",
                            fontSize = 11.sp,
                            color = MaterialTheme.colorScheme.onSurfaceVariant
                        )
                        Text(
                            text = "• Keep your enrollment fee paid up to date to maintain uninterrupted book unlocks.",
                            fontSize = 11.sp,
                            color = MaterialTheme.colorScheme.onSurfaceVariant
                        )
                    }
                }
            }
        }

        // Real-time debug status bar at the bottom of the screen
        val isErrorStatus = debugStatus.contains("failed", ignoreCase = true) || 
                            debugStatus.contains("error", ignoreCase = true) || 
                            debugStatus.contains("Exception", ignoreCase = true)
        val isSuccessStatus = debugStatus.contains("successful", ignoreCase = true)
        
        Box(
            modifier = Modifier
                .fillMaxWidth()
                .align(Alignment.BottomCenter)
                .background(
                    if (isDark) Color(0xFF141722).copy(alpha = 0.95f) 
                    else Color(0xFFF1F5F9).copy(alpha = 0.95f)
                )
                .border(
                    width = 1.dp, 
                    color = if (isDark) Color(0xFF2E3244) else Color(0xFFCBD5E1)
                )
                .padding(horizontal = 16.dp, vertical = 12.dp)
        ) {
            Row(
                modifier = Modifier.fillMaxWidth(),
                verticalAlignment = Alignment.CenterVertically,
                horizontalArrangement = Arrangement.spacedBy(10.dp)
            ) {
                Box(
                    modifier = Modifier
                        .size(8.dp)
                        .clip(CircleShape)
                        .background(
                            when {
                                isErrorStatus -> Color.Red
                                isSuccessStatus -> Color(0xFF2E7D32)
                                else -> Color(0xFFFF9800)
                            }
                        )
                )
                Column(modifier = Modifier.weight(1f)) {
                    Text(
                        text = "LOGIN FLOW MONITOR (DEBUG)",
                        fontSize = 10.sp,
                        fontWeight = FontWeight.Bold,
                        color = if (isDark) Color(0xFF94A3B8) else Color(0xFF475569),
                        letterSpacing = 0.5.sp
                    )
                    Text(
                        text = debugStatus,
                        fontSize = 12.sp,
                        fontWeight = FontWeight.Medium,
                        color = when {
                            isErrorStatus -> Color.Red
                            isSuccessStatus -> if (isDark) Color(0xFF81C784) else Color(0xFF2E7D32)
                            else -> if (isDark) Color.White else Color.Black
                        }
                    )
                }
            }
        }
    }
}

// ==================== SCREEN 2: REGISTER ====================
@Composable
fun RegisterScreen(viewModel: MainViewModel) {
    var username by remember { mutableStateOf("") }
    var password by remember { mutableStateOf("") }
    var confirmPassword by remember { mutableStateOf("") }
    var fullName by remember { mutableStateOf("") }
    var email by remember { mutableStateOf("") }
    var phoneNumber by remember { mutableStateOf("") }
    var studentType by remember { mutableStateOf("Fresher") }
    var gradeLevel by remember { mutableStateOf("Pre-Medical / FSc Part 1") }
    var studyGoal by remember { mutableStateOf("MDCAT") }
    var profileImageUri by remember { mutableStateOf("") }
    var isUploadingImage by remember { mutableStateOf(false) }

    // Visibility toggles for passwords
    var passwordVisible by remember { mutableStateOf(false) }
    var confirmPasswordVisible by remember { mutableStateOf(false) }

    // Social SSO Verification State
    var isSocialVerified by remember { mutableStateOf(false) }
    var verifiedProvider by remember { mutableStateOf("") } // "Google" or "Facebook"

    val context = androidx.compose.ui.platform.LocalContext.current
    val coroutineScope = androidx.compose.runtime.rememberCoroutineScope()

    // Real-time unique username check
    val usersList by viewModel.allUsers.collectAsState()
    
    val isUsernameTaken = remember(username, usersList) {
        username.trim().isNotEmpty() && usersList.any { it.username.trim().equals(username.trim(), ignoreCase = true) }
    }

    // Suggestions generation based on their typing & uniqueness
    val suggestedUsernames = remember(username, fullName, usersList) {
        val base = if (username.trim().isNotEmpty()) username.trim() else if (fullName.trim().isNotEmpty()) fullName.trim().lowercase().replace(" ", "") else ""
        if (base.isNotEmpty()) {
            listOf(
                "${base}_786",
                "${base}99",
                "${base}_pk",
                "${base}_learner",
                "${base}_active"
            ).filter { sug ->
                !sug.contains("admin", ignoreCase = true) && usersList.none { it.username.trim().equals(sug, ignoreCase = true) }
            }
        } else {
            emptyList()
        }
    }

    // Rules & Validations
    val containsAdminWord = remember(username, fullName) {
        username.contains("admin", ignoreCase = true) || fullName.contains("admin", ignoreCase = true)
    }

    val isPhoneValid = remember(phoneNumber) {
        phoneNumber.trim().length == 11 && phoneNumber.trim().startsWith("03") && phoneNumber.all { it.isDigit() }
    }

    val isPasswordValid = remember(password) {
        password.length >= 6
    }

    // Real Google Sign-In Options Configuration
    val gso = remember {
        com.google.android.gms.auth.api.signin.GoogleSignInOptions.Builder(com.google.android.gms.auth.api.signin.GoogleSignInOptions.DEFAULT_SIGN_IN)
            .requestEmail()
            .requestProfile()
            .build()
    }
    val googleSignInClient = remember(gso) {
        com.google.android.gms.auth.api.signin.GoogleSignIn.getClient(context, gso)
    }

    // Launcher for Real Google Sign-In Authentication Flow
    val googleSignInLauncher = androidx.activity.compose.rememberLauncherForActivityResult(
        contract = androidx.activity.result.contract.ActivityResultContracts.StartActivityForResult()
    ) { result ->
        val task = com.google.android.gms.auth.api.signin.GoogleSignIn.getSignedInAccountFromIntent(result.data)
        try {
            val account = task.getResult(com.google.android.gms.common.api.ApiException::class.java)
            if (account != null) {
                email = account.email ?: ""
                fullName = account.displayName ?: ""
                profileImageUri = account.photoUrl?.toString() ?: ""
                isSocialVerified = true
                verifiedProvider = "Google"
                viewModel.feedbackMessage.value = "Identity verified via Google profile in reality!"
            } else {
                viewModel.feedbackMessage.value = "Google authentication cancelled."
            }
        } catch (e: Exception) {
            e.printStackTrace()
            viewModel.feedbackMessage.value = "Google API Connection Issue: ${e.localizedMessage ?: "User must be signed in to Google on this device"}. Please authenticate your device."
        }
    }

    // Native Account Manager Intent Launcher for Facebook profile options
    val accountManagerLauncher = androidx.activity.compose.rememberLauncherForActivityResult(
        contract = androidx.activity.result.contract.ActivityResultContracts.StartActivityForResult()
    ) { result ->
        if (result.resultCode == android.app.Activity.RESULT_OK) {
            val accountName = result.data?.getStringExtra(android.accounts.AccountManager.KEY_ACCOUNT_NAME)
            val accountType = result.data?.getStringExtra(android.accounts.AccountManager.KEY_ACCOUNT_TYPE)
            if (!accountName.isNullOrEmpty()) {
                email = accountName
                val defaultName = accountName.substringBefore("@")
                    .replace(".", " ")
                    .replace("_", " ")
                    .split(" ")
                    .joinToString(" ") { it.replaceFirstChar { char -> char.uppercase() } }
                fullName = defaultName
                isSocialVerified = true
                verifiedProvider = if (accountType?.contains("google", ignoreCase = true) == true) "Google" else "Facebook"
                viewModel.feedbackMessage.value = "Verified successfully via authenticated $verifiedProvider profile!"
            }
        }
    }

    fun launchSocialPicker(provider: String) {
        if (provider == "Google") {
            try {
                // Signs out previous sessions to allow freshly clicking dynamic account choosers / real allow buttons
                googleSignInClient.signOut().addOnCompleteListener {
                    try {
                        val signInIntent = googleSignInClient.signInIntent
                        googleSignInLauncher.launch(signInIntent)
                    } catch (ex: Exception) {
                        ex.printStackTrace()
                        viewModel.feedbackMessage.value = "Failed starting Google Authenticator: ${ex.localizedMessage}"
                    }
                }
            } catch (e: Exception) {
                e.printStackTrace()
                try {
                    val signInIntent = googleSignInClient.signInIntent
                    googleSignInLauncher.launch(signInIntent)
                } catch (ex: Exception) {
                    ex.printStackTrace()
                    viewModel.feedbackMessage.value = "Google Play Services auth initialization failed: ${ex.localizedMessage}"
                }
            }
        } else {
            try {
                val accountTypes = arrayOf("com.facebook.auth.login")
                val intent = android.accounts.AccountManager.newChooseAccountIntent(
                    null, null, accountTypes, null, null, null, null
                )
                accountManagerLauncher.launch(intent)
            } catch (e: Exception) {
                e.printStackTrace()
                viewModel.feedbackMessage.value = "Device accounts lookup failed: ${e.localizedMessage}"
            }
        }
    }

    val imagePickerLauncher = androidx.activity.compose.rememberLauncherForActivityResult(
        contract = androidx.activity.result.contract.ActivityResultContracts.GetContent()
    ) { uri: android.net.Uri? ->
        uri?.let {
            coroutineScope.launch {
                isUploadingImage = true
                try {
                    val savedPath = viewModel.uploadFileToSimulatedStorage(context, it, "profiles")
                    if (savedPath != null) {
                        profileImageUri = savedPath
                        viewModel.feedbackMessage.value = "Profile picture updated!"
                    }
                } finally {
                    isUploadingImage = false
                }
            }
        }
    }



    val isDark = isSystemInDarkTheme()
    val gradientBrush = if (isDark) {
        Brush.linearGradient(
            colors = listOf(Color(0xFF0C0E14), Color(0xFF1B1E2E))
        )
    } else {
        Brush.linearGradient(
            colors = listOf(Color(0xFFF3F7FA), Color(0xFFE2E9F0))
        )
    }

    Box(
        modifier = Modifier
            .fillMaxSize()
            .background(gradientBrush),
        contentAlignment = Alignment.Center
    ) {
        val configuration = androidx.compose.ui.platform.LocalConfiguration.current
        val isCompact = configuration.screenWidthDp < 360
        val isSmallHeight = configuration.screenHeightDp < 640
        val outerPaddingHorizontal = if (isCompact) 10.dp else 16.dp
        val outerPaddingVertical = if (isSmallHeight) 6.dp else 12.dp
        val innerPaddingHorizontal = if (isCompact) 12.dp else 20.dp
        val innerPaddingVertical = if (isSmallHeight) 10.dp else 20.dp

        PremiumStyleContainer(
            style = DesignStyle.GRADIENT_GLASS,
            modifier = Modifier
                .fillMaxWidth()
                .widthIn(max = 600.dp)
                .fillMaxHeight(0.96f)
                .padding(horizontal = outerPaddingHorizontal, vertical = outerPaddingVertical),
            containerColor = MaterialTheme.colorScheme.surface.copy(alpha = 0.82f)
        ) {
            LazyColumn(
                modifier = Modifier
                    .fillMaxSize()
                    .padding(horizontal = innerPaddingHorizontal, vertical = innerPaddingVertical),
                horizontalAlignment = Alignment.CenterHorizontally,
                verticalArrangement = Arrangement.spacedBy(14.dp)
            ) {
                item {
                    androidx.compose.foundation.layout.Box(
                        modifier = Modifier
                            .height(70.dp)
                            .fillMaxWidth(0.5f)
                            .clip(RoundedCornerShape(12.dp))
                            .background(androidx.compose.ui.graphics.Color.White)
                            .padding(4.dp),
                        contentAlignment = androidx.compose.ui.Alignment.Center
                    ) {
                        val logoUrl = viewModel.getAppLogoUrl()
                        if (logoUrl != null) {
                            androidx.compose.foundation.Image(
                                painter = coil.compose.rememberAsyncImagePainter(model = logoUrl),
                                contentDescription = "App Logo",
                                modifier = Modifier.fillMaxSize(),
                                contentScale = androidx.compose.ui.layout.ContentScale.Fit
                            )
                        } else {
                            androidx.compose.foundation.Image(
                                painter = androidx.compose.ui.res.painterResource(id = com.example.R.drawable.logo),
                                contentDescription = "App Logo",
                                modifier = Modifier.fillMaxSize(),
                                contentScale = androidx.compose.ui.layout.ContentScale.Fit
                            )
                        }
                    }
                    Text(
                        text = "Create ${viewModel.getAppName()} Profile",
                        fontSize = 22.sp,
                        fontWeight = FontWeight.ExtraBold,
                        color = MaterialTheme.colorScheme.primary,
                        textAlign = TextAlign.Center
                    )
                    Text(
                        text = "Fill out the registration details below to create your student account.",
                        fontSize = 11.sp,
                        color = MaterialTheme.colorScheme.onSurfaceVariant,
                        textAlign = TextAlign.Center,
                        modifier = Modifier.padding(top = 4.dp, bottom = 4.dp)
                    )
                }
                    // Block administrative words immediately
                    if (containsAdminWord) {
                        item {
                            Row(
                                modifier = Modifier
                                    .fillMaxWidth()
                                    .clip(RoundedCornerShape(10.dp))
                                    .background(Color(0xFFFFEBEE))
                                    .border(1.dp, Color(0xFFEF5350), RoundedCornerShape(10.dp))
                                    .padding(10.dp),
                                verticalAlignment = Alignment.CenterVertically,
                                horizontalArrangement = Arrangement.spacedBy(8.dp)
                            ) {
                                Icon(Icons.Filled.Error, null, tint = Color.Red, modifier = Modifier.size(20.dp))
                                Text(
                                    text = "⚠️ Administrative reservation error: Name or username cannot contain the word 'admin'. Please modify.",
                                    fontSize = 11.sp,
                                    color = Color.Red,
                                    fontWeight = FontWeight.Bold
                                )
                            }
                        }
                    }

                    item {
                        OutlinedTextField(
                            value = fullName,
                            onValueChange = { fullName = it },
                            label = { Text("Full Name") },
                            leadingIcon = { Icon(Icons.Filled.AccountCircle, "Name") },
                            singleLine = true,
                            modifier = Modifier.fillMaxWidth(),
                            shape = RoundedCornerShape(12.dp)
                        )
                    }

                    item {
                        OutlinedTextField(
                            value = email,
                            onValueChange = { email = it },
                            label = { Text("Email Address") },
                            leadingIcon = { Icon(Icons.Filled.Email, "Email") },
                            singleLine = true,
                            modifier = Modifier.fillMaxWidth(),
                            shape = RoundedCornerShape(12.dp)
                        )
                    }

                    item {
                        Column(modifier = Modifier.fillMaxWidth(), verticalArrangement = Arrangement.spacedBy(4.dp)) {
                            OutlinedTextField(
                                value = phoneNumber,
                                onValueChange = { input ->
                                    val cleaned = input.filter { it.isDigit() }
                                    if (cleaned.length <= 11) {
                                        phoneNumber = cleaned
                                    }
                                },
                                label = { Text("Pakistan Phone Number") },
                                leadingIcon = { Icon(Icons.Filled.Phone, "Phone Number") },
                                singleLine = true,
                                keyboardOptions = KeyboardOptions(keyboardType = KeyboardType.Phone),
                                modifier = Modifier.fillMaxWidth(),
                                shape = RoundedCornerShape(12.dp)
                            )
                            
                            // Live indicators of telephone correctness
                            if (phoneNumber.isNotEmpty()) {
                                Row(
                                    verticalAlignment = Alignment.CenterVertically,
                                    modifier = Modifier.padding(start = 4.dp)
                                ) {
                                    Icon(
                                        imageVector = if (isPhoneValid) Icons.Filled.CheckCircle else Icons.Filled.Error,
                                        contentDescription = null,
                                        tint = if (isPhoneValid) Color(0xFF2E7D32) else Color(0xFFD32F2F),
                                        modifier = Modifier.size(14.dp)
                                    )
                                    Spacer(modifier = Modifier.width(4.dp))
                                    Text(
                                        text = if (isPhoneValid) "Valid Pakistan Phone Number!" else "Must be 11 digits starting with \"03\"",
                                        fontSize = 11.sp,
                                        fontWeight = FontWeight.Medium,
                                        color = if (isPhoneValid) Color(0xFF2E7D32) else Color(0xFFD32F2F)
                                    )
                                }
                            }
                        }
                    }

                    item {
                        Column(
                            modifier = Modifier
                                .fillMaxWidth()
                                .padding(vertical = 4.dp),
                            verticalArrangement = Arrangement.spacedBy(8.dp),
                            horizontalAlignment = Alignment.CenterHorizontally
                        ) {
                            Box(
                                modifier = Modifier
                                    .size(80.dp)
                                    .clip(CircleShape)
                                    .background(MaterialTheme.colorScheme.primaryContainer),
                                contentAlignment = Alignment.Center
                            ) {
                                if (isUploadingImage) {
                                    CircularProgressIndicator(
                                        color = MaterialTheme.colorScheme.primary,
                                        modifier = Modifier.size(32.dp)
                                    )
                                } else if (profileImageUri.isNotEmpty()) {
                                    androidx.compose.foundation.Image(
                                        painter = rememberSupabaseImagePainter(model = profileImageUri),
                                        contentDescription = "Selected profile picture",
                                        modifier = Modifier.fillMaxSize(),
                                        contentScale = androidx.compose.ui.layout.ContentScale.Crop
                                    )
                                } else {
                                    Icon(
                                        imageVector = Icons.Filled.Person,
                                        contentDescription = "No profile image selected",
                                        tint = MaterialTheme.colorScheme.onPrimaryContainer,
                                        modifier = Modifier.size(40.dp)
                                    )
                                }
                            }
                            
                            OutlinedButton(
                                onClick = { imagePickerLauncher.launch("image/*") },
                                modifier = Modifier.fillMaxWidth(),
                                shape = RoundedCornerShape(12.dp)
                            ) {
                                Icon(Icons.Filled.Image, contentDescription = "Pick Image")
                                Spacer(modifier = Modifier.width(8.dp))
                                Text(
                                    if (profileImageUri.isEmpty()) "Select Custom Profile Picture (Gallery)"
                                    else "Change Custom Image"
                                )
                            }
                        }
                    }

                    item {
                        Column(modifier = Modifier.fillMaxWidth(), verticalArrangement = Arrangement.spacedBy(4.dp)) {
                            OutlinedTextField(
                                value = username,
                                onValueChange = { username = it },
                                label = { Text("Choose Username") },
                                leadingIcon = { Icon(Icons.Filled.Person, "Username") },
                                singleLine = true,
                                modifier = Modifier.fillMaxWidth(),
                                shape = RoundedCornerShape(12.dp)
                            )

                            // REAL TIME USERNAME TAKEN ENGINE WITH HIGHEST ACCURACY SUGGESTIONS
                            if (username.isNotEmpty()) {
                                if (isUsernameTaken) {
                                    Column(
                                        modifier = Modifier
                                            .fillMaxWidth()
                                            .padding(top = 4.dp, start = 4.dp),
                                        verticalArrangement = Arrangement.spacedBy(4.dp)
                                    ) {
                                        Row(verticalAlignment = Alignment.CenterVertically) {
                                            Icon(Icons.Filled.Error, null, tint = Color.Red, modifier = Modifier.size(14.dp))
                                            Spacer(modifier = Modifier.width(4.dp))
                                            Text(
                                                text = "Username '$username' is already taken!",
                                                color = Color.Red,
                                                fontSize = 11.sp,
                                                fontWeight = FontWeight.Bold
                                            )
                                        }
                                        
                                        if (suggestedUsernames.isNotEmpty()) {
                                            Text(
                                                text = "💡 Tap a suggestion built for you:",
                                                fontSize = 11.sp,
                                                color = MaterialTheme.colorScheme.primary,
                                                fontWeight = FontWeight.SemiBold
                                            )
                                            Row(
                                                horizontalArrangement = Arrangement.spacedBy(6.dp),
                                                modifier = Modifier.fillMaxWidth()
                                            ) {
                                                suggestedUsernames.take(3).forEach { suggest ->
                                                    SuggestionChip(
                                                        onClick = { username = suggest },
                                                        label = { Text(suggest, fontSize = 11.sp, fontWeight = FontWeight.Bold) },
                                                        shape = RoundedCornerShape(8.dp)
                                                    )
                                                }
                                            }
                                        }
                                    }
                                } else {
                                    Row(
                                        verticalAlignment = Alignment.CenterVertically,
                                        modifier = Modifier.padding(top = 4.dp, start = 4.dp)
                                    ) {
                                        Icon(Icons.Filled.CheckCircle, null, tint = Color(0xFF2E7D32), modifier = Modifier.size(14.dp))
                                        Spacer(modifier = Modifier.width(4.dp))
                                        Text(
                                            text = "Username '$username' is available!",
                                            color = Color(0xFF2E7D32),
                                            fontSize = 11.sp,
                                            fontWeight = FontWeight.Medium
                                        )
                                    }
                                }
                            }
                        }
                    }

                    item {
                        Column(modifier = Modifier.fillMaxWidth(), verticalArrangement = Arrangement.spacedBy(4.dp)) {
                            OutlinedTextField(
                                value = password,
                                onValueChange = { password = it },
                                label = { Text("Choose Password (6+ Letters)") },
                                leadingIcon = { Icon(Icons.Filled.Lock, "Password") },
                                trailingIcon = {
                                    IconButton(onClick = { passwordVisible = !passwordVisible }) {
                                        Icon(
                                            imageVector = if (passwordVisible) Icons.Filled.Visibility else Icons.Filled.VisibilityOff,
                                            contentDescription = null
                                        )
                                    }
                                },
                                singleLine = true,
                                visualTransformation = if (passwordVisible) androidx.compose.ui.text.input.VisualTransformation.None else PasswordVisualTransformation(),
                                modifier = Modifier.fillMaxWidth(),
                                shape = RoundedCornerShape(12.dp)
                            )
                            
                            if (password.isNotEmpty() && !isPasswordValid) {
                                Row(
                                    verticalAlignment = Alignment.CenterVertically,
                                    modifier = Modifier.padding(start = 4.dp)
                                ) {
                                    Icon(Icons.Filled.Error, null, tint = Color(0xFFD32F2F), modifier = Modifier.size(14.dp))
                                    Spacer(modifier = Modifier.width(4.dp))
                                    Text(
                                        text = "Must be at least 6 letters long.",
                                        fontSize = 11.sp,
                                        color = Color(0xFFD32F2F)
                                    )
                                }
                            }
                        }
                    }

                    item {
                        OutlinedTextField(
                            value = confirmPassword,
                            onValueChange = { confirmPassword = it },
                            label = { Text("Confirm Password") },
                            leadingIcon = { Icon(Icons.Filled.Lock, "Confirm Password") },
                            trailingIcon = {
                                IconButton(onClick = { confirmPasswordVisible = !confirmPasswordVisible }) {
                                    Icon(
                                        imageVector = if (confirmPasswordVisible) Icons.Filled.Visibility else Icons.Filled.VisibilityOff,
                                        contentDescription = null
                                    )
                                }
                            },
                            singleLine = true,
                            visualTransformation = if (confirmPasswordVisible) androidx.compose.ui.text.input.VisualTransformation.None else PasswordVisualTransformation(),
                            modifier = Modifier.fillMaxWidth(),
                            shape = RoundedCornerShape(12.dp)
                        )
                    }

                    item {
                        NayaRastaDropdown(
                            label = "Student Type",
                            options = listOf("Fresher", "Repeater"),
                            selectedOption = studentType,
                            onOptionSelected = { studentType = it }
                        )
                    }

                    item {
                        NayaRastaDropdown(
                            label = "Grade Level / Class",
                            options = listOf(
                                "Pre-Medical / FSc Part 1",
                                "Pre-Medical / FSc Part 2",
                                "A-Levels",
                                "Other"
                            ),
                            selectedOption = gradeLevel,
                            onOptionSelected = { gradeLevel = it }
                        )
                    }

                    item {
                        NayaRastaDropdown(
                            label = "Study Goal / Target Exam",
                            options = listOf(
                                "MDCAT",
                                "NUMS",
                                "AKU",
                                "Board Exams",
                                "Other"
                            ),
                            selectedOption = studyGoal,
                            onOptionSelected = { studyGoal = it }
                        )
                    }

                    item {
                        Button(
                            onClick = {
                                if (password.isEmpty() || username.isEmpty() || fullName.isEmpty() || email.isEmpty() || phoneNumber.isEmpty()) {
                                    viewModel.feedbackMessage.value = "All profile fields including verified Email and Phone Number are required."
                                    return@Button
                                }
                                if (containsAdminWord) {
                                    viewModel.feedbackMessage.value = "Administrative usernames and names are restricted."
                                    return@Button
                                }
                                if (isUsernameTaken) {
                                    viewModel.feedbackMessage.value = "Username already exists. Please choose a recommended suggestion!"
                                    return@Button
                                }
                                if (!isPhoneValid) {
                                    viewModel.feedbackMessage.value = "Please enter a valid 11-digit Pakistan Phone Number starting with 03."
                                    return@Button
                                }
                                if (!isPasswordValid) {
                                    viewModel.feedbackMessage.value = "Password must be 6 or more characters."
                                    return@Button
                                }
                                if (password != confirmPassword) {
                                    viewModel.feedbackMessage.value = "Passwords do not match."
                                    return@Button
                                }
                                
                                viewModel.registerUser(
                                    usernameInput = username.trim(),
                                    passwordInput = password.trim(),
                                    fullName = fullName.trim(),
                                    email = email.trim(),
                                    phoneNumber = phoneNumber.trim(),
                                    studentType = studentType,
                                    gradeLevel = gradeLevel,
                                    studyGoal = studyGoal,
                                    profileImageUri = profileImageUri.ifEmpty { null }
                                ) { success ->
                                    if (success) {
                                        username = ""
                                        password = ""
                                        confirmPassword = ""
                                        fullName = ""
                                        email = ""
                                        phoneNumber = ""
                                        profileImageUri = ""
                                        isSocialVerified = false
                                        viewModel.navigateTo(Screen.Login)
                                    }
                                }
                            },
                            colors = ButtonDefaults.buttonColors(containerColor = MaterialTheme.colorScheme.primary),
                            modifier = Modifier
                                .fillMaxWidth()
                                .height(52.dp),
                            shape = RoundedCornerShape(12.dp)
                        ) {
                            Text("Register Profile", fontSize = 16.sp, fontWeight = FontWeight.Bold)
                        }
                    }

                item {
                    Row(
                        modifier = Modifier.fillMaxWidth(),
                        horizontalArrangement = Arrangement.Center,
                        verticalAlignment = Alignment.CenterVertically
                    ) {
                        Text("Already registered? ", fontSize = 13.sp)
                        Text(
                            text = "Login here",
                            fontSize = 13.sp,
                            fontWeight = FontWeight.Bold,
                            color = MaterialTheme.colorScheme.primary,
                            modifier = Modifier.clickable { viewModel.navigateTo(Screen.Login) }
                        )
                    }
                }
            }
        }
    }
}

// ==================== SCREEN 3: USER DASHBOARD ====================
private data class SubjectCardColorTheme(
    val backgroundColor: Color,
    val onBackgroundColor: Color,
    val subTextColor: Color,
    val accentBgColor: Color,
    val accentIconColor: Color
)

private fun getSubjectTheme(index: Int, isDark: Boolean): SubjectCardColorTheme {
    return if (isDark) {
        when (index % 4) {
            0 -> SubjectCardColorTheme(
                backgroundColor = Color(0xFF282A33),
                onBackgroundColor = Color(0xFFE2E2E9),
                subTextColor = Color(0xFFA1A5B0),
                accentBgColor = Color(0xFF1F2129),
                accentIconColor = Color(0xFFC1C6DD)
            )
            1 -> SubjectCardColorTheme(
                backgroundColor = Color(0xFF1D263B),
                onBackgroundColor = Color(0xFFD6E3FF),
                subTextColor = Color(0xFFADC6FF),
                accentBgColor = Color(0xFF151C2C),
                accentIconColor = Color(0xFFADC6FF)
            )
            2 -> SubjectCardColorTheme(
                backgroundColor = Color(0xFF2B1D3D),
                onBackgroundColor = Color(0xFFF2E0FF),
                subTextColor = Color(0xFFD9B9FF),
                accentBgColor = Color(0xFF20152D),
                accentIconColor = Color(0xFFD9B9FF)
            )
            else -> SubjectCardColorTheme(
                backgroundColor = Color(0xFF3B1D1A),
                onBackgroundColor = Color(0xFFFFDAD6),
                subTextColor = Color(0xFFFFB4AB),
                accentBgColor = Color(0xFF2C1513),
                accentIconColor = Color(0xFFFFB4AB)
            )
        }
    } else {
        when (index % 4) {
            0 -> SubjectCardColorTheme(
                backgroundColor = Color(0xFFE1E2EC),
                onBackgroundColor = Color(0xFF1B1B1F),
                subTextColor = Color(0xFF44474E),
                accentBgColor = Color(0xFFFFFFFF),
                accentIconColor = Color(0xFF595D6F)
            )
            1 -> SubjectCardColorTheme(
                backgroundColor = Color(0xFFD6E3FF),
                onBackgroundColor = Color(0xFF001D49),
                subTextColor = Color(0xFF004A8C),
                accentBgColor = Color(0xFFFFFFFF),
                accentIconColor = Color(0xFF005FB0)
            )
            2 -> SubjectCardColorTheme(
                backgroundColor = Color(0xFFF2E0FF),
                onBackgroundColor = Color(0xFF250059),
                subTextColor = Color(0xFF6F43C0),
                accentBgColor = Color(0xFFFFFFFF),
                accentIconColor = Color(0xFF6F43C0)
            )
            else -> SubjectCardColorTheme(
                backgroundColor = Color(0xFFFFDAD6),
                onBackgroundColor = Color(0xFF410002),
                subTextColor = Color(0xFF93000A),
                accentBgColor = Color(0xFFFFFFFF),
                accentIconColor = Color(0xFFBA1A1A)
            )
        }
    }
}

@Composable
fun QuickActionTile(
    icon: androidx.compose.ui.graphics.vector.ImageVector,
    title: String,
    subtitle: String,
    color: Color,
    modifier: Modifier = Modifier,
    activeStyle: DesignStyle = DesignStyle.CLASSIC_CLEAN,
    onClick: () -> Unit
) {
    val isDark = isSystemInDarkTheme()
    val configuration = androidx.compose.ui.platform.LocalConfiguration.current
    val isCompact = configuration.screenWidthDp < 360
    val tileHeight = if (isCompact) 94.dp else 108.dp
    val iconBoxSize = if (isCompact) 32.dp else 38.dp
    val iconSize = if (isCompact) 18.dp else 20.dp
    val paddingSize = if (isCompact) 4.dp else 8.dp

    PremiumStyleContainer(
        style = activeStyle,
        onClick = onClick,
        modifier = modifier.height(tileHeight).testTag("quick_action_${title.lowercase().replace(" ", "_").replace(".", "")}"),
        containerColor = if (isDark) Color(0xFF1E1E2E) else Color.White
    ) {
        Column(
            modifier = Modifier
                .fillMaxSize()
                .padding(paddingSize),
            horizontalAlignment = Alignment.CenterHorizontally,
            verticalArrangement = Arrangement.Center
        ) {
            Box(
                modifier = Modifier
                    .size(iconBoxSize)
                    .clip(
                        when (activeStyle) {
                            DesignStyle.CLASSIC_CLEAN -> RoundedCornerShape(10.dp)
                            DesignStyle.GRADIENT_GLASS -> RoundedCornerShape(14.dp)
                            DesignStyle.NEO_BRUTALIST -> RoundedCornerShape(4.dp)
                        }
                    )
                    .background(color.copy(alpha = 0.15f)),
                contentAlignment = Alignment.Center
            ) {
                Icon(
                    imageVector = icon,
                    contentDescription = title,
                    tint = color,
                    modifier = Modifier.size(iconSize)
                )
            }
            Spacer(modifier = Modifier.height(if (isCompact) 4.dp else 6.dp))
            Text(
                text = title,
                fontWeight = if (activeStyle == DesignStyle.NEO_BRUTALIST) FontWeight.Black else FontWeight.Bold,
                fontSize = if (isCompact) 10.sp else 11.5.sp,
                color = if (isDark) Color.White else Color(0xFF1E1E2E),
                maxLines = 1,
                textAlign = TextAlign.Center,
                overflow = androidx.compose.ui.text.style.TextOverflow.Ellipsis
            )
            Spacer(modifier = Modifier.height(if (isCompact) 1.dp else 2.dp))
            Text(
                text = subtitle,
                fontSize = if (isCompact) 8.sp else 9.sp,
                color = if (isDark) Color.White.copy(alpha = 0.6f) else Color(0xFF757575),
                maxLines = 1,
                textAlign = TextAlign.Center,
                overflow = androidx.compose.ui.text.style.TextOverflow.Ellipsis
            )
        }
    }
}

@Composable
fun UserDashboardScreen(viewModel: MainViewModel) {
    val loggedInUser by viewModel.loggedInUser.collectAsState()
    val activeStyle by viewModel.activeDesignStyle.collectAsState()
    val subjects by viewModel.allSubjects.collectAsState()
    val topics by viewModel.allTopics.collectAsState()
    val results by viewModel.userTestResults.collectAsState()
    val totalMcqs by viewModel.totalMcqCount.collectAsState()

    var selectedSubjectFilter by remember { mutableStateOf<Subject?>(null) }
    val isDark = isSystemInDarkTheme()

    val currentUserId = loggedInUser?.id
    androidx.compose.runtime.LaunchedEffect(currentUserId) {
        if (currentUserId != null && loggedInUser?.role == "USER") {
            viewModel.recordUserActivity(currentUserId)
        }
    }

    // --- REALTIME ANNOUNCEMENT OVERLAY SYSTEM ---
    val announcements by viewModel.allAnnouncements.collectAsState()
    val context = androidx.compose.ui.platform.LocalContext.current
    val prefs = remember(context) { context.getSharedPreferences("NayaRastaAnnouncements", android.content.Context.MODE_PRIVATE) }
    var activeAnnouncement by remember { mutableStateOf<Announcement?>(null) }
    var timeLeft by remember { mutableStateOf(5) }
    var fullscreenAnnImageUrl by remember { mutableStateOf<String?>(null) }

    androidx.compose.runtime.LaunchedEffect(announcements, loggedInUser) {
        val user = loggedInUser ?: return@LaunchedEffect
        val unseen = announcements.firstOrNull { announcement ->
            val targets = announcement.targetUserIds.split(",")
            val isTargeted = announcement.targetUserIds == "all" || targets.contains(user.id.toString())
            val hasSeen = prefs.getBoolean("seen_${announcement.id}", false)
            isTargeted && !hasSeen
        }
        if (unseen != null) {
            activeAnnouncement = unseen
            timeLeft = unseen.displayDuration
        } else {
            activeAnnouncement = null
        }
    }

    androidx.compose.runtime.LaunchedEffect(activeAnnouncement) {
        val ann = activeAnnouncement ?: return@LaunchedEffect
        timeLeft = ann.displayDuration
        while (timeLeft > 0) {
            kotlinx.coroutines.delay(1000)
            timeLeft--
        }
        // When timer ends, mark as seen and dismiss automatically!
        prefs.edit().putBoolean("seen_${ann.id}", true).apply()
        
        val user = loggedInUser ?: return@LaunchedEffect
        val unseen = announcements.firstOrNull { a ->
            val targets = a.targetUserIds.split(",")
            val isTargeted = a.targetUserIds == "all" || targets.contains(user.id.toString())
            val hasSeen = prefs.getBoolean("seen_${a.id}", false)
            isTargeted && !hasSeen
        }
        activeAnnouncement = unseen
    }

    if (activeAnnouncement != null) {
        val ann = activeAnnouncement!!
        androidx.compose.ui.window.Dialog(
            onDismissRequest = {
                if (ann.isCloseable) {
                    prefs.edit().putBoolean("seen_${ann.id}", true).apply()
                    activeAnnouncement = null
                }
            },
            properties = androidx.compose.ui.window.DialogProperties(
                dismissOnBackPress = ann.isCloseable,
                dismissOnClickOutside = ann.isCloseable,
                usePlatformDefaultWidth = false
            )
        ) {
            Card(
                shape = RoundedCornerShape(28.dp),
                colors = CardDefaults.cardColors(containerColor = if (isDark) Color(0xFF1E1E2E) else Color.White),
                border = BorderStroke(2.dp, MaterialTheme.colorScheme.primary),
                elevation = CardDefaults.cardElevation(defaultElevation = 16.dp),
                modifier = Modifier
                    .fillMaxWidth(0.92f)
                    .padding(8.dp)
            ) {
                Column(
                    modifier = Modifier.padding(24.dp),
                    horizontalAlignment = Alignment.CenterHorizontally,
                    verticalArrangement = Arrangement.spacedBy(16.dp)
                ) {
                    // Header Status
                    Row(
                        modifier = Modifier.fillMaxWidth(),
                        horizontalArrangement = Arrangement.Center,
                        verticalAlignment = Alignment.CenterVertically
                    ) {
                        Box(
                            modifier = Modifier
                                .size(50.dp)
                                .clip(CircleShape)
                                .background(MaterialTheme.colorScheme.primary.copy(alpha = 0.15f)),
                            contentAlignment = Alignment.Center
                        ) {
                            Text("📢", fontSize = 24.sp)
                        }
                        Spacer(modifier = Modifier.width(12.dp))
                        Text(
                            text = "OFFICIAL ANNOUNCEMENT",
                            fontWeight = FontWeight.Black,
                            letterSpacing = 1.sp,
                            fontSize = 16.sp,
                            color = MaterialTheme.colorScheme.primary
                        )
                    }

                    // Divider
                    HorizontalDivider(color = MaterialTheme.colorScheme.outlineVariant)

                    // Image attachment loading with Coil painter (Bigger, clickable to open full screen zoom mode!)
                    if (ann.imageUrl.isNotEmpty()) {
                        Column(
                            modifier = Modifier.fillMaxWidth(),
                            horizontalAlignment = Alignment.CenterHorizontally,
                            verticalArrangement = Arrangement.spacedBy(6.dp)
                        ) {
                            Box(
                                modifier = Modifier
                                    .fillMaxWidth()
                                    .height(240.dp)
                                    .clip(RoundedCornerShape(16.dp))
                                    .border(1.dp, MaterialTheme.colorScheme.primary.copy(alpha = 0.3f), RoundedCornerShape(16.dp))
                                    .background(Color.Black.copy(alpha = 0.05f))
                                    .pointerInput(Unit) {
                                        // Detect click OR zoom-related scale gesture to open fullscreen!
                                        detectTapGestures(
                                            onTap = {
                                                fullscreenAnnImageUrl = ann.imageUrl
                                            }
                                        )
                                    }
                                    .pointerInput(Unit) {
                                        detectTransformGestures { _, _, _, _ ->
                                            fullscreenAnnImageUrl = ann.imageUrl
                                        }
                                    },
                                contentAlignment = Alignment.Center
                            ) {
                                androidx.compose.foundation.Image(
                                    painter = coil.compose.rememberAsyncImagePainter(model = ann.imageUrl),
                                    contentDescription = "Announcement Image",
                                    contentScale = androidx.compose.ui.layout.ContentScale.Crop,
                                    modifier = Modifier.fillMaxSize()
                                )

                                // Click helper badge overlay
                                Box(
                                    modifier = Modifier
                                        .align(Alignment.BottomEnd)
                                        .padding(12.dp)
                                        .clip(RoundedCornerShape(12.dp))
                                        .background(Color.Black.copy(alpha = 0.7f))
                                        .padding(horizontal = 10.dp, vertical = 6.dp)
                                ) {
                                    Row(
                                        verticalAlignment = Alignment.CenterVertically,
                                        horizontalArrangement = Arrangement.spacedBy(4.dp)
                                    ) {
                                        Icon(
                                            imageVector = Icons.Default.Search,
                                            contentDescription = "Zoom Icon",
                                            tint = Color.White,
                                            modifier = Modifier.size(14.dp)
                                        )
                                        Text(
                                            text = "Click to Zoom / Pan",
                                            color = Color.White,
                                            fontSize = 11.sp,
                                            fontWeight = FontWeight.Bold
                                        )
                                    }
                                }
                            }
                        }
                    }

                    // Announcement Message (bigger, beautiful text!)
                    Text(
                        text = ann.message,
                        fontSize = 16.sp,
                        textAlign = TextAlign.Center,
                        lineHeight = 24.sp,
                        fontWeight = FontWeight.SemiBold,
                        color = if (isDark) Color.White else Color(0xFF1E1E2E),
                        modifier = Modifier
                            .fillMaxWidth()
                            .padding(horizontal = 8.dp)
                    )

                    Spacer(modifier = Modifier.height(2.dp))

                    // Timer details
                    Row(
                        horizontalArrangement = Arrangement.spacedBy(8.dp),
                        verticalAlignment = Alignment.CenterVertically,
                        modifier = Modifier
                            .clip(RoundedCornerShape(30.dp))
                            .background(MaterialTheme.colorScheme.secondaryContainer)
                            .padding(horizontal = 16.dp, vertical = 8.dp)
                    ) {
                        CircularProgressIndicator(
                            progress = if (ann.displayDuration > 0) timeLeft.toFloat() / ann.displayDuration.toFloat() else 0f,
                            modifier = Modifier.size(18.dp),
                            color = MaterialTheme.colorScheme.primary,
                            strokeWidth = 2.5.dp
                        )
                        Text(
                            text = if (timeLeft > 0) "Closing in ${timeLeft}s" else "Completed",
                            fontSize = 12.sp,
                            fontWeight = FontWeight.Bold,
                            color = MaterialTheme.colorScheme.onSecondaryContainer
                        )
                    }

                    // Button controls
                    if (ann.isCloseable) {
                        Button(
                            onClick = {
                                prefs.edit().putBoolean("seen_${ann.id}", true).apply()
                                activeAnnouncement = null
                            },
                            shape = RoundedCornerShape(14.dp),
