        // --- STILL THINK YOU HAVE TIME? MDCAT COUNTDOWN ---
        item {
            val mdcatCountdownStateVal by viewModel.mdcatCountdownState.collectAsState()
            var sysTime by remember { mutableStateOf(System.currentTimeMillis()) }

            androidx.compose.runtime.LaunchedEffect(mdcatCountdownStateVal) {
                while (true) {
                    sysTime = System.currentTimeMillis()
                    kotlinx.coroutines.delay(1000)
                }
            }

            fun parseIsoDate(isoString: String): Long {
                return try {
                    if (android.os.Build.VERSION.SDK_INT >= android.os.Build.VERSION_CODES.O) {
                        java.time.Instant.parse(isoString).toEpochMilli()
                    } else {
                        val sdf = java.text.SimpleDateFormat("yyyy-MM-dd'T'HH:mm:ss", java.util.Locale.US)
                        sdf.timeZone = java.util.TimeZone.getTimeZone("UTC")
                        val clean = isoString.replace("Z", "")
                        sdf.parse(clean)?.time ?: 0L
                    }
                } catch (e: Exception) {
                    try {
                        val sdf = java.text.SimpleDateFormat("yyyy-MM-dd HH:mm:ss", java.util.Locale.US)
                        sdf.parse(isoString)?.time ?: 0L
                    } catch (e2: Exception) {
                        0L
                    }
                }
            }

            val targetMs = if (mdcatCountdownStateVal != null) parseIsoDate(mdcatCountdownStateVal!!.testDate) else 0L
            val diffMs = targetMs - sysTime

            PremiumStyleContainer(
