                                            contentAlignment = Alignment.Center
                                        ) {
                                            Column(horizontalAlignment = Alignment.CenterHorizontally) {
                                                Text(
                                                    text = "LVL",
                                                    color = MaterialTheme.colorScheme.onPrimaryContainer,
                                                    fontWeight = FontWeight.Black,
                                                    fontSize = 9.sp
                                                )
                                                Text(
                                                    text = "${levelInfo.levelNumber}",
                                                    color = MaterialTheme.colorScheme.onPrimaryContainer,
                                                    fontWeight = FontWeight.Black,
                                                    fontSize = 18.sp
                                                )
                                            }
                                        }
                                        Spacer(modifier = Modifier.height(4.dp))
                                        Text(
                                            text = "${levelInfo.currentXp}/${levelInfo.targetXp} XP",
                                            fontSize = 9.sp,
                                            color = MaterialTheme.colorScheme.onPrimaryContainer.copy(alpha = 0.8f),
                                            fontWeight = FontWeight.Black
                                        )
                                    }
                                }
                            }
                        }
                    }
                }
            }
        }

        // TODAY SITUATION REPORT (TSR)
        item {
            TodaySituationReportComponent(histories = results, isDark = isDark)
        }

        // QUICK ACTIONS
        item {
            Column(verticalArrangement = Arrangement.spacedBy(10.dp)) {
                Text(
                    text = "QUICK ACTIONS",
                    fontWeight = if (activeStyle == DesignStyle.NEO_BRUTALIST) FontWeight.Black else FontWeight.Bold,
                    fontSize = 13.sp,
                    letterSpacing = 1.sp,
                    color = if (isDark) MaterialTheme.colorScheme.onBackground.copy(alpha = 0.8f) else Color(0xFF44474E)
                )

                val quickActions = remember {
                    listOf(
                        Triple(Icons.Filled.PlayArrow, "Practice Quiz", "Instant Random Test" to Color(0xFF4CAF50)),
                        Triple(Icons.Filled.Add, "Contribute MCQ", "Submit & Earn Points" to Color(0xFFFF9800)),
                        Triple(Icons.Filled.Leaderboard, "Leaderboard", "Check Standings" to Color(0xFFE91E63)),
                        Triple(Icons.Filled.Analytics, "Progress Analytics", "Analyze Performance" to Color(0xFF2196F3)),
                        Triple(Icons.Filled.Forum, "Study Feed", "Social Discussion" to Color(0xFF9C27B0)),
                        Triple(Icons.Filled.Assignment, "Study Notes", "Self Study Materials" to Color(0xFF00BCD4)),
                        Triple(Icons.Filled.AutoAwesome, "Ask AI Assistant", "Instant Study Answers" to Color(0xFF005FB0)),
                        Triple(Icons.Filled.Redeem, "Get Rewards Program", "Claim free subscription & cash" to Color(0xFFE91E63)),
                        Triple(Icons.Filled.Flag, "Target Tracker", "Track Quizzes & MCQs" to Color(0xFFE53935)),
                        Triple(Icons.Filled.Search, "Search Students", "Find Peers & Profiles" to Color(0xFF00ACC1))
                    )
                }

                val chunkedActions = remember(quickActions, columns) { quickActions.chunked(columns) }
                chunkedActions.forEach { rowItems ->
                    Row(
                        modifier = Modifier.fillMaxWidth(),
                        horizontalArrangement = Arrangement.spacedBy(itemSpacing)
                    ) {
                        rowItems.forEach { itemAction ->
                            val (icon, title, details) = itemAction
                            val (subtitle, color) = details
                            QuickActionTile(
                                icon = icon,
                                title = title,
                                subtitle = subtitle,
                                color = color,
                                modifier = Modifier.weight(1f),
                                activeStyle = activeStyle,
                                onClick = {
                                    when (title) {
                                        "Practice Quiz" -> viewModel.requestStartQuiz(subjectId = null, topicId = null, count = 10, randomOrder = true)
                                        "Contribute MCQ" -> viewModel.navigateTo(Screen.UserAddMcq)
                                        "Leaderboard" -> viewModel.navigateTo(Screen.Leaderboard)
                                        "Progress Analytics" -> viewModel.navigateTo(Screen.UserProgressAnalytics)
                                        "Study Feed" -> viewModel.navigateTo(Screen.StudyFeed)
                                        "Study Notes" -> viewModel.navigateTo(Screen.UserNotes)
                                        "Ask AI Assistant" -> viewModel.navigateTo(Screen.AskAi)
                                        "Get Rewards Program" -> viewModel.navigateTo(Screen.GetReward)
                                        "Target Tracker" -> viewModel.navigateTo(Screen.TargetTracker)
                                        "Search Students" -> viewModel.navigateTo(Screen.UserSearch)
                                    }
                                }
                            )
                        }
                        if (rowItems.size < columns) {
                            repeat(columns - rowItems.size) {
                                Spacer(modifier = Modifier.weight(1f))
                            }
                        }
                    }
                }
            }
        }

        // MDCAT EXAM SPECIAL MODES
        item {
            var showBookSelectDialog by remember { mutableStateOf(false) }

            if (showBookSelectDialog) {
                AlertDialog(
                    onDismissRequest = { showBookSelectDialog = false },
                    title = { Text("Select Book for Exam", fontWeight = FontWeight.Bold) },
                    text = {
                        Column(verticalArrangement = Arrangement.spacedBy(8.dp)) {
                            Text("Choose a subject to generate a Full Book syllabus exam:", fontSize = 14.sp)
                            subjects.forEach { subj ->
                                Row(
                                    modifier = Modifier
                                        .fillMaxWidth()
                                        .clickable {
                                            showBookSelectDialog = false
                                            viewModel.navigateTo(Screen.UserQuizSetup(subj.id, null))
                                        }
                                        .padding(vertical = 12.dp, horizontal = 8.dp),
                                    verticalAlignment = Alignment.CenterVertically
                                ) {
                                    Icon(
                                        imageVector = mapIconNameToVector(subj.iconName),
                                        contentDescription = null,
                                        tint = MaterialTheme.colorScheme.primary,
                                        modifier = Modifier.size(20.dp)
                                    )
                                    Spacer(modifier = Modifier.width(12.dp))
                                    Text(subj.name, fontWeight = FontWeight.Medium, fontSize = 15.sp)
                                }
                            }
                        }
                    },
                    confirmButton = {
                        TextButton(onClick = { showBookSelectDialog = false }) {
                            Text("Cancel")
                        }
                    }
                )
            }

            Column(verticalArrangement = Arrangement.spacedBy(10.dp)) {
                Text(
                    text = "MDCAT EXAM MODES",
                    fontWeight = FontWeight.Bold,
                    fontSize = 13.sp,
                    letterSpacing = 1.sp,
                    color = if (isDark) MaterialTheme.colorScheme.onBackground.copy(alpha = 0.8f) else Color(0xFF44474E)
                )

                Row(
                    modifier = Modifier.fillMaxWidth(),
                    horizontalArrangement = Arrangement.spacedBy(10.dp)
                ) {
                    // PMDC FORMAT CARD
                    PremiumStyleContainer(
                        style = activeStyle,
                        onClick = {
                            viewModel.requestStartPmdcQuiz()
                        },
                        modifier = Modifier.weight(1.1f),
                        containerColor = if (isDark) Color(0xFF13233D) else Color(0xFFE3F2FD)
                    ) {
                        Column(
                            modifier = Modifier.padding(16.dp),
                            verticalArrangement = Arrangement.spacedBy(12.dp)
                        ) {
                            Box(
                                modifier = Modifier
                                    .size(40.dp)
                                    .clip(RoundedCornerShape(12.dp))
                                    .background(if (isDark) Color(0xFF1E88E5).copy(alpha = 0.2f) else Color(0xFFBBDEFB)),
                                contentAlignment = Alignment.Center
                            ) {
                                Icon(
                                    imageVector = Icons.Filled.Stars,
                                    contentDescription = null,
                                    tint = if (isDark) Color(0xFF90CAF9) else Color(0xFF0D47A1),
                                    modifier = Modifier.size(24.dp)
                                )
                            }

                            Column {
                                Text(
                                    text = "PMDC Format",
                                    fontWeight = if (activeStyle == DesignStyle.NEO_BRUTALIST) FontWeight.Black else FontWeight.Bold,
                                    fontSize = 15.sp,
                                    color = if (isDark) Color.White else Color(0xFF0D47A1)
                                )
                                Text(
                                    text = "Grand Mock (180 MCQs)",
                                    fontSize = 11.sp,
                                    color = if (isDark) Color.White.copy(alpha = 0.7f) else Color(0xFF1565C0)
                                )
                            }
                        }
                    }

                    // FULL BOOK EXAM CARD
                    PremiumStyleContainer(
                        style = activeStyle,
                        onClick = {
                            showBookSelectDialog = true
                        },
                        modifier = Modifier.weight(1f),
                        containerColor = if (isDark) Color(0xFF281C2C) else Color(0xFFF3E5F5)
                    ) {
                        Column(
                            modifier = Modifier.padding(16.dp),
                            verticalArrangement = Arrangement.spacedBy(12.dp)
                        ) {
                            Box(
                                modifier = Modifier
                                    .size(40.dp)
                                    .clip(RoundedCornerShape(12.dp))
                                    .background(if (isDark) Color(0xFFAB47BC).copy(alpha = 0.2f) else Color(0xFFE1BEE7)),
                                contentAlignment = Alignment.Center
                            ) {
                                Icon(
                                    imageVector = Icons.Filled.MenuBook,
                                    contentDescription = null,
                                    tint = if (isDark) Color(0xFFCE93D8) else Color(0xFF4A148C),
                                    modifier = Modifier.size(24.dp)
                                )
                            }

                            Column {
                                Text(
                                    text = "Full Book Exam",
                                    fontWeight = if (activeStyle == DesignStyle.NEO_BRUTALIST) FontWeight.Black else FontWeight.Bold,
                                    fontSize = 15.sp,
                                    color = if (isDark) Color.White else Color(0xFF4A148C)
                                )
                                Text(
                                    text = "Choose Book / Syllabus",
                                    fontSize = 11.sp,
                                    color = if (isDark) Color.White.copy(alpha = 0.7f) else Color(0xFF6A1B9A)
                                )
                            }
                        }
                    }
                }
            }
        }

        // MCQ Contribution Section
        item {
            PremiumStyleContainer(
                style = activeStyle,
                onClick = {
                    viewModel.navigateTo(Screen.UserAddMcq)
                },
                modifier = Modifier.fillMaxWidth(),
                containerColor = if (isDark) Color(0xFF132A1C) else Color(0xFFE8F5E9)
            ) {
                Row(
                    modifier = Modifier.padding(16.dp),
                    horizontalArrangement = Arrangement.spacedBy(16.dp),
                    verticalAlignment = Alignment.CenterVertically
                ) {
                    Box(
                        modifier = Modifier
                            .size(40.dp)
                            .clip(RoundedCornerShape(12.dp))
                            .background(if (isDark) Color(0xFF1B5E20).copy(alpha = 0.2f) else Color(0xFFC8E6C9)),
                        contentAlignment = Alignment.Center
                    ) {
                        Icon(
                            imageVector = Icons.Filled.Add,
                            contentDescription = "Add MCQ icon",
                            tint = if (isDark) Color(0xFF81C784) else Color(0xFF1B5E20),
                            modifier = Modifier.size(24.dp)
                        )
                    }

                    Column(modifier = Modifier.weight(1f)) {
                        Text(
                            text = "Add MCQs",
                            fontWeight = FontWeight.Bold,
                            fontSize = 15.sp,
                            color = if (isDark) Color.White else Color(0xFF1B5E20)
                        )
                        Text(
                            text = "Contribute your physics, chemistry or bio questions to our community catalog.",
                            fontSize = 11.sp,
                            color = if (isDark) Color.White.copy(alpha = 0.7f) else Color(0xFF2E7D32)
                        )
                        Row(
                            horizontalArrangement = Arrangement.spacedBy(8.dp),
                            modifier = Modifier.padding(top = 6.dp),
                            verticalAlignment = Alignment.CenterVertically
                        ) {
                            Card(
                                colors = CardDefaults.cardColors(
                                    containerColor = if (isDark) Color(0xFF1B5E20) else Color(0xFFC8E6C9)
                                ),
                                shape = RoundedCornerShape(4.dp)
                            ) {
                                Text(
                                    text = "Approved: ${loggedInUser?.approvedMcqs ?: 0}",
                                    fontSize = 10.sp,
                                    fontWeight = FontWeight.Bold,
                                    color = if (isDark) Color.White else Color(0xFF1B5E20),
                                    modifier = Modifier.padding(horizontal = 6.dp, vertical = 2.dp)
                                )
                            }
                            Card(
                                colors = CardDefaults.cardColors(
                                    containerColor = if (isDark) Color(0xFFC62828).copy(alpha = 0.2f) else Color(0xFFFFEBEE)
                                ),
                                shape = RoundedCornerShape(4.dp)
                            ) {
                                Text(
                                    text = "Rejected: ${loggedInUser?.rejectedMcqs ?: 0}",
                                    fontSize = 10.sp,
                                    fontWeight = FontWeight.Bold,
                                    color = if (isDark) Color(0xFFFF8A80) else Color(0xFFC62828),
                                    modifier = Modifier.padding(horizontal = 6.dp, vertical = 2.dp)
                                )
                            }
                        }
                    }
                }
            }
        }

        // Subject Master Section
        item {
            Row(
                modifier = Modifier.fillMaxWidth(),
                horizontalArrangement = Arrangement.SpaceBetween,
                verticalAlignment = Alignment.CenterVertically
            ) {
                Text(
                    text = "SUBJECT MASTER",
                    fontWeight = FontWeight.Bold,
                    fontSize = 13.sp,
                    letterSpacing = 1.sp,
                    color = if (isDark) MaterialTheme.colorScheme.onBackground.copy(alpha = 0.8f) else Color(0xFF44474E)
                )
                if (selectedSubjectFilter != null) {
                    Text(
                        text = "Clear Filter",
                        fontWeight = FontWeight.Bold,
                        fontSize = 12.sp,
                        color = Color(0xFF005FB0),
                        modifier = Modifier.clickable { selectedSubjectFilter = null }
                    )
                }
            }
        }

        // Custom High-Density Subject Grid Layout (Chunked by subjectColumns)
        item {
            Column(verticalArrangement = Arrangement.spacedBy(itemSpacing)) {
                val chunkedSubjects = subjects.chunked(subjectColumns)
                chunkedSubjects.forEach { rowSubjects ->
                    Row(
                        modifier = Modifier.fillMaxWidth(),
                        horizontalArrangement = Arrangement.spacedBy(itemSpacing)
                    ) {
                        rowSubjects.forEach { subj ->
                            val index = subjects.indexOf(subj)
                            val isSelected = selectedSubjectFilter?.id == subj.id
                            val theme = getSubjectTheme(index, isDark)
 
                            PremiumStyleContainer(
                                style = activeStyle,
                                onClick = {
                                    selectedSubjectFilter = if (isSelected) null else subj
                                },
                                modifier = Modifier.weight(1f),
                                containerColor = if (isSelected) {
                                    MaterialTheme.colorScheme.primaryContainer
                                } else {
                                    theme.backgroundColor
                                }
                            ) {
                                Column(
                                    modifier = Modifier.padding(cardPadding),
                                    verticalArrangement = Arrangement.spacedBy(if (isCompact) 8.dp else 12.dp)
                                ) {
                                    Box(
                                        modifier = Modifier
                                            .size(if (isCompact) 32.dp else 40.dp)
                                            .clip(
                                                when (activeStyle) {
                                                    DesignStyle.CLASSIC_CLEAN -> RoundedCornerShape(12.dp)
                                                    DesignStyle.GRADIENT_GLASS -> RoundedCornerShape(18.dp)
                                                    DesignStyle.NEO_BRUTALIST -> RoundedCornerShape(4.dp)
                                                }
                                            )
                                            .background(if (isSelected) MaterialTheme.colorScheme.surface else theme.accentBgColor),
                                        contentAlignment = Alignment.Center
                                    ) {
                                        Icon(
                                            imageVector = mapIconNameToVector(subj.iconName),
                                            contentDescription = null,
                                            tint = if (isSelected) MaterialTheme.colorScheme.primary else theme.accentIconColor,
                                            modifier = Modifier.size(if (isCompact) 18.dp else 24.dp)
                                        )
                                    }
 
                                    Column {
                                        Text(
                                            text = subj.name,
                                            fontWeight = if (activeStyle == DesignStyle.NEO_BRUTALIST) FontWeight.Black else FontWeight.Bold,
                                            fontSize = cardTitleFontSize,
                                            color = if (isSelected) MaterialTheme.colorScheme.onPrimaryContainer else theme.onBackgroundColor,
                                            maxLines = 1,
                                            overflow = TextOverflow.Ellipsis
                                        )
                                        val topicsForSubj = topics.filter { it.subjectId == subj.id }
                                        Text(
                                            text = "${topicsForSubj.size} Topics",
                                            fontSize = if (isCompact) 9.sp else 11.sp,
                                            color = if (isSelected) MaterialTheme.colorScheme.onPrimaryContainer.copy(alpha = 0.8f) else theme.subTextColor
                                        )
                                    }
                                }
                            }
                        }
                        if (rowSubjects.size < subjectColumns) {
                            repeat(subjectColumns - rowSubjects.size) {
                                Spacer(modifier = Modifier.weight(1f))
                            }
                        }
                    }
                }
            }
        }

        // Topics section header
        item {
            Text(
                text = if (selectedSubjectFilter != null) "TOPICS IN ${selectedSubjectFilter?.name?.uppercase()}" else "RECOMMENDED TOPICS",
                fontWeight = FontWeight.Bold,
                fontSize = 12.sp,
                letterSpacing = 1.sp,
                color = if (isDark) MaterialTheme.colorScheme.onBackground.copy(alpha = 0.8f) else Color(0xFF44474E)
            )
        }

        val filteredTopics = if (selectedSubjectFilter != null) {
            topics.filter { it.subjectId == selectedSubjectFilter?.id }
        } else {
            recommendedTopics
        }

        if (filteredTopics.isEmpty()) {
            item {
                Box(
                    modifier = Modifier
                        .fillMaxWidth()
                        .padding(24.dp),
                    contentAlignment = Alignment.Center
                ) {
                    Text("No topics matching this filter.", color = MaterialTheme.colorScheme.onSurfaceVariant, fontSize = 13.sp)
                }
            }
        } else {
            items(filteredTopics) { topic ->
                val parentSubject = subjects.firstOrNull { it.id == topic.subjectId }
                Card(
                    modifier = Modifier
                        .fillMaxWidth()
                        .clickable {
                            viewModel.navigateTo(Screen.UserQuizSetup(topic.subjectId, topic.id))
                        },
                    shape = RoundedCornerShape(16.dp),
                    border = BorderStroke(1.dp, if (isDark) Color(0xFF2C2D35) else Color(0xFFE1E2EC)),
                    colors = CardDefaults.cardColors(
                        containerColor = if (isDark) MaterialTheme.colorScheme.surfaceColorAtElevation(1.dp) else Color(0xFFF7F9FF)
                    )
                ) {
                    Row(
                        modifier = Modifier
                            .fillMaxWidth()
                            .padding(14.dp),
                        verticalAlignment = Alignment.CenterVertically
                    ) {
                        Box(
                            modifier = Modifier
                                .size(40.dp)
                                .clip(RoundedCornerShape(10.dp))
                                .background(MaterialTheme.colorScheme.primaryContainer),
                            contentAlignment = Alignment.Center
                        ) {
                            Icon(
                                imageVector = mapIconNameToVector(parentSubject?.iconName ?: ""),
                                contentDescription = null,
                                tint = MaterialTheme.colorScheme.primary,
                                modifier = Modifier.size(24.dp)
                            )
                        }

                        Spacer(modifier = Modifier.width(14.dp))

                        Column(modifier = Modifier.weight(1f)) {
                            Text(
                                text = topic.name,
                                fontWeight = FontWeight.Bold,
                                fontSize = 14.sp,
                                color = MaterialTheme.colorScheme.onSurface
                            )
                            Text(
                                text = topic.description,
                                fontSize = 11.sp,
                                color = MaterialTheme.colorScheme.onSurfaceVariant,
                                maxLines = 1,
                                overflow = TextOverflow.Ellipsis
                            )
                            if (parentSubject != null) {
                                Text(
                                    text = parentSubject.name.uppercase(),
                                    fontSize = 9.sp,
                                    fontWeight = FontWeight.Bold,
                                    letterSpacing = 0.5.sp,
                                    color = MaterialTheme.colorScheme.primary,
                                    modifier = Modifier.padding(top = 2.dp)
                                )
                            }
                        }

                        Icon(
                            imageVector = Icons.Filled.PlayArrow,
                            contentDescription = "Start Quiz",
                            tint = MaterialTheme.colorScheme.primary,
                            modifier = Modifier.size(22.dp)
                        )
                    }
                }
            }
        }

        // Recent / Last Test Performance indicator footer
        if (results.isNotEmpty()) {
            val lastResult = results.last()
            item {
                Spacer(modifier = Modifier.height(4.dp))
                Card(
                    modifier = Modifier.fillMaxWidth(),
                    shape = RoundedCornerShape(16.dp),
                    border = BorderStroke(1.dp, if (isDark) Color.Transparent else Color(0xFFDDE2EB)),
                    colors = CardDefaults.cardColors(
                        containerColor = if (isDark) MaterialTheme.colorScheme.surfaceVariant else Color(0xFFF1F3F8)
                    )
                ) {
                    Row(
                        modifier = Modifier
                            .fillMaxWidth()
                            .padding(14.dp),
                        verticalAlignment = Alignment.CenterVertically,
                        horizontalArrangement = Arrangement.spacedBy(12.dp)
                    ) {
                        Box(
                            modifier = Modifier
                                .size(32.dp)
                                .clip(RoundedCornerShape(8.dp))
                                .background(Color(0xFF005FB0)),
                            contentAlignment = Alignment.Center
                        ) {
                            Icon(
                                imageVector = Icons.Filled.Check,
                                contentDescription = null,
                                tint = Color.White,
                                modifier = Modifier.size(16.dp)
                            )
                        }

                        Column(modifier = Modifier.weight(1f)) {
                            Text(
                                text = "Last Test Performance",
                                fontSize = 12.sp,
                                fontWeight = FontWeight.Bold,
                                color = if (isDark) MaterialTheme.colorScheme.onSurface else Color(0xFF1B1B1F)
                            )
                            Text(
                                text = "${lastResult.metadataName}: ${lastResult.correctAnswers}/${lastResult.totalQuestions} Correct",
                                fontSize = 10.sp,
                                color = if (isDark) MaterialTheme.colorScheme.onSurfaceVariant else Color(0xFF595D6F)
                            )
                        }

                        Text(
                            text = "${lastResult.scorePercentage.toInt()}%",
                            fontSize = 13.sp,
                            fontWeight = FontWeight.Bold,
                            color = Color(0xFF005FB0)
                        )
                    }
                }
            }
        }
    }
}

fun Modifier.fillModifier(): Modifier = this.wrapContentWidth()

// ==================== SCREEN 4: USER QUIZ SETUP ====================
@Composable
fun UserQuizSetupScreen(viewModel: MainViewModel, subjectId: Int?, topicId: Int?) {
    val subjects by viewModel.allSubjects.collectAsState()
    val topics by viewModel.allTopics.collectAsState()
    val activeStyle by viewModel.activeDesignStyle.collectAsState()

    val targetSubject = subjects.firstOrNull { it.id == subjectId }
    val targetTopic = topics.firstOrNull { it.id == topicId }

    var questionCount by remember { mutableStateOf(10) }
    var selectedDifficulty by remember { mutableStateOf("ALL") }
    val randomizeOrder = true

    val limitOptions = listOf(5, 10, 15, 20, 30, 40)
    val difficultyOptions = listOf("ALL", "EASY", "MEDIUM", "HARD")

    Column(
        modifier = Modifier
            .fillMaxSize()
            .padding(16.dp),
        verticalArrangement = Arrangement.spacedBy(16.dp)
    ) {
        // App header with Back
        Row(
            verticalAlignment = Alignment.CenterVertically,
            modifier = Modifier.fillMaxWidth()
        ) {
            IconButton(onClick = { viewModel.navigateBack() }) {
                Icon(Icons.Filled.ArrowBack, contentDescription = "Go Back")
            }
            Text("Quiz Play Setup", fontWeight = FontWeight.Bold, fontSize = 20.sp)
        }

        PremiumStyleContainer(
            style = activeStyle,
            modifier = Modifier.fillMaxWidth(),
            containerColor = MaterialTheme.colorScheme.surfaceVariant.copy(alpha = 0.5f)
        ) {
            Column(
                modifier = Modifier.padding(16.dp),
                verticalArrangement = Arrangement.spacedBy(8.dp)
            ) {
                Text(
                    text = targetTopic?.name ?: (targetSubject?.let { "${it.name} • Full Book" } ?: "Mixed Custom Quiz"),
                    fontWeight = FontWeight.Bold,
                    fontSize = 18.sp,
                    color = MaterialTheme.colorScheme.primary
                )
                Text(
                    text = targetTopic?.description ?: (targetSubject?.let { "A comprehensive test pulling questions across all topics of ${it.name}." } ?: "Complete evaluation drawing questions from the whole database."),
                    fontSize = 13.sp,
                    color = MaterialTheme.colorScheme.onSurfaceVariant
                )
            }
        }

        Spacer(modifier = Modifier.height(4.dp))

        // MCQs Count Selection
        Text("Select Number of Questions (Max 40)", fontWeight = FontWeight.SemiBold, fontSize = 16.sp)

        Row(
            modifier = Modifier.fillMaxWidth(),
            horizontalArrangement = Arrangement.spacedBy(6.dp)
        ) {
            limitOptions.forEach { limit ->
                val active = questionCount == limit
                OutlinedButton(
                    onClick = { questionCount = limit },
                    modifier = Modifier.weight(1f),
                    colors = if (active) ButtonDefaults.outlinedButtonColors(containerColor = MaterialTheme.colorScheme.primaryContainer) else ButtonDefaults.outlinedButtonColors(),
                    border = BorderStroke(1.dp, if (active) MaterialTheme.colorScheme.primary else MaterialTheme.colorScheme.outline),
                    contentPadding = PaddingValues(horizontal = 2.dp, vertical = 6.dp)
                ) {
                    Text(
                        text = limit.toString(),
                        fontWeight = FontWeight.Bold,
                        fontSize = 13.sp,
                        maxLines = 1
                    )
                }
            }
        }

        // Custom counter adjuster
        Row(
            modifier = Modifier.fillMaxWidth(),
            horizontalArrangement = Arrangement.Center,
            verticalAlignment = Alignment.CenterVertically
        ) {
            IconButton(
                onClick = { if (questionCount > 1) questionCount-- },
                modifier = Modifier.background(MaterialTheme.colorScheme.surfaceVariant, shape = RoundedCornerShape(8.dp))
            ) {
                Icon(Icons.Filled.Remove, contentDescription = "Decrease MCQs Count", tint = MaterialTheme.colorScheme.primary)
            }
            Text(
                text = "$questionCount MCQs",
                fontWeight = FontWeight.Bold,
                fontSize = 16.sp,
                modifier = Modifier.padding(horizontal = 24.dp)
            )
            IconButton(
                onClick = { if (questionCount < 40) questionCount++ },
                modifier = Modifier.background(MaterialTheme.colorScheme.surfaceVariant, shape = RoundedCornerShape(8.dp))
            ) {
                Icon(Icons.Filled.Add, contentDescription = "Increase MCQs Count", tint = MaterialTheme.colorScheme.primary)
            }
        }

        Spacer(modifier = Modifier.height(4.dp))

        // Difficulty Selection
        Text("Select MCQ Difficulty Level", fontWeight = FontWeight.SemiBold, fontSize = 16.sp)

        Row(
            modifier = Modifier.fillMaxWidth(),
            horizontalArrangement = Arrangement.spacedBy(6.dp)
        ) {
            difficultyOptions.forEach { diff ->
                val active = selectedDifficulty == diff
                val displayName = when (diff) {
                    "ALL" -> "All"
                    "EASY" -> "Easy"
                    "MEDIUM" -> "Medium"
                    "HARD" -> "Hard"
                    else -> diff
                }
                OutlinedButton(
                    onClick = { selectedDifficulty = diff },
                    modifier = Modifier.weight(1f),
                    colors = if (active) ButtonDefaults.outlinedButtonColors(containerColor = MaterialTheme.colorScheme.secondaryContainer) else ButtonDefaults.outlinedButtonColors(),
                    border = BorderStroke(1.dp, if (active) MaterialTheme.colorScheme.secondary else MaterialTheme.colorScheme.outline),
                    contentPadding = PaddingValues(horizontal = 2.dp, vertical = 6.dp)
                ) {
                    Text(
                        text = displayName,
                        fontWeight = FontWeight.Bold,
                        fontSize = 13.sp,
                        maxLines = 1
                    )
                }
            }
        }

        Spacer(modifier = Modifier.weight(1f))

        Button(
            onClick = {
                viewModel.requestStartQuiz(subjectId, topicId, questionCount, randomizeOrder, selectedDifficulty)
            },
            modifier = Modifier
                .fillMaxWidth()
                .height(52.dp),
            shape = RoundedCornerShape(16.dp)
        ) {
            Text("Begin Active Quiz Session", fontSize = 16.sp, fontWeight = FontWeight.Bold)
        }
    }
}

// ==================== SCREEN 5: USER QUIZ PLAY ====================
@Composable
fun UserQuizPlayScreen(viewModel: MainViewModel, subjectId: Int?, topicId: Int?, enableTimer: Boolean = false) {
    val questions by viewModel.quizQuestions.collectAsState()
    val currentIndex by viewModel.quizCurrentIndex.collectAsState()
    val userAnswers by viewModel.quizSelectedAnswers.collectAsState()
    val activeStyle by viewModel.activeDesignStyle.collectAsState()

    var showSubmitConfirmation by remember { mutableStateOf(false) }
    var showUnsolvedSubmitDialog by remember { mutableStateOf(false) }

    if (questions.isEmpty()) {
        Box(modifier = Modifier.fillMaxSize(), contentAlignment = Alignment.Center) {
            CircularProgressIndicator()
        }
        return
    }

    var remainingSeconds by remember(questions.size, enableTimer) {
        mutableStateOf(questions.size * 60)
    }

    if (enableTimer && questions.isNotEmpty()) {
        LaunchedEffect(questions.size) {
            while (remainingSeconds > 0) {
                kotlinx.coroutines.delay(1000L)
                remainingSeconds -= 1
            }
            if (remainingSeconds <= 0) {
                viewModel.submitQuiz()
            }
        }
    }

    val formattedTime = remember(remainingSeconds) {
        val minutes = remainingSeconds / 60
        val seconds = remainingSeconds % 60
        String.format("%02d:%02d", minutes, seconds)
    }

    val currentQuestion = questions[currentIndex]
    val selectedOption = userAnswers[currentQuestion.id]
    val unsolvedCount = questions.count { !userAnswers.containsKey(it.id) || userAnswers[it.id].isNullOrEmpty() }

    Column(
        modifier = Modifier
            .fillMaxSize()
            .padding(16.dp),
        verticalArrangement = Arrangement.spacedBy(16.dp)
    ) {
        // Navigation Header
        Row(
            modifier = Modifier.fillMaxWidth(),
            horizontalArrangement = Arrangement.SpaceBetween,
            verticalAlignment = Alignment.CenterVertically
        ) {
            Row(verticalAlignment = Alignment.CenterVertically, modifier = Modifier.weight(1f)) {
                IconButton(onClick = { showSubmitConfirmation = true }) {
                    Icon(Icons.Filled.Close, contentDescription = "Abort Quiz")
                }
                val quizTitle by viewModel.quizTitle.collectAsState()
                Text(
                    text = quizTitle,
                    fontWeight = FontWeight.SemiBold,
                    fontSize = 16.sp,
                    maxLines = 1,
                    overflow = TextOverflow.Ellipsis
                )
            }

            Row(verticalAlignment = Alignment.CenterVertically) {
                if (enableTimer) {
                    val isLowTime = remainingSeconds < 30
                    Surface(
                        color = if (isLowTime) MaterialTheme.colorScheme.errorContainer else MaterialTheme.colorScheme.primaryContainer,
                        shape = RoundedCornerShape(16.dp),
                        modifier = Modifier.padding(end = 6.dp)
                    ) {
                        Row(
                            verticalAlignment = Alignment.CenterVertically,
                            modifier = Modifier.padding(horizontal = 8.dp, vertical = 4.dp)
                        ) {
                            Icon(
                                imageVector = Icons.Default.Timer,
                                contentDescription = "Timer",
                                tint = if (isLowTime) MaterialTheme.colorScheme.onErrorContainer else MaterialTheme.colorScheme.onPrimaryContainer,
                                modifier = Modifier.size(13.dp)
                            )
                            Spacer(modifier = Modifier.width(4.dp))
                            Text(
                                text = formattedTime,
                                fontSize = 11.sp,
                                fontWeight = FontWeight.Bold,
                                color = if (isLowTime) MaterialTheme.colorScheme.onErrorContainer else MaterialTheme.colorScheme.onPrimaryContainer
                            )
                        }
                    }
                }

                // Quick Submit Button
                TextButton(
                    onClick = {
                        if (unsolvedCount > 0) {
                            showUnsolvedSubmitDialog = true
                        } else {
                            viewModel.submitQuiz()
                        }
                    }
                ) {
                    Text("Submit", fontWeight = FontWeight.Bold, color = MaterialTheme.colorScheme.primary)
                }
                Spacer(modifier = Modifier.width(4.dp))
                Text(
                    "Q: ${currentIndex + 1} of ${questions.size}",
                    fontWeight = FontWeight.Bold,
                    fontSize = 14.sp,
                    color = MaterialTheme.colorScheme.secondary
                )
            }
        }

        // Progress Bar
        val progressPercent = (currentIndex + 1).toFloat() / questions.size.toFloat()
        LinearProgressIndicator(
            progress = progressPercent,
            modifier = Modifier
                .fillMaxWidth()
                .height(6.dp)
                .clip(RoundedCornerShape(3.dp)),
            color = MaterialTheme.colorScheme.primary,
            trackColor = MaterialTheme.colorScheme.surfaceVariant
        )

        // Difficult badge
        Row(
            verticalAlignment = Alignment.CenterVertically,
            horizontalArrangement = Arrangement.SpaceBetween,
            modifier = Modifier.fillMaxWidth()
        ) {
            SuggestionChip(
                onClick = {},
                label = { Text(currentQuestion.difficulty) },
                icon = { Icon(Icons.Filled.Star, null, modifier = Modifier.size(16.dp)) },
                colors = SuggestionChipDefaults.suggestionChipColors(
                    labelColor = when (currentQuestion.difficulty.uppercase()) {
                        "EASY" -> Color(0xFF2E7D32)
                        "MEDIUM" -> Color(0xFFEF6C00)
                        else -> Color(0xFFC62828)
                    }
                )
            )

            Text(
                "Tap details to solve",
                fontSize = 12.sp,
                color = MaterialTheme.colorScheme.onSurfaceVariant.copy(alpha = 0.6f),
                fontWeight = FontWeight.Light
            )
        }

        // --- Question Navigator ---
        val navigatorLazyListState = rememberLazyListState()
        LaunchedEffect(currentIndex) {
            if (questions.isNotEmpty()) {
                navigatorLazyListState.animateScrollToItem(currentIndex)
            }
        }

        PremiumStyleContainer(
            style = activeStyle,
            modifier = Modifier.fillMaxWidth(),
            containerColor = MaterialTheme.colorScheme.surfaceVariant.copy(alpha = 0.15f)
        ) {
            LazyRow(
                state = navigatorLazyListState,
                modifier = Modifier
                    .fillMaxWidth()
                    .padding(8.dp),
                horizontalArrangement = Arrangement.spacedBy(8.dp),
                verticalAlignment = Alignment.CenterVertically
            ) {
                itemsIndexed(questions) { idx, mcq ->
                    val isCurrent = idx == currentIndex
                    val isSolved = userAnswers.containsKey(mcq.id) && !userAnswers[mcq.id].isNullOrEmpty()

                    Box(
                        modifier = Modifier
                            .size(38.dp)
                            .clip(CircleShape)
                            .background(
                                when {
                                    isCurrent -> MaterialTheme.colorScheme.primaryContainer
                                    isSolved -> Color(0xFFE8F5E9)
                                    else -> MaterialTheme.colorScheme.surface
                                }
                            )
                            .border(
                                width = if (isCurrent) 2.dp else 1.dp,
                                color = when {
                                    isCurrent -> MaterialTheme.colorScheme.primary
                                    isSolved -> Color(0xFF4CAF50)
                                    else -> MaterialTheme.colorScheme.outline.copy(alpha = 0.3f)
                                },
                                shape = CircleShape
                            )
                            .clickable {
                                viewModel.quizCurrentIndex.value = idx
                            },
                        contentAlignment = Alignment.Center
                    ) {
                        Text(
                            text = (idx + 1).toString(),
                            fontSize = 13.sp,
                            fontWeight = if (isCurrent) FontWeight.Bold else FontWeight.Medium,
                            color = when {
                                isCurrent -> MaterialTheme.colorScheme.onPrimaryContainer
                                isSolved -> Color(0xFF2E7D32)
                                else -> MaterialTheme.colorScheme.onSurfaceVariant
                            }
                        )
                    }
                }
            }
        }

        // Question Statement & Options scrollable area
        Column(
            modifier = Modifier
                .weight(1f)
                .fillMaxWidth()
                .verticalScroll(rememberScrollState()),
            verticalArrangement = Arrangement.spacedBy(16.dp)
        ) {
            // Question Statement Card
            PremiumStyleContainer(
                style = activeStyle,
                modifier = Modifier.fillMaxWidth(),
                containerColor = MaterialTheme.colorScheme.surfaceVariant.copy(alpha = 0.3f)
            ) {
                Box(
                    modifier = Modifier
                        .fillMaxWidth()
                        .padding(20.dp),
                    contentAlignment = Alignment.CenterStart
                ) {
                    Text(
                        text = currentQuestion.question,
                        fontSize = 18.sp,
                        fontWeight = FontWeight.Bold,
                        color = MaterialTheme.colorScheme.onSurface,
                        lineHeight = 24.sp
                    )
                }
            }

            // Answer options list
            Column(
                modifier = Modifier.fillMaxWidth(),
                verticalArrangement = Arrangement.spacedBy(10.dp)
            ) {
                val options = listOf(
                    "A" to currentQuestion.optionA,
                    "B" to currentQuestion.optionB,
                    "C" to currentQuestion.optionC,
                    "D" to currentQuestion.optionD
                )

                options.forEach { (optionCode, optionText) ->
                    val active = selectedOption == optionCode
                    PremiumStyleContainer(
                        style = activeStyle,
                        onClick = { viewModel.selectQuizOption(currentQuestion.id, optionCode) },
                        modifier = Modifier.fillMaxWidth(),
                        containerColor = if (active) MaterialTheme.colorScheme.primaryContainer.copy(alpha = 0.6f) else MaterialTheme.colorScheme.surface
                    ) {
                        Row(
                            modifier = Modifier
                                .fillMaxWidth()
                                .padding(16.dp),
                            verticalAlignment = Alignment.CenterVertically
                        ) {
                            Box(
                                modifier = Modifier
                                    .size(28.dp)
                                    .clip(RoundedCornerShape(6.dp))
                                    .background(if (active) MaterialTheme.colorScheme.primary else MaterialTheme.colorScheme.surfaceVariant),
                                contentAlignment = Alignment.Center
                            ) {
                                Text(
                                    optionCode,
                                    fontWeight = FontWeight.Bold,
                                    color = if (active) MaterialTheme.colorScheme.onPrimary else MaterialTheme.colorScheme.onSurfaceVariant
                                )
                            }

                            Spacer(modifier = Modifier.width(16.dp))

                            Text(
                                text = optionText,
                                fontSize = 14.sp,
                                fontWeight = FontWeight.Medium,
                                color = MaterialTheme.colorScheme.onSurface
                            )
                        }
                    }
                }
            }
        }

        // Footer Actions
        Row(
            modifier = Modifier
                .fillMaxWidth()
                .padding(vertical = 8.dp),
            horizontalArrangement = Arrangement.SpaceBetween,
            verticalAlignment = Alignment.CenterVertically
        ) {
            OutlinedButton(
                onClick = { viewModel.selectPreviousQuestion() },
                enabled = currentIndex > 0,
                modifier = Modifier.weight(1f)
            ) {
                Text("Previous")
            }

            Spacer(modifier = Modifier.width(12.dp))

            if (currentIndex == questions.size - 1) {
                Button(
                    onClick = {
                        if (unsolvedCount > 0) {
                            showUnsolvedSubmitDialog = true
                        } else {
                            viewModel.submitQuiz()
                        }
                    },
                    colors = ButtonDefaults.buttonColors(containerColor = Color(0xFF2E7D32)),
                    modifier = Modifier.weight(1.5f)
                ) {
                    Text("Submit Answers", fontWeight = FontWeight.Bold)
                }
            } else {
                Button(
                    onClick = { viewModel.selectNextQuestion() },
                    modifier = Modifier.weight(1f)
                ) {
                    Text("Next")
                }
            }
        }
    }

    // Abort dialog confirmation
    if (showSubmitConfirmation) {
        AlertDialog(
            onDismissRequest = { showSubmitConfirmation = false },
            title = { Text("Abort ongoing test?") },
            text = { Text("Progress and completed answers for this current test will be discarded.") },
            confirmButton = {
                TextButton(onClick = {
                    showSubmitConfirmation = false
                    viewModel.navigateTo(Screen.UserDashboard)
                }) {
                    Text("Discard", color = MaterialTheme.colorScheme.error)
                }
            },
            dismissButton = {
                TextButton(onClick = { showSubmitConfirmation = false }) {
                    Text("Resume Practice")
                }
            }
        )
    }

    // Unsolved summary confirmation dialog
    if (showUnsolvedSubmitDialog) {
        AlertDialog(
            onDismissRequest = { showUnsolvedSubmitDialog = false },
            title = {
                Row(verticalAlignment = Alignment.CenterVertically) {
                    Icon(
                        imageVector = Icons.Default.Warning,
                        contentDescription = "Warning",
                        tint = MaterialTheme.colorScheme.error,
                        modifier = Modifier.size(24.dp)
                    )
                    Spacer(modifier = Modifier.width(8.dp))
                    Text("Unsolved Questions")
                }
            },
            text = {
                Text("You have $unsolvedCount unsolved question(s) remaining. Do you want to submit the test anyway?")
            },
            confirmButton = {
                TextButton(
                    onClick = {
                        showUnsolvedSubmitDialog = false
                        viewModel.submitQuiz()
                    }
                ) {
                    Text("Submit Anyway", color = MaterialTheme.colorScheme.error, fontWeight = FontWeight.Bold)
                }
            },
            dismissButton = {
                TextButton(
                    onClick = { showUnsolvedSubmitDialog = false }
                ) {
                    Text("Cancel")
                }
            }
        )
    }
}

// ==================== SCREEN 6: USER QUIZ REVIEW ====================
@Composable
fun UserQuizReviewScreen(viewModel: MainViewModel, testResultResultId: Int) {
    val results by viewModel.allTestResults.collectAsState()
    val originalQuestions by viewModel.quizQuestions.collectAsState()
    val originalAnswers by viewModel.quizSelectedAnswers.collectAsState()
    val activeStyle by viewModel.activeDesignStyle.collectAsState()

    val tr = results.firstOrNull { it.id == testResultResultId }

    if (tr == null) {
        Box(modifier = Modifier.fillMaxSize(), contentAlignment = Alignment.Center) {
            Text("No test record found. Loading details...")
        }
        return
    }

    LazyColumn(
        modifier = Modifier
            .fillMaxSize()
            .padding(16.dp),
        verticalArrangement = Arrangement.spacedBy(16.dp)
    ) {
        // App header
        item {
            Text(
                "Evaluation Result",
                fontWeight = FontWeight.Bold,
                fontSize = 22.sp,
                color = MaterialTheme.colorScheme.onBackground
            )
        }

        // Circular dynamic Score card
        item {
            PremiumStyleContainer(
                style = activeStyle,
                modifier = Modifier.fillMaxWidth(),
                containerColor = if (tr.isPassed) Color(0xFFE8F5E9) else Color(0xFFFFEBEE)
            ) {
                Column(
                    modifier = Modifier
                        .fillMaxWidth()
                        .padding(20.dp),
                    horizontalAlignment = Alignment.CenterHorizontally,
                    verticalArrangement = Arrangement.spacedBy(8.dp)
                ) {
                    Text(
                        text = if (tr.isPassed) "PASSED!" else "FAILED",
                        fontSize = 24.sp,
                        fontWeight = FontWeight.ExtraBold,
                        color = if (tr.isPassed) Color(0xFF2E7D32) else Color(0xFFC62828)
                    )

                    Text(
                        text = "${tr.scorePercentage.toInt()}% Accuracy",
                        fontSize = 32.sp,
                        fontWeight = FontWeight.Black,
                        color = if (tr.isPassed) Color(0xFF1B5E20) else Color(0xFFB71C1C)
                    )

                    Text(
                        text = "${tr.correctAnswers} Correct • ${tr.wrongAnswers} Wrong • ${tr.totalQuestions} Total",
                        fontSize = 14.sp,
                        color = MaterialTheme.colorScheme.onSurfaceVariant
                    )

                    Divider(color = MaterialTheme.colorScheme.onSurface.copy(alpha = 0.1f))

                    Text(
                        text = "The minimum target parsing logic is 60%. Below is a complete question reviews.",
                        fontSize = 11.sp,
                        textAlign = TextAlign.Center,
                        color = MaterialTheme.colorScheme.onSurfaceVariant
                    )
                }
            }
        }

        // PDF Single Test Report Download Button
        item {
            val context = LocalContext.current
            val allUsersList by viewModel.allUsers.collectAsState()
            val user = remember(allUsersList, tr) { allUsersList.find { it.id == tr.userId } }
            
            if (user != null) {
                PremiumStyleContainer(
                    style = activeStyle,
                    modifier = Modifier.fillMaxWidth(),
                    containerColor = MaterialTheme.colorScheme.primaryContainer.copy(alpha = 0.1f)
                ) {
                    Row(
                        modifier = Modifier
                            .fillMaxWidth()
                            .padding(12.dp),
                        verticalAlignment = Alignment.CenterVertically,
                        horizontalArrangement = Arrangement.SpaceBetween
                    ) {
                        Column(modifier = Modifier.weight(1f), verticalArrangement = Arrangement.spacedBy(2.dp)) {
                            Text(
                                "Evaluated PDF report sheet",
                                fontWeight = FontWeight.Bold,
                                fontSize = 13.sp,
                                color = MaterialTheme.colorScheme.primary
                            )
                            Text(
                                "Download this specific test worksheet evaluation details with full score card.",
                                fontSize = 10.sp,
                                color = MaterialTheme.colorScheme.onSurfaceVariant
                            )
                        }
                        Button(
                            onClick = {
                                viewModel.activeReportTask.value = ReportTask.SingleTestCard(user, tr)
                            },
                            shape = RoundedCornerShape(8.dp),
                            contentPadding = PaddingValues(horizontal = 12.dp, vertical = 6.dp)
                        ) {
                            Icon(Icons.Filled.PictureAsPdf, contentDescription = "Download sheet", modifier = Modifier.size(14.dp))
                            Spacer(modifier = Modifier.width(6.dp))
                            Text("Download", fontSize = 11.sp, fontWeight = FontWeight.Bold)
                        }
                    }
                }
            }
        }

        item {
            Text(
                "Detailed Answers Breakdown",
                fontWeight = FontWeight.SemiBold,
                fontSize = 16.sp,
                color = MaterialTheme.colorScheme.onBackground
            )
        }

        // Iterative reviews of seeded quiz play questions
        if (originalQuestions.isEmpty()) {
            item {
                Text(
                    "Detailed interactive question data is only cached immediately during active play session.",
                    fontSize = 12.sp,
                    color = MaterialTheme.colorScheme.onSurfaceVariant
                )
            }
        } else {
            items(originalQuestions) { mcq ->
                val userChoice = originalAnswers[mcq.id]
                val isCorrect = userChoice == mcq.correctOption

                PremiumStyleContainer(
                    style = activeStyle,
                    modifier = Modifier.fillMaxWidth(),
                    containerColor = MaterialTheme.colorScheme.surface
                ) {
                    Column(
                        modifier = Modifier.padding(16.dp),
                        verticalArrangement = Arrangement.spacedBy(10.dp)
                    ) {
                        // Title / Status Badge
                        Row(
                            horizontalArrangement = Arrangement.SpaceBetween,
                            verticalAlignment = Alignment.CenterVertically,
                            modifier = Modifier.fillMaxWidth()
                        ) {
                            Text(
                                text = "Difficulty: " + mcq.difficulty,
                                style = MaterialTheme.typography.labelSmall,
                                fontWeight = FontWeight.Bold,
                                color = MaterialTheme.colorScheme.primary
                            )

                            if (isCorrect) {
                                Row(verticalAlignment = Alignment.CenterVertically) {
                                    Icon(Icons.Filled.CheckCircle, "Correct", tint = Color(0xFF2E7D32), modifier = Modifier.size(16.dp))
                                    Spacer(modifier = Modifier.width(4.dp))
                                    Text("Correct", color = Color(0xFF2E7D32), fontWeight = FontWeight.Bold, fontSize = 12.sp)
                                }
                            } else {
                                Row(verticalAlignment = Alignment.CenterVertically) {
                                    Icon(Icons.Filled.Cancel, "Incorrect", tint = Color(0xFFC62828), modifier = Modifier.size(16.dp))
                                    Spacer(modifier = Modifier.width(4.dp))
                                    Text("Incorrect", color = Color(0xFFC62828), fontWeight = FontWeight.Bold, fontSize = 12.sp)
                                }
                            }
                        }

                        // Question
                        Text(
                            text = mcq.question,
                            fontWeight = FontWeight.Bold,
                            fontSize = 15.sp,
                            color = MaterialTheme.colorScheme.onSurface
                        )

                        // Option review bars
                        val ops = listOf(
                            "A" to mcq.optionA,
                            "B" to mcq.optionB,
                            "C" to mcq.optionC,
                            "D" to mcq.optionD
                        )

                        ops.forEach { (code, text) ->
                            val selectedByMe = userChoice == code
                            val isRightChoice = mcq.correctOption == code

                            val cardColor = when {
                                isRightChoice -> Color(0xFFE8F5E9)   // Green success bar
                                selectedByMe -> Color(0xFFFFEBEE)   // Red error bar
                                else -> MaterialTheme.colorScheme.surfaceColorAtElevation(1.dp)
                            }

                            Row(
                                modifier = Modifier
                                    .fillMaxWidth()
                                    .clip(RoundedCornerShape(8.dp))
                                    .background(cardColor)
                                    .padding(12.dp),
                                verticalAlignment = Alignment.CenterVertically
                            ) {
                                Text(
                                    text = "$code: $text",
                                    fontSize = 13.sp,
                                    color = MaterialTheme.colorScheme.onSurface,
                                    modifier = Modifier.weight(1f)
                                )

                                if (isRightChoice) {
                                    Icon(Icons.Filled.Check, null, tint = Color(0xFF2E7D32), modifier = Modifier.size(16.dp))
                                } else if (selectedByMe) {
                                    Icon(Icons.Filled.Close, null, tint = Color(0xFFC62828), modifier = Modifier.size(16.dp))
                                }
                            }
                        }

                        // Detailed logical explanation reveal
                        Card(
                            colors = CardDefaults.cardColors(containerColor = MaterialTheme.colorScheme.secondaryContainer.copy(alpha = 0.3f)),
                            shape = RoundedCornerShape(8.dp)
                        ) {
                            Column(
                                modifier = Modifier.padding(12.dp)
                            ) {
                                Row(verticalAlignment = Alignment.CenterVertically) {
                                    Icon(Icons.Filled.Info, null, tint = MaterialTheme.colorScheme.secondary, modifier = Modifier.size(16.dp))
                                    Spacer(modifier = Modifier.width(6.dp))
                                    Text("Logical Explanation", fontSize = 12.sp, fontWeight = FontWeight.Bold, color = MaterialTheme.colorScheme.secondary)
                                }
                                Spacer(modifier = Modifier.height(4.dp))
                                Text(
                                    mcq.detailedExplanation,
                                    fontSize = 12.sp,
                                    lineHeight = 16.sp,
                                    color = MaterialTheme.colorScheme.onSurfaceVariant
                                )
                            }
                        }
                    }
                }
            }
        }

        // Return button
        item {
            Button(
                onClick = {
                    viewModel.clearQuizState()
                    viewModel.navigateTo(Screen.UserDashboard)
                },
                modifier = Modifier
                    .fillMaxWidth()
                    .padding(vertical = 12.dp)
            ) {
                Text("Return to Dashboard", fontWeight = FontWeight.Bold)
            }
        }
    }
}

// ==================== SCREEN: TARGET TRACKER & TSR SCREEN ====================
@Composable
fun TargetTrackerScreen(viewModel: MainViewModel) {
    val histories by viewModel.userTestResults.collectAsState()
    val activeStyle by viewModel.activeDesignStyle.collectAsState()
    val targetSettings by viewModel.targetSettingsState.collectAsState()
    val isDark = isSystemInDarkTheme()

    var setupQuizzes by remember { mutableStateOf(5) }
    var setupMcqs by remember { mutableStateOf(100) }
    var setupDays by remember { mutableStateOf(3) }

    val dayOptions = listOf(1, 2, 3, 5, 7, 10, 15, 30)

    val filteredResults = remember(histories, targetSettings) {
        if (!targetSettings.isActive) emptyList()
        else histories.filter { it.timestamp >= targetSettings.startTimestamp }
    }

    val quizzesCompleted = filteredResults.size
    val mcqsAttempted = filteredResults.sumOf { it.totalQuestions }
    
    val quizzesRemaining = (targetSettings.quizzesCount - quizzesCompleted).coerceAtLeast(0)
    val mcqsRemaining = (targetSettings.mcqsCount - mcqsAttempted).coerceAtLeast(0)

    val quizzesProgress = if (targetSettings.quizzesCount > 0) {
        quizzesCompleted.toFloat() / targetSettings.quizzesCount.toFloat()
    } else 0f

    val mcqsProgress = if (targetSettings.mcqsCount > 0) {
        mcqsAttempted.toFloat() / targetSettings.mcqsCount.toFloat()
    } else 0f

    val timeLeftMs = if (targetSettings.isActive) {
        val targetEndTime = targetSettings.startTimestamp + (targetSettings.durationDays * 24 * 60 * 60 * 1000L)
        (targetEndTime - System.currentTimeMillis()).coerceAtLeast(0L)
    } else 0L

    val daysLeft = (timeLeftMs / (24 * 60 * 60 * 1000L)).toInt()
    val hoursLeft = ((timeLeftMs % (24 * 60 * 60 * 1000L)) / (60 * 60 * 1000L)).toInt()

    Column(
        modifier = Modifier
            .fillMaxSize()
            .padding(16.dp),
        verticalArrangement = Arrangement.spacedBy(16.dp)
    ) {
        Row(
            verticalAlignment = Alignment.CenterVertically,
            modifier = Modifier.fillMaxWidth()
        ) {
            IconButton(onClick = { viewModel.navigateBack() }) {
                Icon(Icons.Filled.ArrowBack, contentDescription = "Back")
            }
            Text("Target Tracker & Today Report", fontWeight = FontWeight.Bold, fontSize = 20.sp)
        }

        if (!targetSettings.isActive) {
            Card(
                modifier = Modifier.fillMaxWidth(),
                shape = RoundedCornerShape(16.dp),
                border = BorderStroke(1.dp, if (isDark) Color(0xFF2C2D35) else Color(0xFFE1E2EC)),
                colors = CardDefaults.cardColors(containerColor = MaterialTheme.colorScheme.surface)
            ) {
                Column(
                    modifier = Modifier.padding(16.dp),
                    verticalArrangement = Arrangement.spacedBy(16.dp)
                ) {
                    Text("🎯 Set a New Study Target", fontWeight = FontWeight.Bold, fontSize = 18.sp, color = MaterialTheme.colorScheme.primary)
                    Text("Define a study target to stay focused and track how many quizzes and MCQs you complete over time.", fontSize = 12.sp, color = Color.Gray)

                    Text("Target Quizzes to Complete:", fontWeight = FontWeight.Bold, fontSize = 14.sp)
                    Row(
                        verticalAlignment = Alignment.CenterVertically,
                        horizontalArrangement = Arrangement.spacedBy(12.dp)
                    ) {
                        IconButton(onClick = { if (setupQuizzes > 1) setupQuizzes-- }) {
                            Text("-", fontSize = 24.sp, fontWeight = FontWeight.Bold)
                        }
                        Text("$setupQuizzes Quizzes", fontWeight = FontWeight.Bold, fontSize = 16.sp, modifier = Modifier.width(100.dp))
                        IconButton(onClick = { setupQuizzes++ }) {
                            Text("+", fontSize = 24.sp, fontWeight = FontWeight.Bold)
                        }
                    }

                    Text("Target MCQs to Attempt:", fontWeight = FontWeight.Bold, fontSize = 14.sp)
                    Row(
                        verticalAlignment = Alignment.CenterVertically,
                        horizontalArrangement = Arrangement.spacedBy(12.dp)
                    ) {
                        IconButton(onClick = { if (setupMcqs > 10) setupMcqs -= 10 }) {
                            Text("-", fontSize = 24.sp, fontWeight = FontWeight.Bold)
                        }
                        Text("$setupMcqs MCQs", fontWeight = FontWeight.Bold, fontSize = 16.sp, modifier = Modifier.width(100.dp))
                        IconButton(onClick = { setupMcqs += 10 }) {
                            Text("+", fontSize = 24.sp, fontWeight = FontWeight.Bold)
                        }
                    }

                    Text("Target Duration (Days):", fontWeight = FontWeight.Bold, fontSize = 14.sp)
                    Row(
                        modifier = Modifier.fillMaxWidth(),
                        horizontalArrangement = Arrangement.spacedBy(6.dp)
                    ) {
                        dayOptions.forEach { days ->
                            val active = setupDays == days
                            OutlinedButton(
                                onClick = { setupDays = days },
                                modifier = Modifier.weight(1f),
                                contentPadding = PaddingValues(0.dp),
                                colors = if (active) ButtonDefaults.outlinedButtonColors(containerColor = MaterialTheme.colorScheme.primaryContainer) else ButtonDefaults.outlinedButtonColors()
                            ) {
                                Text(
                                    text = if (days == 30) "1M" else "${days}D",
                                    fontSize = 11.sp,
                                    fontWeight = FontWeight.Bold
                                )
                            }
                        }
                    }

                    Button(
                        onClick = {
                            viewModel.setTarget(setupQuizzes, setupMcqs, setupDays)
                        },
                        modifier = Modifier.fillMaxWidth(),
                        shape = RoundedCornerShape(12.dp)
                    ) {
                        Text("Activate Target Tracking")
                    }
                }
            }
        } else {
            Card(
                modifier = Modifier.fillMaxWidth(),
                shape = RoundedCornerShape(16.dp),
                colors = CardDefaults.cardColors(containerColor = MaterialTheme.colorScheme.surfaceVariant.copy(alpha = 0.3f))
            ) {
                Column(
                    modifier = Modifier.padding(16.dp),
                    verticalArrangement = Arrangement.spacedBy(14.dp)
                ) {
                    Row(
                        modifier = Modifier.fillMaxWidth(),
                        horizontalArrangement = Arrangement.SpaceBetween,
                        verticalAlignment = Alignment.CenterVertically
                    ) {
                        Text("🎯 Active Target Tracker", fontWeight = FontWeight.Bold, fontSize = 18.sp, color = MaterialTheme.colorScheme.primary)
                        IconButton(onClick = { viewModel.clearTarget() }) {
                            Icon(Icons.Filled.Delete, contentDescription = "Reset Target", tint = Color.Red)
                        }
                    }

                    Row(
                        modifier = Modifier.fillMaxWidth(),
                        horizontalArrangement = Arrangement.SpaceBetween
                    ) {
                        Text(
                            text = "Time Left: " + if (timeLeftMs == 0L) "Time's Up!" else "${daysLeft}d ${hoursLeft}h",
                            fontWeight = FontWeight.Bold,
                            fontSize = 14.sp
                        )
                        Text(text = "Period: ${targetSettings.durationDays} Days", fontSize = 12.sp, color = Color.Gray)
                    }

                    Column(verticalArrangement = Arrangement.spacedBy(8.dp)) {
                        Row(
                            modifier = Modifier.fillMaxWidth(),
                            horizontalArrangement = Arrangement.SpaceBetween
                        ) {
                            Text("Quizzes: $quizzesCompleted / ${targetSettings.quizzesCount}", fontSize = 13.sp, fontWeight = FontWeight.Bold)
                            Text("${(quizzesProgress * 100).toInt()}%", fontSize = 13.sp, color = MaterialTheme.colorScheme.primary)
                        }
                        LinearProgressIndicator(
                            progress = quizzesProgress.coerceIn(0f, 1f),
                            modifier = Modifier.fillMaxWidth().height(8.dp).clip(RoundedCornerShape(4.dp))
                        )
                        if (quizzesRemaining > 0) {
                            Text("⚠️ $quizzesRemaining quizzes left to meet your goal.", fontSize = 11.sp, color = Color.Gray)
                        } else {
                            Text("🎉 Target Quizzes Completed!", fontSize = 11.sp, color = Color(0xFF4CAF50), fontWeight = FontWeight.Bold)
                        }
                    }

                    Column(verticalArrangement = Arrangement.spacedBy(8.dp)) {
                        Row(
                            modifier = Modifier.fillMaxWidth(),
                            horizontalArrangement = Arrangement.SpaceBetween
                        ) {
                            Text("MCQs Attempted: $mcqsAttempted / ${targetSettings.mcqsCount}", fontSize = 13.sp, fontWeight = FontWeight.Bold)
                            Text("${(mcqsProgress * 100).toInt()}%", fontSize = 13.sp, color = MaterialTheme.colorScheme.secondary)
                        }
                        LinearProgressIndicator(
                            progress = mcqsProgress.coerceIn(0f, 1f),
                            modifier = Modifier.fillMaxWidth().height(8.dp).clip(RoundedCornerShape(4.dp)),
                            color = MaterialTheme.colorScheme.secondary
                        )
                        if (mcqsRemaining > 0) {
                            Text("⚠️ $mcqsRemaining MCQs left to meet your goal.", fontSize = 11.sp, color = Color.Gray)
                        } else {
                            Text("🎉 Target MCQs Completed!", fontSize = 11.sp, color = Color(0xFF4CAF50), fontWeight = FontWeight.Bold)
                        }
                    }
                }
            }
        }

        TodaySituationReportComponent(histories = histories, isDark = isDark)
    }
}

@Composable
fun TodaySituationReportComponent(histories: List<com.example.data.model.TestResult>, isDark: Boolean) {
    val startOfToday = remember {
        val cal = java.util.Calendar.getInstance()
        cal.set(java.util.Calendar.HOUR_OF_DAY, 0)
        cal.set(java.util.Calendar.MINUTE, 0)
        cal.set(java.util.Calendar.SECOND, 0)
        cal.set(java.util.Calendar.MILLISECOND, 0)
        cal.timeInMillis
    }

    val todayResults = remember(histories, startOfToday) {
        histories.filter { it.timestamp >= startOfToday }
    }

    val todayQuizzes = todayResults.size
    val todayCorrect = todayResults.sumOf { it.correctAnswers }
    val todayWrong = todayResults.sumOf { it.wrongAnswers }
    val todayMcqs = todayResults.sumOf { it.totalQuestions }

    val todayAccuracy = if (todayMcqs > 0) {
        ((todayCorrect.toFloat() / todayMcqs.toFloat()) * 100f).toInt()
    } else null

    val tsrFeedback = when {
        todayQuizzes == 0 -> "⚠️ Idle - No activities recorded today. Let's start a quiz to make today productive!"
        todayAccuracy == null -> "📈 Quiz in progress or no questions solved yet."
        todayAccuracy >= 80 -> "🏆 Excellent - You are performing exceptionally well today!"
        todayAccuracy >= 50 -> "📈 Good Progress - Keep practicing to boost your accuracy!"
        else -> "⚠️ Review Needed - Work on your weak topics to improve today's accuracy."
    }

    Card(
        modifier = Modifier.fillMaxWidth(),
        shape = RoundedCornerShape(16.dp),
        border = BorderStroke(1.dp, if (isDark) Color(0xFF2C2D35) else Color(0xFFE1E2EC)),
        colors = CardDefaults.cardColors(containerColor = MaterialTheme.colorScheme.surface)
    ) {
        Column(
            modifier = Modifier.padding(16.dp),
            verticalArrangement = Arrangement.spacedBy(12.dp)
        ) {
            Row(
                verticalAlignment = Alignment.CenterVertically,
                modifier = Modifier.fillMaxWidth()
            ) {
                Text("📊 TSR: Today Situation Report", fontWeight = FontWeight.Bold, fontSize = 16.sp, color = MaterialTheme.colorScheme.primary)
                Spacer(modifier = Modifier.weight(1f))
                Box(
                    modifier = Modifier
                        .clip(RoundedCornerShape(8.dp))
                        .background(MaterialTheme.colorScheme.primaryContainer)
                        .padding(horizontal = 8.dp, vertical = 4.dp)
                ) {
                    Text("Today", fontSize = 10.sp, fontWeight = FontWeight.Bold, color = MaterialTheme.colorScheme.onPrimaryContainer)
                }
            }

            Row(
                modifier = Modifier.fillMaxWidth(),
                horizontalArrangement = Arrangement.SpaceBetween
            ) {
                Column(horizontalAlignment = Alignment.CenterHorizontally, modifier = Modifier.weight(1f)) {
                    Text("Quizzes", fontSize = 11.sp, color = Color.Gray)
                    Text("$todayQuizzes", fontSize = 18.sp, fontWeight = FontWeight.Bold)
                }
                Column(horizontalAlignment = Alignment.CenterHorizontally, modifier = Modifier.weight(1f)) {
                    Text("Total MCQs", fontSize = 11.sp, color = Color.Gray)
                    Text("$todayMcqs", fontSize = 18.sp, fontWeight = FontWeight.Bold)
                }
                Column(horizontalAlignment = Alignment.CenterHorizontally, modifier = Modifier.weight(1f)) {
                    Text("Correct", fontSize = 11.sp, color = Color.Gray)
                    Text("$todayCorrect", fontSize = 18.sp, fontWeight = FontWeight.Bold, color = Color(0xFF4CAF50))
                }
                Column(horizontalAlignment = Alignment.CenterHorizontally, modifier = Modifier.weight(1f)) {
                    Text("Accuracy", fontSize = 11.sp, color = Color.Gray)
                    Text(if (todayAccuracy != null) "$todayAccuracy%" else "--", fontSize = 18.sp, fontWeight = FontWeight.Bold, color = MaterialTheme.colorScheme.secondary)
                }
            }

            HorizontalDivider(color = MaterialTheme.colorScheme.outlineVariant)

            Text(
                text = tsrFeedback,
                fontSize = 12.sp,
                color = if (isDark) Color.LightGray else Color.DarkGray,
                lineHeight = 16.sp
            )
        }
    }
}

// ==================== SCREEN 7: USER PROGRESS / HISTORIC PERFORMANCE ANALYTICS ====================
@Composable
fun UserProgressScreen(viewModel: MainViewModel) {
    val histories by viewModel.userTestResults.collectAsState()
    val subjects by viewModel.allSubjects.collectAsState()
    val progressList by viewModel.userProgress.collectAsState()
    val topics by viewModel.allTopics.collectAsState()
    val loggedInUser by viewModel.loggedInUser.collectAsState()
    val activeStyle by viewModel.activeDesignStyle.collectAsState()

    // Aggregate key metrics
    val totalAttempts = histories.size
    val totalQuestionsCorrect = progressList.sumOf { it.questionsCorrect }
    val totalQuestionsAttempted = progressList.sumOf { it.questionsAttempted }
    val totalQuestionsIncorrect = (totalQuestionsAttempted - totalQuestionsCorrect).coerceAtLeast(0)
    
    val overallAccuracy = if (totalQuestionsAttempted > 0) {
        ((totalQuestionsCorrect.toFloat() / totalQuestionsAttempted.toFloat()) * 100f).toInt()
    } else 0

    // XP calculation
    val levelInfo = loggedInUser?.let { viewModel.calculateUserLevel(it, histories) } 
        ?: com.example.ui.UserLevelInfo(1, "New Student", 0, 500, 0f)

    val relevantTopics = remember(topics, progressList) {
        topics.filter { t -> progressList.any { it.topicId == t.id } }
