                                }
                            }

                            // Pick Preview Document Row
                            Column(verticalArrangement = Arrangement.spacedBy(4.dp)) {
                                Text("Preview Document Attachment Upload (Separate):", fontSize = 11.sp, fontWeight = FontWeight.Bold)
                                Row(
                                    modifier = Modifier.fillMaxWidth(),
                                    horizontalArrangement = Arrangement.spacedBy(8.dp)
                                ) {
                                    Button(
                                        onClick = { previewFilePickerLauncher.launch("*/*") },
                                        modifier = Modifier.weight(1.2f),
                                        colors = ButtonDefaults.buttonColors(containerColor = MaterialTheme.colorScheme.tertiary),
                                        shape = RoundedCornerShape(8.dp)
                                    ) {
                                        Icon(Icons.Filled.Visibility, null, modifier = Modifier.size(16.dp))
                                        Spacer(modifier = Modifier.width(4.dp))
                                        Text("Select Preview File", fontSize = 11.sp)
                                    }
                                    
                                    Box(
                                        modifier = Modifier
                                            .weight(1f)
                                            .height(38.dp)
                                            .background(MaterialTheme.colorScheme.surface, RoundedCornerShape(8.dp))
                                            .border(1.dp, Color.LightGray, RoundedCornerShape(8.dp))
                                            .padding(horizontal = 8.dp),
                                        contentAlignment = Alignment.CenterStart
                                    ) {
                                        val path = selectedPreviewPdfPath ?: selectedPreviewImagePath ?: selectedPreviewDocPath
                                        Text(
                                            text = if (path != null) "✓ ${path.substringAfterLast('/')}" else "No preview file",
                                            fontSize = 9.sp,
                                            fontWeight = FontWeight.Bold,
                                            color = if (path != null) Color(0xFF2E7D32) else Color.Red,
                                            maxLines = 1,
                                            overflow = TextOverflow.Ellipsis
                                        )
                                    }
                                }
                            }

                            Button(
                                onClick = {
                                    if (title.isEmpty() || desc.isEmpty()) {
                                        viewModel.feedbackMessage.value = "Title and summary are mandatory."
                                        return@Button
                                    }
                                    viewModel.saveNote(
                                        id = 0,
                                        title = title,
                                        desc = desc,
                                        subjectId = null,
                                        pdfUri = selectedMainPdfPath,
                                        imageUri = selectedMainImagePath,
                                        docUri = selectedMainDocPath,
                                        previewPdfUri = selectedPreviewPdfPath,
                                        previewImageUri = selectedPreviewImagePath,
                                        previewDocUri = selectedPreviewDocPath
                                    )
                                    title = ""
                                    desc = ""
                                    selectedMainPdfPath = null
                                    selectedMainImagePath = null
                                    selectedMainDocPath = null
                                    selectedPreviewPdfPath = null
                                    selectedPreviewImagePath = null
                                    selectedPreviewDocPath = null
                                    showUploadPanel = false
                                },
                                modifier = Modifier.fillMaxWidth(),
                                shape = RoundedCornerShape(10.dp)
                            ) {
                                Text("Publish Study Note & Preview", fontWeight = FontWeight.Bold)
                            }
                        }
                    }
                }
            }

            // Access Management UI station
            if (showAccessManagement) {
                item {
                    Card(
                        modifier = Modifier.fillMaxWidth(),
                        colors = CardDefaults.cardColors(containerColor = MaterialTheme.colorScheme.secondaryContainer.copy(alpha = 0.25f)),
                        shape = RoundedCornerShape(16.dp),
                        border = BorderStroke(1.dp, MaterialTheme.colorScheme.primary.copy(alpha = 0.3f))
                    ) {
                        Column(
                            modifier = Modifier.padding(16.dp),
                            verticalArrangement = Arrangement.spacedBy(10.dp)
                        ) {
                            Text("Student Access Station", fontWeight = FontWeight.Bold, fontSize = 15.sp, color = MaterialTheme.colorScheme.primary)
                            
                            // Target note specification dropdown
                            var dropExpanded by remember { mutableStateOf(false) }
                            val targetNoteLabel = notes.find { it.id == selectedTargetNoteId }?.title ?: "Select Target Study Note"
                            
                            Box(modifier = Modifier.fillMaxWidth()) {
                                OutlinedButton(
                                    onClick = { dropExpanded = true },
                                    modifier = Modifier.fillMaxWidth()
                                ) {
                                    Row(
                                        modifier = Modifier.fillMaxWidth(),
                                        horizontalArrangement = Arrangement.SpaceBetween,
                                        verticalAlignment = Alignment.CenterVertically
                                    ) {
                                        Text(targetNoteLabel, fontSize = 11.sp, maxLines = 1, overflow = TextOverflow.Ellipsis)
                                        Icon(Icons.Filled.ArrowDropDown, null)
                                    }
                                }
                                DropdownMenu(
                                    expanded = dropExpanded,
                                    onDismissRequest = { dropExpanded = false },
                                    modifier = Modifier.fillMaxWidth(0.9f)
                                ) {
                                    notes.forEach { note ->
                                        DropdownMenuItem(
                                            text = { Text(note.title, maxLines = 1, overflow = TextOverflow.Ellipsis) },
                                            onClick = {
                                                selectedTargetNoteId = note.id
                                                dropExpanded = false
                                            }
                                        )
                                    }
                                }
                            }

                            if (selectedTargetNoteId != null) {
                                val currentNoteId = selectedTargetNoteId ?: 0
                                
                                Text("Search User by Username:", fontSize = 11.sp, fontWeight = FontWeight.Bold)
                                OutlinedTextField(
                                    value = userSearchQuery,
                                    onValueChange = { userSearchQuery = it },
                                    placeholder = { Text("Enter username...", fontSize = 12.sp) },
                                    singleLine = true,
                                    modifier = Modifier.fillMaxWidth(),
                                    shape = RoundedCornerShape(10.dp)
                                )

                                // Grant Access to all users button
                                Button(
                                    onClick = { 
                                        viewModel.grantNoteAccessToAllUsers(currentNoteId)
                                    },
                                    modifier = Modifier.fillMaxWidth(),
                                    colors = ButtonDefaults.buttonColors(containerColor = MaterialTheme.colorScheme.primary)
                                ) {
                                    Icon(Icons.Filled.Group, null, modifier = Modifier.size(16.dp))
                                    Spacer(modifier = Modifier.width(6.dp))
                                    Text("Grant Access To All Users", fontSize = 12.sp, fontWeight = FontWeight.Bold)
                                }

                                Spacer(modifier = Modifier.height(4.dp))
                                Text("Matching Accounts", fontSize = 11.sp, fontWeight = FontWeight.Bold, color = MaterialTheme.colorScheme.outline)

                                // Filtering user lists
                                val userProfiles = allUsers.filter { student ->
                                    student.role == "USER" && (
                                        student.username.contains(userSearchQuery, ignoreCase = true) ||
                                        student.fullName.contains(userSearchQuery, ignoreCase = true)
                                    )
                                }

                                if (userProfiles.isEmpty()) {
                                    Text("No matching students found in directory.", fontSize = 11.sp, color = MaterialTheme.colorScheme.outline)
                                } else {
                                    userProfiles.take(5).forEach { student ->
                                        val request = accessRequests.find { it.userId == student.id && it.noteId == currentNoteId }
                                        val hasAccess = request?.status == "APPROVED"

                                        Card(
                                            modifier = Modifier.fillMaxWidth(),
                                            colors = CardDefaults.cardColors(containerColor = MaterialTheme.colorScheme.surface)
                                        ) {
                                            Row(
                                                modifier = Modifier.padding(10.dp).fillMaxWidth(),
                                                horizontalArrangement = Arrangement.SpaceBetween,
                                                verticalAlignment = Alignment.CenterVertically
                                            ) {
                                                Column {
                                                    Text(student.fullName, fontSize = 12.sp, fontWeight = FontWeight.Bold)
                                                    Text("@${student.username}", fontSize = 10.sp, color = MaterialTheme.colorScheme.outline)
                                                }

                                                if (hasAccess) {
                                                    Button(
                                                        onClick = { 
                                                            viewModel.revokeNoteAccess(student.id, currentNoteId)
                                                        },
                                                        colors = ButtonDefaults.buttonColors(containerColor = MaterialTheme.colorScheme.error),
                                                        shape = RoundedCornerShape(8.dp),
                                                        contentPadding = PaddingValues(horizontal = 10.dp),
                                                        modifier = Modifier.height(30.dp)
                                                    ) {
                                                        Text("Revoke Access", fontSize = 10.sp)
                                                    }
                                                } else {
                                                    Button(
                                                        onClick = { 
                                                            viewModel.grantNoteAccessToUser(student.username, currentNoteId)
                                                        },
                                                        colors = ButtonDefaults.buttonColors(containerColor = Color(0xFF2E7D32)),
                                                        shape = RoundedCornerShape(8.dp),
                                                        contentPadding = PaddingValues(horizontal = 10.dp),
                                                        modifier = Modifier.height(30.dp)
                                                    ) {
                                                        Text("Grant Access", fontSize = 10.sp)
                                                    }
                                                }
                                            }
                                        }
                                    }
                                }
                            } else {
                                Text("Select a target study note above to enable manual access override controls.", fontSize = 11.sp, color = MaterialTheme.colorScheme.outline)
                            }
                        }
                    }
                }
            }

            // Section: Access requests queue
            item {
                Text(
                    text = "PENDING USER REQUISITIONS",
                    fontWeight = FontWeight.Bold,
                    fontSize = 12.sp,
                    letterSpacing = 1.sp,
                    color = MaterialTheme.colorScheme.primary,
                    modifier = Modifier.padding(top = 8.dp)
                )
            }

            val pendingRequests = accessRequests.filter { it.status == "PENDING" }
            if (pendingRequests.isEmpty()) {
                item {
                    Card(
                        modifier = Modifier.fillMaxWidth(),
                        colors = CardDefaults.cardColors(containerColor = MaterialTheme.colorScheme.surfaceVariant.copy(alpha = 0.2f))
                    ) {
                        Box(
                            modifier = Modifier.padding(20.dp).fillMaxWidth(),
                            contentAlignment = Alignment.Center
                        ) {
                            Text("No pending unlock requests from users.", fontSize = 12.sp, color = MaterialTheme.colorScheme.outline)
                        }
                    }
                }
            } else {
                items(pendingRequests) { req ->
                    val requester = allUsers.find { it.id == req.userId }
                    val paper = notes.find { it.id == req.noteId }

                    Card(
                        modifier = Modifier.fillMaxWidth(),
                        border = BorderStroke(1.dp, MaterialTheme.colorScheme.outlineVariant),
                        colors = CardDefaults.cardColors(containerColor = MaterialTheme.colorScheme.surface)
                    ) {
                        Column(
                            modifier = Modifier.padding(14.dp),
                            verticalArrangement = Arrangement.spacedBy(8.dp)
                        ) {
                            Text(
                                text = "Request from: ${requester?.fullName ?: "Unknown Student"} (@${requester?.username ?: "anon"})",
                                fontWeight = FontWeight.Bold,
                                fontSize = 13.sp
                            )
                            Text(
                                text = "Note requested: ${paper?.title ?: "Note #${req.noteId}"}",
                                fontSize = 12.sp,
                                color = MaterialTheme.colorScheme.outline
                            )
                            if (requester?.phoneNumber?.isNotEmpty() == true) {
                                Text(
                                    text = "Mobile Contact: ${requester.phoneNumber}",
                                    fontSize = 11.sp,
                                    fontWeight = FontWeight.Bold,
                                    color = MaterialTheme.colorScheme.primary
                                )
                            }

                            Row(
                                modifier = Modifier.fillMaxWidth().padding(top = 4.dp),
                                horizontalArrangement = Arrangement.spacedBy(10.dp)
                            ) {
                                Button(
                                    onClick = { viewModel.approveAccessRequest(req.userId, req.noteId) },
                                    colors = ButtonDefaults.buttonColors(containerColor = Color(0xFF2E7D32)),
                                    modifier = Modifier.weight(1f).height(36.dp),
                                    shape = RoundedCornerShape(8.dp)
                                ) {
                                    Text("Approve / Grant", fontSize = 11.sp, fontWeight = FontWeight.Bold, color = Color.White)
                                }

                                OutlinedButton(
                                    onClick = { viewModel.rejectAccessRequest(req.userId, req.noteId) },
                                    colors = ButtonDefaults.outlinedButtonColors(contentColor = MaterialTheme.colorScheme.error),
                                    modifier = Modifier.weight(1f).height(36.dp),
                                    shape = RoundedCornerShape(8.dp),
                                    border = BorderStroke(1.dp, MaterialTheme.colorScheme.error.copy(alpha = 0.4f))
                                ) {
                                    Text("Deny Access", fontSize = 11.sp, fontWeight = FontWeight.Bold)
                                }
                            }
                        }
                    }
                }
            }

            // Section: Current notes list with option to delete
            item {
                Text(
                    text = "ACTIVE PUBLISHED PAPERS",
                    fontWeight = FontWeight.Bold,
                    fontSize = 12.sp,
                    letterSpacing = 1.sp,
                    color = MaterialTheme.colorScheme.outline,
                    modifier = Modifier.padding(top = 12.dp)
                )
            }

            if (notes.isEmpty()) {
                item {
                    Text("No documents loaded yet.", fontSize = 12.sp, color = MaterialTheme.colorScheme.outline)
                }
            } else {
                items(notes) { n ->
                    Card(
                        modifier = Modifier.fillMaxWidth(),
                        colors = CardDefaults.cardColors(containerColor = MaterialTheme.colorScheme.surfaceVariant.copy(alpha = 0.2f))
                    ) {
                        Row(
                            modifier = Modifier.padding(14.dp).fillMaxWidth(),
                            horizontalArrangement = Arrangement.SpaceBetween,
                            verticalAlignment = Alignment.CenterVertically
                        ) {
                            Column(modifier = Modifier.weight(1f)) {
                                Text(n.title, fontWeight = FontWeight.Bold, fontSize = 13.sp)
                                Text(n.description, fontSize = 11.sp, maxLines = 1, color = MaterialTheme.colorScheme.outline)
                            }
                            IconButton(
                                onClick = { viewModel.deleteNote(n) },
                                modifier = Modifier.size(36.dp)
                            ) {
                                Icon(Icons.Filled.Delete, "Delete", tint = MaterialTheme.colorScheme.error, modifier = Modifier.size(20.dp))
                            }
                        }
                    }
                }
            }
        }
    }
}

// ==================== SCREEN: STUDYFEED (COMMUNITY STUDY CORNER) ====================
@Composable
fun ZoomableImageDialog(imageUri: String, onDismiss: () -> Unit) {
    androidx.compose.ui.window.Dialog(
        onDismissRequest = onDismiss,
        properties = androidx.compose.ui.window.DialogProperties(
            usePlatformDefaultWidth = false
        )
    ) {
        Box(
            modifier = Modifier
                .fillMaxSize()
                .background(Color.Black),
            contentAlignment = Alignment.Center
        ) {
            var scale by remember { mutableStateOf(1f) }
            var offset by remember { mutableStateOf(Offset.Zero) }
            
            val transformState = rememberTransformableState { zoomChange, offsetChange, _ ->
                scale = (scale * zoomChange).coerceIn(1f, 8f)
                if (scale > 1f) {
                    offset += offsetChange
                } else {
                    offset = Offset.Zero
                }
            }

            Box(
                modifier = Modifier
                    .fillMaxSize()
                    .pointerInput(Unit) {
                        detectTapGestures(onDoubleTap = {
                            if (scale > 1f) {
                                scale = 1f
                                offset = Offset.Zero
                            } else {
                                scale = 3f
                            }
                        })
                    }
                    .transformable(state = transformState)
            ) {
                androidx.compose.foundation.Image(
                    painter = coil.compose.rememberAsyncImagePainter(model = imageUri),
                    contentDescription = "Zoomed Attached graphic",
                    modifier = Modifier
                        .fillMaxSize()
                        .graphicsLayer(
                            scaleX = scale,
                            scaleY = scale,
                            translationX = offset.x,
                            translationY = offset.y
                        ),
                    contentScale = androidx.compose.ui.layout.ContentScale.Fit
                )
            }
            
            Row(
                modifier = Modifier
                    .fillMaxWidth()
                    .align(Alignment.TopCenter)
                    .windowInsetsPadding(WindowInsets.statusBars)
                    .padding(16.dp),
                horizontalArrangement = Arrangement.SpaceBetween,
                verticalAlignment = Alignment.CenterVertically
            ) {
                Row(verticalAlignment = Alignment.CenterVertically) {
                    Icon(Icons.Filled.ZoomIn, "Zoom indicator", tint = Color.White)
                    Spacer(modifier = Modifier.width(8.dp))
                    Text(
                        text = "Pinch to Zoom & Pan",
                        color = Color.White,
                        fontSize = 14.sp,
                        fontWeight = FontWeight.Bold
                    )
                }
                IconButton(
                    onClick = onDismiss,
                    modifier = Modifier.background(Color.Black.copy(alpha = 0.6f), CircleShape)
                ) {
                    Icon(
                        imageVector = Icons.Filled.Close,
                        contentDescription = "Close zoom view",
                        tint = Color.White
                    )
                }
            }
        }
    }
}

@Composable
fun StudyFeedScreen(viewModel: MainViewModel) {
    val posts by viewModel.allPosts.collectAsState()
    val loggedInUser by viewModel.loggedInUser.collectAsState()
    var postContent by remember { mutableStateOf("") }
    var selectedPostImageUri by remember { mutableStateOf("") }
    var filterStatus by remember { mutableStateOf("ALL") }
    var zoomedImageUri by remember { mutableStateOf<String?>(null) }

    val filteredPosts = remember(posts, filterStatus) {
        when (filterStatus) {
            "UNSOLVED" -> posts.filter { !it.isSolved }
            "SOLVED" -> posts.filter { it.isSolved }
            else -> posts
        }
    }

    val feedContext = androidx.compose.ui.platform.LocalContext.current
    val coroutineScope = androidx.compose.runtime.rememberCoroutineScope()
    val feedImagePickerLauncher = androidx.activity.compose.rememberLauncherForActivityResult(
        contract = androidx.activity.result.contract.ActivityResultContracts.GetContent()
    ) { uri: android.net.Uri? ->
        uri?.let {
            coroutineScope.launch {
                val savedPath = viewModel.uploadFileToSimulatedStorage(feedContext, it, "feed_images")
                if (savedPath != null) {
                    selectedPostImageUri = savedPath
                    viewModel.feedbackMessage.value = "Post graphic attached!"
                }
            }
        }
    }

    val micPermissionLauncher = androidx.activity.compose.rememberLauncherForActivityResult(
        contract = androidx.activity.result.contract.ActivityResultContracts.RequestPermission()
    ) { isGranted: Boolean ->
        if (isGranted) {
            viewModel.startVoiceRecording(feedContext)
        } else {
            viewModel.feedbackMessage.value = "Microphone permission is required to record audio notes."
        }
    }

    val isRecording by viewModel.isRecording.collectAsState()
    val currentRecordedFilePath by viewModel.currentRecordedFilePath.collectAsState()
    val activePlayingUrl by viewModel.activePlayingUrl.collectAsState()
    val isAudioPlaying by viewModel.isAudioPlaying.collectAsState()

    var activeCommentPostId by remember { mutableStateOf<Int?>(null) }

    val isDark = isSystemInDarkTheme()
    
    val themePrimary = Color(0xFF2563EB) 
    val themeSecondary = Color(0xFF4F46E5) 
    val themeAccentDarkBg = Color(0xFF1E293B) 
    
    val chatBgColor = if (isDark) Color(0xFF0F172A) else Color(0xFFF8FAFC)
    val cardFillColor = if (isDark) Color(0xFF1E293B) else Color.White
    val chatTextColor = if (isDark) Color(0xFFF1F5F9) else Color(0xFF0F172A)
    val subTextColor = if (isDark) Color(0xFF94A3B8) else Color(0xFF64748B)

    Scaffold(
        topBar = {
            Surface(
                color = if (isDark) Color(0xFF1E293B) else themePrimary,
                tonalElevation = 8.dp,
                shadowElevation = 4.dp,
                modifier = Modifier.fillMaxWidth()
            ) {
                Row(
                    modifier = Modifier
                        .fillMaxWidth()
                        .windowInsetsPadding(WindowInsets.statusBars)
                        .padding(horizontal = 16.dp, vertical = 14.dp),
                    verticalAlignment = Alignment.CenterVertically
                ) {
                    IconButton(
                        onClick = { viewModel.navigateBack() },
                        modifier = Modifier
                            .clip(CircleShape)
                            .background(Color.White.copy(alpha = 0.15f))
                            .size(36.dp)
                    ) {
                        Icon(
                            imageVector = Icons.AutoMirrored.Filled.ArrowBack,
                            contentDescription = "Back",
                            tint = Color.White,
                            modifier = Modifier.size(18.dp)
                        )
                    }
                    
                    Spacer(modifier = Modifier.width(12.dp))
                    
                    Box(
                        modifier = Modifier
                            .size(42.dp)
                            .clip(RoundedCornerShape(12.dp))
                            .background(Color.White.copy(alpha = 0.2f)),
                        contentAlignment = Alignment.Center
                    ) {
                        Text("📚", fontSize = 22.sp)
                    }
                    
                    Spacer(modifier = Modifier.width(12.dp))
                    
                    Column(modifier = Modifier.weight(1f)) {
                        Text(
                            text = "NayaRasta Study Corner",
                            fontWeight = FontWeight.ExtraBold,
                            color = Color.White,
                            fontSize = 18.sp,
                            letterSpacing = 0.5.sp
                        )
                        Row(
                            verticalAlignment = Alignment.CenterVertically,
                            horizontalArrangement = Arrangement.spacedBy(4.dp)
                        ) {
                            Box(
                                modifier = Modifier
                                    .size(6.dp)
                                    .clip(CircleShape)
                                    .background(Color(0xFF4ADE80))
                            )
                            Text(
                                text = "Ask questions • Voice walkthroughs • Live",
                                color = Color.White.copy(alpha = 0.85f),
                                fontSize = 11.sp,
                                fontWeight = FontWeight.Medium
                            )
                        }
                    }
                    
                    IconButton(
                        onClick = { viewModel.feedbackMessage.value = "Welcome to the real educational discussion space!" },
                        modifier = Modifier
                            .clip(CircleShape)
                            .background(Color.White.copy(alpha = 0.1f))
                            .size(36.dp)
                    ) {
                        Icon(Icons.Filled.Group, "Connected users", tint = Color.White, modifier = Modifier.size(18.dp))
                    }
                }
            }
        },
        bottomBar = {
            Surface(
                modifier = Modifier
                    .fillMaxWidth()
                    .windowInsetsPadding(WindowInsets.navigationBars),
                color = if (isDark) Color(0xFF1E293B) else Color.White,
                tonalElevation = 8.dp,
                shadowElevation = 8.dp
            ) {
                Column(
                    modifier = Modifier
                        .fillMaxWidth()
                        .padding(horizontal = 12.dp, vertical = 10.dp)
                ) {
                    if (currentRecordedFilePath != null || selectedPostImageUri.isNotEmpty()) {
                        Row(
                            modifier = Modifier
                                .fillMaxWidth()
                                .padding(bottom = 8.dp)
                                .clip(RoundedCornerShape(12.dp))
                                .background(if (isDark) Color(0xFF0F172A) else Color(0xFFF1F5F9))
                                .padding(horizontal = 12.dp, vertical = 8.dp),
                            verticalAlignment = Alignment.CenterVertically,
                            horizontalArrangement = Arrangement.spacedBy(8.dp)
                        ) {
                            Text(
                                "Payload Preview:",
                                fontSize = 11.sp,
                                fontWeight = FontWeight.Bold,
                                color = themePrimary
                            )
                            
                            if (currentRecordedFilePath != null) {
                                val isDraftPlaying = activePlayingUrl == currentRecordedFilePath && isAudioPlaying
                                Row(
                                    modifier = Modifier
                                        .clip(RoundedCornerShape(8.dp))
                                        .background(themeSecondary.copy(alpha = 0.15f))
                                        .padding(horizontal = 10.dp, vertical = 5.dp),
                                    verticalAlignment = Alignment.CenterVertically
                                ) {
                                    IconButton(
                                        onClick = {
                                            if (isDraftPlaying) viewModel.stopVoicePlayback()
                                            else viewModel.playVoiceAudio(currentRecordedFilePath!!)
                                        },
                                        modifier = Modifier.size(24.dp)
                                    ) {
                                        Icon(
                                            if (isDraftPlaying) Icons.Filled.PauseCircle else Icons.Filled.PlayCircle,
                                            null,
                                            tint = themeSecondary,
                                            modifier = Modifier.size(20.dp)
                                        )
                                    }
                                    Spacer(modifier = Modifier.width(4.dp))
                                    Text("Voice walkthrough 🎙️", fontSize = 11.sp, fontWeight = FontWeight.SemiBold, color = themeSecondary)
                                    Spacer(modifier = Modifier.width(6.dp))
                                    IconButton(
                                        onClick = { viewModel.deleteDraftRecording() },
                                        modifier = Modifier.size(20.dp)
                                    ) {
                                        Icon(Icons.Filled.Delete, "Delete", tint = Color.Red, modifier = Modifier.size(14.dp))
                                    }
                                }
                            }

                            if (selectedPostImageUri.isNotEmpty()) {
                                Row(
                                    modifier = Modifier
                                        .clip(RoundedCornerShape(8.dp))
                                        .background(themePrimary.copy(alpha = 0.15f))
                                        .padding(horizontal = 10.dp, vertical = 5.dp),
                                    verticalAlignment = Alignment.CenterVertically
                                ) {
                                    Icon(Icons.Filled.Image, null, tint = themePrimary, modifier = Modifier.size(14.dp))
                                    Spacer(modifier = Modifier.width(4.dp))
                                    Text("Photo attached", fontSize = 11.sp, fontWeight = FontWeight.SemiBold, color = themePrimary)
                                    Spacer(modifier = Modifier.width(6.dp))
                                    IconButton(
                                        onClick = { selectedPostImageUri = "" },
                                        modifier = Modifier.size(20.dp)
                                    ) {
                                        Icon(Icons.Filled.Close, "Remove", tint = Color.Red, modifier = Modifier.size(14.dp))
                                    }
                                }
                            }
                        }
                    }

                    Row(
                        modifier = Modifier.fillMaxWidth(),
                        verticalAlignment = Alignment.CenterVertically,
                        horizontalArrangement = Arrangement.spacedBy(10.dp)
                    ) {
                        IconButton(
                            onClick = { feedImagePickerLauncher.launch("image/*") },
                            modifier = Modifier
                                .background(if (isDark) Color(0xFF0F172A) else Color(0xFFF1F5F9), CircleShape)
                                .size(44.dp)
                        ) {
                            Icon(
                                imageVector = Icons.Filled.AddPhotoAlternate,
                                contentDescription = "Attach Question Image",
                                tint = themePrimary,
                                modifier = Modifier.size(22.dp)
                            )
                        }

                        Row(
                            modifier = Modifier
                                .weight(1f)
                                .clip(RoundedCornerShape(24.dp))
                                .border(1.dp, if (isDark) Color(0xFF334155) else Color(0xFFCBD5E1), RoundedCornerShape(24.dp))
                                .background(if (isDark) Color(0xFF0F172A) else Color(0xFFF8FAFC))
                                .padding(horizontal = 16.dp, vertical = 2.dp),
                            verticalAlignment = Alignment.CenterVertically
                        ) {
                            BasicTextField(
                                value = postContent,
                                onValueChange = { postContent = it },
                                textStyle = MaterialTheme.typography.bodyMedium.copy(color = chatTextColor),
                                modifier = Modifier
                                    .weight(1f)
                                    .padding(vertical = 10.dp),
                                maxLines = 4,
                                decorationBox = { innerTextField ->
                                    Box {
                                        if (postContent.isEmpty()) {
                                            Text(
                                                "Ask a question or explain your query...",
                                                color = subTextColor.copy(alpha = 0.8f),
                                                fontSize = 13.sp
                                            )
                                        }
                                        innerTextField()
                                    }
                                }
                            )
                        }

                        val micBg = if (isRecording) Color(0xFFEF4444) else themePrimary
                        Box(
                            modifier = Modifier
                                .size(44.dp)
                                .clip(CircleShape)
                                .background(micBg)
                                .clickable {
                                    if (isRecording) {
                                        viewModel.stopVoiceRecording(feedContext)
                                    } else {
                                        val hasMicPermission = androidx.core.content.ContextCompat.checkSelfPermission(
                                            feedContext,
                                            android.Manifest.permission.RECORD_AUDIO
                                        ) == android.content.pm.PackageManager.PERMISSION_GRANTED
                                        
                                        if (hasMicPermission) {
                                            viewModel.startVoiceRecording(feedContext)
                                        } else {
                                            micPermissionLauncher.launch(android.Manifest.permission.RECORD_AUDIO)
                                        }
                                    }
                                },
                            contentAlignment = Alignment.Center
                        ) {
                            Icon(
                                imageVector = if (isRecording) Icons.Filled.MicNone else Icons.Filled.Mic,
                                contentDescription = "Click to toggle mic",
                                tint = Color.White,
                                modifier = Modifier.size(20.dp)
                            )
                        }

                        val hasPayload = postContent.trim().isNotEmpty() || selectedPostImageUri.isNotEmpty() || currentRecordedFilePath != null
                        Box(
                            modifier = Modifier
                                .size(44.dp)
                                .clip(CircleShape)
                                .background(if (hasPayload) themeSecondary else Color.LightGray.copy(alpha = 0.4f))
                                .clickable(enabled = hasPayload) {
                                    viewModel.createPost(
                                        content = postContent,
                                        imageUri = selectedPostImageUri.ifEmpty { null },
                                        audioUri = currentRecordedFilePath
                                    )
                                    postContent = ""
                                    selectedPostImageUri = ""
                                    viewModel.currentRecordedFilePath.value = null
                                },
                            contentAlignment = Alignment.Center
                        ) {
                            Icon(
                                imageVector = Icons.Filled.Send,
                                contentDescription = "Post to Corner",
                                tint = Color.White,
                                modifier = Modifier.size(18.dp)
                            )
                        }
                    }
                    
                    if (isRecording) {
                        Text(
                            text = "🔴 Recording walk-through memo... Tap the red mic again when done!",
                            color = Color(0xFFEF4444),
                            fontSize = 11.sp,
                            fontWeight = FontWeight.Bold,
                            textAlign = androidx.compose.ui.text.style.TextAlign.Center,
                            modifier = Modifier
                                .fillMaxWidth()
                                .padding(top = 6.dp)
                        )
                    }
                }
            }
        },
        contentWindowInsets = WindowInsets.safeDrawing
    ) { padding ->
        LazyColumn(
            modifier = Modifier
                .fillMaxSize()
                .background(chatBgColor)
                .padding(padding)
                .padding(horizontal = 12.dp),
            verticalArrangement = Arrangement.spacedBy(12.dp),
            contentPadding = PaddingValues(top = 10.dp, bottom = 80.dp)
        ) {
            item {
                Row(
                    modifier = Modifier
                        .fillMaxWidth()
                        .padding(vertical = 8.dp),
                    horizontalArrangement = Arrangement.spacedBy(8.dp),
                    verticalAlignment = Alignment.CenterVertically
                ) {
                    listOf(
                        "ALL" to "All Questions 💬",
                        "UNSOLVED" to "Active Queries ❓",
                        "SOLVED" to "Solved Solutions ✅"
                    ).forEach { (status, label) ->
                        val isSelected = filterStatus == status
                        Box(
                            modifier = Modifier
                                .clip(RoundedCornerShape(12.dp))
                                .background(
                                    if (isSelected) themePrimary.copy(alpha = 0.15f)
                                    else if (isDark) Color(0xFF1E293B)
                                    else Color.White
                                )
                                .border(
                                    width = 1.2.dp,
                                    color = if (isSelected) themePrimary else if (isDark) Color(0xFF334155) else Color(0xFFE2E8F0),
                                    shape = RoundedCornerShape(12.dp)
                                )
                                .clickable { filterStatus = status }
                                .padding(horizontal = 14.dp, vertical = 9.dp)
                        ) {
                            Text(
                                text = label,
                                fontSize = 12.sp,
                                fontWeight = if (isSelected) FontWeight.ExtraBold else FontWeight.Medium,
                                color = if (isSelected) themePrimary else chatTextColor
                            )
                        }
                    }
                }
            }

            if (filteredPosts.isEmpty()) {
                item {
                    Box(
                        modifier = Modifier
                            .fillMaxWidth()
                            .padding(top = 40.dp),
                        contentAlignment = Alignment.Center
                    ) {
                        Card(
                            colors = CardDefaults.cardColors(containerColor = if (isDark) Color(0xFF1E293B) else Color.White),
                            modifier = Modifier.widthIn(max = 340.dp),
                            shape = RoundedCornerShape(20.dp),
                            elevation = CardDefaults.cardElevation(defaultElevation = 3.dp),
                            border = BorderStroke(1.dp, if (isDark) Color(0xFF334155) else Color(0xFFE2E8F0))
                        ) {
                            Column(
                                modifier = Modifier.padding(24.dp),
                                horizontalAlignment = Alignment.CenterHorizontally,
                                verticalArrangement = Arrangement.spacedBy(12.dp)
                            ) {
                                Text("💡", fontSize = 48.sp)
                                Text(
                                    text = if (filterStatus == "ALL") {
                                        "Welcome to the study feed room. Ask a question, paste or write doubt context, attach diagrams, and post voice walkthroughs to request peer solving!"
                                    } else {
                                        "No study questions match this filter category right now."
                                    },
                                    color = chatTextColor,
                                    fontSize = 13.sp,
                                    lineHeight = 18.sp,
                                    textAlign = androidx.compose.ui.text.style.TextAlign.Center,
                                    fontWeight = FontWeight.Medium
                                )
                                Text(
                                    text = "Be the first one to post a doubt to start the discussion!",
                                    color = subTextColor,
                                    fontSize = 11.sp,
                                    textAlign = androidx.compose.ui.text.style.TextAlign.Center
                                )
                            }
                        }
                    }
                }
            } else {
                items(filteredPosts) { post ->
                    val isMyPost = loggedInUser != null && loggedInUser?.id == post.userId
                    val isAdmin = loggedInUser != null && loggedInUser?.role == "ADMIN"
                    
                    Card(
                        modifier = Modifier
                            .fillMaxWidth()
                            .padding(vertical = 4.dp),
                        colors = CardDefaults.cardColors(
                            containerColor = cardFillColor
                        ),
                        shape = RoundedCornerShape(20.dp),
                        elevation = CardDefaults.cardElevation(defaultElevation = 2.dp),
                        border = if (isMyPost) BorderStroke(1.5.dp, themePrimary.copy(alpha = 0.5f)) else BorderStroke(1.dp, if (isDark) Color(0xFF334155) else Color(0xFFE2E8F0))
                    ) {
                        Column(
                            modifier = Modifier
                                .fillMaxWidth()
                                .padding(16.dp),
                            verticalArrangement = Arrangement.spacedBy(12.dp)
                        ) {
                            Row(
                                modifier = Modifier.fillMaxWidth(),
                                horizontalArrangement = Arrangement.SpaceBetween,
                                verticalAlignment = Alignment.CenterVertically
                            ) {
                                Row(
                                    verticalAlignment = Alignment.CenterVertically,
                                    horizontalArrangement = Arrangement.spacedBy(10.dp)
                                ) {
                                    Box(
                                        modifier = Modifier
                                            .size(38.dp)
                                            .clip(RoundedCornerShape(12.dp))
                                            .background(
                                                Brush.radialGradient(
                                                    colors = listOf(
                                                        Color(post.avatarColor),
                                                        Color(post.avatarColor).copy(alpha = 0.7f)
                                                    )
                                                )
                                            ),
                                        contentAlignment = Alignment.Center
                                    ) {
                                        Text(
                                            text = if (post.fullName.isNotEmpty()) post.fullName.take(1).uppercase() else "?",
                                            color = Color.White,
                                            fontWeight = FontWeight.ExtraBold,
                                            fontSize = 14.sp
                                        )
                                    }
                                    
                                    Column {
                                        Text(
                                            text = if (isMyPost) "You" else post.fullName,
                                            fontWeight = FontWeight.ExtraBold,
                                            fontSize = 14.sp,
                                            color = if (isMyPost) themePrimary else chatTextColor
                                        )
                                        Text(
                                            text = java.text.SimpleDateFormat("MMM dd, HH:mm", java.util.Locale.getDefault()).format(post.createdAt),
                                            fontSize = 11.sp,
                                            fontWeight = FontWeight.Medium,
                                            color = subTextColor
                                        )
                                    }
                                }
                                
                                Row(
                                    verticalAlignment = Alignment.CenterVertically,
                                    horizontalArrangement = Arrangement.spacedBy(6.dp)
                                ) {
                                    val isTagged = post.content.contains("@")
                                    if (isTagged) {
                                        Surface(
                                            color = themeSecondary.copy(alpha = 0.12f),
                                            shape = RoundedCornerShape(6.dp)
                                        ) {
                                            Text(
                                                text = "🏷️ Tagged",
                                                color = themeSecondary,
                                                fontSize = 9.sp,
                                                fontWeight = FontWeight.Bold,
                                                modifier = Modifier.padding(horizontal = 6.dp, vertical = 3.dp)
                                            )
                                        }
                                    }

                                    if (post.isSolved) {
                                        val solvedLabel = if (post.isClosedByAdmin) "CLOSED ✅" else "SOLVED ✅"
                                        val solvedBg = if (post.isClosedByAdmin) Color(0xFFFFEBEE) else Color(0xFFE8F5E9)
                                        val solvedText = if (post.isClosedByAdmin) Color(0xFFC62828) else Color(0xFF2E7D32)
                                        Surface(
                                            color = solvedBg,
                                            shape = RoundedCornerShape(6.dp)
                                        ) {
                                            Text(
                                                text = solvedLabel,
                                                color = solvedText,
                                                fontSize = 9.sp,
                                                fontWeight = FontWeight.Bold,
                                                modifier = Modifier.padding(horizontal = 6.dp, vertical = 3.dp)
                                            )
                                        }
                                    }
                                    
                                    val canMarkSolved = isAdmin || (isMyPost && !post.isClosedByAdmin)
                                    if (canMarkSolved) {
                                        IconButton(
                                            onClick = {
                                                if (post.isClosedByAdmin) {
                                                    viewModel.feedbackMessage.value = "Permanently locked by management! Cannot reopen."
                                                } else {
                                                    val shouldSolve = !post.isSolved
                                                    viewModel.markPostSolved(
                                                        post = post,
                                                        isSolved = shouldSolve,
                                                        isClosedByAdmin = shouldSolve && isAdmin
                                                    )
                                                }
                                            },
                                            modifier = Modifier
                                                .background(if (isDark) Color(0xFF1E293B) else Color(0xFFF1F5F9), CircleShape)
                                                .size(28.dp)
                                        ) {
                                            Icon(
                                                imageVector = if (post.isClosedByAdmin) Icons.Filled.Lock else if (post.isSolved) Icons.Filled.LockOpen else Icons.Filled.CheckCircle,
                                                contentDescription = "Lock/Solve status",
                                                tint = if (post.isClosedByAdmin) Color(0xFFC62828) else if (post.isSolved) Color(0xFF2E7D32) else Color.Gray,
                                                modifier = Modifier.size(16.dp)
                                            )
                                        }
                                    }

                                    if (isMyPost || isAdmin) {
                                        IconButton(
                                            onClick = { viewModel.deletePost(post) },
                                            modifier = Modifier
                                                .background(Color(0xFFFFEBEE), CircleShape)
                                                .size(28.dp)
                                        ) {
                                            Icon(
                                                imageVector = Icons.Filled.DeleteOutline,
                                                contentDescription = "Delete Question",
                                                tint = Color(0xFFC62828),
                                                modifier = Modifier.size(16.dp)
                                            )
                                        }
                                    }
                                }
                            }

                            if (post.content.isNotEmpty()) {
                                val annotatedString = androidx.compose.ui.text.buildAnnotatedString {
                                    val words = post.content.split(" ")
                                    words.forEachIndexed { idx, word ->
                                        if (word.startsWith("@") && word.length > 1) {
                                            pushStyle(
                                                androidx.compose.ui.text.SpanStyle(
                                                    color = themePrimary,
                                                    fontWeight = FontWeight.ExtraBold,
                                                    background = themePrimary.copy(alpha = 0.12f)
                                                )
                                            )
                                            append(word)
                                            pop()
                                        } else {
                                            append(word)
                                        }
                                        if (idx < words.size - 1) append(" ")
                                    }
                                }
                                Text(
                                    text = annotatedString,
                                    fontSize = 15.sp,
                                    lineHeight = 20.sp,
                                    color = chatTextColor,
                                    fontWeight = FontWeight.Normal,
                                    modifier = Modifier.padding(vertical = 2.dp)
                                )
                            }

                            if (post.audioUri != null) {
                                val isCurrentVoicePlaying = isAudioPlaying && activePlayingUrl == post.audioUri
                                
                                Row(
                                    modifier = Modifier
                                        .fillMaxWidth()
                                        .clip(RoundedCornerShape(16.dp))
                                        .background(if (isDark) Color(0xFF0F172A) else Color(0xFFF1F5F9))
                                        .border(1.dp, if (isDark) Color(0xFF334155) else Color(0xFFE2E8F0), RoundedCornerShape(16.dp))
                                        .padding(12.dp),
                                    verticalAlignment = Alignment.CenterVertically,
                                    horizontalArrangement = Arrangement.spacedBy(12.dp)
                                ) {
                                    IconButton(
                                        onClick = {
                                            if (isCurrentVoicePlaying) viewModel.stopVoicePlayback()
                                            else viewModel.playVoiceAudio(post.audioUri)
                                        },
                                        modifier = Modifier
                                            .background(themePrimary, CircleShape)
                                            .size(38.dp)
                                    ) {
                                        Icon(
                                            imageVector = if (isCurrentVoicePlaying) Icons.Filled.PauseCircle else Icons.Filled.PlayCircle,
                                            contentDescription = "Play Question walk-through note",
                                            tint = Color.White,
                                            modifier = Modifier.size(24.dp)
                                        )
                                    }

                                    Column(modifier = Modifier.weight(1f)) {
                                        Text(
                                            text = "Microphone Walkthrough Explain 🎙️",
                                            fontSize = 12.sp,
                                            fontWeight = FontWeight.Bold,
                                            color = chatTextColor
                                        )
                                        Text(
                                            text = if (isCurrentVoicePlaying) "Now playing..." else "Tap to hear speech explanation",
                                            fontSize = 10.sp,
                                            color = subTextColor
                                        )
                                        
                                        val progressPct = if (isCurrentVoicePlaying) 0.5f else 0f
                                        LinearProgressIndicator(
                                            progress = { progressPct },
                                            modifier = Modifier
                                                .fillMaxWidth()
                                                .padding(top = 6.dp)
                                                .height(4.dp)
                                                .clip(CircleShape),
                                            color = themePrimary,
                                            trackColor = if (isDark) Color(0xFF1E293B) else Color(0xFFE2E8F0)
                                        )
                                    }
                                }
                            }

                            if (!post.imageUri.isNullOrEmpty()) {
                                Card(
                                    modifier = Modifier
                                        .fillMaxWidth()
                                        .height(200.dp)
                                        .clickable { zoomedImageUri = post.imageUri },
                                    shape = RoundedCornerShape(16.dp),
                                    border = BorderStroke(1.dp, if (isDark) Color(0xFF334155) else Color(0xFFE2E8F0))
                                ) {
                                    Box(modifier = Modifier.fillMaxSize()) {
                                        androidx.compose.foundation.Image(
                                            painter = coil.compose.rememberAsyncImagePainter(model = post.imageUri),
                                            contentDescription = "Attached diagram graph zoomable",
                                            modifier = Modifier.fillMaxSize(),
                                            contentScale = androidx.compose.ui.layout.ContentScale.Crop
                                        )
                                        Box(
                                            modifier = Modifier
                                                .align(Alignment.BottomEnd)
                                                .padding(10.dp)
                                                .background(Color.Black.copy(alpha = 0.65f), RoundedCornerShape(10.dp))
                                                .padding(horizontal = 8.dp, vertical = 4.dp)
                                        ) {
                                            Row(
                                                verticalAlignment = Alignment.CenterVertically,
                                                horizontalArrangement = Arrangement.spacedBy(4.dp)
                                            ) {
                                                Icon(Icons.Filled.ZoomIn, null, tint = Color.White, modifier = Modifier.size(12.dp))
                                                Text("Tap to Zoom", color = Color.White, fontSize = 10.sp, fontWeight = FontWeight.Bold)
                                            }
                                        }
                                    }
                                }
                            }

                            Divider(color = if (isDark) Color(0xFF334155) else Color(0xFFF1F5F9), thickness = 1.dp)

                            Row(
                                modifier = Modifier.fillMaxWidth(),
                                horizontalArrangement = Arrangement.SpaceBetween,
                                verticalAlignment = Alignment.CenterVertically
                            ) {
                                Row(horizontalArrangement = Arrangement.spacedBy(20.dp)) {
                                    Row(
                                        modifier = Modifier
                                            .clip(RoundedCornerShape(8.dp))
                                            .clickable { viewModel.togglePostLike(post.id) }
                                            .padding(horizontal = 8.dp, vertical = 4.dp),
                                        verticalAlignment = Alignment.CenterVertically,
                                        horizontalArrangement = Arrangement.spacedBy(6.dp)
                                    ) {
                                        Icon(
                                            imageVector = Icons.Filled.ThumbUp, 
                                            contentDescription = "Like icon",
                                            tint = themePrimary,
                                            modifier = Modifier.size(18.dp)
                                        )
                                        Text(
                                            text = "${post.likeCount}",
                                            fontSize = 13.sp,
                                            fontWeight = FontWeight.Bold,
                                            color = chatTextColor
                                        )
                                    }

                                    Row(
                                        modifier = Modifier
                                            .clip(RoundedCornerShape(8.dp))
                                            .clickable {
                                                activeCommentPostId = if (activeCommentPostId == post.id) null else post.id
                                            }
                                            .padding(horizontal = 8.dp, vertical = 4.dp),
                                        verticalAlignment = Alignment.CenterVertically,
                                        horizontalArrangement = Arrangement.spacedBy(6.dp)
                                    ) {
                                        Icon(
                                            imageVector = Icons.Filled.Comment, 
                                            contentDescription = "Comment button",
                                            tint = themeSecondary,
                                            modifier = Modifier.size(18.dp)
                                        )
                                        Text(
                                            text = "${post.commentCount}",
                                            fontSize = 13.sp,
                                            fontWeight = FontWeight.Bold,
                                            color = chatTextColor
                                        )
                                    }
                                }

                                if (isMyPost) {
                                    Row(
                                        verticalAlignment = Alignment.CenterVertically,
                                        horizontalArrangement = Arrangement.spacedBy(4.dp)
                                    ) {
                                        Icon(
                                            imageVector = Icons.Filled.DoneAll,
                                            contentDescription = "Synced successfully",
                                            tint = Color(0xFF10B981),
                                            modifier = Modifier.size(16.dp)
                                        )
                                        Text(
                                            text = "Synced",
                                            fontSize = 11.sp,
                                            fontWeight = FontWeight.Bold,
                                            color = Color(0xFF10B981)
                                        )
                                    }
                                }
                            }

                            if (activeCommentPostId == post.id) {
                                Box(
                                    modifier = Modifier
                                        .fillMaxWidth()
                                        .clip(RoundedCornerShape(16.dp))
                                        .background(if (isDark) Color(0xFF0F172A) else Color(0xFFF8FAFC))
                                        .border(1.dp, if (isDark) Color(0xFF1E293B) else Color(0xFFE2E8F0), RoundedCornerShape(16.dp))
                                        .padding(12.dp)
                                ) {
                                    CommentSection(viewModel = viewModel, post = post, currentUser = loggedInUser)
                                }
                            }
                        }
                    }
                }
            }
        }
    }

    zoomedImageUri?.let { uri ->
        ZoomableImageDialog(imageUri = uri, onDismiss = { zoomedImageUri = null })
    }
}

@Composable
fun CommentSection(
    viewModel: MainViewModel,
    post: Post,
    currentUser: User?
) {
    val comments by viewModel.getCommentsForPost(post.id).collectAsState(initial = emptyList())
    var commentText by remember { mutableStateOf("") }
    var replyToCommentId by remember { mutableStateOf<Int?>(null) }
    var replyToUser by remember { mutableStateOf<String?>(null) }

    val isAdmin = currentUser?.role == "ADMIN"

    Column(verticalArrangement = Arrangement.spacedBy(8.dp)) {
        if (post.isSolved) {
            Card(
                colors = CardDefaults.cardColors(
                    containerColor = MaterialTheme.colorScheme.surfaceVariant.copy(alpha = 0.5f)
                ),
                shape = RoundedCornerShape(10.dp),
                modifier = Modifier.fillMaxWidth()
            ) {
                Row(
                    modifier = Modifier.padding(12.dp),
                    horizontalArrangement = Arrangement.spacedBy(8.dp),
                    verticalAlignment = Alignment.CenterVertically
                ) {
                    Icon(
                        imageVector = Icons.Filled.Lock,
                        contentDescription = "Post Closed",
                        tint = MaterialTheme.colorScheme.outline,
                        modifier = Modifier.size(16.dp)
                    )
                    Text(
                        text = "This query is marked solved/closed. Comments & replies are locked.",
                        fontSize = 11.sp,
                        color = MaterialTheme.colorScheme.outline,
                        fontWeight = FontWeight.Medium
                    )
                }
            }
        } else {
            // Add comment/reply form
            Row(
                modifier = Modifier.fillMaxWidth(),
                horizontalArrangement = Arrangement.spacedBy(6.dp),
                verticalAlignment = Alignment.CenterVertically
            ) {
                OutlinedTextField(
                    value = commentText,
                    onValueChange = { commentText = it },
                    placeholder = { 
                        Text(
                            text = if (replyToUser != null) "Reply to @$replyToUser..." else "Write helpful reply...", 
                            fontSize = 11.sp
                        ) 
                    },
                    modifier = Modifier.weight(1f),
                    shape = RoundedCornerShape(10.dp),
                    singleLine = true,
                    trailingIcon = {
                        if (replyToUser != null) {
                            IconButton(onClick = {
                                replyToCommentId = null
                                replyToUser = null
                            }) {
                                Icon(Icons.Filled.Close, "Cancel", modifier = Modifier.size(16.dp))
                            }
                        }
                    }
                )
                Button(
                    onClick = {
                        if (commentText.trim().isEmpty()) return@Button
                        viewModel.addComment(post.id, commentText, parentCommentId = replyToCommentId)
                        commentText = ""
                        replyToCommentId = null
                        replyToUser = null
                    },
                    shape = RoundedCornerShape(8.dp),
                    contentPadding = PaddingValues(horizontal = 10.dp)
                ) {
                    Text("Send", fontSize = 11.sp)
                }
            }
        }

        Text("Class Replies (${comments.size}):", fontSize = 11.sp, fontWeight = FontWeight.Bold, color = MaterialTheme.colorScheme.outline)

        // Draw comment tree beautifully
        val mainComments = comments.filter { it.parentCommentId == null }
        mainComments.forEach { parentComment ->
            CommentItem(
                comment = parentComment,
                onReplyClick = if (post.isSolved) null else {
                    {
                        replyToCommentId = parentComment.id
                        replyToUser = parentComment.username
                    }
                },
                onDeleteClick = if (isAdmin || currentUser?.id == parentComment.userId) {
                    { viewModel.deleteComment(parentComment) }
                } else null
            )

            // Draw child replies nested under this parent
            val childReplies = comments.filter { it.parentCommentId == parentComment.id }
            childReplies.forEach { childComment ->
                Row(
                    modifier = Modifier
                        .fillMaxWidth()
                        .padding(start = 24.dp, top = 2.dp, bottom = 2.dp)
                ) {
                    Text(
                        text = "↳",
                        fontSize = 14.sp,
                        fontWeight = FontWeight.ExtraBold,
                        color = MaterialTheme.colorScheme.outline.copy(alpha = 0.5f),
                        modifier = Modifier.padding(end = 4.dp, top = 2.dp)
                    )
                    Box(modifier = Modifier.weight(1f)) {
                        CommentItem(
                            comment = childComment,
                            onReplyClick = if (post.isSolved) null else {
                                {
                                    replyToCommentId = parentComment.id // Keep nesting under parent
                                    replyToUser = childComment.username
                                }
                            },
                            onDeleteClick = if (isAdmin || currentUser?.id == childComment.userId) {
                                { viewModel.deleteComment(childComment) }
                            } else null
                        )
                    }
                }
            }
        }
    }
}

@Composable
fun CommentItem(
    comment: Comment,
    onReplyClick: (() -> Unit)? = null,
    onDeleteClick: (() -> Unit)? = null
) {
    Card(
        shape = RoundedCornerShape(12.dp),
        colors = CardDefaults.cardColors(containerColor = MaterialTheme.colorScheme.surfaceVariant.copy(alpha = 0.4f)),
        modifier = Modifier.fillMaxWidth()
    ) {
        Column(modifier = Modifier.padding(10.dp)) {
            Row(
                verticalAlignment = Alignment.CenterVertically,
                horizontalArrangement = Arrangement.spacedBy(8.dp)
            ) {
                // Profile picture/initials
                Box(
                    modifier = Modifier
                        .size(28.dp)
                        .clip(CircleShape)
                        .background(Color(if (comment.avatarColor != 0) comment.avatarColor else 0xFF005FB0.toInt())),
                    contentAlignment = Alignment.Center
                ) {
                    if (!comment.profileImageUri.isNullOrEmpty()) {
                        androidx.compose.foundation.Image(
                            painter = coil.compose.rememberAsyncImagePainter(model = comment.profileImageUri),
                            contentDescription = "Comment avatar",
                            modifier = Modifier.fillMaxSize(),
                            contentScale = androidx.compose.ui.layout.ContentScale.Crop
                        )
                    } else {
                        Text(
                            text = comment.fullName.firstOrNull()?.uppercase() ?: "S",
                            fontSize = 10.sp,
                            color = Color.White,
                            fontWeight = FontWeight.Bold
                        )
                    }
                }

                Column(modifier = Modifier.weight(1f)) {
                    Text(
                        text = comment.fullName,
                        fontSize = 11.sp,
                        fontWeight = FontWeight.Bold,
                        color = MaterialTheme.colorScheme.onSurface
                    )
                    Text(
                        text = "@${comment.username}",
                        fontSize = 9.sp,
                        color = MaterialTheme.colorScheme.outline
                    )
                }

                Row(
                    horizontalArrangement = Arrangement.spacedBy(4.dp),
                    verticalAlignment = Alignment.CenterVertically
                ) {
                    if (onReplyClick != null) {
                        TextButton(
                            onClick = onReplyClick,
                            contentPadding = PaddingValues(0.dp),
                            modifier = Modifier.height(24.dp)
                        ) {
                            Text("Reply", fontSize = 10.sp, fontWeight = FontWeight.Bold)
                        }
                    }
                    if (onDeleteClick != null) {
                        IconButton(
                            onClick = onDeleteClick,
                            modifier = Modifier.size(24.dp)
                        ) {
                            Icon(
                                imageVector = Icons.Filled.Delete,
                                contentDescription = "Delete comment",
                                tint = MaterialTheme.colorScheme.error,
                                modifier = Modifier.size(14.dp)
                            )
                        }
                    }
                }
            }

            Spacer(modifier = Modifier.height(4.dp))

            Text(
                text = comment.content,
                fontSize = 11.sp,
                color = MaterialTheme.colorScheme.onSurfaceVariant,
                modifier = Modifier.padding(start = 2.dp)
            )
        }
    }
}

// ==================== SCREEN: USER PROFILE (STUDENT EDIT DECK) ====================
@Composable
fun UserProfileScreen(viewModel: MainViewModel) {
    val loggedInUser by viewModel.loggedInUser.collectAsState()
    val activeStyle by viewModel.activeDesignStyle.collectAsState()
    val privacySettings by viewModel.loggedInUserPrivacySettings.collectAsState()
    var editMode by remember { mutableStateOf(false) }

    var fullName by remember { mutableStateOf("") }
    var username by remember { mutableStateOf("") }
    var phoneNumber by remember { mutableStateOf("") }
    var selectedStudentType by remember { mutableStateOf("Fresher") }
    var selectedGradeLevel by remember { mutableStateOf("Pre-Medical / FSc Part 1") }
    var selectedStudyGoal by remember { mutableStateOf("MDCAT") }
    var profileImageUri by remember { mutableStateOf("") }
    var isUploadingImage by remember { mutableStateOf(false) }

    // Password change popup dialog state
    var showChangePasswordDialog by remember { mutableStateOf(false) }
    var changePassCurrent by remember { mutableStateOf("") }
    var changePassNew1 by remember { mutableStateOf("") }
    var changePassNew2 by remember { mutableStateOf("") }
    var changePassCurrentVisible by remember { mutableStateOf(false) }
    var changePassNew1Visible by remember { mutableStateOf(false) }
    var changePassNew2Visible by remember { mutableStateOf(false) }
    var changePassErrorMsg by remember { mutableStateOf("") }

    val context = androidx.compose.ui.platform.LocalContext.current
    val coroutineScope = androidx.compose.runtime.rememberCoroutineScope()
    val imagePickerLauncher = androidx.activity.compose.rememberLauncherForActivityResult(
        contract = androidx.activity.result.contract.ActivityResultContracts.GetContent()
    ) { uri: android.net.Uri? ->
        uri?.let {
            coroutineScope.launch {
                isUploadingImage = true
                try {
                    val savedPath = viewModel.uploadFileToSimulatedStorage(context, it, "profiles")
                    if (savedPath != null) {
                        profileImageUri = savedPath
                        viewModel.feedbackMessage.value = "Profile image selected!"
                    }
                } finally {
                    isUploadingImage = false
                }
            }
        }
    }

    LaunchedEffect(loggedInUser) {
        loggedInUser?.let {
            fullName = it.fullName
            username = it.username
            phoneNumber = it.phoneNumber
            selectedStudentType = if (it.studentType.isEmpty()) "Fresher" else it.studentType
            selectedGradeLevel = if (it.gradeLevel.isEmpty()) "Pre-Medical / FSc Part 1" else it.gradeLevel
            selectedStudyGoal = if (it.studyGoal.isEmpty()) "MDCAT" else it.studyGoal
            profileImageUri = it.profileImageUri ?: ""
        }
    }

    Scaffold(
        topBar = {
            Column(
                modifier = Modifier
                    .fillMaxWidth()
                    .padding(horizontal = 20.dp, vertical = 12.dp)
            ) {
                Text(
                    text = "My Student Desk",
                    fontSize = 22.sp,
                    fontWeight = FontWeight.ExtraBold,
                    color = MaterialTheme.colorScheme.primary
                )
                Text(
                    text = "Manage credentials, review contact info and update repeater details.",
                    fontSize = 11.sp,
                    color = MaterialTheme.colorScheme.onSurfaceVariant
                )
            }
        },
        contentWindowInsets = WindowInsets.safeDrawing
    ) { paddingVal ->
        loggedInUser?.let { user ->
            LazyColumn(
                modifier = Modifier
                    .fillMaxSize()
                    .padding(paddingVal)
                    .padding(horizontal = 20.dp),
                verticalArrangement = Arrangement.spacedBy(16.dp),
                contentPadding = PaddingValues(bottom = 32.dp)
            ) {
                item {
                    PremiumStyleContainer(
                        style = activeStyle,
                        modifier = Modifier.fillMaxWidth(),
                        containerColor = MaterialTheme.colorScheme.surface
                    ) {
                        Column(
                            modifier = Modifier.padding(20.dp),
                            horizontalAlignment = Alignment.CenterHorizontally,
                            verticalArrangement = Arrangement.spacedBy(12.dp)
                        ) {
                            // Avatar header
                            Box(
                                modifier = Modifier
                                    .size(84.dp)
                                    .clip(CircleShape)
                                    .background(Color(if (user.avatarColor != 0) user.avatarColor else 0xFF625B71.toInt())),
                                contentAlignment = Alignment.Center
                            ) {
                                if (!user.profileImageUri.isNullOrEmpty()) {
                                    androidx.compose.foundation.Image(
                                        painter = coil.compose.rememberAsyncImagePainter(model = user.profileImageUri),
                                        contentDescription = "User profile picture",
                                        modifier = Modifier.fillMaxSize(),
                                        contentScale = androidx.compose.ui.layout.ContentScale.Crop
                                    )
                                } else {
                                    val initial = user.username.firstOrNull()?.uppercase() ?: "S"
                                    Text(
                                        text = initial,
                                        fontSize = 28.sp,
                                        fontWeight = FontWeight.Bold,
                                        color = Color.White
                                    )
                                }
                            }

                            Text(
                                text = user.fullName,
                                fontSize = 18.sp,
                                fontWeight = FontWeight.Bold,
                                color = MaterialTheme.colorScheme.onSurface
                            )

                            Badge(containerColor = MaterialTheme.colorScheme.primaryContainer) {
                                Text(
                                    text = if (user.studentType.isEmpty()) "Fresher" else user.studentType.uppercase(),
                                    fontWeight = FontWeight.Bold,
                                    color = MaterialTheme.colorScheme.onPrimaryContainer,
                                    fontSize = 10.sp,
                                    modifier = Modifier.padding(horizontal = 8.dp, vertical = 2.dp)
                                )
                            }
                        }
                    }
                }

                if (!editMode) {
                    item {
                        PremiumStyleContainer(
                            style = activeStyle,
                            modifier = Modifier.fillMaxWidth(),
                            containerColor = MaterialTheme.colorScheme.surface
                        ) {
                            Column(
                                modifier = Modifier.padding(16.dp),
                                verticalArrangement = Arrangement.spacedBy(12.dp)
                            ) {
                                ProfileInfoRow(label = "Primary email address", value = user.email, icon = Icons.Filled.Email)
                                ProfileInfoRow(label = "Phone registration contact", value = user.phoneNumber.ifEmpty { "None recorded" }, icon = Icons.Filled.Phone)
                                ProfileInfoRow(label = "Global username", value = "@${user.username}", icon = Icons.Filled.Person)
                                ProfileInfoRow(label = "Student base type", value = user.studentType.ifEmpty { "Fresher" }, icon = Icons.Filled.School)

                                Button(
                                    onClick = { editMode = true },
                                    modifier = Modifier
                                        .fillMaxWidth()
                                        .padding(top = 8.dp),
                                    shape = RoundedCornerShape(12.dp)
                                ) {
                                    Row(
                                        verticalAlignment = Alignment.CenterVertically,
                                        horizontalArrangement = Arrangement.spacedBy(6.dp)
                                    ) {
                                        Icon(Icons.Filled.Edit, "Edit Profile")
                                        Text("Edit Profile Details", fontWeight = FontWeight.Bold)
                                    }
                                }
                            }
                        }
                    }

                    item {
                        PremiumStyleContainer(
                            style = activeStyle,
                            modifier = Modifier.fillMaxWidth(),
                            containerColor = MaterialTheme.colorScheme.surface
                        ) {
                            Column(
                                modifier = Modifier.padding(16.dp),
                                verticalArrangement = Arrangement.spacedBy(12.dp)
                            ) {
                                Text(
                                    text = "🔒 Profile Privacy & Visibility",
                                    fontWeight = FontWeight.Bold,
                                    fontSize = 16.sp,
                                    color = MaterialTheme.colorScheme.primary
                                )
                                Text(
                                    text = "Configure what other students can see when they search for your profile.",
                                    fontSize = 12.sp,
                                    color = MaterialTheme.colorScheme.onSurfaceVariant
                                )

                                HorizontalDivider(color = MaterialTheme.colorScheme.outlineVariant)

                                // Public switch
                                Row(
                                    modifier = Modifier.fillMaxWidth(),
                                    horizontalArrangement = Arrangement.SpaceBetween,
                                    verticalAlignment = Alignment.CenterVertically
                                ) {
                                    Column(modifier = Modifier.weight(1f)) {
                                        Text("Allow Profile Searches", fontWeight = FontWeight.SemiBold, fontSize = 14.sp)
                                        Text("Let other students find you in student search list.", fontSize = 11.sp, color = Color.Gray)
                                    }
                                    Switch(
                                        checked = privacySettings.isProfilePublic,
                                        onCheckedChange = {
                                            viewModel.updateLoggedInUserPrivacy(privacySettings.copy(isProfilePublic = it))
                                        }
                                    )
                                }

                                if (privacySettings.isProfilePublic) {
                                    HorizontalDivider(color = MaterialTheme.colorScheme.outlineVariant)

                                    // Granular options
                                    PrivacyToggleRow(
                                        title = "Hide Profile Image",
                                        subtitle = "Show a text initial avatar instead of your image to other students.",
                                        checked = privacySettings.hideProfileImage,
                                        onCheckedChange = {
                                            viewModel.updateLoggedInUserPrivacy(privacySettings.copy(hideProfileImage = it))
                                        }
                                    )

                                    PrivacyToggleRow(
                                        title = "Hide Full Name",
                                        subtitle = "Show only your @username to other students.",
                                        checked = privacySettings.hideFullName,
                                        onCheckedChange = {
                                            viewModel.updateLoggedInUserPrivacy(privacySettings.copy(hideFullName = it))
                                        }
                                    )

                                    PrivacyToggleRow(
                                        title = "Hide Email",
                                        subtitle = "Do not display your primary email address.",
                                        checked = privacySettings.hideEmail,
                                        onCheckedChange = {
                                            viewModel.updateLoggedInUserPrivacy(privacySettings.copy(hideEmail = it))
                                        }
                                    )

                                    PrivacyToggleRow(
                                        title = "Hide Phone Number",
                                        subtitle = "Do not display your registered phone number.",
                                        checked = privacySettings.hidePhoneNumber,
                                        onCheckedChange = {
                                            viewModel.updateLoggedInUserPrivacy(privacySettings.copy(hidePhoneNumber = it))
                                        }
                                    )

                                    PrivacyToggleRow(
                                        title = "Hide TSR Report",
                                        subtitle = "Do not display today's situation reports.",
