                                        onCheckedChange = {
                                            viewModel.updateLoggedInUserPrivacy(privacySettings.copy(hideTsr = it))
                                        }
                                    )

                                    PrivacyToggleRow(
                                        title = "Hide Leaderboard Rank",
                                        subtitle = "Do not show your MDCAT global leader rank.",
                                        checked = privacySettings.hideLeaderboard,
                                        onCheckedChange = {
                                            viewModel.updateLoggedInUserPrivacy(privacySettings.copy(hideLeaderboard = it))
                                        }
                                    )

                                    PrivacyToggleRow(
                                        title = "Hide Quiz History Reports",
                                        subtitle = "Do not list your last 5 quiz performance cards.",
                                        checked = privacySettings.hideQuizReports,
                                        onCheckedChange = {
                                            viewModel.updateLoggedInUserPrivacy(privacySettings.copy(hideQuizReports = it))
                                        }
                                    )
                                }
                            }
                        }
                    }
                } else {
                    item {
                        PremiumStyleContainer(
                            style = activeStyle,
                            modifier = Modifier.fillMaxWidth(),
                            containerColor = MaterialTheme.colorScheme.surface
                        ) {
                            Column(
                                modifier = Modifier.padding(16.dp),
                                verticalArrangement = Arrangement.spacedBy(12.dp)
                            ) {
                                Text("Edit NayaRasta Profile", fontWeight = FontWeight.Bold, fontSize = 14.sp)

                                OutlinedTextField(
                                    value = fullName,
                                    onValueChange = { fullName = it },
                                    label = { Text("Full Name") },
                                    singleLine = true,
                                    modifier = Modifier.fillMaxWidth(),
                                    shape = RoundedCornerShape(10.dp)
                                )

                                OutlinedTextField(
                                    value = phoneNumber,
                                    onValueChange = { input ->
                                        val cleaned = input.filter { it.isDigit() }
                                        if (cleaned.length <= 11) {
                                            phoneNumber = cleaned
                                        }
                                    },
                                    label = { Text("Phone Number") },
                                    singleLine = true,
                                    modifier = Modifier.fillMaxWidth(),
                                    shape = RoundedCornerShape(10.dp)
                                )

                                OutlinedButton(
                                    onClick = {
                                        changePassCurrent = ""
                                        changePassNew1 = ""
                                        changePassNew2 = ""
                                        changePassErrorMsg = ""
                                        showChangePasswordDialog = true
                                    },
                                    modifier = Modifier.fillMaxWidth(),
                                    shape = RoundedCornerShape(10.dp)
                                ) {
                                    Icon(
                                        imageVector = Icons.Filled.Lock,
                                        contentDescription = "Change Password",
                                        tint = MaterialTheme.colorScheme.primary
                                    )
                                    Spacer(modifier = Modifier.width(8.dp))
                                    Text("Change Password Security (Popup)", fontWeight = FontWeight.Bold)
                                }

                                NayaRastaDropdown(
                                    label = "Student Type",
                                    options = listOf("Fresher", "Repeater"),
                                    selectedOption = selectedStudentType,
                                    onOptionSelected = { selectedStudentType = it }
