                                NayaRastaDropdown(
                                    label = "Study Goal / Target Exam",
                                    options = listOf(
                                        "MDCAT",
                                        "NUMS",
                                        "AKU",
                                        "Board Exams",
                                        "Other"
                                    ),
                                    selectedOption = selectedStudyGoal,
                                    onOptionSelected = { selectedStudyGoal = it }
                                )

                                Column(
                                    modifier = Modifier
                                        .fillMaxWidth()
                                        .padding(vertical = 4.dp),
                                    verticalArrangement = Arrangement.spacedBy(8.dp),
                                    horizontalAlignment = Alignment.CenterHorizontally
                                ) {
                                    Box(
                                        modifier = Modifier
                                            .size(80.dp)
                                            .clip(CircleShape)
                                            .background(MaterialTheme.colorScheme.primaryContainer),
