// ==================== SCREEN: TUTORIAL SCREEN ====================
@Composable
fun TutorialScreen(viewModel: MainViewModel) {
    val context = androidx.compose.ui.platform.LocalContext.current
    val isDark = isSystemInDarkTheme()
    
    // We have 7 slides as requested
    var currentSlideIndex by remember { mutableStateOf(0) }
    
    val slides = listOf(
        TutorialSlideData(
            title = "Welcome to ${viewModel.getAppName()}",
            description = "${viewModel.getAppName()} is your primary entry test prep companion. Learn Physics, Chemistry, Biology, and other subjects seamlessly under our curated interactive guides.",
            icon = Icons.Filled.School,
            backgroundColor = if (isDark) Color(0xFF0F172A) else Color(0xFFEFF6FF)
        ),
        TutorialSlideData(
            title = "Organized Subjects & Topics",
            description = "Each subject is divided into key chapters and micro-topics. Dive deep into targeted concept lists, study notes, and master specific course syllabus areas step-by-step.",
            icon = Icons.Filled.MenuBook,
            backgroundColor = if (isDark) Color(0xFF1E1B4B) else Color(0xFFEEF2F6)
        ),
        TutorialSlideData(
            title = "Interactive Quizzes",
            description = "Test your skills with our ultra-fast practice engines. Customize question count, pick systematic or randomized order, and play quizzes under real exam-style timers.",
            icon = Icons.Filled.PlayArrow,
            backgroundColor = if (isDark) Color(0xFF14532D) else Color(0xFFF0FDF4)
        ),
        TutorialSlideData(
            title = "Step-By-Step Progress",
            description = "Never lose track of your progress. Live dashboards display grade level accuracy, streak milestones, correct answer distributions, and visual achievement badges.",
            icon = Icons.Filled.Analytics,
            backgroundColor = if (isDark) Color(0xFF701A75) else Color(0xFFFDF4FF)
        ),
        TutorialSlideData(
            title = "Premium PDF Study Notes",
            description = "Gain digital access to direct subject matter keys and downloadable hand-crafted reference notes. Read them offline for quick revision before entering the exam room.",
            icon = Icons.Filled.PictureAsPdf,
            backgroundColor = if (isDark) Color(0xFF0369A1) else Color(0xFFF0F9FF)
        ),
        TutorialSlideData(
            title = "Dynamic Community Feed",
            description = "Contribute or browse our study feed. Share text and photo questions, explain tricky concepts in comment boards, save feed templates, or share posts directly with friends.",
            icon = Icons.Filled.Forum,
            backgroundColor = if (isDark) Color(0xFF7C2D12) else Color(0xFFFFF7ED)
        ),
        TutorialSlideData(
            title = "Add & Submit MCQs",
            description = "Submit your own quality practice multiple-choice questions to our database. Provide 4 options, a logical description, and subject/topic tags for a chance to earn rewards!",
            icon = Icons.Filled.Add,
            backgroundColor = if (isDark) Color(0xFF0F172A) else Color(0xFFF8FAFC)
        )
    )
    
    val slide = slides[currentSlideIndex]
    
    fun onFinishTutorial() {
        val prefs = context.getSharedPreferences("NayaRastaPrefs", android.content.Context.MODE_PRIVATE)
        prefs.edit().putBoolean("has_seen_tutorial", true).apply()
        viewModel.navigateTo(Screen.Login)
    }
    
    Scaffold(
        modifier = Modifier.fillMaxSize(),
        containerColor = slide.backgroundColor
    ) { paddingValues ->
        Column(
            modifier = Modifier
                .fillMaxSize()
                .padding(paddingValues)
                .padding(24.dp),
            verticalArrangement = Arrangement.SpaceBetween,
            horizontalAlignment = Alignment.CenterHorizontally
        ) {
            // Header Row: Skip Button
            Row(
                modifier = Modifier.fillMaxWidth(),
                horizontalArrangement = Arrangement.End
            ) {
                if (currentSlideIndex < 6) {
                    TextButton(
                        onClick = { onFinishTutorial() },
                        modifier = Modifier.testTag("tutorial_skip_button")
                    ) {
                        Text(
                            text = "Skip",
                            fontSize = 15.sp,
                            fontWeight = FontWeight.Bold,
                            color = if (isDark) Color.White.copy(alpha = 0.6f) else MaterialTheme.colorScheme.primary
                        )
                    }
                } else {
                    Spacer(modifier = Modifier.height(36.dp))
                }
            }
            
            // Middle Column: Icon + Title + Description
            Column(
                horizontalAlignment = Alignment.CenterHorizontally,
                verticalArrangement = Arrangement.spacedBy(16.dp),
                modifier = Modifier
                    .weight(1f)
                    .fillMaxWidth()
                    .verticalScroll(rememberScrollState())
                    .padding(horizontal = 8.dp)
            ) {
                Spacer(modifier = Modifier.weight(0.1f))
                
                // Pulsing Icon Frame
                Box(
                    modifier = Modifier
                        .size(140.dp)
                        .clip(RoundedCornerShape(32.dp))
                        .background(
                            if (isDark) Color.White.copy(alpha = 0.08f)
                            else MaterialTheme.colorScheme.primary.copy(alpha = 0.12f)
                        ),
                    contentAlignment = Alignment.Center
                ) {
                    Icon(
                        imageVector = slide.icon,
                        contentDescription = "Slide icon",
                        tint = if (isDark) Color.White else MaterialTheme.colorScheme.primary,
                        modifier = Modifier.size(72.dp)
                    )
                }
                
                Spacer(modifier = Modifier.height(12.dp))
                
                // Slide Title
                Text(
                    text = slide.title,
                    fontSize = 24.sp,
                    fontWeight = FontWeight.ExtraBold,
                    color = if (isDark) Color.White else Color(0xFF1E293B),
                    textAlign = TextAlign.Center,
                    style = MaterialTheme.typography.headlineMedium
                )
                
                // Slide Description
                Text(
                    text = slide.description,
                    fontSize = 15.sp,
                    lineHeight = 22.sp,
                    color = if (isDark) Color.White.copy(alpha = 0.7f) else Color(0xFF475569),
                    textAlign = TextAlign.Center,
                    modifier = Modifier.padding(horizontal = 16.dp),
                    style = MaterialTheme.typography.bodyMedium
                )
                
                Spacer(modifier = Modifier.weight(0.2f))
            }
            
            // Bottom Section: Progress indicators & Next button
            Column(
                modifier = Modifier.fillMaxWidth(),
                horizontalAlignment = Alignment.CenterHorizontally,
                verticalArrangement = Arrangement.spacedBy(24.dp)
            ) {
                // Progress Dots Indicator
                Row(
                    horizontalArrangement = Arrangement.spacedBy(8.dp),
                    verticalAlignment = Alignment.CenterVertically
                ) {
                    repeat(7) { index ->
                        Box(
                            modifier = Modifier
                                .size(width = if (index == currentSlideIndex) 20.dp else 8.dp, height = 8.dp)
                                .clip(RoundedCornerShape(4.dp))
                                .background(
                                    if (index == currentSlideIndex) {
                                        if (isDark) Color.White else MaterialTheme.colorScheme.primary
                                    } else {
                                        if (isDark) Color.White.copy(alpha = 0.2f) else Color(0xFFCBD5E1)
                                    }
                                )
                        )
                    }
                }
                
                // Next / Get Started Action Button
                Button(
                    onClick = {
                        if (currentSlideIndex < 6) {
                            currentSlideIndex++
                        } else {
                            onFinishTutorial()
                        }
                    },
                    modifier = Modifier
                        .fillMaxWidth()
                        .height(54.dp)
                        .testTag("tutorial_next_button"),
                    shape = RoundedCornerShape(16.dp),
                    colors = ButtonDefaults.buttonColors(
                        containerColor = if (isDark) Color.White else MaterialTheme.colorScheme.primary,
                        contentColor = if (isDark) Color.Black else Color.White
                    )
                ) {
                    Text(
                        text = if (currentSlideIndex == 6) "Get Started" else "Next Slide",
                        fontSize = 16.sp,
                        fontWeight = FontWeight.Bold
                    )
                    Spacer(modifier = Modifier.width(6.dp))
                    Icon(
                        imageVector = Icons.Filled.ArrowForward,
                        contentDescription = "Forward"
                    )
                }
            }
        }
    }
}

data class TutorialSlideData(
    val title: String,
    val description: String,
    val icon: androidx.compose.ui.graphics.vector.ImageVector,
    val backgroundColor: androidx.compose.ui.graphics.Color
)

// ==================== SCREEN: SPLASH SCREEN ====================
@Composable
fun SplashScreen(viewModel: MainViewModel) {
    val context = androidx.compose.ui.platform.LocalContext.current
    LaunchedEffect(Unit) {
        kotlinx.coroutines.delay(2000)
        val prefs = context.getSharedPreferences("NayaRastaPrefs", android.content.Context.MODE_PRIVATE)
        val hasSeenTutorial = prefs.getBoolean("has_seen_tutorial", false)
        if (!hasSeenTutorial) {
            viewModel.navigateTo(Screen.Tutorial)
        } else {
            viewModel.checkAutoLogin { success ->
                if (!success) {
                    viewModel.navigateTo(Screen.Login)
                }
            }
        }
    }
    Box(
        modifier = Modifier
            .fillMaxSize()
            .background(
                Brush.verticalGradient(
                    colors = listOf(
                        MaterialTheme.colorScheme.primaryContainer.copy(alpha = 0.2f),
                        MaterialTheme.colorScheme.background
                    )
                )
            ),
        contentAlignment = Alignment.Center
    ) {
        Column(
            horizontalAlignment = Alignment.CenterHorizontally,
            verticalArrangement = Arrangement.spacedBy(16.dp)
        ) {
            androidx.compose.foundation.layout.Box(
                modifier = Modifier
                    .size(120.dp)
                    .clip(RoundedCornerShape(28.dp))
                    .background(androidx.compose.ui.graphics.Color.White)
                    .padding(10.dp),
                contentAlignment = androidx.compose.ui.Alignment.Center
            ) {
                val splashUrl = viewModel.getSplashScreenUrl()
                val logoUrl = viewModel.getAppLogoUrl()
                val imageToLoad = splashUrl ?: logoUrl
                if (imageToLoad != null) {
                    androidx.compose.foundation.Image(
                        painter = coil.compose.rememberAsyncImagePainter(model = imageToLoad),
                        contentDescription = "App Splash Image",
                        modifier = Modifier.fillMaxSize(),
                        contentScale = androidx.compose.ui.layout.ContentScale.Fit
                    )
                } else {
                    androidx.compose.foundation.Image(
                        painter = androidx.compose.ui.res.painterResource(id = com.example.R.drawable.logo),
                        contentDescription = "App Splash Image",
                        modifier = Modifier.fillMaxSize(),
                        contentScale = androidx.compose.ui.layout.ContentScale.Fit
                    )
                }
            }
            Spacer(modifier = Modifier.height(4.dp))
            Text(
                text = viewModel.getAppName(),
                fontSize = 32.sp,
                fontWeight = FontWeight.ExtraBold,
                color = MaterialTheme.colorScheme.primary,
                letterSpacing = 1.sp
            )
            Text(
                text = "Till Entry, Till Victory",
                fontSize = 14.sp,
                fontWeight = FontWeight.SemiBold,
                color = MaterialTheme.colorScheme.outline
            )
            Spacer(modifier = Modifier.height(32.dp))
            CircularProgressIndicator(
                color = MaterialTheme.colorScheme.primary,
                modifier = Modifier.size(36.dp)
            )
        }
    }
}

@Composable
fun AnimatedEntranceContainer(
    index: Int = 0,
    delayMultiplier: Int = 50,
    content: @Composable () -> Unit
) {
    var visible by remember { mutableStateOf(false) }
    LaunchedEffect(Unit) {
        kotlinx.coroutines.delay((index * delayMultiplier).toLong())
        visible = true
    }
    AnimatedVisibility(
        visible = visible,
        enter = slideInVertically(
            initialOffsetY = { 30 },
            animationSpec = spring(stiffness = Spring.StiffnessLow, dampingRatio = Spring.DampingRatioMediumBouncy)
        ) + fadeIn(animationSpec = tween(200)),
        exit = fadeOut(animationSpec = tween(120))
    ) {
        content()
    }
}

// ==================== SCREEN: LEADERBOARD ====================
data class LeaderRankItem(
    val user: User,
    val testsAttempted: Int,
    val successRate: Int,
    val totalScore: Int,
    val levelName: String,
    val levelNumber: Int,
    val streak: Int
)

@OptIn(ExperimentalLayoutApi::class)
@Composable
fun LeaderboardScreen(viewModel: MainViewModel) {
    val users by viewModel.allUsers.collectAsState()
    val allResults by viewModel.allTestResults.collectAsState()
    var selectedPeriod by remember { mutableStateOf("Overall") } // "Weekly", "Monthly", "Overall"

    // Filter results based on selected period
    val periodResults = remember(allResults, selectedPeriod) {
        val now = System.currentTimeMillis()
        when (selectedPeriod) {
            "Weekly" -> allResults.filter { it.timestamp >= now - 7 * 24 * 3600 * 1000L }
            "Monthly" -> allResults.filter { it.timestamp >= now - 30 * 24 * 3600 * 1000L }
            else -> allResults
        }
    }

    // Aggregate user scores
    val rankedList = remember(users, periodResults, allResults) {
        users.filter { it.role == "USER" }.map { user ->
            val userResults = periodResults.filter { it.userId == user.id }
            val totalResults = allResults.filter { it.userId == user.id }
            val levelInfo = viewModel.calculateUserLevel(user, totalResults)
            
            val testsCount = userResults.size
            val correctCount = userResults.sumOf { it.correctAnswers }
            val totalQuestions = userResults.sumOf { it.totalQuestions }
            
            val successRate = if (totalQuestions > 0) {
                (correctCount.toFloat() / totalQuestions * 100f).toInt()
            } else 0

            val totalScore = userResults.sumOf { it.scorePercentage.toInt() }
            
            LeaderRankItem(
                user = user,
                testsAttempted = testsCount,
                successRate = successRate,
                totalScore = totalScore,
                levelName = levelInfo.levelName,
                levelNumber = levelInfo.levelNumber,
                streak = user.currentStreak
            )
        }.sortedWith(compareByDescending<LeaderRankItem> { it.totalScore }.thenByDescending { it.successRate })
    }

    Scaffold(
        topBar = {
            Column(
                modifier = Modifier
                    .fillMaxWidth()
                    .padding(horizontal = 20.dp, vertical = 12.dp),
                verticalArrangement = Arrangement.spacedBy(4.dp)
            ) {
                Row(
                    modifier = Modifier.fillMaxWidth(),
                    verticalAlignment = Alignment.CenterVertically,
                    horizontalArrangement = Arrangement.spacedBy(10.dp)
                ) {
                    IconButton(onClick = { viewModel.navigateBack() }) {
                        Icon(Icons.AutoMirrored.Filled.ArrowBack, "Back")
                    }
                    Text(
                        text = "NayaRasta Leaderboard",
                        fontSize = 20.sp,
                        fontWeight = FontWeight.Bold,
                        color = MaterialTheme.colorScheme.primary
                    )
                }
                Text(
                    text = "Weekly, monthly and overall rank listings based on test performance.",
                    fontSize = 11.sp,
                    color = MaterialTheme.colorScheme.onSurfaceVariant
                )
                
                // Period tabs
                Row(
                    modifier = Modifier.fillMaxWidth().padding(top = 10.dp),
                    horizontalArrangement = Arrangement.spacedBy(8.dp)
                ) {
                    listOf("Overall", "Weekly", "Monthly").forEach { period ->
                        val isSelected = selectedPeriod == period
                        val contentColor = if (isSelected) MaterialTheme.colorScheme.onPrimary else MaterialTheme.colorScheme.onSurfaceVariant
                        val containerColor = if (isSelected) MaterialTheme.colorScheme.primary else MaterialTheme.colorScheme.surfaceVariant.copy(alpha = 0.5f)
                        
                        Box(
                            modifier = Modifier
                                .weight(1f)
                                .clip(RoundedCornerShape(20.dp))
                                .background(containerColor)
                                .clickable { selectedPeriod = period }
                                .padding(vertical = 8.dp),
                            contentAlignment = Alignment.Center
                        ) {
                            Text(period, fontSize = 12.sp, fontWeight = FontWeight.Bold, color = contentColor)
                        }
                    }
                }
            }
        }
    ) { padding ->
        LazyColumn(
            modifier = Modifier
                .fillMaxSize()
                .padding(padding)
                .padding(horizontal = 20.dp),
            verticalArrangement = Arrangement.spacedBy(12.dp),
            contentPadding = PaddingValues(bottom = 32.dp)
        ) {
            if (rankedList.isEmpty()) {
                item {
                    Box(
                        modifier = Modifier
                            .fillMaxWidth()
                            .padding(top = 64.dp),
                        contentAlignment = Alignment.Center
                    ) {
                        Text(
                            text = "No submissions recorded for this period yet.",
                            color = MaterialTheme.colorScheme.outline,
                            fontSize = 14.sp
                        )
                    }
                }
            } else {
                // High Performers Podium
                item {
                    val podiumList = rankedList.take(3)
                    Row(
                        modifier = Modifier
                            .fillMaxWidth()
                            .padding(vertical = 12.dp),
                        horizontalArrangement = Arrangement.spacedBy(8.dp),
                        verticalAlignment = Alignment.Bottom
                    ) {
                        // 2nd Place
                        if (podiumList.size > 1) {
                            PodiumWidget(
                                rankItem = podiumList[1],
                                rank = 2,
                                height = 120.dp,
                                color = Color(0xFFAEB2B5),
                                trophy = "🥈",
                                modifier = Modifier.weight(1f)
                            )
                        }
                        // 1st Place
                        if (podiumList.isNotEmpty()) {
                            PodiumWidget(
                                rankItem = podiumList[0],
                                rank = 1,
                                height = 150.dp,
                                color = Color(0xFFFFD700),
                                trophy = "🏆",
                                modifier = Modifier.weight(1.2f)
                            )
                        }
                        // 3rd Place
                        if (podiumList.size > 2) {
                            PodiumWidget(
                                rankItem = podiumList[2],
                                rank = 3,
                                height = 100.dp,
                                color = Color(0xFFCD7F32),
                                trophy = "🥉",
                                modifier = Modifier.weight(1f)
                            )
                        }
                    }
                }

                if (rankedList.size > 3) {
                    item {
                        Column {
                            Text(
                                "Top Academic Contenders",
                                fontWeight = FontWeight.Bold,
                                fontSize = 14.sp,
                                color = MaterialTheme.colorScheme.primary,
                                modifier = Modifier.padding(top = 16.dp, bottom = 8.dp)
                            )
                            // Tabular header
                            Row(
                                modifier = Modifier
                                    .fillMaxWidth()
                                    .background(MaterialTheme.colorScheme.surfaceVariant.copy(alpha = 0.5f), shape = RoundedCornerShape(8.dp))
                                    .padding(horizontal = 12.dp, vertical = 8.dp),
                                verticalAlignment = Alignment.CenterVertically
                            ) {
                                Text("#", fontWeight = FontWeight.Bold, fontSize = 11.sp, color = MaterialTheme.colorScheme.outline, modifier = Modifier.weight(0.5f), textAlign = TextAlign.Center)
                                Text("Student", fontWeight = FontWeight.Bold, fontSize = 11.sp, color = MaterialTheme.colorScheme.outline, modifier = Modifier.weight(1.8f))
                                Text("Tests", fontWeight = FontWeight.Bold, fontSize = 11.sp, color = MaterialTheme.colorScheme.outline, modifier = Modifier.weight(1.0f), textAlign = TextAlign.Center)
                                Text("Acc", fontWeight = FontWeight.Bold, fontSize = 11.sp, color = MaterialTheme.colorScheme.outline, modifier = Modifier.weight(1.0f), textAlign = TextAlign.Center)
                                Text("Points", fontWeight = FontWeight.Bold, fontSize = 11.sp, color = MaterialTheme.colorScheme.outline, modifier = Modifier.weight(1.0f), textAlign = TextAlign.End)
                            }
                        }
                    }

                    items(rankedList.drop(3)) { rankItem ->
                        val index = rankedList.indexOf(rankItem) + 1
                        AnimatedEntranceContainer(index = index) {
                            Card(
                                modifier = Modifier.fillMaxWidth(),
                                shape = RoundedCornerShape(8.dp),
                                colors = CardDefaults.cardColors(containerColor = MaterialTheme.colorScheme.surface),
                                border = BorderStroke(1.dp, MaterialTheme.colorScheme.outlineVariant.copy(alpha = 0.5f))
                            ) {
                                Row(
                                    modifier = Modifier
                                        .fillMaxWidth()
                                        .padding(vertical = 10.dp, horizontal = 12.dp),
                                    verticalAlignment = Alignment.CenterVertically
                                ) {
                                    // Rank
                                    Text(
                                        text = "$index",
                                        fontWeight = FontWeight.ExtraBold,
                                        fontSize = 12.sp,
                                        color = MaterialTheme.colorScheme.onSurfaceVariant,
                                        modifier = Modifier.weight(0.5f),
                                        textAlign = TextAlign.Center
                                    )

                                    // Student Details (Avatar + Name & Subtitle Level)
                                    Row(
                                        modifier = Modifier.weight(1.8f),
                                        verticalAlignment = Alignment.CenterVertically,
                                        horizontalArrangement = Arrangement.spacedBy(8.dp)
                                    ) {
                                        Box(
                                            modifier = Modifier
                                                .size(30.dp)
                                                .clip(CircleShape)
                                                .background(MaterialTheme.colorScheme.primaryContainer),
                                            contentAlignment = Alignment.Center
                                        ) {
                                            if (!rankItem.user.profileImageUri.isNullOrEmpty()) {
                                                androidx.compose.foundation.Image(
                                                    painter = coil.compose.rememberAsyncImagePainter(model = rankItem.user.profileImageUri),
                                                    contentDescription = "avatar",
                                                    modifier = Modifier.fillMaxSize(),
                                                    contentScale = androidx.compose.ui.layout.ContentScale.Crop
                                                )
                                            } else {
                                                Text(
                                                    text = rankItem.user.fullName.firstOrNull()?.uppercase() ?: "S",
                                                    color = MaterialTheme.colorScheme.onPrimaryContainer,
                                                    fontWeight = FontWeight.Bold,
                                                    fontSize = 11.sp
                                                )
                                            }
                                        }
                                        Column {
                                            Text(
                                                text = rankItem.user.fullName,
                                                fontWeight = FontWeight.Bold,
                                                fontSize = 12.sp,
                                                maxLines = 1,
                                                overflow = TextOverflow.Ellipsis
                                            )
                                            Text(
                                                text = "LVL ${rankItem.levelNumber} - ${rankItem.levelName}",
                                                fontSize = 9.sp,
                                                color = MaterialTheme.colorScheme.outline,
                                                fontWeight = FontWeight.SemiBold,
                                                maxLines = 1,
                                                overflow = TextOverflow.Ellipsis
                                            )
                                        }
                                    }

                                    // Tests count
                                    Box(modifier = Modifier.weight(1.0f), contentAlignment = Alignment.Center) {
                                        Text(
                                            text = "${rankItem.testsAttempted}",
                                            fontWeight = FontWeight.SemiBold,
                                            fontSize = 12.sp,
                                            color = MaterialTheme.colorScheme.onSurface
                                        )
                                    }

                                    // Accuracy
                                    Box(modifier = Modifier.weight(1.0f), contentAlignment = Alignment.Center) {
                                        Text(
                                            text = "${rankItem.successRate}%",
                                            fontWeight = FontWeight.Bold,
                                            fontSize = 12.sp,
                                            color = MaterialTheme.colorScheme.primary
                                        )
                                    }

                                    // Points
                                    Text(
                                        text = "${rankItem.totalScore} pts",
                                        fontWeight = FontWeight.ExtraBold,
                                        fontSize = 12.sp,
                                        color = MaterialTheme.colorScheme.secondary,
                                        modifier = Modifier.weight(1.0f),
                                        textAlign = TextAlign.End
                                    )
                                }
                            }
                        }
                    }
                }
            }
        }
    }
}

@Composable
fun PodiumWidget(
    rankItem: LeaderRankItem,
    rank: Int,
    height: androidx.compose.ui.unit.Dp,
    color: Color,
    trophy: String,
    modifier: Modifier = Modifier
) {
    var startAnimate by remember { mutableStateOf(false) }
    LaunchedEffect(Unit) {
        startAnimate = true
    }
    val animatedHeight by animateDpAsState(
        targetValue = if (startAnimate) (height + 124.dp) else 0.dp,
        animationSpec = spring(stiffness = Spring.StiffnessLow, dampingRatio = Spring.DampingRatioMediumBouncy)
    )

    Card(
        modifier = modifier.height(animatedHeight),
        shape = RoundedCornerShape(24.dp),
        colors = CardDefaults.cardColors(containerColor = MaterialTheme.colorScheme.surface),
        border = BorderStroke(2.dp, color)
    ) {
        Column(
            modifier = Modifier
                .fillMaxSize()
                .padding(12.dp),
            horizontalAlignment = Alignment.CenterHorizontally,
            verticalArrangement = Arrangement.SpaceBetween
        ) {
            // Trophy Badge
            Row(
                verticalAlignment = Alignment.CenterVertically,
                horizontalArrangement = Arrangement.spacedBy(4.dp)
            ) {
                Text(trophy, fontSize = 18.sp)
                Box(
                    modifier = Modifier
                        .size(24.dp)
                        .clip(CircleShape)
                        .background(color),
                    contentAlignment = Alignment.Center
                ) {
                    Text(
                        text = rank.toString(),
                        color = Color.White,
                        fontWeight = FontWeight.Black,
                        fontSize = 12.sp
                    )
                }
            }

            // Profile Image
            Box(
                modifier = Modifier
                    .size(54.dp)
                    .clip(CircleShape)
                    .background(MaterialTheme.colorScheme.primaryContainer),
                contentAlignment = Alignment.Center
            ) {
                if (!rankItem.user.profileImageUri.isNullOrEmpty()) {
                    androidx.compose.foundation.Image(
                        painter = coil.compose.rememberAsyncImagePainter(model = rankItem.user.profileImageUri),
                        contentDescription = "avatar",
                        modifier = Modifier.fillMaxSize(),
                        contentScale = androidx.compose.ui.layout.ContentScale.Crop
                    )
                } else {
                    Text(
                        text = rankItem.user.fullName.firstOrNull()?.uppercase() ?: "S",
                        fontWeight = FontWeight.Bold,
                        color = MaterialTheme.colorScheme.onPrimaryContainer,
                        fontSize = 16.sp
                    )
                }
            }

            // Name and Scores
            Column(horizontalAlignment = Alignment.CenterHorizontally) {
                Text(
                    text = rankItem.user.fullName,
                    fontWeight = FontWeight.Bold,
                    fontSize = 12.sp,
                    maxLines = 1,
                    overflow = TextOverflow.Ellipsis
                )
                Text(
                    text = "Lvl ${rankItem.levelNumber}",
                    fontWeight = FontWeight.SemiBold,
                    fontSize = 10.sp,
                    color = MaterialTheme.colorScheme.outline
                )
                Text(
                    text = "${rankItem.successRate}% Success",
                    fontSize = 11.sp,
                    color = MaterialTheme.colorScheme.primary,
                    fontWeight = FontWeight.ExtraBold
                )
                Text(
                    text = "${rankItem.totalScore} pts",
                    fontSize = 10.sp,
                    color = MaterialTheme.colorScheme.outline
                )
                Text(
                    text = "${rankItem.testsAttempted} Tests Completed",
                    fontSize = 9.sp,
                    color = MaterialTheme.colorScheme.outline,
                    fontWeight = FontWeight.Bold
                )
            }
        }
    }
}

// ==================== SCREEN: REPORTS SECTION ====================
@Composable
fun ReportsScreen(viewModel: MainViewModel) {
    val context = LocalContext.current
    val loggedInUser by viewModel.loggedInUser.collectAsState()
    val allUsers by viewModel.allUsers.collectAsState()
    val allResults by viewModel.allTestResults.collectAsState()

    var selectedUserId by remember { mutableStateOf<Int?>(null) }
    var selectedSubjectId by remember { mutableStateOf<Int?>(null) }
    var selectedTopicId by remember { mutableStateOf<Int?>(null) }
    var showReportViewerUser by remember { mutableStateOf<com.example.data.model.User?>(null) }
    
    val subjects by viewModel.allSubjects.collectAsState()
    val topics by viewModel.allTopics.collectAsState()

    // Enforce matching selected user for non-admins
    val activeUser = loggedInUser
    val isAdmin = activeUser?.role == "ADMIN"
    
    LaunchedEffect(activeUser) {
        if (activeUser != null && !isAdmin) {
            selectedUserId = activeUser.id
        }
    }

    // Dynamic list filtering
    val filteredResults = remember(allResults, selectedUserId, selectedSubjectId, selectedTopicId) {
        allResults.filter { res ->
            val matchUser = selectedUserId == null || res.userId == selectedUserId
            val matchSubject = selectedSubjectId == null || res.subjectId == selectedSubjectId
            val matchTopic = selectedTopicId == null || res.topicId == selectedTopicId
            matchUser && matchSubject && matchTopic
        }
    }

    Scaffold(
        topBar = {
            Row(
                modifier = Modifier
                    .fillMaxWidth()
                    .padding(horizontal = 16.dp, vertical = 12.dp),
                verticalAlignment = Alignment.CenterVertically,
                horizontalArrangement = Arrangement.spacedBy(10.dp)
            ) {
                IconButton(onClick = { viewModel.navigateBack() }) {
                    Icon(Icons.AutoMirrored.Filled.ArrowBack, "Back")
                }
                Text(
                    text = "Reports Center",
                    fontSize = 20.sp,
                    fontWeight = FontWeight.Bold,
                    color = MaterialTheme.colorScheme.primary
                )
            }
        }
    ) { padding ->
        Column(
            modifier = Modifier
                .fillMaxSize()
                .padding(padding)
                .padding(horizontal = 16.dp),
            verticalArrangement = Arrangement.spacedBy(12.dp)
        ) {
            // Filters block
            Card(
                modifier = Modifier.fillMaxWidth(),
                colors = CardDefaults.cardColors(containerColor = MaterialTheme.colorScheme.surfaceVariant.copy(alpha = 0.3f))
            ) {
                Column(
                    modifier = Modifier.padding(12.dp),
                    verticalArrangement = Arrangement.spacedBy(8.dp)
                ) {
                    Text("Filter Results Summary", fontWeight = FontWeight.Bold, fontSize = 12.sp)

                    if (isAdmin) {
                        // User selection dropdown simulation
                        var dropdownExpanded by remember { mutableStateOf(false) }
                        val currentLabel = allUsers.find { it.id == selectedUserId }?.fullName ?: "All Students"
                        
                        Box(modifier = Modifier.fillMaxWidth()) {
                            OutlinedButton(
                                onClick = { dropdownExpanded = true },
                                modifier = Modifier.fillMaxWidth()
                            ) {
                                Row(
                                    modifier = Modifier.fillMaxWidth(),
                                    horizontalArrangement = Arrangement.SpaceBetween
                                ) {
                                    Text("Student: $currentLabel", fontSize = 11.sp)
                                    Icon(Icons.Filled.ArrowDropDown, null)
                                }
                            }
                            DropdownMenu(
                                expanded = dropdownExpanded,
                                onDismissRequest = { dropdownExpanded = false }
                            ) {
                                DropdownMenuItem(
                                    text = { Text("All Students") },
                                    onClick = { selectedUserId = null; dropdownExpanded = false }
                                )
                                allUsers.filter { it.role == "USER" }.forEach { student ->
                                    DropdownMenuItem(
                                        text = { Text(student.fullName) },
                                        onClick = { selectedUserId = student.id; dropdownExpanded = false }
                                    )
                                }
                            }
                        }
                    }

                    // Subject dropdown
                    var subjectDropdownExpanded by remember { mutableStateOf(false) }
                    val subjectLabel = subjects.find { it.id == selectedSubjectId }?.name ?: "All Subjects"
                    Box(modifier = Modifier.fillMaxWidth()) {
                        OutlinedButton(
                            onClick = { subjectDropdownExpanded = true },
                            modifier = Modifier.fillMaxWidth()
                        ) {
                            Row(
                                modifier = Modifier.fillMaxWidth(),
                                horizontalArrangement = Arrangement.SpaceBetween
                            ) {
                                Text("Subject: $subjectLabel", fontSize = 11.sp)
                                Icon(Icons.Filled.ArrowDropDown, null)
                            }
                        }
                        DropdownMenu(
                            expanded = subjectDropdownExpanded,
                            onDismissRequest = { subjectDropdownExpanded = false }
                        ) {
                            DropdownMenuItem(
                                text = { Text("All Subjects") },
                                onClick = { selectedSubjectId = null; subjectDropdownExpanded = false }
                            )
                            subjects.forEach { subject ->
                                DropdownMenuItem(
                                    text = { Text(subject.name) },
                                    onClick = { selectedSubjectId = subject.id; subjectDropdownExpanded = false }
                                )
                            }
                        }
                    }
                }
            }

            // Stats Widget
            Card(
                modifier = Modifier.fillMaxWidth(),
                colors = CardDefaults.cardColors(containerColor = MaterialTheme.colorScheme.primaryContainer.copy(alpha = 0.3f))
            ) {
                Row(
                    modifier = Modifier
                        .fillMaxWidth()
                        .padding(14.dp),
                    horizontalArrangement = Arrangement.SpaceAround
                ) {
                    Column(horizontalAlignment = Alignment.CenterHorizontally) {
                        Text("Attempted", fontSize = 10.sp, color = MaterialTheme.colorScheme.outline)
                        Text("${filteredResults.size}", fontWeight = FontWeight.Bold, fontSize = 16.sp)
                    }
                    Column(horizontalAlignment = Alignment.CenterHorizontally) {
                        Text("Avg Score", fontSize = 10.sp, color = MaterialTheme.colorScheme.outline)
                        val avg = if (filteredResults.isNotEmpty()) filteredResults.map { it.scorePercentage }.average().toInt() else 0
                        Text("$avg%", fontWeight = FontWeight.Bold, fontSize = 16.sp)
                    }
                    Column(horizontalAlignment = Alignment.CenterHorizontally) {
                        Text("Best Score", fontSize = 10.sp, color = MaterialTheme.colorScheme.outline)
                        val best = if (filteredResults.isNotEmpty()) filteredResults.maxOf { it.scorePercentage }.toInt() else 0
                        Text("$best%", fontWeight = FontWeight.Bold, fontSize = 16.sp)
                    }
                }
            }

            // Report Generation Section (PDF, PNG and Preview modes)
            val userToReport = allUsers.find { it.id == selectedUserId } ?: activeUser
            if (userToReport != null) {
                Card(
                    modifier = Modifier.fillMaxWidth(),
                    shape = RoundedCornerShape(16.dp),
                    colors = CardDefaults.cardColors(containerColor = MaterialTheme.colorScheme.surfaceVariant.copy(alpha = 0.2f)),
                    border = BorderStroke(1.dp, MaterialTheme.colorScheme.primary.copy(alpha = 0.2f))
                ) {
                    Column(
                        modifier = Modifier.padding(12.dp),
                        verticalArrangement = Arrangement.spacedBy(8.dp)
                    ) {
                        Text(
                            text = "Download & Preview Actions",
                            fontWeight = FontWeight.Bold,
                            fontSize = 12.sp,
                            color = MaterialTheme.colorScheme.primary
                        )
                        Row(
                            modifier = Modifier.fillMaxWidth(),
                            horizontalArrangement = Arrangement.spacedBy(8.dp)
                        ) {
                            Button(
                                onClick = {
                                    viewModel.generateAndSavePdfReport(context, userToReport, filteredResults, asImage = false)
                                },
                                modifier = Modifier.weight(1f),
                                contentPadding = PaddingValues(horizontal = 4.dp),
                                shape = RoundedCornerShape(10.dp)
                            ) {
                                Icon(Icons.Filled.PictureAsPdf, "PDF", modifier = Modifier.size(16.dp))
                                Spacer(modifier = Modifier.width(4.dp))
                                Text("Download PDF", fontSize = 11.sp, fontWeight = FontWeight.Bold)
                            }
                            Button(
                                onClick = {
                                    viewModel.generateAndSavePdfReport(context, userToReport, filteredResults, asImage = true)
                                },
                                modifier = Modifier.weight(1f),
                                contentPadding = PaddingValues(horizontal = 4.dp),
                                shape = RoundedCornerShape(10.dp)
                            ) {
                                Icon(Icons.Filled.Image, "Image", modifier = Modifier.size(16.dp))
                                Spacer(modifier = Modifier.width(4.dp))
                                Text("Download Image", fontSize = 11.sp, fontWeight = FontWeight.Bold)
                            }
                        }
                        OutlinedButton(
                            onClick = {
                                showReportViewerUser = userToReport
                            },
                            modifier = Modifier.fillMaxWidth(),
                            shape = RoundedCornerShape(10.dp),
                            border = BorderStroke(1.dp, MaterialTheme.colorScheme.primary)
                        ) {
                            Icon(Icons.Filled.Visibility, "View Card", modifier = Modifier.size(16.dp))
                            Spacer(modifier = Modifier.width(6.dp))
                            Text("View Printable Report Card", fontSize = 11.sp, fontWeight = FontWeight.Bold)
                        }
                    }
                }
            } else {
                Card(
                    modifier = Modifier.fillMaxWidth().padding(10.dp),
                    colors = CardDefaults.cardColors(containerColor = MaterialTheme.colorScheme.errorContainer.copy(alpha = 0.1f))
                ) {
                    Text(
                        "Please login to use report generation.",
                        color = MaterialTheme.colorScheme.error,
                        fontSize = 11.sp,
                        modifier = Modifier.padding(10.dp)
                    )
                }
            }

            // Results Table List
            Text("History Details", fontSize = 12.sp, fontWeight = FontWeight.Bold, color = MaterialTheme.colorScheme.outline)
            
            if (filteredResults.isEmpty()) {
                Box(modifier = Modifier.fillMaxSize(), contentAlignment = Alignment.Center) {
                    Text("No matching test history records found.", color = MaterialTheme.colorScheme.outline)
                }
            } else {
                LazyColumn(
                    verticalArrangement = Arrangement.spacedBy(8.dp),
                    modifier = Modifier.fillMaxSize()
                ) {
                    items(filteredResults) { result ->
                        val matchedStudent = allUsers.find { it.id == result.userId }
                        Card(
                            modifier = Modifier.fillMaxWidth(),
                            colors = CardDefaults.cardColors(containerColor = MaterialTheme.colorScheme.surface),
                            border = BorderStroke(1.dp, MaterialTheme.colorScheme.outlineVariant)
                        ) {
                            Row(
                                modifier = Modifier
                                    .fillMaxWidth()
                                    .padding(12.dp),
                                horizontalArrangement = Arrangement.SpaceBetween,
                                verticalAlignment = Alignment.CenterVertically
                            ) {
                                Column(modifier = Modifier.weight(1f)) {
                                    Text(
                                        text = matchedStudent?.fullName ?: "Student ID: ${result.userId}",
                                        fontWeight = FontWeight.Bold,
                                        fontSize = 13.sp
                                    )
                                    val completedDateString = java.text.SimpleDateFormat("yyyy-MM-dd HH:mm", java.util.Locale.getDefault()).format(java.util.Date(result.timestamp))
                                    Text(
                                        text = "Duration: ${result.correctAnswers * 15 + 20}s | Date: $completedDateString",
                                        fontSize = 10.sp,
                                        color = MaterialTheme.colorScheme.outline
                                    )
                                }
                                
                                val targetUser = matchedStudent ?: activeUser
                                if (targetUser != null) {
                                    IconButton(
                                        onClick = {
                                            viewModel.activeReportTask.value = ReportTask.SingleTestCard(targetUser, result)
                                        },
                                        modifier = Modifier.padding(end = 4.dp)
                                    ) {
                                        Icon(
                                            imageVector = Icons.Filled.PictureAsPdf,
                                            contentDescription = "Download sheet",
                                            tint = MaterialTheme.colorScheme.primary,
                                            modifier = Modifier.size(24.dp)
                                        )
                                    }
                                }

                                Box(
                                    modifier = Modifier
                                        .size(44.dp)
                                        .clip(RoundedCornerShape(8.dp))
                                        .background(
                                            if (result.scorePercentage.toInt() >= 50) Color(0xFFE8F5E9)
                                            else Color(0xFFFFEBEE)
                                        ),
                                    contentAlignment = Alignment.Center
                                ) {
                                    Text(
                                        text = "${result.scorePercentage.toInt()}%",
                                        fontWeight = FontWeight.Bold,
                                        fontSize = 12.sp,
                                        color = if (result.scorePercentage.toInt() >= 50) Color(0xFF2E7D32) else Color(0xFFC62828)
                                    )
                                }
                            }
                        }
                    }
                }
            }

            // Printable Academic Report Preview Dialog Modal
            showReportViewerUser?.let { selectedUser ->
                PrintableReportCardPreviewDialog(
                    user = selectedUser,
                    results = filteredResults,
                    viewModel = viewModel,
                    onDismiss = { showReportViewerUser = null }
                )
            }
        }
    }
}

@Composable
fun PrintableReportCardPreviewDialog(
    user: com.example.data.model.User,
    results: List<com.example.data.model.TestResult>,
    viewModel: MainViewModel,
    onDismiss: () -> Unit
) {
    AlertDialog(
        onDismissRequest = onDismiss,
        confirmButton = {
            TextButton(onClick = onDismiss) {
                Text("Dismiss Progress Report", fontWeight = FontWeight.Bold)
            }
        },
        title = {
            Column(horizontalAlignment = Alignment.CenterHorizontally, modifier = Modifier.fillMaxWidth()) {
                Text("Digital Report Preview", fontSize = 16.sp, fontWeight = FontWeight.ExtraBold, color = MaterialTheme.colorScheme.primary)
                Text("Print-Ready Academic Assessment Card", fontSize = 10.sp, color = MaterialTheme.colorScheme.outline)
            }
        },
        text = {
            Column(
                modifier = Modifier
                    .fillMaxWidth()
                    .height(480.dp)
                    .verticalScroll(rememberScrollState()),
                verticalArrangement = Arrangement.spacedBy(16.dp)
            ) {
                // Printable Sheet Design Concept (styled on an elegant academic container)
                Card(
                    modifier = Modifier.fillMaxWidth(),
                    shape = RoundedCornerShape(12.dp),
                    colors = CardDefaults.cardColors(containerColor = Color(0xFFFDFDFD)),
                    border = BorderStroke(1.dp, Color(0xFFE0E0E0))
                ) {
                    Column(
                        modifier = Modifier
                            .fillMaxWidth()
                            .padding(16.dp),
                        verticalArrangement = Arrangement.spacedBy(14.dp)
                    ) {
                        // Printable Header Logo block
                        Row(
                            modifier = Modifier.fillMaxWidth(),
                            horizontalArrangement = Arrangement.spacedBy(12.dp),
                            verticalAlignment = Alignment.CenterVertically
                        ) {
                            Box(
                                modifier = Modifier
                                    .size(44.dp)
                                    .clip(CircleShape)
                                    .background(MaterialTheme.colorScheme.primary),
                                contentAlignment = Alignment.Center
                            ) {
                                Text(viewModel.getAppName().take(2).uppercase(), color = Color.White, fontWeight = FontWeight.ExtraBold, fontSize = 20.sp)
                            }
                            Column {
                                Text(
                                    text = "${viewModel.getAppName().uppercase()} ACADEMIC FOUNDATION",
                                    fontWeight = FontWeight.Black,
                                    fontSize = 11.sp,
                                    color = Color(0xFF1E3A8A)
                                )
                                Text(
                                    text = "Path to Competitive Success | Helpline: ${viewModel.getHelplineNumber()}",
                                    fontSize = 8.sp,
                                    fontWeight = FontWeight.SemiBold,
                                    color = Color.Gray
                                )
                            }
                        }

                        Divider(color = Color(0xFFE0E0E0), thickness = 1.dp)

                        // Student Profile Info block
                        Row(
                            modifier = Modifier.fillMaxWidth(),
                            horizontalArrangement = Arrangement.spacedBy(12.dp),
                            verticalAlignment = Alignment.CenterVertically
                        ) {
                            Box(
                                modifier = Modifier
                                    .size(54.dp)
                                    .clip(CircleShape)
                                    .background(MaterialTheme.colorScheme.primaryContainer),
                                contentAlignment = Alignment.Center
                            ) {
                                if (!user.profileImageUri.isNullOrEmpty()) {
                                    androidx.compose.foundation.Image(
                                        painter = coil.compose.rememberAsyncImagePainter(model = user.profileImageUri),
                                        contentDescription = null,
                                        modifier = Modifier.fillMaxSize(),
                                        contentScale = androidx.compose.ui.layout.ContentScale.Crop
                                    )
                                } else {
                                    Text(
                                        text = user.fullName.firstOrNull()?.uppercase() ?: "S",
                                        fontWeight = FontWeight.Bold,
                                        color = MaterialTheme.colorScheme.onPrimaryContainer,
                                        fontSize = 18.sp
                                    )
                                }
                            }
                            Column {
                                Text(user.fullName, fontWeight = FontWeight.Bold, fontSize = 14.sp, color = Color.Black)
                                Text("ID: #${user.id} | @${user.username}", fontSize = 10.sp, color = Color.Gray)
                                Row(
                                    verticalAlignment = Alignment.CenterVertically,
                                    horizontalArrangement = Arrangement.spacedBy(6.dp),
                                    modifier = Modifier.padding(top = 2.dp)
                                ) {
                                    Badge(containerColor = Color(0xFFE8F5E9)) {
                                        Text("ACADEMIC LEVEL: LVL ${user.id % 4 + 1}", fontSize = 8.sp, color = Color(0xFF2E7D32), fontWeight = FontWeight.Bold)
                                    }
                                    if (user.currentStreak > 0) {
                                        Badge(containerColor = Color(0xFFFFF3E0)) {
                                            Text("🔥 ${user.currentStreak} Days Streak", fontSize = 8.sp, color = Color(0xFFE65100), fontWeight = FontWeight.Bold)
                                        }
                                    }
                                }
                            }
                        }

                        // Aggregate Stats Area (Trophy layout details)
                        val totalTests = results.size
                        val avgScore = if (results.isNotEmpty()) results.map { it.scorePercentage }.average().toInt() else 0
                        val bestScore = if (results.isNotEmpty()) results.maxOf { it.scorePercentage }.toInt() else 0

                        Row(
                            modifier = Modifier.fillMaxWidth(),
                            horizontalArrangement = Arrangement.spacedBy(6.dp)
                        ) {
                            listOf(
                                Triple("Attempted Tests", "$totalTests Tests", Color(0xFF1E3A8A)),
                                Triple("Avg Score Accuracy", "$avgScore%", Color(0xFF2E7D32)),
                                Triple("Highest Perf Record", "$bestScore%", Color(0xFFE65100))
                            ).forEach { (label, value, tint) ->
                                Box(
                                    modifier = Modifier
                                        .weight(1f)
                                        .background(tint.copy(alpha = 0.06f), RoundedCornerShape(8.dp))
                                        .border(0.5.dp, tint.copy(alpha = 0.2f), RoundedCornerShape(8.dp))
                                        .padding(8.dp)
                                ) {
                                    Column(horizontalAlignment = Alignment.CenterHorizontally, modifier = Modifier.fillMaxWidth()) {
                                        Text(label, fontSize = 8.sp, color = Color.Gray, fontWeight = FontWeight.Bold)
                                        Spacer(modifier = Modifier.height(2.dp))
                                        Text(value, fontSize = 12.sp, fontWeight = FontWeight.ExtraBold, color = tint)
                                    }
                                }
                            }
                        }

                        // Subject & Topic Performance Table Grid
                        Text(
                            text = "SUBJECT & LESSON SCORES BREAKDOWN",
                            fontSize = 9.sp,
                            fontWeight = FontWeight.Black,
                            color = Color.Black,
                            modifier = Modifier.padding(top = 4.dp)
                        )

                        if (results.isEmpty()) {
                            Text("No test history recordings found for this criteria.", fontSize = 10.sp, color = Color.Gray)
                        } else {
                            Column(
                                modifier = Modifier.fillMaxWidth(),
                                verticalArrangement = Arrangement.spacedBy(6.dp)
                            ) {
                                results.take(4).forEach { res ->
                                    Row(
                                        modifier = Modifier
                                            .fillMaxWidth()
                                            .background(Color(0xFFF9F9F9), RoundedCornerShape(6.dp))
                                            .border(0.5.dp, Color(0xFFECEFF1), RoundedCornerShape(6.dp))
                                            .padding(8.dp),
                                        horizontalArrangement = Arrangement.SpaceBetween,
                                        verticalAlignment = Alignment.CenterVertically
                                    ) {
                                        Column(modifier = Modifier.weight(1f)) {
                                            Text("Syllabus MCQ Sheet #T-${res.id}", fontWeight = FontWeight.Bold, fontSize = 11.sp, color = Color.DarkGray)
                                            val dateText = java.text.SimpleDateFormat("yyyy-MM-dd HH:mm", java.util.Locale.getDefault()).format(java.util.Date(res.timestamp))
                                            Text("Attempt Time: $dateText", fontSize = 8.sp, color = Color.Gray)
                                        }
                                        Row(
                                            verticalAlignment = Alignment.CenterVertically,
                                            horizontalArrangement = Arrangement.spacedBy(6.dp)
                                        ) {
                                            Text(
                                                text = "${res.scorePercentage.toInt()}%",
                                                fontWeight = FontWeight.ExtraBold,
                                                fontSize = 12.sp,
                                                color = if (res.scorePercentage >= 50) Color(0xFF2E7D32) else Color(0xFFC62828)
                                            )
                                            Badge(
                                                containerColor = if (res.scorePercentage >= 50) Color(0xFFE8F5E9) else Color(0xFFFFEBEE)
                                            ) {
                                                Text(
                                                    text = if (res.scorePercentage >= 50) "PASSED" else "FAILED",
                                                    fontSize = 7.sp,
                                                    fontWeight = FontWeight.Bold,
                                                    color = if (res.scorePercentage >= 50) Color(0xFF2E7D32) else Color(0xFFC62828),
                                                    modifier = Modifier.padding(horizontal = 4.dp, vertical = 1.dp)
                                                )
                                            }
                                        }
                                    }
                                }
                            }
                        }

                        // Progress performance summary appraisal
                        Box(
                            modifier = Modifier
                                .fillMaxWidth()
                                .background(Color(0xFFE8EAF6), RoundedCornerShape(8.dp))
                                .padding(10.dp)
                        ) {
                            Column(verticalArrangement = Arrangement.spacedBy(4.dp)) {
                                Text("PERFORMANCE SUMMARY & APPRAISAL:", fontSize = 9.sp, fontWeight = FontWeight.Bold, color = Color(0xFF1E3A8A))
                                val summaryAppraisal = when {
                                    results.isEmpty() -> "No active academic metrics registered yet."
                                    avgScore >= 80 -> "EXCELLENT ACADEMIC STANDING - Demonstrating exceptionally strong concept conceptualization, high accuracy indexes, and diligent reviews. Fully prepared for official board assessments!"
                                    avgScore >= 50 -> "GOOD PROGRESS REPORT - Satisfactory concept verification visible. Continue practicing the unlocked PDF worksheets and targeted mock reviews to reach the 80% mark."
                                    else -> "PRACTICE RECOMMENDED - Focus on the curriculum handouts, request unlocked access to PDF Notes worksheets, and consult Admin Desk for extra help."
                                }
                                Text(
                                    text = summaryAppraisal,
                                    fontSize = 9.sp,
                                    color = Color.DarkGray,
                                    lineHeight = 13.sp
                                )
                            }
                        }

                        // Printable Digital signature block
                        Row(
                            modifier = Modifier
                                .fillMaxWidth()
                                .padding(top = 8.dp),
                            horizontalArrangement = Arrangement.SpaceBetween,
                            verticalAlignment = Alignment.CenterVertically
                        ) {
                            Column {
                                val generatedDate = java.text.SimpleDateFormat("yyyy-MM-dd", java.util.Locale.getDefault()).format(java.util.Date())
                                Text("SYSTEM GENERATION DATE: $generatedDate", fontSize = 8.sp, fontWeight = FontWeight.Bold, color = Color.Gray)
                                Text("VERIFICATION SHA-256 SECURED", fontSize = 7.sp, color = Color.LightGray)
                            }
                            Column(horizontalAlignment = Alignment.End) {
                                Text("NayaRasta Admin Desk", fontSize = 8.sp, fontWeight = FontWeight.Black, color = Color(0xFF1E3A8A))
                                Text("DIGITAL RECORD AUTHENTICATED", fontSize = 7.sp, color = Color(0xFF2E7D32), fontWeight = FontWeight.Bold)
                            }
                        }
                    }
                }
            }
        }
    )
}

// ==================== SCREEN: ADMIN PUSH NOTIFICATIONS ====================
@OptIn(ExperimentalMaterial3Api::class)
@Composable
fun AdminPushNotificationsScreen(viewModel: MainViewModel) {
    val allNotifications by viewModel.allPushNotifications.collectAsState()
    val allUsers by viewModel.allUsers.collectAsState()
    val context = androidx.compose.ui.platform.LocalContext.current
    val coroutineScope = androidx.compose.runtime.rememberCoroutineScope()

    var notificationTitle by remember { mutableStateOf("") }
    var notificationMessage by remember { mutableStateOf("") }
    var notificationImageUrl by remember { mutableStateOf("") }

    val galleryLauncher = androidx.activity.compose.rememberLauncherForActivityResult(
        contract = androidx.activity.result.contract.ActivityResultContracts.GetContent()
    ) { uri: android.net.Uri? ->
        uri?.let {
            coroutineScope.launch {
                val resolvedPath = viewModel.uploadFileToSimulatedStorage(context, it, "push_notifications")
                if (resolvedPath != null) {
                    notificationImageUrl = resolvedPath
                    viewModel.feedbackMessage.value = "Banner image loaded from gallery!"
                } else {
                    viewModel.feedbackMessage.value = "Failed to load selected image."
                }
            }
        }
    }
    
    // Target choices: true for everyone, false for specific user
    var isBroadcast by remember { mutableStateOf(true) }
    var selectedTargetUser by remember { mutableStateOf<com.example.data.model.User?>(null) }
    var userSelectorExpanded by remember { mutableStateOf(false) }

    val studentUsers = remember(allUsers) {
        allUsers.filter { it.role == "USER" }
    }

    Scaffold(
        topBar = {
            TopAppBar(
                title = {
                    Row(
                        verticalAlignment = Alignment.CenterVertically,
                        horizontalArrangement = Arrangement.spacedBy(8.dp)
                    ) {
                        IconButton(onClick = { viewModel.navigateBack() }) {
                            Icon(Icons.AutoMirrored.Filled.ArrowBack, "Back")
                        }
                        Text("Active Push Desk", fontWeight = FontWeight.ExtraBold)
                    }
                },
                colors = TopAppBarDefaults.topAppBarColors(containerColor = MaterialTheme.colorScheme.surface)
            )
        }
    ) { padding ->
        LazyColumn(
            modifier = Modifier
                .fillMaxSize()
                .padding(padding)
                .padding(horizontal = 20.dp),
            verticalArrangement = Arrangement.spacedBy(16.dp),
            contentPadding = PaddingValues(bottom = 32.dp)
        ) {
            // Desk Header Welcome banner
            item {
                Card(
                    modifier = Modifier.fillMaxWidth(),
                    shape = RoundedCornerShape(24.dp),
                    colors = CardDefaults.cardColors(containerColor = MaterialTheme.colorScheme.primaryContainer.copy(alpha = 0.25f))
                ) {
                    Column(
                        modifier = Modifier.padding(20.dp),
                        verticalArrangement = Arrangement.spacedBy(8.dp)
                    ) {
                        Row(verticalAlignment = Alignment.CenterVertically, horizontalArrangement = Arrangement.spacedBy(8.dp)) {
                            Icon(Icons.Filled.NotificationsActive, null, tint = MaterialTheme.colorScheme.primary, modifier = Modifier.size(24.dp))
                            Text("Secure Broadcast Console", fontWeight = FontWeight.ExtraBold, fontSize = 16.sp, color = MaterialTheme.colorScheme.primary)
                        }
                        Text(
                            "Dispatch live headlines, flash syllabus alerts, or individual report reminders directly to student handsets instantly.",
                            fontSize = 11.6.sp,
                            color = MaterialTheme.colorScheme.onSurfaceVariant
                        )
                    }
                }
            }

            // Composer Card form
            item {
                Card(
                    modifier = Modifier.fillMaxWidth(),
                    shape = RoundedCornerShape(20.dp),
                    colors = CardDefaults.cardColors(containerColor = MaterialTheme.colorScheme.surface),
                    border = BorderStroke(1.dp, MaterialTheme.colorScheme.outlineVariant.copy(alpha = 0.8f))
                ) {
                    Column(
                        modifier = Modifier.padding(18.dp),
                        verticalArrangement = Arrangement.spacedBy(14.dp)
                    ) {
                        Text("Compose Push Message", fontWeight = FontWeight.Bold, fontSize = 14.sp)

                        OutlinedTextField(
                            value = notificationTitle,
                            onValueChange = { notificationTitle = it },
                            label = { Text("Alert Title") },
                            placeholder = { Text("e.g. Urgent Exam Prep Sheet Uploaded") },
                            leadingIcon = { Icon(Icons.Filled.Title, null) },
                            modifier = Modifier.fillMaxWidth(),
                            shape = RoundedCornerShape(12.dp),
                            singleLine = true
                        )

                        OutlinedTextField(
                            value = notificationMessage,
                            onValueChange = { notificationMessage = it },
                            label = { Text("Message Body") },
                            placeholder = { Text("e.g. Unlocked 5 complete sets of syllabus matrices...") },
                            leadingIcon = { Icon(Icons.Filled.Notes, null) },
                            modifier = Modifier.fillMaxWidth(),
                            shape = RoundedCornerShape(12.dp)
                        )

                        // Gallery Picture Picker
                        if (notificationImageUrl.isBlank()) {
                            OutlinedCard(
                                onClick = { galleryLauncher.launch("image/*") },
                                modifier = Modifier.fillMaxWidth(),
                                shape = RoundedCornerShape(12.dp),
                                border = BorderStroke(1.dp, MaterialTheme.colorScheme.outline.copy(alpha = 0.5f))
                            ) {
                                Row(
                                    modifier = Modifier
                                        .fillMaxWidth()
                                        .padding(16.dp),
                                    verticalAlignment = Alignment.CenterVertically,
                                    horizontalArrangement = Arrangement.Center
                                ) {
                                    Icon(
                                        imageVector = Icons.Filled.Image,
                                        contentDescription = "Gallery Picker",
                                        tint = MaterialTheme.colorScheme.primary,
                                        modifier = Modifier.size(24.dp)
                                    )
                                    Spacer(modifier = Modifier.width(12.dp))
                                    Text(
                                        text = "Add Banner Image from Gallery (Optional)",
                                        fontSize = 13.sp,
                                        fontWeight = FontWeight.Bold,
                                        color = MaterialTheme.colorScheme.primary
                                    )
                                }
                            }
                        } else {
                            Card(
                                modifier = Modifier
                                    .fillMaxWidth()
                                    .height(145.dp),
                                shape = RoundedCornerShape(12.dp)
                            ) {
                                Box(modifier = Modifier.fillMaxSize()) {
                                    val painter = coil.compose.rememberAsyncImagePainter(model = notificationImageUrl)
                                    androidx.compose.foundation.Image(
                                        painter = painter,
                                        contentDescription = "Selected Banner Design",
                                        modifier = Modifier.fillMaxSize(),
                                        contentScale = androidx.compose.ui.layout.ContentScale.Crop
                                    )

                                    // Clear Button overlay
                                    IconButton(
                                        onClick = { notificationImageUrl = "" },
                                        modifier = Modifier
                                            .align(Alignment.TopEnd)
                                            .padding(10.dp)
                                            .background(
                                                color = Color.Black.copy(alpha = 0.6f),
                                                shape = CircleShape
                                            )
                                            .size(28.dp)
                                    ) {
                                        Icon(
                                            imageVector = Icons.Filled.Close,
                                            contentDescription = "Clear Banner Image",
                                            tint = Color.White,
                                            modifier = Modifier.size(16.dp)
                                        )
                                    }

                                    // Attachment label badge
                                    Text(
                                        text = "Banner attached",
                                        color = Color.White,
                                        fontSize = 11.sp,
                                        fontWeight = FontWeight.Bold,
                                        modifier = Modifier
                                            .align(Alignment.BottomStart)
                                            .padding(10.dp)
                                            .background(
                                                color = Color.Black.copy(alpha = 0.6f),
                                                shape = RoundedCornerShape(6.dp)
                                            )
                                            .padding(horizontal = 8.dp, vertical = 3.dp)
                                    )
                                }
                            }
                        }

                        // Recipient Selector
                        Column(verticalArrangement = Arrangement.spacedBy(8.dp)) {
                            Text("Target Recipients", fontWeight = FontWeight.SemiBold, fontSize = 12.sp)
                            
                            Row(
                                modifier = Modifier.fillMaxWidth(),
                                horizontalArrangement = Arrangement.spacedBy(12.dp)
                            ) {
                                FilterChip(
                                    selected = isBroadcast,
                                    onClick = { 
                                        isBroadcast = true 
                                        selectedTargetUser = null
                                    },
                                    label = { Text("All Students (Broadcast)", fontSize = 11.sp) },
                                    leadingIcon = if (isBroadcast) {
                                        { Icon(Icons.Filled.Check, null, modifier = Modifier.size(14.dp)) }
                                    } else null
                                )

                                FilterChip(
                                    selected = !isBroadcast,
                                    onClick = { isBroadcast = false },
                                    label = { Text("Specific Student", fontSize = 11.sp) },
                                    leadingIcon = if (!isBroadcast) {
                                        { Icon(Icons.Filled.Check, null, modifier = Modifier.size(14.dp)) }
                                    } else null
                                )
                            }

                            if (!isBroadcast) {
                                Box(modifier = Modifier.fillMaxWidth()) {
                                    OutlinedCard(
                                        onClick = { userSelectorExpanded = true },
                                        modifier = Modifier.fillMaxWidth(),
                                        shape = RoundedCornerShape(12.dp)
                                    ) {
                                        Row(
                                            modifier = Modifier.padding(14.dp).fillMaxWidth(),
                                            horizontalArrangement = Arrangement.SpaceBetween,
                                            verticalAlignment = Alignment.CenterVertically
                                        ) {
                                            Column {
                                                Text("Selected Recipient", fontSize = 10.sp, color = MaterialTheme.colorScheme.primary, fontWeight = FontWeight.Bold)
                                                Text(
                                                    text = selectedTargetUser?.fullName ?: "Tap to choose a student...",
                                                    fontWeight = if (selectedTargetUser != null) FontWeight.Bold else FontWeight.Normal,
                                                    fontSize = 13.sp
                                                )
                                            }
                                            Icon(Icons.Filled.ArrowDropDown, null)
                                        }
                                    }

                                    DropdownMenu(
                                        expanded = userSelectorExpanded,
                                        onDismissRequest = { userSelectorExpanded = false },
                                        modifier = Modifier.fillMaxWidth(0.9f)
                                    ) {
                                        if (studentUsers.isEmpty()) {
                                            DropdownMenuItem(
                                                text = { Text("No active students registered.") },
                                                onClick = { userSelectorExpanded = false }
                                            )
                                        } else {
                                            studentUsers.forEach { usr ->
                                                DropdownMenuItem(
                                                    text = {
                                                        Column {
                                                            Text(usr.fullName, fontWeight = FontWeight.Bold, fontSize = 12.sp)
                                                            Text("ID: #${usr.id} • ${usr.username}", fontSize = 10.sp, color = Color.Gray)
                                                        }
                                                    },
                                                    onClick = {
                                                        selectedTargetUser = usr
                                                        userSelectorExpanded = false
                                                    }
                                                )
                                            }
                                        }
                                    }
                                }
                            }
                        }

                        Spacer(modifier = Modifier.height(4.dp))

                        Button(
                            onClick = {
                                if (notificationTitle.isBlank() || notificationMessage.isBlank()) {
                                    viewModel.feedbackMessage.value = "Please specify both title and core message."
                                    return@Button
                                }
                                if (!isBroadcast && selectedTargetUser == null) {
                                    viewModel.feedbackMessage.value = "Please select a target student first."
                                    return@Button
                                }
                                
                                viewModel.sendPushNotification(
                                    title = notificationTitle,
                                    message = notificationMessage,
                                    imageUrl = notificationImageUrl.ifBlank { null },
                                    targetUserId = if (isBroadcast) null else selectedTargetUser?.id
                                )

                                notificationTitle = ""
                                notificationMessage = ""
                                notificationImageUrl = ""
                                selectedTargetUser = null
                            },
                            modifier = Modifier.fillMaxWidth(),
                            shape = RoundedCornerShape(12.dp)
                        ) {
                            Icon(Icons.Filled.Send, null, modifier = Modifier.size(16.dp))
                            Spacer(modifier = Modifier.width(8.dp))
                            Text("Dispatch Notification Desk")
                        }
                    }
                }
            }

            // Historical dispatch Logs Section Header
            item {
                Text(
                    text = "Historical Pulse Alerts Log",
                    fontWeight = FontWeight.ExtraBold,
                    fontSize = 15.sp,
                    color = MaterialTheme.colorScheme.onSurface,
                    modifier = Modifier.padding(top = 8.dp)
                )
            }

            if (allNotifications.isEmpty()) {
                item {
                    Box(
                        modifier = Modifier
                            .fillMaxWidth()
                            .padding(20.dp),
                        contentAlignment = Alignment.Center
                    ) {
                        Column(horizontalAlignment = Alignment.CenterHorizontally, verticalArrangement = Arrangement.spacedBy(8.dp)) {
                            Icon(Icons.Filled.NotificationsNone, null, modifier = Modifier.size(48.dp), tint = MaterialTheme.colorScheme.outlineVariant)
                            Text("No dispatched notifications cataloged.", color = MaterialTheme.colorScheme.outline, fontSize = 12.sp)
                        }
                    }
                }
            } else {
                items(allNotifications.reversed()) { notif ->
                    val recipientName = remember(notif.targetUserId, studentUsers) {
                        if (notif.targetUserId == null) {
                            "Broadcast (All Users)"
                        } else {
                            val userMatch = allUsers.find { it.id == notif.targetUserId }
                            if (userMatch != null) "${userMatch.fullName} (#${userMatch.id})" else "User ID: #${notif.targetUserId}"
                        }
                    }

                    Card(
                        modifier = Modifier.fillMaxWidth(),
                        shape = RoundedCornerShape(16.dp),
                        colors = CardDefaults.cardColors(containerColor = MaterialTheme.colorScheme.surfaceVariant.copy(alpha = 0.4f)),
                        border = BorderStroke(1.dp, MaterialTheme.colorScheme.outlineVariant.copy(alpha = 0.5f))
                    ) {
                        Column(modifier = Modifier.padding(14.dp), verticalArrangement = Arrangement.spacedBy(8.dp)) {
                            Row(
                                modifier = Modifier.fillMaxWidth(),
                                horizontalArrangement = Arrangement.SpaceBetween,
                                verticalAlignment = Alignment.CenterVertically
                            ) {
                                Row(
                                    verticalAlignment = Alignment.CenterVertically,
                                    horizontalArrangement = Arrangement.spacedBy(6.dp)
                                ) {
                                    Icon(
                                        imageVector = if (notif.targetUserId == null) Icons.Filled.Public else Icons.Filled.Person,
                                        contentDescription = null,
                                        tint = MaterialTheme.colorScheme.primary,
                                        modifier = Modifier.size(16.dp)
                                    )
                                    Text(
                                        text = recipientName,
                                        fontWeight = FontWeight.Bold,
                                        fontSize = 11.sp,
                                        color = MaterialTheme.colorScheme.primary
                                    )
                                }

                                Row(
                                    verticalAlignment = Alignment.CenterVertically,
                                    horizontalArrangement = Arrangement.spacedBy(8.dp)
                                ) {
                                    // Resend Notification action
                                    IconButton(
                                        onClick = {
                                            viewModel.sendPushNotification(
                                                title = notif.title,
                                                message = notif.message,
                                                imageUrl = notif.imageUrl,
                                                targetUserId = notif.targetUserId
                                            )
                                            viewModel.feedbackMessage.value = "Notification re-dispatched & broadcast successfully!"
                                        },
                                        modifier = Modifier.size(24.dp)
                                    ) {
                                        Icon(
                                            imageVector = Icons.Filled.Send,
                                            contentDescription = "Resend Notification",
                                            tint = MaterialTheme.colorScheme.primary,
                                            modifier = Modifier.size(16.dp)
                                        )
                                    }

                                    IconButton(
                                        onClick = { viewModel.deletePushNotification(notif) },
                                        modifier = Modifier.size(24.dp)
                                    ) {
                                        Icon(
                                            imageVector = Icons.Filled.Delete,
                                            contentDescription = "Recall Notification",
                                            tint = MaterialTheme.colorScheme.error,
                                            modifier = Modifier.size(16.dp)
                                        )
                                    }
                                }
                            }

                            Divider(color = MaterialTheme.colorScheme.outlineVariant.copy(alpha = 0.5f))

                            Text(notif.title, fontWeight = FontWeight.Bold, fontSize = 13.sp, color = MaterialTheme.colorScheme.onSurface)
                            Text(notif.message, fontSize = 11.6.sp, color = MaterialTheme.colorScheme.onSurfaceVariant)

                            if (!notif.imageUrl.isNullOrBlank()) {
                                Spacer(modifier = Modifier.height(4.dp))
                                val painter = coil.compose.rememberAsyncImagePainter(model = notif.imageUrl)
                                androidx.compose.foundation.Image(
                                    painter = painter,
                                    contentDescription = "Notification Image",
                                    modifier = Modifier
                                        .fillMaxWidth()
                                        .height(115.dp)
                                        .clip(RoundedCornerShape(8.dp)),
                                    contentScale = androidx.compose.ui.layout.ContentScale.Crop
                                )
                            }

                            val tString = java.text.SimpleDateFormat("yyyy-MM-dd HH:mm", java.util.Locale.getDefault()).format(java.util.Date(notif.timestamp))
                            Row(
                                modifier = Modifier.fillMaxWidth(),
                                horizontalArrangement = Arrangement.SpaceBetween
                            ) {
                                Text("Sent by: ${notif.senderName}", fontSize = 9.sp, color = MaterialTheme.colorScheme.outline, fontWeight = FontWeight.SemiBold)
                                Text(tString, fontSize = 9.sp, color = MaterialTheme.colorScheme.outline)
                            }
                        }
                    }
                }
            }
        }
    }
}

@OptIn(ExperimentalMaterial3Api::class)
@Composable
fun AdminFeeManagementScreen(viewModel: MainViewModel) {
    LaunchedEffect(Unit) {
        viewModel.triggerManualSync()
    }

    val allUsers by viewModel.allUsers.collectAsState()
    val regularStudents = remember(allUsers) { allUsers }

    var searchQuery by remember { mutableStateOf("") }
    var statusFilter by remember { mutableStateOf("All") } // "All", "Paid", "Unpaid"

    // Student fees state flow
    val studentFees by viewModel.allStudentFees.collectAsState()

    val filteredStudents = remember(allUsers, studentFees, searchQuery, statusFilter) {
        allUsers.filter { u ->
            val matchQuery = searchQuery.isEmpty() ||
                    u.fullName.contains(searchQuery, ignoreCase = true) ||
                    u.username.contains(searchQuery, ignoreCase = true) ||
                    u.phoneNumber.contains(searchQuery, ignoreCase = true) ||
                    u.id.toString() == searchQuery ||
                    u.id.toString().contains(searchQuery)
            
            val feeInfo = studentFees.find { it.userId == u.id }
            val isPaid = feeInfo?.feeStatus == "PAID" || u.isPaid
            
            matchQuery && when (statusFilter) {
                "Paid" -> isPaid
                "Unpaid" -> !isPaid
                else -> true
            }
        }
    }

    val totalCount = regularStudents.size
    val paidCount = regularStudents.count { u ->
        val feeInfo = studentFees.find { it.userId == u.id }
        feeInfo?.feeStatus == "PAID" || u.isPaid
    }
    val unpaidCount = totalCount - paidCount

    val context = LocalContext.current
    val uriHandler = androidx.compose.ui.platform.LocalUriHandler.current

    // Active expanded/message composition student ID mapping
    var activeMessageEditingUserId by remember { mutableStateOf<Int?>(null) }
    val customMessageMap = androidx.compose.runtime.remember { androidx.compose.runtime.mutableStateMapOf<Int, String>() }

    var selectedTab by remember { mutableStateOf(0) } // 0 = Student Dues, 1 = Academy Ledger

    // Dialog state for collecting payment details when toggling student to Paid
    var userToMarkPaid by remember { mutableStateOf<User?>(null) }
    var feePaymentAmount by remember { mutableStateOf("3000") }
    var feePaymentTimestamp by remember { mutableStateOf(System.currentTimeMillis()) }

    // Dialog state for editing student fee details
    var userToEditFee by remember { mutableStateOf<User?>(null) }
    var editMonthlyFee by remember { mutableStateOf("3000") }
    var editOutstandingBalance by remember { mutableStateOf("0") }
    var editFeeStatus by remember { mutableStateOf("UNPAID") }
    var editRemarks by remember { mutableStateOf("") }
    var editDueDateTimestamp by remember { mutableStateOf(System.currentTimeMillis()) }
    var editSubscriptionType by remember { mutableStateOf("TRIAL") }
    var editTrialDays by remember { mutableStateOf("7") }

    if (userToEditFee != null) {
        val student = userToEditFee!!
        AlertDialog(
            onDismissRequest = { userToEditFee = null },
            title = {
                Text(
                    text = "Edit Student Plan & Fee: ${student.fullName}",
                    fontWeight = FontWeight.Bold,
                    fontSize = 18.sp
                )
            },
            text = {
                Column(
                    verticalArrangement = Arrangement.spacedBy(12.dp),
                    modifier = Modifier.fillMaxWidth().verticalScroll(rememberScrollState())
                ) {
                    // Subscription Type Choice
                    Text("Subscription Plan:", fontSize = 12.sp, fontWeight = FontWeight.Bold, color = MaterialTheme.colorScheme.primary)
                    Row(
                        modifier = Modifier.fillMaxWidth(),
                        horizontalArrangement = Arrangement.spacedBy(4.dp)
                    ) {
                        listOf("TRIAL", "MONTHLY", "YEARLY", "SUSPENDED").forEach { plan ->
                            val isSel = editSubscriptionType == plan
                            val planLabel = when (plan) {
                                "TRIAL" -> "Trial"
                                "MONTHLY" -> "Monthly"
                                "YEARLY" -> "Yearly"
                                else -> "Suspend"
                            }
                            Button(
                                onClick = { editSubscriptionType = plan },
                                modifier = Modifier.weight(1f),
                                colors = ButtonDefaults.buttonColors(
                                    containerColor = if (isSel) {
                                        when (plan) {
                                            "TRIAL" -> MaterialTheme.colorScheme.primary
                                            "MONTHLY" -> MaterialTheme.colorScheme.secondary
                                            "YEARLY" -> Color(0xFF2E7D32)
                                            else -> Color(0xFFC62828)
                                        }
                                    } else MaterialTheme.colorScheme.surfaceVariant,
                                    contentColor = if (isSel) Color.White else MaterialTheme.colorScheme.onSurfaceVariant
                                ),
                                shape = RoundedCornerShape(8.dp),
                                contentPadding = PaddingValues(0.dp)
                            ) {
                                Text(planLabel, fontSize = 10.sp, fontWeight = FontWeight.Bold)
                            }
                        }
                    }

                    // Trial Days (Only shown if plan is TRIAL)
                    if (editSubscriptionType == "TRIAL") {
                        OutlinedTextField(
                            value = editTrialDays,
                            onValueChange = { editTrialDays = it },
                            label = { Text("Free Trial Duration (Days)") },
                            keyboardOptions = KeyboardOptions(keyboardType = KeyboardType.Number),
                            singleLine = true,
                            shape = RoundedCornerShape(10.dp),
                            modifier = Modifier.fillMaxWidth()
                        )
                    }

                    OutlinedTextField(
                        value = editMonthlyFee,
                        onValueChange = { editMonthlyFee = it },
                        label = { Text("Monthly Tuition Fee (Rs.)") },
                        keyboardOptions = KeyboardOptions(keyboardType = KeyboardType.Number),
                        singleLine = true,
                        shape = RoundedCornerShape(10.dp),
                        modifier = Modifier.fillMaxWidth()
                    )

                    OutlinedTextField(
                        value = editOutstandingBalance,
                        onValueChange = { editOutstandingBalance = it },
                        label = { Text("Outstanding Balance (Rs.)") },
                        keyboardOptions = KeyboardOptions(keyboardType = KeyboardType.Number),
                        singleLine = true,
                        shape = RoundedCornerShape(10.dp),
                        modifier = Modifier.fillMaxWidth()
                    )

                    // Dropdown / Segmented Row for Fee Status
                    Text("Fee Status:", fontSize = 12.sp, fontWeight = FontWeight.Bold, color = MaterialTheme.colorScheme.primary)
                    Row(
                        modifier = Modifier.fillMaxWidth(),
                        horizontalArrangement = Arrangement.spacedBy(6.dp)
                    ) {
                        listOf("PAID", "PENDING", "UNPAID").forEach { status ->
                            val isSel = editFeeStatus == status
                            Button(
                                onClick = { editFeeStatus = status },
                                modifier = Modifier.weight(1f),
                                colors = ButtonDefaults.buttonColors(
                                    containerColor = if (isSel) {
                                        when (status) {
                                            "PAID" -> Color(0xFF2E7D32)
                                            "PENDING" -> Color(0xFFE65100)
                                            else -> Color(0xFFC62828)
                                        }
                                    } else MaterialTheme.colorScheme.surfaceVariant,
                                    contentColor = if (isSel) Color.White else MaterialTheme.colorScheme.onSurfaceVariant
                                ),
                                shape = RoundedCornerShape(8.dp),
                                contentPadding = PaddingValues(0.dp)
                            ) {
                                Text(status, fontSize = 11.sp, fontWeight = FontWeight.Bold)
                            }
                        }
                    }

                    OutlinedTextField(
                        value = editRemarks,
                        onValueChange = { editRemarks = it },
                        label = { Text("Remarks (e.g. Scholarship, Late fee)") },
                        singleLine = true,
                        shape = RoundedCornerShape(10.dp),
                        modifier = Modifier.fillMaxWidth()
                    )

                    // Due Date Selector
                    val formattedDueDate = remember(editDueDateTimestamp) {
                        java.text.SimpleDateFormat("yyyy-MM-dd", java.util.Locale.getDefault()).format(java.util.Date(editDueDateTimestamp))
                    }

                    Row(
                        modifier = Modifier
                            .fillMaxWidth()
                            .clip(RoundedCornerShape(10.dp))
                            .background(MaterialTheme.colorScheme.surfaceVariant.copy(alpha = 0.5f))
                            .clickable {
                                val calendar = java.util.Calendar.getInstance()
                                calendar.timeInMillis = editDueDateTimestamp
                                val year = calendar.get(java.util.Calendar.YEAR)
                                val month = calendar.get(java.util.Calendar.MONTH)
                                val day = calendar.get(java.util.Calendar.DAY_OF_MONTH)

                                android.app.DatePickerDialog(
                                    context,
                                    { _, selectedYear, selectedMonth, selectedDay ->
                                        val selectedCal = java.util.Calendar.getInstance()
                                        selectedCal.set(selectedYear, selectedMonth, selectedDay)
                                        editDueDateTimestamp = selectedCal.timeInMillis
                                    },
                                    year, month, day
                                ).show()
                            }
                            .padding(12.dp),
                        horizontalArrangement = Arrangement.SpaceBetween,
                        verticalAlignment = Alignment.CenterVertically
                    ) {
                        Row(
                            horizontalArrangement = Arrangement.spacedBy(8.dp),
                            verticalAlignment = Alignment.CenterVertically
                        ) {
                            Icon(Icons.Default.DateRange, null, tint = MaterialTheme.colorScheme.primary, modifier = Modifier.size(18.dp))
                            Column {
                                val dueLabel = if (editSubscriptionType == "MONTHLY" || editSubscriptionType == "YEARLY") "Plan Expiry & Due Date" else "Fee Due Date"
                                Text(dueLabel, fontSize = 10.sp, color = MaterialTheme.colorScheme.outline)
                                Text(formattedDueDate, fontSize = 13.sp, fontWeight = FontWeight.Bold)
                            }
                        }
                        Text("Change", fontSize = 11.sp, fontWeight = FontWeight.Bold, color = MaterialTheme.colorScheme.primary)
                    }
                }
            },
            confirmButton = {
                Button(
                    onClick = {
                        val monthlyAmt = editMonthlyFee.toDoubleOrNull() ?: 3000.0
                        val outstandingAmt = editOutstandingBalance.toDoubleOrNull() ?: 0.0
                        val trialDaysVal = editTrialDays.toIntOrNull() ?: 7
                        
                        viewModel.adminUpdateStudentFee(
                            userId = student.id,
                            monthlyFee = monthlyAmt,
                            outstandingBalance = outstandingAmt,
                            feeStatus = editFeeStatus,
                            remarks = editRemarks,
                            trialDays = trialDaysVal
                        )
                        
                        // Calculate subscription start & expiry based on subscription plan selection
                        val calculatedExpiry = when (editSubscriptionType) {
                            "TRIAL" -> System.currentTimeMillis() + trialDaysVal * 86400000L
                            "MONTHLY" -> editDueDateTimestamp // Let MONTHLY expiry date be the selected Due Date for perfect custom flexibility!
                            "YEARLY" -> System.currentTimeMillis() + 365L * 24 * 60 * 60 * 1000L
                            else -> System.currentTimeMillis() - 1000L // Suspended / Expired
                        }

                        // Update the user details
                        viewModel.adminUpdateUser(
                            student.copy(
                                isPaid = (editFeeStatus == "PAID" && outstandingAmt <= 0.0),
                                subscriptionType = editSubscriptionType,
                                subscriptionExpiresAt = calculatedExpiry
                            )
                        )
                        
                        userToEditFee = null
                    }
                ) {
                    Text("Save Details", fontWeight = FontWeight.Bold)
                }
            },
            dismissButton = {
                TextButton(onClick = { userToEditFee = null }) {
                    Text("Cancel")
                }
            }
        )
    }

    // Dialog trigger
    if (userToMarkPaid != null) {
        val student = userToMarkPaid!!
        AlertDialog(
            onDismissRequest = { userToMarkPaid = null },
            title = {
                Text(
                    text = "Record Fee & Credit",
                    fontWeight = FontWeight.Bold,
                    fontSize = 18.sp
                )
            },
            text = {
                Column(
                    verticalArrangement = Arrangement.spacedBy(12.dp),
                    modifier = Modifier.fillMaxWidth()
                ) {
                    Text(
                        text = "Marking ${student.fullName} (username: ${student.username}) as PAID. Enter the amount received, select the payment date, and we'll log it as automatic credit in the Academy financial system.",
                        fontSize = 12.sp,
                        color = MaterialTheme.colorScheme.onSurfaceVariant
                    )

                    OutlinedTextField(
                        value = feePaymentAmount,
                        onValueChange = { feePaymentAmount = it },
                        label = { Text("Amount Paid (Rs.)") },
                        keyboardOptions = KeyboardOptions(keyboardType = KeyboardType.Number),
                        singleLine = true,
                        shape = RoundedCornerShape(10.dp),
                        modifier = Modifier.fillMaxWidth()
                    )

                    // Custom Date Selector
                    val formattedSelectedDate = remember(feePaymentTimestamp) {
                        java.text.SimpleDateFormat("yyyy-MM-dd", java.util.Locale.getDefault()).format(java.util.Date(feePaymentTimestamp))
                    }

                    Row(
                        modifier = Modifier
                            .fillMaxWidth()
                            .clip(RoundedCornerShape(10.dp))
                            .background(MaterialTheme.colorScheme.surfaceVariant.copy(alpha = 0.5f))
                            .clickable {
                                val calendar = java.util.Calendar.getInstance()
                                calendar.timeInMillis = feePaymentTimestamp
                                val year = calendar.get(java.util.Calendar.YEAR)
                                val month = calendar.get(java.util.Calendar.MONTH)
                                val day = calendar.get(java.util.Calendar.DAY_OF_MONTH)

                                android.app.DatePickerDialog(
                                    context,
                                    { _, selectedYear, selectedMonth, selectedDay ->
                                        val selectedCal = java.util.Calendar.getInstance()
                                        selectedCal.set(selectedYear, selectedMonth, selectedDay)
                                        feePaymentTimestamp = selectedCal.timeInMillis
                                    },
                                    year, month, day
                                ).show()
                            }
                            .padding(12.dp),
                        horizontalArrangement = Arrangement.SpaceBetween,
                        verticalAlignment = Alignment.CenterVertically
                    ) {
                        Row(
                            horizontalArrangement = Arrangement.spacedBy(8.dp),
                            verticalAlignment = Alignment.CenterVertically
                        ) {
                            Icon(Icons.Default.DateRange, null, tint = MaterialTheme.colorScheme.primary, modifier = Modifier.size(18.dp))
                            Column {
                                Text("Payment Date", fontSize = 10.sp, color = MaterialTheme.colorScheme.outline)
                                Text(formattedSelectedDate, fontSize = 13.sp, fontWeight = FontWeight.Bold)
                            }
                        }
                        Text("Change", fontSize = 11.sp, fontWeight = FontWeight.Bold, color = MaterialTheme.colorScheme.primary)
                    }
                }
            },
            confirmButton = {
                Button(
                    onClick = {
                        val amt = feePaymentAmount.toDoubleOrNull()
                        if (amt == null || amt <= 0.0) {
                            viewModel.feedbackMessage.value = "Please enter a valid amount."
                            return@Button
                        }
                        // Update status
                        viewModel.adminUpdateUser(student.copy(isPaid = true))
                        // Automatically record as credit with description
                        viewModel.addFinancialTransaction(
                            amount = amt,
                            type = "CREDIT",
                            description = "Tuition Fee payment from ${student.fullName} (username: ${student.username})",
                            timestamp = feePaymentTimestamp
                        )
                        userToMarkPaid = null
                    },
                    colors = ButtonDefaults.buttonColors(containerColor = Color(0xFF2E7D32))
                ) {
                    Text("Confirm & Record", fontWeight = FontWeight.Bold)
                }
            },
            dismissButton = {
                TextButton(onClick = { userToMarkPaid = null }) {
                    Text("Cancel")
                }
            }
        )
    }

    Scaffold(
        topBar = {
            TopAppBar(
                title = { Text("Debit & Credit Ledger", fontWeight = FontWeight.Bold, fontSize = 18.sp) },
                navigationIcon = {
                    IconButton(onClick = { viewModel.navigateBack() }) {
                        Icon(Icons.Filled.ArrowBack, "Back")
                    }
                },
                actions = {
                    IconButton(onClick = { viewModel.triggerManualSync() }) {
                        Icon(Icons.Default.Refresh, "Sync Database", tint = MaterialTheme.colorScheme.onPrimaryContainer)
                    }
                },
                colors = TopAppBarDefaults.topAppBarColors(
                    containerColor = MaterialTheme.colorScheme.primaryContainer,
                    titleContentColor = MaterialTheme.colorScheme.onPrimaryContainer
                )
            )
        }
    ) { padding ->
        Column(
            modifier = Modifier
                .fillMaxSize()
                .padding(padding)
                .padding(16.dp),
            verticalArrangement = Arrangement.spacedBy(12.dp)
        ) {
            // Tab Buttons Selector
            Row(
                modifier = Modifier
                    .fillMaxWidth()
                    .background(MaterialTheme.colorScheme.surfaceVariant, RoundedCornerShape(12.dp))
                    .padding(4.dp),
                horizontalArrangement = Arrangement.spacedBy(4.dp)
            ) {
                Button(
                    onClick = { selectedTab = 0 },
                    colors = ButtonDefaults.buttonColors(
                        containerColor = if (selectedTab == 0) MaterialTheme.colorScheme.surface else Color.Transparent,
                        contentColor = if (selectedTab == 0) MaterialTheme.colorScheme.onSurface else MaterialTheme.colorScheme.onSurfaceVariant
                    ),
                    modifier = Modifier.weight(1f),
                    shape = RoundedCornerShape(10.dp),
                    contentPadding = PaddingValues(vertical = 10.dp),
                    elevation = null
                ) {
                    Icon(Icons.Filled.Person, null, modifier = Modifier.size(16.dp))
                    Spacer(modifier = Modifier.width(6.dp))
                    Text("Student Dues", fontSize = 12.sp, fontWeight = FontWeight.Bold)
                }

                Button(
                    onClick = { selectedTab = 1 },
                    colors = ButtonDefaults.buttonColors(
                        containerColor = if (selectedTab == 1) MaterialTheme.colorScheme.surface else Color.Transparent,
                        contentColor = if (selectedTab == 1) MaterialTheme.colorScheme.onSurface else MaterialTheme.colorScheme.onSurfaceVariant
                    ),
                    modifier = Modifier.weight(1f),
                    shape = RoundedCornerShape(10.dp),
                    contentPadding = PaddingValues(vertical = 10.dp),
                    elevation = null
                ) {
                    Icon(Icons.Filled.AccountBalanceWallet, null, modifier = Modifier.size(16.dp))
                    Spacer(modifier = Modifier.width(6.dp))
                    Text("Academy Ledger", fontSize = 12.sp, fontWeight = FontWeight.Bold)
                }
            }

            if (selectedTab == 0) {
                // STUDENT DUES PANEL
                LazyColumn(
                    verticalArrangement = Arrangement.spacedBy(12.dp),
                    modifier = Modifier.fillMaxWidth().weight(1f)
                ) {
                    // General status overview card counters
                    item {
                        Row(
                            modifier = Modifier.fillMaxWidth(),
                            horizontalArrangement = Arrangement.spacedBy(8.dp)
                        ) {
                            Card(
                                modifier = Modifier.weight(1f),
                                colors = CardDefaults.cardColors(containerColor = MaterialTheme.colorScheme.surfaceVariant.copy(alpha = 0.5f))
                            ) {
                                Column(
                                    modifier = Modifier
                                        .fillMaxWidth()
                                        .padding(12.dp),
                                    horizontalAlignment = Alignment.CenterHorizontally
                                ) {
                                    Text("Total Students", fontSize = 10.sp, color = MaterialTheme.colorScheme.outline)
                                    Text(totalCount.toString(), fontSize = 20.sp, fontWeight = FontWeight.ExtraBold)
                                }
                            }
                            Card(
                                modifier = Modifier.weight(1f),
                                colors = CardDefaults.cardColors(containerColor = Color(0xFFE8F5E9))
                            ) {
                                Column(
                                    modifier = Modifier
                                        .fillMaxWidth()
                                        .padding(12.dp),
                                    horizontalAlignment = Alignment.CenterHorizontally
                                ) {
                                    Text("Paid List", fontSize = 10.sp, color = Color(0xFF2E7D32))
                                    Text(paidCount.toString(), fontSize = 20.sp, fontWeight = FontWeight.ExtraBold, color = Color(0xFF2E7D32))
                                }
                            }
                            Card(
                                modifier = Modifier.weight(1f),
                                colors = CardDefaults.cardColors(containerColor = Color(0xFFFFEBEE))
                            ) {
                                Column(
                                    modifier = Modifier
                                        .fillMaxWidth()
                                        .padding(12.dp),
                                    horizontalAlignment = Alignment.CenterHorizontally
                                ) {
                                    Text("Due List", fontSize = 10.sp, color = Color(0xFFC62828))
                                    Text(unpaidCount.toString(), fontSize = 20.sp, fontWeight = FontWeight.ExtraBold, color = Color(0xFFC62828))
                                }
                            }
                        }
                    }

                    item {
                        Card(
                            modifier = Modifier.fillMaxWidth(),
                            colors = CardDefaults.cardColors(containerColor = MaterialTheme.colorScheme.surfaceVariant.copy(alpha = 0.35f)),
                            border = BorderStroke(1.dp, MaterialTheme.colorScheme.outlineVariant)
                        ) {
                            Column(
                                modifier = Modifier.padding(14.dp),
                                verticalArrangement = Arrangement.spacedBy(10.dp)
                            ) {
                                Row(
                                    modifier = Modifier.fillMaxWidth(),
                                    horizontalArrangement = Arrangement.SpaceBetween,
                                    verticalAlignment = Alignment.CenterVertically
                                ) {
                                    Text("Trial Policy & Membership Audits", fontWeight = FontWeight.Bold, fontSize = 13.sp, color = MaterialTheme.colorScheme.primary)
                                    Icon(Icons.Filled.Settings, null, tint = MaterialTheme.colorScheme.primary, modifier = Modifier.size(16.dp))
                                }
                                
                                Row(
                                    modifier = Modifier.fillMaxWidth(),
                                    horizontalArrangement = Arrangement.spacedBy(10.dp),
                                    verticalAlignment = Alignment.CenterVertically
                                ) {
                                    var showTrialEditDialog by remember { mutableStateOf(false) }
                                    val currentTrialDays = viewModel.getTrialDaysLimit()
                                    
                                    Column(modifier = Modifier.weight(1f)) {
                                        Text("New User Free Trial Limit", fontSize = 11.sp, color = MaterialTheme.colorScheme.onSurfaceVariant)
                                        Text("$currentTrialDays Days Access", fontWeight = FontWeight.ExtraBold, fontSize = 14.sp)
                                    }
                                    
                                    Button(
                                        onClick = { showTrialEditDialog = true },
                                        colors = ButtonDefaults.buttonColors(containerColor = MaterialTheme.colorScheme.secondary),
                                        contentPadding = PaddingValues(horizontal = 12.dp, vertical = 6.dp)
                                    ) {
                                        Text("Configure Trial", fontSize = 11.sp)
                                    }
                                    
                                    if (showTrialEditDialog) {
                                        var tempLimit by remember { mutableStateOf(currentTrialDays.toString()) }
                                        AlertDialog(
                                            onDismissRequest = { showTrialEditDialog = false },
                                            title = { Text("Configure Trial Days") },
                                            text = {
                                                Column(verticalArrangement = Arrangement.spacedBy(8.dp)) {
                                                    Text("Set the default number of days for newly registered accounts.")
                                                    OutlinedTextField(
                                                        value = tempLimit,
                                                        onValueChange = { tempLimit = it },
                                                        label = { Text("Trial Duration (Days)") },
                                                        singleLine = true,
                                                        keyboardOptions = androidx.compose.foundation.text.KeyboardOptions(
                                                            keyboardType = androidx.compose.ui.text.input.KeyboardType.Number
                                                        )
                                                    )
                                                }
                                            },
                                            confirmButton = {
                                                Button(onClick = {
                                                    val days = tempLimit.toIntOrNull()
                                                    if (days != null && days > 0) {
                                                        viewModel.updateAppSetting("trial_days_limit", days.toString())
                                                        showTrialEditDialog = false
                                                    } else {
                                                        viewModel.feedbackMessage.value = "Enter a valid positive number"
                                                    }
                                                }) {
                                                    Text("Save Policy")
                                                }
                                            },
                                            dismissButton = {
                                                TextButton(onClick = { showTrialEditDialog = false }) {
                                                    Text("Cancel")
                                                }
                                            }
                                        )
                                    }
                                }
                                
                                HorizontalDivider(color = MaterialTheme.colorScheme.outlineVariant)
                                
                                Button(
                                    onClick = {
                                        viewModel.generateAndSaveSubscriptionReportPdf(context, regularStudents)
                                    },
                                    modifier = Modifier.fillMaxWidth(),
                                    colors = ButtonDefaults.buttonColors(containerColor = Color(0xFF1B365D))
                                ) {
                                    Icon(Icons.Filled.PictureAsPdf, null, modifier = Modifier.size(16.dp))
                                    Spacer(modifier = Modifier.width(8.dp))
                                    Text("Download Subscription Audit PDF Report", fontWeight = FontWeight.Bold, fontSize = 12.sp)
                                }
                            }
                        }
                    }

                    // Search bar & status filter buttons
                    item {
                        Card(
                            modifier = Modifier.fillMaxWidth(),
                            colors = CardDefaults.cardColors(containerColor = MaterialTheme.colorScheme.surface)
                        ) {
                            Column(
                                modifier = Modifier.padding(10.dp),
                                verticalArrangement = Arrangement.spacedBy(8.dp)
                            ) {
                                OutlinedTextField(
                                    value = searchQuery,
                                    onValueChange = { searchQuery = it },
                                    placeholder = { Text("Search by name, username, phone...", fontSize = 12.sp) },
                                    modifier = Modifier.fillMaxWidth(),
                                    singleLine = true,
                                    leadingIcon = { Icon(Icons.Filled.Search, null, modifier = Modifier.size(18.dp)) },
                                    shape = RoundedCornerShape(10.dp)
                                )

                                Row(
                                    modifier = Modifier.fillMaxWidth(),
                                    horizontalArrangement = Arrangement.spacedBy(6.dp)
                                ) {
                                    listOf("All", "Paid", "Unpaid").forEach { label ->
                                        val isSelected = statusFilter == label
                                        Button(
                                            onClick = { statusFilter = label },
                                            modifier = Modifier.weight(1f),
                                            colors = ButtonDefaults.buttonColors(
                                                containerColor = if (isSelected) MaterialTheme.colorScheme.primary else MaterialTheme.colorScheme.surfaceVariant,
                                                contentColor = if (isSelected) MaterialTheme.colorScheme.onPrimary else MaterialTheme.colorScheme.onSurfaceVariant
                                            ),
                                            shape = RoundedCornerShape(8.dp),
                                            contentPadding = PaddingValues(0.dp)
                                        ) {
                                            Text(label, fontSize = 11.sp, fontWeight = FontWeight.Bold)
                                        }
                                    }
                                }
                            }
                        }
                    }

                    // Student fee list
                    if (filteredStudents.isEmpty()) {
                        item {
                            Box(modifier = Modifier.fillMaxWidth().padding(vertical = 32.dp), contentAlignment = Alignment.Center) {
                                Text("No matching students found.", color = MaterialTheme.colorScheme.outline)
                            }
                        }
                    } else {
                        items(filteredStudents) { u ->
                            val currentDraft = customMessageMap[u.id] ?: if (u.isPaid) {
                                "Dear ${u.fullName}, thank you for your payment to NayaRasta Academy! Your tuition fee status is marked as PAID. Keep up the amazing work!"
                            } else {
                                "Dear ${u.fullName}, this is a gentle reminder from NayaRasta Academy. Your tuition fee status is currently marked as UNPAID. Kindly clear your dues. Thank you!"
                            }

                            Card(
                                modifier = Modifier.fillMaxWidth(),
                                colors = CardDefaults.cardColors(containerColor = MaterialTheme.colorScheme.surface),
                                border = BorderStroke(1.dp, MaterialTheme.colorScheme.outlineVariant)
                            ) {
                                Column(modifier = Modifier.padding(12.dp), verticalArrangement = Arrangement.spacedBy(8.dp)) {
                                    Row(
                                        modifier = Modifier.fillMaxWidth(),
                                        horizontalArrangement = Arrangement.SpaceBetween,
                                        verticalAlignment = Alignment.CenterVertically
                                    ) {
                                        Row(
                                            horizontalArrangement = Arrangement.spacedBy(10.dp),
                                            verticalAlignment = Alignment.CenterVertically,
                                            modifier = Modifier.weight(1f)
                                        ) {
                                            Box(
                                                modifier = Modifier
                                                    .size(36.dp)
                                                    .clip(CircleShape)
                                                    .background(Color(if (u.avatarColor != 0) u.avatarColor else 0xFF005FB0.toInt())),
                                                contentAlignment = Alignment.Center
                                            ) {
                                                Text(
                                                    text = u.fullName.firstOrNull()?.uppercase() ?: "S",
                                                    color = Color.White,
                                                    fontWeight = FontWeight.Bold,
                                                    fontSize = 14.sp
                                                )
                                            }
                                            Column {
                                                Row(verticalAlignment = Alignment.CenterVertically) {
                                                    Text(u.fullName, fontWeight = FontWeight.Bold, fontSize = 14.sp)
                                                    Spacer(modifier = Modifier.width(6.dp))
                                                    Box(
                                                        modifier = Modifier
                                                            .clip(RoundedCornerShape(4.dp))
                                                            .background(MaterialTheme.colorScheme.secondaryContainer)
                                                            .padding(horizontal = 4.dp, vertical = 1.dp)
                                                    ) {
                                                        Text("ID: ${u.id}", fontSize = 9.sp, fontWeight = FontWeight.Bold, color = MaterialTheme.colorScheme.onSecondaryContainer)
                                                    }
                                                    if (u.role != "USER") {
                                                        Spacer(modifier = Modifier.width(4.dp))
                                                        Box(
                                                            modifier = Modifier
                                                                .clip(RoundedCornerShape(4.dp))
                                                                .background(MaterialTheme.colorScheme.tertiaryContainer)
                                                                .padding(horizontal = 4.dp, vertical = 1.dp)
                                                        ) {
                                                            Text(u.role, fontSize = 9.sp, fontWeight = FontWeight.Bold, color = MaterialTheme.colorScheme.onTertiaryContainer)
                                                        }
                                                    }
                                                }
                                                Text(
                                                    text = "Username: @${u.username} | WhatsApp: ${if (u.phoneNumber.isEmpty()) "Not Set" else u.phoneNumber}",
                                                    fontSize = 11.sp,
                                                    color = MaterialTheme.colorScheme.onSurfaceVariant
                                                )
                                            }
                                        }

                                        // Mark Status switch
                                        Row(
                                            horizontalArrangement = Arrangement.spacedBy(6.dp),
                                            verticalAlignment = Alignment.CenterVertically
                                        ) {
                                            SuggestionChip(
                                                onClick = {
                                                    if (u.isPaid) {
                                                        // Toggling Paid back to Unpaid
                                                        viewModel.adminUpdateUser(u.copy(isPaid = false))
                                                    } else {
                                                        // Toggle Unpaid to Paid: open custom receipt dialog
                                                        feePaymentAmount = "3000"
                                                        feePaymentTimestamp = System.currentTimeMillis()
                                                        userToMarkPaid = u
                                                    }
                                                },
                                                label = { Text(if (u.isPaid) "PAID" else "UNPAID", fontSize = 10.sp, fontWeight = FontWeight.Black) },
                                                colors = SuggestionChipDefaults.suggestionChipColors(
                                                    containerColor = if (u.isPaid) Color(0xFFE8F5E9) else Color(0xFFFFEBEE),
                                                    labelColor = if (u.isPaid) Color(0xFF2E7D32) else Color(0xFFC62828)
                                                ),
                                                icon = {
                                                    Icon(
                                                        imageVector = if (u.isPaid) Icons.Default.CheckCircle else Icons.Default.Cancel,
                                                        contentDescription = null,
                                                        modifier = Modifier.size(12.dp),
                                                        tint = if (u.isPaid) Color(0xFF2E7D32) else Color(0xFFC62828)
                                                    )
                                                },
                                                border = null
                                            )
                                        }
                                    }

                                    Divider(color = MaterialTheme.colorScheme.outlineVariant.copy(alpha = 0.5f))

                                    // Alert draft panel and action buttons
                                    val isEditing = activeMessageEditingUserId == u.id
                                    if (isEditing) {
                                        Column(verticalArrangement = Arrangement.spacedBy(6.dp)) {
                                            Text("Draft Alert Message:", fontSize = 11.sp, fontWeight = FontWeight.SemiBold, color = MaterialTheme.colorScheme.primary)
                                            OutlinedTextField(
                                                value = currentDraft,
                                                onValueChange = { customMessageMap[u.id] = it },
                                                modifier = Modifier.fillMaxWidth(),
                                                textStyle = MaterialTheme.typography.bodySmall,
                                                shape = RoundedCornerShape(8.dp)
                                            )

                                            Row(
                                                modifier = Modifier.fillMaxWidth(),
                                                horizontalArrangement = Arrangement.spacedBy(6.dp)
                                            ) {
                                                OutlinedButton(
                                                    onClick = { activeMessageEditingUserId = null },
                                                    modifier = Modifier.weight(1f),
                                                    shape = RoundedCornerShape(8.dp),
                                                    contentPadding = PaddingValues(0.dp)
                                                ) {
                                                    Text("Hide Draft", fontSize = 10.sp)
                                                }

                                                Button(
                                                    onClick = {
                                                        if (u.phoneNumber.isEmpty()) {
                                                            viewModel.feedbackMessage.value = "User hasn't registered a phone number!"
                                                            return@Button
                                                        }
                                                        val rawPhone = u.phoneNumber.filter { it.isDigit() }
                                                        // Convert local 03... to international 923... format
                                                        val cleanPhone = if (rawPhone.startsWith("0")) "92" + rawPhone.substring(1) else rawPhone
                                                        try {
                                                            val encodedMsg = java.net.URLEncoder.encode(currentDraft, "UTF-8")
                                                            uriHandler.openUri("https://api.whatsapp.com/send?phone=$cleanPhone&text=$encodedMsg")
                                                        } catch (e: Exception) {
                                                            viewModel.feedbackMessage.value = "Couldn't send: ${e.localizedMessage}"
                                                        }
                                                    },
                                                    colors = ButtonDefaults.buttonColors(containerColor = Color(0xFF25D366)), // WhatsApp Green
                                                    modifier = Modifier.weight(1.5f),
                                                    shape = RoundedCornerShape(8.dp),
                                                    contentPadding = PaddingValues(horizontal = 8.dp, vertical = 4.dp)
                                                ) {
                                                    Row(
                                                        horizontalArrangement = Arrangement.spacedBy(4.dp),
                                                        verticalAlignment = Alignment.CenterVertically
                                                    ) {
                                                        Icon(Icons.Filled.Send, "Send", modifier = Modifier.size(12.dp), tint = Color.White)
                                                        Text("WhatsApp Alert", fontSize = 10.sp, fontWeight = FontWeight.Bold, color = Color.White)
                                                    }
                                                }
                                            }
                                        }
                                    } else {
                                        Row(
                                            modifier = Modifier.fillMaxWidth(),
                                            horizontalArrangement = Arrangement.SpaceBetween,
                                            verticalAlignment = Alignment.CenterVertically
                                        ) {
                                            Text(
                                                text = if (currentDraft.length > 50) currentDraft.take(50) + "..." else currentDraft,
                                                fontSize = 11.sp,
                                                color = MaterialTheme.colorScheme.outline,
                                                modifier = Modifier.weight(1f)
                                            )
                                            
                                            Spacer(modifier = Modifier.width(6.dp))

                                            OutlinedButton(
                                                onClick = { activeMessageEditingUserId = u.id },
                                                shape = RoundedCornerShape(8.dp),
                                                contentPadding = PaddingValues(horizontal = 10.dp, vertical = 2.dp),
                                                modifier = Modifier.height(28.dp)
                                            ) {
                                                Icon(Icons.Filled.Message, null, modifier = Modifier.size(12.dp))
                                                Spacer(modifier = Modifier.width(4.dp))
                                                Text("Customize Alert", fontSize = 10.sp)
                                            }
                                        }
                                    }

                                    // FEE MANAGEMENT DETAILS BLOCK
                                    val feeInfo = studentFees.find { it.userId == u.id }
                                    HorizontalDivider(color = MaterialTheme.colorScheme.outlineVariant.copy(alpha = 0.35f))
                                    Column(
                                        modifier = Modifier.fillMaxWidth(),
                                        verticalArrangement = Arrangement.spacedBy(6.dp)
                                    ) {
                                        Row(
                                            modifier = Modifier.fillMaxWidth(),
                                            horizontalArrangement = Arrangement.SpaceBetween,
                                            verticalAlignment = Alignment.CenterVertically
                                        ) {
                                            Text(
                                                text = "Fee Details & Records",
                                                fontWeight = FontWeight.Bold,
                                                fontSize = 12.sp,
                                                color = MaterialTheme.colorScheme.primary
                                            )
                                            
                                            // Status Badge
                                            val statusLabel = feeInfo?.feeStatus ?: "UNSET"
                                            val badgeColor = when (statusLabel) {
                                                "PAID" -> Color(0xFFE8F5E9)
                                                "PENDING" -> Color(0xFFFFF3E0)
                                                else -> Color(0xFFFFEBEE)
                                            }
                                            val badgeTextColor = when (statusLabel) {
                                                "PAID" -> Color(0xFF2E7D32)
                                                "PENDING" -> Color(0xFFE65100)
                                                else -> Color(0xFFC62828)
                                            }
                                            Box(
                                                modifier = Modifier
                                                    .clip(RoundedCornerShape(4.dp))
                                                    .background(badgeColor)
                                                    .padding(horizontal = 6.dp, vertical = 2.dp)
                                            ) {
                                                Text(
                                                    text = statusLabel,
                                                    fontSize = 10.sp,
                                                    fontWeight = FontWeight.Bold,
                                                    color = badgeTextColor
                                                )
                                            }
                                        }

                                        if (feeInfo == null) {
                                            Text(
                                                text = "No custom fee records found for this student. Default values will apply.",
                                                fontSize = 11.sp,
                                                color = MaterialTheme.colorScheme.outline
                                            )
                                        } else {
                                            Row(
                                                modifier = Modifier.fillMaxWidth(),
                                                horizontalArrangement = Arrangement.SpaceBetween
                                            ) {
                                                Column {
                                                    Text("Monthly Fee", fontSize = 10.sp, color = MaterialTheme.colorScheme.outline)
                                                    Text("PKR ${feeInfo.monthlyFee}", fontSize = 12.sp, fontWeight = FontWeight.Bold)
                                                }
                                                Column {
                                                    Text("Outstanding", fontSize = 10.sp, color = MaterialTheme.colorScheme.outline)
                                                    Text("PKR ${feeInfo.outstandingBalance}", fontSize = 12.sp, fontWeight = FontWeight.Bold, color = if (feeInfo.outstandingBalance > 0.0) Color(0xFFC62828) else Color(0xFF2E7D32))
                                                }
                                                Column {
                                                    Text("Due Date", fontSize = 10.sp, color = MaterialTheme.colorScheme.outline)
                                                    val sdf = java.text.SimpleDateFormat("yyyy-MM-dd", java.util.Locale.getDefault())
                                                    Text(sdf.format(java.util.Date(feeInfo.feeDueDate)), fontSize = 12.sp, fontWeight = FontWeight.Bold)
                                                }
                                            }
                                            if (feeInfo.remarks.isNotEmpty()) {
                                                Text(
                                                    text = "Remarks: ${feeInfo.remarks}",
                                                    fontSize = 11.sp,
                                                    fontStyle = FontStyle.Italic,
                                                    color = MaterialTheme.colorScheme.onSurfaceVariant
                                                )
                                            }
                                        }

                                        Row(
                                            modifier = Modifier.fillMaxWidth(),
                                            horizontalArrangement = Arrangement.spacedBy(8.dp)
                                        ) {
                                            // Edit Fee Details
                                            OutlinedButton(
                                                onClick = {
                                                    editMonthlyFee = (feeInfo?.monthlyFee ?: 3000.0).toString()
                                                    editOutstandingBalance = (feeInfo?.outstandingBalance ?: 0.0).toString()
                                                    editFeeStatus = feeInfo?.feeStatus ?: "UNPAID"
                                                    editRemarks = feeInfo?.remarks ?: ""
                                                    editDueDateTimestamp = feeInfo?.feeDueDate ?: System.currentTimeMillis()
                                                    editSubscriptionType = u.subscriptionType
                                                    editTrialDays = (feeInfo?.trialDays ?: 7).toString()
                                                    userToEditFee = u
                                                },
                                                modifier = Modifier.weight(1f),
                                                shape = RoundedCornerShape(8.dp),
                                                contentPadding = PaddingValues(vertical = 4.dp)
                                            ) {
                                                Icon(Icons.Default.Edit, null, modifier = Modifier.size(12.dp))
                                                Spacer(modifier = Modifier.width(4.dp))
                                                Text("Edit Fee", fontSize = 11.sp, fontWeight = FontWeight.Bold)
                                            }

                                            // Record Payment
                                            Button(
                                                onClick = {
                                                    feePaymentAmount = (feeInfo?.outstandingBalance?.takeIf { it > 0.0 } ?: feeInfo?.monthlyFee ?: 3000.0).toString()
                                                    feePaymentTimestamp = System.currentTimeMillis()
                                                    userToMarkPaid = u
                                                },
                                                modifier = Modifier.weight(1.2f),
                                                shape = RoundedCornerShape(8.dp),
                                                colors = ButtonDefaults.buttonColors(containerColor = Color(0xFF2E7D32)),
                                                contentPadding = PaddingValues(vertical = 4.dp)
                                            ) {
                                                Icon(Icons.Default.Add, null, modifier = Modifier.size(12.dp))
                                                Spacer(modifier = Modifier.width(4.dp))
                                                Text("Record Pay", fontSize = 11.sp, fontWeight = FontWeight.Bold)
                                            }
                                        }
                                    }

                                    // SUBSCRIPTION MANAGEMENT BARRIER
                                    var showSubMgr by remember { mutableStateOf(false) }
                                    HorizontalDivider(color = MaterialTheme.colorScheme.outlineVariant.copy(alpha = 0.35f))
                                    Row(
                                        modifier = Modifier.fillMaxWidth(),
                                        horizontalArrangement = Arrangement.SpaceBetween,
                                        verticalAlignment = Alignment.CenterVertically
                                    ) {
                                        Column {
                                            Text(
                                                text = "Plan: ${u.subscriptionType} (${if (viewModel.isUserSubscriptionActive(u)) "Active" else "Expired/Suspended"})",
                                                fontSize = 11.sp,
                                                fontWeight = FontWeight.Bold,
                                                color = if (viewModel.isUserSubscriptionActive(u)) Color(0xFF2E7D32) else Color(0xFFC62828)
                                            )
                                            val exp = u.subscriptionExpiresAt
                                            if (exp > 0L) {
                                                val sdf = java.text.SimpleDateFormat("yyyy-MM-dd", java.util.Locale.getDefault())
                                                Text("Expires: ${sdf.format(java.util.Date(exp))}", fontSize = 10.sp, color = MaterialTheme.colorScheme.outline)
                                            } else {
                                                Text("Expires: Unlimited / Trial Duration", fontSize = 10.sp, color = MaterialTheme.colorScheme.outline)
                                            }
                                        }
                                        
                                        Row(horizontalArrangement = Arrangement.spacedBy(6.dp)) {
                                            IconButton(
                                                onClick = {
                                                    viewModel.generateAndSaveSubscriptionReportPdf(context, listOf(u))
                                                },
                                                modifier = Modifier.size(28.dp)
                                            ) {
                                                Icon(
                                                    imageVector = Icons.Filled.PictureAsPdf,
                                                    contentDescription = "PDF Report",
                                                    tint = MaterialTheme.colorScheme.primary,
                                                    modifier = Modifier.size(16.dp)
                                                )
                                            }
                                            
                                            TextButton(
                                                onClick = { showSubMgr = !showSubMgr },
                                                contentPadding = PaddingValues(horizontal = 8.dp, vertical = 2.dp),
                                                modifier = Modifier.height(28.dp)
                                            ) {
                                                Text(if (showSubMgr) "Hide" else "Manage Plan", fontSize = 11.sp, fontWeight = FontWeight.Bold)
                                            }
                                        }
                                    }
                                    
                                    if (showSubMgr) {
                                        Column(
                                            modifier = Modifier
                                                .fillMaxWidth()
                                                .background(MaterialTheme.colorScheme.surfaceVariant.copy(alpha = 0.4f), RoundedCornerShape(8.dp))
                                                .padding(10.dp),
                                            verticalArrangement = Arrangement.spacedBy(8.dp)
                                        ) {
                                            Text("Update Plan for ${u.fullName}:", fontWeight = FontWeight.Bold, fontSize = 12.sp, color = MaterialTheme.colorScheme.primary)
                                            
                                            Column(
                                                verticalArrangement = Arrangement.spacedBy(6.dp),
                                                modifier = Modifier.fillMaxWidth()
                                            ) {
                                                Row(
                                                    modifier = Modifier.fillMaxWidth(),
                                                    horizontalArrangement = Arrangement.spacedBy(6.dp)
                                                ) {
                                                    // FREE TRIAL BUTTON
                                                    Button(
                                                        onClick = {
                                                            val tDays = feeInfo?.trialDays ?: 7
                                                            val expiryTime = System.currentTimeMillis() + tDays * 86400000L
                                                            viewModel.adminUpdateUser(u.copy(
                                                                subscriptionType = "TRIAL",
                                                                subscriptionStartAt = System.currentTimeMillis(),
                                                                subscriptionExpiresAt = expiryTime
                                                            ))
                                                            viewModel.sendPushNotification(
                                                                title = "Free Trial Activated!",
                                                                message = "Your account is now on a Free Trial plan for $tDays days.",
                                                                imageUrl = null,
                                                                targetUserId = u.id
                                                            )
                                                            viewModel.feedbackMessage.value = "Trial plan activated for ${u.fullName} ($tDays Days)."
                                                        },
                                                        modifier = Modifier.weight(1f),
                                                        colors = ButtonDefaults.buttonColors(containerColor = MaterialTheme.colorScheme.primary),
                                                        contentPadding = PaddingValues(0.dp),
                                                        shape = RoundedCornerShape(6.dp)
                                                    ) {
                                                        Text("FREE TRIAL", fontSize = 10.sp, fontWeight = FontWeight.Bold)
                                                    }

                                                    // SUSPEND BUTTON
                                                    Button(
                                                        onClick = {
                                                            viewModel.adminUpdateUser(u.copy(
                                                                subscriptionType = "SUSPENDED",
                                                                subscriptionExpiresAt = System.currentTimeMillis() - 1000L
                                                            ))
                                                            viewModel.sendPushNotification(
                                                                title = "Account Suspended",
                                                                message = "Your NayaRasta account has been suspended by the administrator. Please contact us to renew.",
                                                                imageUrl = null,
                                                                targetUserId = u.id
                                                            )
                                                            viewModel.feedbackMessage.value = "User account suspended successfully."
                                                        },
                                                        modifier = Modifier.weight(1f),
                                                        colors = ButtonDefaults.buttonColors(containerColor = Color(0xFFC62828)),
                                                        contentPadding = PaddingValues(0.dp),
                                                        shape = RoundedCornerShape(6.dp)
                                                    ) {
                                                        Text("SUSPEND", fontSize = 10.sp, fontWeight = FontWeight.Bold, color = Color.White)
                                                    }
                                                }

                                                Row(
                                                    modifier = Modifier.fillMaxWidth(),
                                                    horizontalArrangement = Arrangement.spacedBy(6.dp)
                                                ) {
                                                    // MONTHLY BUTTON
                                                    Button(
                                                        onClick = {
                                                            val cal = java.util.Calendar.getInstance()
                                                            cal.add(java.util.Calendar.DAY_OF_MONTH, 30)
                                                            val year = cal.get(java.util.Calendar.YEAR)
                                                            val month = cal.get(java.util.Calendar.MONTH)
                                                            val day = cal.get(java.util.Calendar.DAY_OF_MONTH)
                                                            
                                                            android.app.DatePickerDialog(
                                                                context,
                                                                { _, selectedYear, selectedMonth, selectedDay ->
                                                                    val selectedCal = java.util.Calendar.getInstance()
                                                                    selectedCal.set(selectedYear, selectedMonth, selectedDay, 23, 59, 59)
                                                                    val expiryTime = selectedCal.timeInMillis
                                                                    
                                                                    viewModel.adminUpdateUser(u.copy(
                                                                        subscriptionType = "MONTHLY",
                                                                        subscriptionStartAt = System.currentTimeMillis(),
                                                                        subscriptionExpiresAt = expiryTime
                                                                    ))
                                                                    viewModel.sendPushNotification(
                                                                        title = "Membership Activated!",
                                                                        message = "Congratulations! Your account is now active on the Monthly Package until ${java.text.SimpleDateFormat("yyyy-MM-dd", java.util.Locale.getDefault()).format(java.util.Date(expiryTime))}.",
                                                                        imageUrl = null,
                                                                        targetUserId = u.id
                                                                    )
                                                                    viewModel.feedbackMessage.value = "Monthly membership active for ${u.fullName}."
                                                                },
                                                                year, month, day
                                                            ).show()
                                                        },
                                                        modifier = Modifier.weight(1f),
                                                        colors = ButtonDefaults.buttonColors(containerColor = MaterialTheme.colorScheme.secondary),
                                                        contentPadding = PaddingValues(0.dp),
                                                        shape = RoundedCornerShape(6.dp)
                                                    ) {
                                                        Text("MONTHLY PLAN", fontSize = 10.sp, fontWeight = FontWeight.Bold)
                                                    }
                                                    
                                                    // YEARLY BUTTON
                                                    Button(
                                                        onClick = {
                                                            val oneYearMs = 365L * 24 * 60 * 60 * 1000L
                                                            val expiryTime = System.currentTimeMillis() + oneYearMs
                                                            viewModel.adminUpdateUser(u.copy(
                                                                subscriptionType = "YEARLY",
                                                                subscriptionStartAt = System.currentTimeMillis(),
                                                                subscriptionExpiresAt = expiryTime
                                                            ))
                                                            viewModel.sendPushNotification(
                                                                title = "Yearly Membership Active!",
                                                                message = "Congratulations! Your account is now fully active on our Unlimited Yearly Package until ${java.text.SimpleDateFormat("yyyy-MM-dd", java.util.Locale.getDefault()).format(java.util.Date(expiryTime))}.",
                                                                imageUrl = null,
                                                                targetUserId = u.id
                                                            )
                                                            viewModel.feedbackMessage.value = "Yearly membership active for ${u.fullName}."
                                                        },
                                                        modifier = Modifier.weight(1f),
                                                        colors = ButtonDefaults.buttonColors(containerColor = Color(0xFF2E7D32)),
                                                        contentPadding = PaddingValues(0.dp),
                                                        shape = RoundedCornerShape(6.dp)
                                                    ) {
                                                        Text("YEARLY PLAN", fontSize = 10.sp, fontWeight = FontWeight.Bold, color = Color.White)
                                                    }
                                                }
                                            }
                                        }
                                    }
                                }
                            }
                        }
                    }
                }
            } else {
                // ACADEMY FINANCIAL RECORD KEEPING LEDGER (DEBIT & CREDIT)
                Box(modifier = Modifier.fillMaxWidth().weight(1f)) {
                    AcademyLedgerTab(viewModel)
                }
            }
        }
    }
}

@Composable
fun AcademyLedgerTab(viewModel: MainViewModel) {
    val context = LocalContext.current
    val transactions by viewModel.allFinancialTransactions.collectAsState()

    var amountInput by remember { mutableStateOf("") }
    var descriptionInput by remember { mutableStateOf("") }
    var transactionType by remember { mutableStateOf("CREDIT") } // "CREDIT" or "EXPENSE"
    var transactionTimestamp by remember { mutableStateOf(System.currentTimeMillis()) }

    val totalCredit = remember(transactions) { transactions.filter { it.type == "CREDIT" }.sumOf { it.amount } }
    val totalExpense = remember(transactions) { transactions.filter { it.type == "EXPENSE" }.sumOf { it.amount } }
    val netBalance = totalCredit - totalExpense

    // Grouping transactions by date for outstanding visualization
    val groupedTransactions = remember(transactions) {
        transactions.groupBy { tx ->
            java.text.SimpleDateFormat("yyyy-MM-dd", java.util.Locale.getDefault()).format(java.util.Date(tx.timestamp))
        }.toSortedMap(compareByDescending { it })
    }

    LazyColumn(
        verticalArrangement = Arrangement.spacedBy(16.dp),
        modifier = Modifier.fillMaxSize()
    ) {
        // Financial summary widgets card
        item {
            Card(
                modifier = Modifier.fillMaxWidth(),
                colors = CardDefaults.cardColors(containerColor = MaterialTheme.colorScheme.surface)
            ) {
                Column(
                    modifier = Modifier.padding(16.dp),
                    verticalArrangement = Arrangement.spacedBy(12.dp)
                ) {
                    Text(
                        "Academy Financial Health Overview",
                        fontWeight = FontWeight.Bold,
                        fontSize = 14.sp,
                        color = MaterialTheme.colorScheme.onSurface
                    )

                    Row(
                        modifier = Modifier.fillMaxWidth(),
                        horizontalArrangement = Arrangement.spacedBy(8.dp)
                    ) {
                        // Total Credit (Inflow) Card
                        Card(
                            modifier = Modifier.weight(1f),
                            colors = CardDefaults.cardColors(containerColor = Color(0xFFE8F5E9))
                        ) {
                            Column(
                                modifier = Modifier.padding(12.dp),
                                horizontalAlignment = Alignment.CenterHorizontally
                            ) {
                                Text("Total Credits", fontSize = 10.sp, color = Color(0xFF2E7D32), fontWeight = FontWeight.Bold)
                                Spacer(modifier = Modifier.height(4.dp))
                                Text("Rs. ${String.format("%,.0f", totalCredit)}", fontSize = 15.sp, fontWeight = FontWeight.ExtraBold, color = Color(0xFF2E7D32))
                            }
                        }

                        // Total Expense (Outflow) Card
                        Card(
                            modifier = Modifier.weight(1f),
                            colors = CardDefaults.cardColors(containerColor = Color(0xFFFFEBEE))
                        ) {
                            Column(
                                modifier = Modifier.padding(12.dp),
                                horizontalAlignment = Alignment.CenterHorizontally
                            ) {
                                Text("Total Expenses", fontSize = 10.sp, color = Color(0xFFC62828), fontWeight = FontWeight.Bold)
                                Spacer(modifier = Modifier.height(4.dp))
                                Text("Rs. ${String.format("%,.0f", totalExpense)}", fontSize = 15.sp, fontWeight = FontWeight.ExtraBold, color = Color(0xFFC62828))
                            }
                        }
                    }

                    // Net Status Box
                    val balanceColor = if (netBalance >= 0) Color(0xFF2E7D32) else Color(0xFFC62828)
                    val balanceBg = if (netBalance >= 0) Color(0xFFE8F5E9).copy(alpha = 0.5f) else Color(0xFFFFEBEE).copy(alpha = 0.5f)
                    Box(
                        modifier = Modifier
                            .fillMaxWidth()
                            .clip(RoundedCornerShape(10.dp))
                            .background(balanceBg)
                            .padding(12.dp),
                        contentAlignment = Alignment.Center
                    ) {
                        Row(
                            horizontalArrangement = Arrangement.spacedBy(8.dp),
                            verticalAlignment = Alignment.CenterVertically
                        ) {
                            Icon(
                                imageVector = if (netBalance >= 0) Icons.Default.TrendingUp else Icons.Default.TrendingDown,
                                contentDescription = null,
                                tint = balanceColor,
                                modifier = Modifier.size(18.dp)
                            )
                            Column(horizontalAlignment = Alignment.CenterHorizontally) {
                                Text("NET SURPLUS / DEFICIT", fontSize = 9.sp, fontWeight = FontWeight.Bold, color = MaterialTheme.colorScheme.outline)
                                Text("Rs. ${String.format("%,.2f", netBalance)}", fontSize = 18.sp, fontWeight = FontWeight.Black, color = balanceColor)
                            }
                        }
                    }
                }
            }
        }

        // Add Transaction Form Card
        item {
            Card(
                modifier = Modifier.fillMaxWidth(),
                colors = CardDefaults.cardColors(containerColor = MaterialTheme.colorScheme.surface),
                border = BorderStroke(1.dp, MaterialTheme.colorScheme.outlineVariant)
            ) {
                Column(
                    modifier = Modifier.padding(16.dp),
                    verticalArrangement = Arrangement.spacedBy(12.dp)
                ) {
                    Text(
                        "Add Statement / Entry",
                        fontWeight = FontWeight.Bold,
                        fontSize = 14.sp
                    )

                    // Type Selector Tab Row
                    Row(
                        modifier = Modifier.fillMaxWidth(),
                        horizontalArrangement = Arrangement.spacedBy(6.dp)
                    ) {
                        Button(
                            onClick = { transactionType = "CREDIT" },
                            modifier = Modifier.weight(1f),
                            colors = ButtonDefaults.buttonColors(
                                containerColor = if (transactionType == "CREDIT") Color(0xFFE8F5E9) else MaterialTheme.colorScheme.surfaceVariant,
                                contentColor = if (transactionType == "CREDIT") Color(0xFF2E7D32) else MaterialTheme.colorScheme.onSurfaceVariant
                            ),
                            shape = RoundedCornerShape(8.dp)
                        ) {
                            Row(
                                horizontalArrangement = Arrangement.spacedBy(4.dp),
                                verticalAlignment = Alignment.CenterVertically
                            ) {
                                Icon(Icons.Default.ArrowUpward, null, modifier = Modifier.size(14.dp), tint = if (transactionType == "CREDIT") Color(0xFF2E7D32) else MaterialTheme.colorScheme.onSurfaceVariant)
                                Text("CREDIT (In)", fontSize = 11.sp, fontWeight = FontWeight.Bold)
                            }
                        }

                        Button(
                            onClick = { transactionType = "EXPENSE" },
                            modifier = Modifier.weight(1f),
                            colors = ButtonDefaults.buttonColors(
                                containerColor = if (transactionType == "EXPENSE") Color(0xFFFFEBEE) else MaterialTheme.colorScheme.surfaceVariant,
                                contentColor = if (transactionType == "EXPENSE") Color(0xFFC62828) else MaterialTheme.colorScheme.onSurfaceVariant
                            ),
                            shape = RoundedCornerShape(8.dp)
                        ) {
                            Row(
                                horizontalArrangement = Arrangement.spacedBy(4.dp),
                                verticalAlignment = Alignment.CenterVertically
                            ) {
                                Icon(Icons.Default.ArrowDownward, null, modifier = Modifier.size(14.dp), tint = if (transactionType == "EXPENSE") Color(0xFFC62828) else MaterialTheme.colorScheme.onSurfaceVariant)
                                Text("EXPENSE (Out)", fontSize = 11.sp, fontWeight = FontWeight.Bold)
                            }
                        }
                    }

                    // Amount Input field
                    OutlinedTextField(
                        value = amountInput,
                        onValueChange = { amountInput = it },
                        label = { Text("Amount (Rs.) e.g., 5000") },
                        modifier = Modifier.fillMaxWidth(),
                        keyboardOptions = KeyboardOptions(keyboardType = KeyboardType.Number),
                        singleLine = true,
                        shape = RoundedCornerShape(10.dp)
                    )

                    // Description Input field
                    OutlinedTextField(
                        value = descriptionInput,
                        onValueChange = { descriptionInput = it },
                        label = { Text("Statement Description (e.g., Stationeries, Rent)") },
                        modifier = Modifier.fillMaxWidth(),
                        singleLine = true,
                        shape = RoundedCornerShape(10.dp)
                    )

                    // Custom Date Selector Row for Ledger Addition
                    val formattedTxDate = remember(transactionTimestamp) {
                        java.text.SimpleDateFormat("yyyy-MM-dd", java.util.Locale.getDefault()).format(java.util.Date(transactionTimestamp))
                    }

                    Row(
                        modifier = Modifier
                            .fillMaxWidth()
                            .clip(RoundedCornerShape(10.dp))
                            .background(MaterialTheme.colorScheme.surfaceVariant.copy(alpha = 0.4f))
                            .clickable {
                                val calendar = java.util.Calendar.getInstance()
                                calendar.timeInMillis = transactionTimestamp
                                val year = calendar.get(java.util.Calendar.YEAR)
                                val month = calendar.get(java.util.Calendar.MONTH)
                                val day = calendar.get(java.util.Calendar.DAY_OF_MONTH)

                                android.app.DatePickerDialog(
                                    context,
                                    { _, selectedYear, selectedMonth, selectedDay ->
                                        val selectedCal = java.util.Calendar.getInstance()
                                        selectedCal.set(selectedYear, selectedMonth, selectedDay)
                                        transactionTimestamp = selectedCal.timeInMillis
                                    },
                                    year, month, day
                                ).show()
                            }
                            .padding(12.dp),
                        horizontalArrangement = Arrangement.SpaceBetween,
                        verticalAlignment = Alignment.CenterVertically
                    ) {
                        Row(
                            horizontalArrangement = Arrangement.spacedBy(8.dp),
                            verticalAlignment = Alignment.CenterVertically
                        ) {
                            Icon(Icons.Default.DateRange, null, tint = MaterialTheme.colorScheme.primary, modifier = Modifier.size(16.dp))
                            Text("Transaction Date:", fontSize = 12.sp, fontWeight = FontWeight.Bold)
                            Text(formattedTxDate, fontSize = 12.sp, color = MaterialTheme.colorScheme.primary, fontWeight = FontWeight.Bold)
                        }
                        Text("Pick Date", fontSize = 11.sp, fontWeight = FontWeight.Bold, color = MaterialTheme.colorScheme.primary)
                    }

                    // Buttons (PDF & Save)
                    Row(
                        modifier = Modifier.fillMaxWidth(),
                        horizontalArrangement = Arrangement.spacedBy(8.dp)
                    ) {
                        // PDF Download Button
                        OutlinedButton(
                            onClick = {
                                viewModel.activeReportTask.value = ReportTask.FinancialLedger(transactions)
                            },
                            modifier = Modifier.weight(1f),
                            shape = RoundedCornerShape(10.dp),
                            contentPadding = PaddingValues(horizontal = 8.dp, vertical = 6.dp)
                        ) {
                            Icon(Icons.Default.PictureAsPdf, null, modifier = Modifier.size(16.dp))
                            Spacer(modifier = Modifier.width(4.dp))
                            Text("Download", fontSize = 11.sp)
                        }

                        // Save Entry Button
                        Button(
                            onClick = {
                                val amount = amountInput.toDoubleOrNull()
                                if (amount == null || amount <= 0.0) {
                                    viewModel.feedbackMessage.value = "Please enter a valid positive numeric amount."
                                    return@Button
                                }
                                if (descriptionInput.isBlank()) {
                                    viewModel.feedbackMessage.value = "Please write a brief description."
                                    return@Button
                                }
                                viewModel.addFinancialTransaction(amount, transactionType, descriptionInput, transactionTimestamp)
                                amountInput = ""
                                descriptionInput = ""
                                transactionTimestamp = System.currentTimeMillis() // reset to current date
                            },
                            modifier = Modifier.weight(1.2f),
                            shape = RoundedCornerShape(10.dp),
                            colors = ButtonDefaults.buttonColors(
                                containerColor = if (transactionType == "CREDIT") Color(0xFF2E7D32) else Color(0xFFC62828)
                            )
                        ) {
                            Icon(Icons.Default.Add, null, modifier = Modifier.size(16.dp))
                            Spacer(modifier = Modifier.width(4.dp))
                            Text("Save Entry", fontSize = 11.sp, fontWeight = FontWeight.Bold, maxLines = 1)
                        }
                    }
                }
            }
        }

        // Ledger Statement list item header
        item {
            Row(
                modifier = Modifier.fillMaxWidth(),
                horizontalArrangement = Arrangement.SpaceBetween,
                verticalAlignment = Alignment.CenterVertically
            ) {
                Text(
                    "Statement Archive (${transactions.size} records)",
                    style = MaterialTheme.typography.titleMedium,
                    fontWeight = FontWeight.Bold
                )

                if (transactions.isNotEmpty()) {
                    TextButton(
                        onClick = { viewModel.clearAllFinancialTransactions() },
                        colors = ButtonDefaults.textButtonColors(contentColor = Color(0xFFC62828))
                    ) {
                        Icon(Icons.Default.DeleteForever, null, modifier = Modifier.size(14.dp))
                        Spacer(modifier = Modifier.width(4.dp))
                        Text("Clear All", fontSize = 11.sp, fontWeight = FontWeight.SemiBold)
                    }
                }
            }
        }

        if (transactions.isEmpty()) {
            item {
                Box(
                    modifier = Modifier
                        .fillMaxWidth()
                        .padding(vertical = 32.dp),
                    contentAlignment = Alignment.Center
                ) {
                    Column(horizontalAlignment = Alignment.CenterHorizontally) {
                        Icon(
                            Icons.Default.ReceiptLong,
                            null,
                            tint = MaterialTheme.colorScheme.outline.copy(alpha = 0.5f),
                            modifier = Modifier.size(48.dp)
                        )
                        Spacer(modifier = Modifier.height(8.dp))
                        Text("No ledger transactions recorded yet.", color = MaterialTheme.colorScheme.outline, fontSize = 13.sp)
                    }
                }
            }
        } else {
            // Grouped Rendering for immaculate Date Organization & Summary Details
            groupedTransactions.forEach { (dateStr, txList) ->
                item {
                    Surface(
                        color = MaterialTheme.colorScheme.surfaceVariant.copy(alpha = 0.5f),
                        shape = RoundedCornerShape(8.dp),
                        modifier = Modifier.fillMaxWidth().padding(top = 8.dp)
                    ) {
                        Row(
                            modifier = Modifier.padding(horizontal = 12.dp, vertical = 6.dp),
                            horizontalArrangement = Arrangement.SpaceBetween,
                            verticalAlignment = Alignment.CenterVertically
                        ) {
                            Row(
                                horizontalArrangement = Arrangement.spacedBy(6.dp),
                                verticalAlignment = Alignment.CenterVertically
                            ) {
                                Icon(Icons.Default.Event, null, modifier = Modifier.size(14.dp), tint = MaterialTheme.colorScheme.primary)
                                Text(
                                    text = dateStr,
                                    fontSize = 12.sp,
                                    fontWeight = FontWeight.ExtraBold,
                                    color = MaterialTheme.colorScheme.onSurfaceVariant
                                )
                            }
                            
                            val dayCredits = txList.filter { it.type == "CREDIT" }.sumOf { it.amount }
                            val dayExpenses = txList.filter { it.type == "EXPENSE" }.sumOf { it.amount }
                            Text(
                                text = "Inflow: Rs. ${String.format("%,.0f", dayCredits)} | Outflow: Rs. ${String.format("%,.0f", dayExpenses)}",
                                fontSize = 10.sp,
                                fontWeight = FontWeight.SemiBold,
                                color = MaterialTheme.colorScheme.outline
                            )
                        }
                    }
                }

                items(txList) { tx ->
                    Card(
                        modifier = Modifier.fillMaxWidth(),
                        colors = CardDefaults.cardColors(containerColor = MaterialTheme.colorScheme.surface),
                        border = BorderStroke(1.dp, MaterialTheme.colorScheme.outlineVariant.copy(alpha = 0.7f))
                    ) {
                        Row(
                            modifier = Modifier
                                .fillMaxWidth()
                                .padding(12.dp),
                            horizontalArrangement = Arrangement.SpaceBetween,
                            verticalAlignment = Alignment.CenterVertically
                        ) {
                            Row(
                                horizontalArrangement = Arrangement.spacedBy(10.dp),
                                verticalAlignment = Alignment.CenterVertically,
                                modifier = Modifier.weight(1f)
                            ) {
                                // Icon representing transaction type
                                val typeColor = if (tx.type == "CREDIT") Color(0xFF2E7D32) else Color(0xFFC62828)
                                val typeBg = if (tx.type == "CREDIT") Color(0xFFE8F5E9) else Color(0xFFFFEBEE)
                                Box(
                                    modifier = Modifier
                                        .size(36.dp)
                                        .clip(CircleShape)
                                        .background(typeBg),
                                    contentAlignment = Alignment.Center
                                ) {
                                    Icon(
                                        imageVector = if (tx.type == "CREDIT") Icons.Default.ArrowUpward else Icons.Default.ArrowDownward,
                                        contentDescription = null,
                                        tint = typeColor,
                                        modifier = Modifier.size(16.dp)
                                    )
                                }

                                Column {
                                    Text(tx.description, fontWeight = FontWeight.Bold, fontSize = 13.sp, maxLines = 1, overflow = TextOverflow.Ellipsis)
                                    val timeStr = java.text.SimpleDateFormat("HH:mm", java.util.Locale.getDefault()).format(java.util.Date(tx.timestamp))
                                    Text("Logged at: $timeStr", fontSize = 10.sp, color = MaterialTheme.colorScheme.outline)
                                }
                            }

                            Row(
                                horizontalArrangement = Arrangement.spacedBy(8.dp),
                                verticalAlignment = Alignment.CenterVertically
                            ) {
                                Text(
                                    text = "Rs. ${String.format("%,.0f", tx.amount)}",
                                    fontWeight = FontWeight.ExtraBold,
                                    fontSize = 14.sp,
                                    color = if (tx.type == "CREDIT") Color(0xFF2E7D32) else Color(0xFFC62828)
                                )

                                IconButton(
                                    onClick = { viewModel.deleteFinancialTransaction(tx) },
                                    modifier = Modifier.size(24.dp)
                                ) {
                                    Icon(
                                        Icons.Default.Delete,
                                        "Delete transaction",
                                        tint = MaterialTheme.colorScheme.outline,
                                        modifier = Modifier.size(16.dp)
                                    )
                                }
                            }
                        }
                    }
                }
            }
        }
    }
}

// ==================== SCREEN: ABOUT US ====================
@Composable
fun AboutUsScreen(viewModel: MainViewModel, customizeMode: Boolean) {
    val context = androidx.compose.ui.platform.LocalContext.current
    
    // Loaded states
    val textInputState by viewModel.aboutUsText.collectAsState()
    val imagesList by viewModel.aboutUsImages.collectAsState()
    val successStories by viewModel.allSuccessStories.collectAsState()
    
    var textInput by remember { mutableStateOf("") }
    LaunchedEffect(textInputState) {
        textInput = textInputState
    }

    var showStoryDialog by remember { mutableStateOf(false) }
    var editingStory by remember { mutableStateOf<SuccessStory?>(null) }
    
    var storyName by remember { mutableStateOf("") }
    var storyAchievement by remember { mutableStateOf("") }
    var storyText by remember { mutableStateOf("") }
    var storyImage by remember { mutableStateOf("") }
    var isUploadingStoryImage by remember { mutableStateOf(false) }
    
    val coroutineScope = androidx.compose.runtime.rememberCoroutineScope()
    
    val storyImagePickerLauncher = androidx.activity.compose.rememberLauncherForActivityResult(
        contract = androidx.activity.result.contract.ActivityResultContracts.GetContent()
    ) { uri: android.net.Uri? ->
        uri?.let {
            coroutineScope.launch {
                isUploadingStoryImage = true
                val savedPath = viewModel.uploadFileToSimulatedStorage(context, it, "success_images")
                if (savedPath != null) {
                    storyImage = savedPath
                    viewModel.feedbackMessage.value = "Student photo attached!"
                } else {
                    viewModel.feedbackMessage.value = "Failed to upload photo."
                }
                isUploadingStoryImage = false
            }
        }
    }

    fun openAddStory() {
        editingStory = null
        storyName = ""
        storyAchievement = ""
        storyText = ""
        storyImage = ""
        showStoryDialog = true
    }
    
    fun openEditStory(story: SuccessStory) {
        editingStory = story
        storyName = story.studentName
        storyAchievement = story.achievement
        storyText = story.storyText
        storyImage = story.studentImage
        showStoryDialog = true
    }
    
    val imagePickerLauncher = androidx.activity.compose.rememberLauncherForActivityResult(
        contract = androidx.activity.result.contract.ActivityResultContracts.GetContent()
    ) { uri: android.net.Uri? ->
        uri?.let {
            viewModel.addAboutUsImage(context, it)
        }
    }

    if (showStoryDialog) {
        AlertDialog(
            onDismissRequest = { showStoryDialog = false },
            title = {
                Text(
                    text = if (editingStory == null) "Add Success Story" else "Edit Success Story",
                    fontWeight = FontWeight.Bold,
                    fontSize = 18.sp
                )
            },
            text = {
                Column(
                    modifier = Modifier
                        .fillMaxWidth()
                        .verticalScroll(rememberScrollState()),
                    verticalArrangement = Arrangement.spacedBy(12.dp),
                    horizontalAlignment = Alignment.CenterHorizontally
                ) {
                    // Image Picker placeholder / preview
                    Box(
                        modifier = Modifier
                            .size(100.dp)
                            .clip(RoundedCornerShape(percent = 50))
                            .background(MaterialTheme.colorScheme.surfaceVariant)
                            .clickable { storyImagePickerLauncher.launch("image/*") },
                        contentAlignment = Alignment.Center
                    ) {
                        if (isUploadingStoryImage) {
                            CircularProgressIndicator(modifier = Modifier.size(24.dp))
                        } else if (storyImage.isNotEmpty()) {
                            androidx.compose.foundation.Image(
                                painter = coil.compose.rememberAsyncImagePainter(model = storyImage),
                                contentDescription = "Student photo preview",
                                modifier = Modifier.fillMaxSize(),
                                contentScale = androidx.compose.ui.layout.ContentScale.Crop
                            )
                        } else {
                            Column(
                                horizontalAlignment = Alignment.CenterHorizontally,
                                verticalArrangement = Arrangement.Center,
                                modifier = Modifier.padding(4.dp)
                            ) {
                                Icon(Icons.Filled.AddPhotoAlternate, null, tint = MaterialTheme.colorScheme.primary, modifier = Modifier.size(24.dp))
                                Spacer(modifier = Modifier.height(2.dp))
                                Text("Student Photo", fontSize = 10.sp, color = MaterialTheme.colorScheme.primary)
                            }
                        }
                    }
                    
                    OutlinedTextField(
                        value = storyName,
                        onValueChange = { storyName = it },
                        label = { Text("Student Name") },
                        modifier = Modifier.fillMaxWidth(),
                        shape = RoundedCornerShape(10.dp)
                    )
                    
                    OutlinedTextField(
                        value = storyAchievement,
                        onValueChange = { storyAchievement = it },
                        label = { Text("Result / Achievement") },
                        placeholder = { Text("E.g., 99.2% Marks, Selected in IIT") },
                        modifier = Modifier.fillMaxWidth(),
                        shape = RoundedCornerShape(10.dp)
                    )
                    
                    OutlinedTextField(
                        value = storyText,
                        onValueChange = { storyText = it },
                        label = { Text("Success Story Details") },
                        placeholder = { Text("Write a short statement about their classes, tips, and achievements...") },
                        modifier = Modifier.fillMaxWidth()
                            .height(100.dp),
                        shape = RoundedCornerShape(10.dp)
                    )
                }
            },
            confirmButton = {
                Button(
                    onClick = {
                        if (storyName.isBlank() || storyAchievement.isBlank() || storyText.isBlank()) {
                            viewModel.feedbackMessage.value = "Please fill in all core fields!"
                            return@Button
                        }
                        
                        viewModel.saveSuccessStory(
                            id = editingStory?.id ?: 0,
                            name = storyName,
                            image = storyImage,
                            achievement = storyAchievement,
                            text = storyText
                        )
                        showStoryDialog = false
                    },
                    shape = RoundedCornerShape(8.dp)
                ) {
                    Text("Save", fontSize = 13.sp)
                }
            },
            dismissButton = {
                TextButton(onClick = { showStoryDialog = false }) {
                    Text("Cancel", fontSize = 13.sp)
                }
            },
            shape = RoundedCornerShape(16.dp)
        )
    }

    Scaffold(
        topBar = {
            Row(
                modifier = Modifier
                    .fillMaxWidth()
                    .background(MaterialTheme.colorScheme.primaryContainer)
                    .windowInsetsPadding(WindowInsets.statusBars)
                    .padding(horizontal = 8.dp, vertical = 12.dp),
                verticalAlignment = Alignment.CenterVertically
            ) {
                IconButton(onClick = { viewModel.navigateBack() }) {
                    Icon(
                        imageVector = Icons.AutoMirrored.Filled.ArrowBack,
                        contentDescription = "Back",
                        tint = MaterialTheme.colorScheme.onPrimaryContainer
                    )
                }
                Spacer(modifier = Modifier.width(8.dp))
                Text(
                    text = if (customizeMode) "Customize About Us" else "About ${viewModel.getAppName()}",
                    fontWeight = FontWeight.Bold,
                    fontSize = 18.sp,
                    color = MaterialTheme.colorScheme.onPrimaryContainer
                )
            }
        },
        contentWindowInsets = WindowInsets.safeDrawing
    ) { paddingValues ->
        Column(
            modifier = Modifier
                .fillMaxSize()
                .padding(paddingValues)
                .verticalScroll(rememberScrollState())
                .padding(20.dp),
            verticalArrangement = Arrangement.spacedBy(20.dp)
        ) {
            if (customizeMode) {
                // Admin Edit Section
                Card(
                    modifier = Modifier.fillMaxWidth(),
                    shape = RoundedCornerShape(16.dp),
                    colors = CardDefaults.cardColors(containerColor = MaterialTheme.colorScheme.surfaceVariant.copy(alpha = 0.5f))
                ) {
                    Column(
                        modifier = Modifier.padding(16.dp),
                        verticalArrangement = Arrangement.spacedBy(12.dp)
                    ) {
                        Text(
                            text = "Edit About Us Description",
                            fontWeight = FontWeight.Bold,
                            fontSize = 15.sp,
                            color = MaterialTheme.colorScheme.primary
                        )
                        
                        OutlinedTextField(
                            value = textInput,
                            onValueChange = { textInput = it },
                            placeholder = { Text("Enter organization details...") },
                            modifier = Modifier
                                .fillMaxWidth()
                                .height(150.dp),
                            shape = RoundedCornerShape(12.dp)
                        )
                        
                        Button(
                            onClick = {
                                viewModel.saveAboutUsText(textInput)
                            },
                            modifier = Modifier.align(Alignment.End),
                            shape = RoundedCornerShape(8.dp)
                        ) {
                            Icon(Icons.Filled.Check, null, modifier = Modifier.size(16.dp))
                            Spacer(modifier = Modifier.width(4.dp))
                            Text("Save Text", fontSize = 12.sp)
                        }
                    }
                }
                
                Card(
                    modifier = Modifier.fillMaxWidth(),
                    shape = RoundedCornerShape(16.dp),
                    colors = CardDefaults.cardColors(containerColor = MaterialTheme.colorScheme.surfaceVariant.copy(alpha = 0.5f))
                ) {
                    Column(
                        modifier = Modifier.padding(16.dp),
                        verticalArrangement = Arrangement.spacedBy(12.dp)
                    ) {
                        Row(
                            modifier = Modifier.fillMaxWidth(),
                            horizontalArrangement = Arrangement.SpaceBetween,
                            verticalAlignment = Alignment.CenterVertically
                        ) {
                            Text(
                                text = "Customize Images Gallery",
                                fontWeight = FontWeight.Bold,
                                fontSize = 15.sp,
                                color = MaterialTheme.colorScheme.primary
                            )
                            
                            OutlinedButton(
                                onClick = { imagePickerLauncher.launch("image/*") },
                                contentPadding = PaddingValues(horizontal = 10.dp, vertical = 4.dp),
                                shape = RoundedCornerShape(8.dp)
                            ) {
                                Icon(Icons.Filled.AddPhotoAlternate, null, modifier = Modifier.size(16.dp))
                                Spacer(modifier = Modifier.width(4.dp))
                                Text("Add Local File", fontSize = 11.sp)
                            }
                        }
                        
                        if (imagesList.isEmpty()) {
                            Text(
                                text = "No local images uploaded yet. Use the 'Add Local File' button to attach graphic material from your device gallery.",
                                fontSize = 12.sp,
                                color = MaterialTheme.colorScheme.outline,
                                modifier = Modifier.padding(vertical = 12.dp)
                            )
                        } else {
                            // Display uploaded images with DELETE button
                            imagesList.forEach { imgPath ->
                                Row(
                                    modifier = Modifier
                                        .fillMaxWidth()
                                        .clip(RoundedCornerShape(12.dp))
                                        .background(MaterialTheme.colorScheme.surface)
                                        .padding(8.dp),
                                    verticalAlignment = Alignment.CenterVertically,
                                    horizontalArrangement = Arrangement.spacedBy(12.dp)
                                ) {
                                    Card(
                                        modifier = Modifier.size(60.dp),
                                        shape = RoundedCornerShape(8.dp)
                                    ) {
                                        androidx.compose.foundation.Image(
                                            painter = coil.compose.rememberAsyncImagePainter(model = imgPath),
                                            contentDescription = "Gallery image thumbnail",
                                            modifier = Modifier.fillMaxSize(),
                                            contentScale = androidx.compose.ui.layout.ContentScale.Crop
                                        )
                                    }
                                    
                                    Text(
                                        text = imgPath.substringAfterLast("/"),
                                        modifier = Modifier.weight(1f),
                                        fontSize = 11.sp,
                                        maxLines = 1,
                                        overflow = TextOverflow.Ellipsis
                                    )
                                    
                                    IconButton(
                                        onClick = {
                                            viewModel.removeAboutUsImage(imgPath)
                                        }
                                    ) {
                                        Icon(Icons.Filled.Delete, "Remove Image", tint = Color.Red)
                                    }
                                }
                            }
                        }
                    }
                }

                // Customize Success Stories Card
                Card(
                    modifier = Modifier.fillMaxWidth(),
                    shape = RoundedCornerShape(16.dp),
                    colors = CardDefaults.cardColors(containerColor = MaterialTheme.colorScheme.surfaceVariant.copy(alpha = 0.5f))
                ) {
                    Column(
                        modifier = Modifier.padding(16.dp),
                        verticalArrangement = Arrangement.spacedBy(12.dp)
                    ) {
                        Row(
                            modifier = Modifier.fillMaxWidth(),
                            horizontalArrangement = Arrangement.SpaceBetween,
                            verticalAlignment = Alignment.CenterVertically
                        ) {
                            Text(
                                text = "Customize Student Success Stories",
                                fontWeight = FontWeight.Bold,
                                fontSize = 15.sp,
                                color = MaterialTheme.colorScheme.primary
                            )
                            
                            OutlinedButton(
                                onClick = { openAddStory() },
                                contentPadding = PaddingValues(horizontal = 10.dp, vertical = 4.dp),
                                shape = RoundedCornerShape(8.dp)
                            ) {
                                Icon(Icons.Filled.Add, null, modifier = Modifier.size(16.dp))
                                Spacer(modifier = Modifier.width(4.dp))
                                Text("Add Story", fontSize = 11.sp)
                            }
                        }
                        
                        if (successStories.isEmpty()) {
                            Text(
                                text = "No success stories added yet. Click 'Add Story' to celebrate our students' achievements!",
                                fontSize = 12.sp,
                                color = MaterialTheme.colorScheme.outline,
                                modifier = Modifier.padding(vertical = 12.dp)
                            )
                        } else {
                            successStories.forEach { story ->
                                Row(
                                    modifier = Modifier
                                        .fillMaxWidth()
                                        .clip(RoundedCornerShape(12.dp))
                                        .background(MaterialTheme.colorScheme.surface)
                                        .clickable { openEditStory(story) }
                                        .padding(8.dp),
                                    verticalAlignment = Alignment.CenterVertically,
                                    horizontalArrangement = Arrangement.spacedBy(12.dp)
                                ) {
                                    Card(
                                        modifier = Modifier.size(50.dp),
                                        shape = RoundedCornerShape(8.dp)
                                    ) {
                                        if (story.studentImage.isNotEmpty()) {
                                            androidx.compose.foundation.Image(
                                                painter = coil.compose.rememberAsyncImagePainter(model = story.studentImage),
                                                contentDescription = "Success student photo",
                                                modifier = Modifier.fillMaxSize(),
                                                contentScale = androidx.compose.ui.layout.ContentScale.Crop
                                            )
                                        } else {
                                            Box(
                                                modifier = Modifier.fillMaxSize()
                                                    .background(MaterialTheme.colorScheme.primaryContainer),
                                                contentAlignment = Alignment.Center
                                            ) {
                                                Text(
                                                    text = story.studentName.take(1).uppercase(),
                                                    fontWeight = FontWeight.Bold,
                                                    fontSize = 18.sp,
                                                    color = MaterialTheme.colorScheme.onPrimaryContainer
                                                )
                                            }
                                        }
                                    }
                                    
                                    Column(modifier = Modifier.weight(1f)) {
                                        Text(story.studentName, fontWeight = FontWeight.Bold, fontSize = 13.sp)
                                        Text(story.achievement, fontSize = 11.sp, color = MaterialTheme.colorScheme.secondary, maxLines = 1, overflow = TextOverflow.Ellipsis)
                                        Text(story.storyText, fontSize = 11.sp, color = MaterialTheme.colorScheme.outline, maxLines = 1, overflow = TextOverflow.Ellipsis)
                                    }
                                    
                                    IconButton(
                                        onClick = {
                                            viewModel.deleteSuccessStory(story)
                                        }
                                    ) {
                                        Icon(Icons.Filled.Delete, "Delete Story", tint = Color.Red, modifier = Modifier.size(20.dp))
                                    }
                                }
                            }
                        }
                    }
                }
            } else {
                // User Screen Mode: Read About Us
                Box(
                    modifier = Modifier
                        .fillMaxWidth()
                        .height(180.dp)
                        .clip(RoundedCornerShape(20.dp)),
                    contentAlignment = Alignment.Center
                ) {
                    val bannerUrl = viewModel.getAboutUsImage()
                    if (bannerUrl.isNotEmpty()) {
                        androidx.compose.foundation.Image(
                            painter = coil.compose.rememberAsyncImagePainter(model = bannerUrl),
                            contentDescription = "About Us Banner Image",
                            modifier = Modifier.fillMaxSize(),
                            contentScale = androidx.compose.ui.layout.ContentScale.Crop
                        )
                        // Dark overlay for text readability
                        Box(
                            modifier = Modifier
                                .fillMaxSize()
                                .background(Color.Black.copy(alpha = 0.5f))
                        )
                    } else {
                        Box(
                            modifier = Modifier
                                .fillMaxSize()
                                .background(
                                    Brush.linearGradient(
                                        colors = listOf(
                                            MaterialTheme.colorScheme.primary,
                                            MaterialTheme.colorScheme.primaryContainer
                                        )
                                    )
                                )
                        )
                    }

                    Column(
                        horizontalAlignment = Alignment.CenterHorizontally,
                        verticalArrangement = Arrangement.spacedBy(6.dp)
                    ) {
                        Text(
                            text = viewModel.getAppName(),
                            fontSize = 32.sp,
                            fontWeight = FontWeight.ExtraBold,
                            color = Color.White
                        )
                        Text(
                            text = "Till Entry, Till Victory • About Us",
                            fontSize = 13.sp,
                            fontWeight = FontWeight.Medium,
                            color = Color.White.copy(alpha = 0.9f)
                        )
                    }
                }
                
                // Content Description
                Card(
                    modifier = Modifier.fillMaxWidth(),
                    shape = RoundedCornerShape(16.dp),
                    colors = CardDefaults.cardColors(containerColor = MaterialTheme.colorScheme.surface),
                    elevation = CardDefaults.cardElevation(defaultElevation = 2.dp)
                ) {
                    Column(
                        modifier = Modifier.padding(16.dp),
                        verticalArrangement = Arrangement.spacedBy(8.dp)
                    ) {
                        Text(
                            text = "Our Mission & Goals",
                            fontWeight = FontWeight.Bold,
                            fontSize = 16.sp,
                            color = MaterialTheme.colorScheme.primary
                        )
                        
                        Text(
                            text = textInput,
                            fontSize = 14.sp,
                            lineHeight = 20.sp,
                            color = MaterialTheme.colorScheme.onSurface
                        )
                    }
                }
                
                // Image gallery (showing local files as a beautiful Carousel)
                if (imagesList.isNotEmpty()) {
                    Text(
                        text = "Visual Tour & Highlights",
                        fontWeight = FontWeight.Bold,
                        fontSize = 15.sp,
                        color = MaterialTheme.colorScheme.primary
                    )
                    
                    val lazyListState = androidx.compose.foundation.lazy.rememberLazyListState()
                    val coroutineScopeCarousel = rememberCoroutineScope()
                    
                    val activeIndex by remember {
                        derivedStateOf { lazyListState.firstVisibleItemIndex }
                    }
                    
                    Column(
                        modifier = Modifier.fillMaxWidth(),
                        verticalArrangement = Arrangement.spacedBy(10.dp),
                        horizontalAlignment = Alignment.CenterHorizontally
                    ) {
                        androidx.compose.foundation.lazy.LazyRow(
                            state = lazyListState,
                            modifier = Modifier
                                .fillMaxWidth()
                                .height(220.dp)
                                .clip(RoundedCornerShape(16.dp)),
                            horizontalArrangement = Arrangement.spacedBy(12.dp)
                        ) {
                            items(imagesList.size) { index ->
                                val imgPath = imagesList[index]
                                Card(
                                    modifier = Modifier
                                        .fillParentMaxWidth()
                                        .fillMaxHeight(),
                                    shape = RoundedCornerShape(16.dp),
                                    elevation = CardDefaults.cardElevation(defaultElevation = 2.dp)
                                ) {
                                    Box(modifier = Modifier.fillMaxSize()) {
                                        androidx.compose.foundation.Image(
                                            painter = coil.compose.rememberAsyncImagePainter(model = imgPath),
                                            contentDescription = "Gallery item $index",
                                            modifier = Modifier.fillMaxSize(),
                                            contentScale = androidx.compose.ui.layout.ContentScale.Crop
                                        )
                                        
                                        // Navigation overlay buttons
                                        if (imagesList.size > 1) {
                                            Row(
                                                modifier = Modifier
                                                    .fillMaxSize()
                                                    .padding(horizontal = 8.dp),
                                                horizontalArrangement = Arrangement.SpaceBetween,
                                                verticalAlignment = Alignment.CenterVertically
                                            ) {
                                                if (index > 0) {
                                                    FilledIconButton(
                                                        onClick = {
                                                            coroutineScopeCarousel.launch {
                                                                lazyListState.animateScrollToItem(index - 1)
                                                            }
                                                        },
                                                        colors = IconButtonDefaults.filledIconButtonColors(
                                                            containerColor = Color.Black.copy(alpha = 0.4f),
                                                            contentColor = Color.White
                                                        ),
                                                        modifier = Modifier.size(32.dp)
                                                    ) {
                                                        Icon(Icons.Filled.KeyboardArrowLeft, null, modifier = Modifier.size(16.dp))
                                                    }
                                                } else {
                                                    Spacer(modifier = Modifier.size(32.dp))
                                                }
                                                
                                                if (index < imagesList.size - 1) {
                                                    FilledIconButton(
                                                        onClick = {
                                                            coroutineScopeCarousel.launch {
                                                                lazyListState.animateScrollToItem(index + 1)
                                                            }
                                                        },
                                                        colors = IconButtonDefaults.filledIconButtonColors(
                                                            containerColor = Color.Black.copy(alpha = 0.4f),
                                                            contentColor = Color.White
                                                        ),
                                                        modifier = Modifier.size(32.dp)
                                                    ) {
                                                        Icon(Icons.Filled.KeyboardArrowRight, null, modifier = Modifier.size(16.dp))
                                                    }
                                                } else {
                                                    Spacer(modifier = Modifier.size(32.dp))
                                                }
                                            }
                                        }

                                        // Indicator Overlay Card
                                        Box(
                                            modifier = Modifier
                                                .align(Alignment.BottomEnd)
                                                .padding(12.dp)
                                                .background(Color.Black.copy(alpha = 0.6f), RoundedCornerShape(8.dp))
                                                .padding(horizontal = 8.dp, vertical = 4.dp)
                                        ) {
                                            Text(
                                                text = "${index + 1}/${imagesList.size}",
                                                color = Color.White,
                                                fontSize = 10.sp,
                                                fontWeight = FontWeight.Bold
                                            )
                                        }
                                    }
                                }
                            }
                        }
                        
                        if (imagesList.size > 1) {
                            Row(
                                horizontalArrangement = Arrangement.spacedBy(6.dp),
                                verticalAlignment = Alignment.CenterVertically
                            ) {
                                repeat(imagesList.size) { dotIdx ->
                                    val isSelected = activeIndex == dotIdx
                                    Box(
                                        modifier = Modifier
                                            .size(if (isSelected) 8.dp else 5.dp)
                                            .clip(RoundedCornerShape(percent = 50))
                                            .background(
                                                if (isSelected) MaterialTheme.colorScheme.primary 
                                                else MaterialTheme.colorScheme.outlineVariant
                                            )
                                    )
                                }
                            }
                        }
                    }
                }

                // Student Success Stories Sub-section definition
                if (successStories.isNotEmpty()) {
                    Text(
                        text = "Celebrating Our Student Success Stories",
                        fontWeight = FontWeight.Bold,
                        fontSize = 16.sp,
                        color = MaterialTheme.colorScheme.primary
                    )

                    successStories.forEach { story ->
                        Card(
                            modifier = Modifier.fillMaxWidth(),
                            shape = RoundedCornerShape(16.dp),
                            colors = CardDefaults.cardColors(containerColor = MaterialTheme.colorScheme.surface),
                            elevation = CardDefaults.cardElevation(defaultElevation = 2.dp)
                        ) {
                            Row(
                                modifier = Modifier.padding(16.dp),
                                horizontalArrangement = Arrangement.spacedBy(16.dp),
                                verticalAlignment = Alignment.Top
                            ) {
                                Card(
                                    modifier = Modifier
                                        .size(64.dp)
                                        .clip(RoundedCornerShape(percent = 50))
                                        .background(MaterialTheme.colorScheme.surfaceVariant),
                                    shape = RoundedCornerShape(percent = 50)
                                ) {
                                    if (story.studentImage.isNotEmpty()) {
                                        androidx.compose.foundation.Image(
                                            painter = coil.compose.rememberAsyncImagePainter(model = story.studentImage),
                                            contentDescription = "Portrait of ${story.studentName}",
                                            modifier = Modifier.fillMaxSize(),
                                            contentScale = androidx.compose.ui.layout.ContentScale.Crop
                                        )
                                    } else {
                                        Box(
                                            modifier = Modifier.fillMaxSize()
                                                .background(MaterialTheme.colorScheme.primaryContainer),
                                            contentAlignment = Alignment.Center
                                        ) {
                                            Text(
                                                text = story.studentName.take(1).uppercase(),
                                                fontWeight = FontWeight.Bold,
                                                fontSize = 20.sp,
                                                color = MaterialTheme.colorScheme.onPrimaryContainer
                                            )
                                        }
                                    }
                                }

                                Column(
                                    modifier = Modifier.weight(1f),
                                    verticalArrangement = Arrangement.spacedBy(4.dp)
                                ) {
                                    Text(
                                        text = story.studentName,
                                        fontWeight = FontWeight.Bold,
                                        fontSize = 16.sp,
                                        color = MaterialTheme.colorScheme.onSurface
                                    )

                                    // Achievement chip badge
                                    Card(
                                        colors = CardDefaults.cardColors(
                                            containerColor = MaterialTheme.colorScheme.primary.copy(alpha = 0.1f)
                                        ),
                                        shape = RoundedCornerShape(6.dp)
                                    ) {
                                        Text(
                                            text = story.achievement,
                                            fontWeight = FontWeight.Bold,
                                            fontSize = 11.sp,
                                            color = MaterialTheme.colorScheme.primary,
                                            modifier = Modifier.padding(horizontal = 8.dp, vertical = 4.dp)
                                        )
                                    }

                                    Spacer(modifier = Modifier.height(4.dp))

                                    Text(
                                        text = story.storyText,
                                        fontSize = 13.sp,
                                        lineHeight = 18.sp,
                                        color = MaterialTheme.colorScheme.onSurfaceVariant
                                    )
                                }
                            }
                        }
                    }
                }
                
                Spacer(modifier = Modifier.height(10.dp))

                // WhatsApp Connect Connection Button below
                Button(
                    onClick = {
                        try {
                            val url = "https://api.whatsapp.com/send?phone=${viewModel.getHelplineNumberInternational()}&text=Hello%20${java.net.URLEncoder.encode(viewModel.getAppName(), "UTF-8")}%20Admin%21%20I%20have%20some%20questions%20regarding%20the%20app."
                            val intent = Intent(Intent.ACTION_VIEW, Uri.parse(url))
                            context.startActivity(intent)
                        } catch (e: Exception) {
                            viewModel.feedbackMessage.value = "Unable to open WhatsApp. Please save contact manually: +${viewModel.getHelplineNumberInternational()}"
                        }
                    },
                    modifier = Modifier
                        .fillMaxWidth()
                        .height(54.dp),
                    shape = RoundedCornerShape(14.dp),
                    colors = ButtonDefaults.buttonColors(containerColor = Color(0xFF25D366)) // Official WhatsApp Green Color!
                ) {
                    Icon(
                        imageVector = Icons.Default.Call,
                        contentDescription = "WhatsApp icon",
                        tint = Color.White,
                        modifier = Modifier.size(24.dp)
                    )
                    Spacer(modifier = Modifier.width(10.dp))
                    Text(
                        text = "Connect on Whatsapp",
                        color = Color.White,
                        fontSize = 15.sp,
                        fontWeight = FontWeight.Bold
                    )
                }
            }
        }
    }
}

@OptIn(ExperimentalMaterial3Api::class)
@Composable
fun UserAddMcqScreen(viewModel: MainViewModel) {
    val context = androidx.compose.ui.platform.LocalContext.current
    val isDark = isSystemInDarkTheme()
    
    val loggedInUser by viewModel.loggedInUser.collectAsState()
    val subjects by viewModel.allSubjects.collectAsState()
    val topics by viewModel.allTopics.collectAsState()
    val activeStyle by viewModel.activeDesignStyle.collectAsState()
    
    var questionText by remember { mutableStateOf("") }
    var optA by remember { mutableStateOf("") }
    var optB by remember { mutableStateOf("") }
    var optC by remember { mutableStateOf("") }
    var optD by remember { mutableStateOf("") }
    var explanation by remember { mutableStateOf("") }
    
    var selectedSubject by remember { mutableStateOf<Subject?>(null) }
    var selectedTopic by remember { mutableStateOf<Topic?>(null) }
    var correctOpt by remember { mutableStateOf("A") } // Default Correct Option
    var selectedDifficulty by remember { mutableStateOf("MEDIUM") }
    
    var isSubmitting by remember { mutableStateOf(false) }

    // Dynamic topic filtering when subject changes
    val filteredTopics = remember(selectedSubject, topics) {
        if (selectedSubject == null) emptyList()
        else topics.filter { it.subjectId == selectedSubject!!.id }
    }

    // Dropdown open states
    var subjectDropdownExpanded by remember { mutableStateOf(false) }
    var topicDropdownExpanded by remember { mutableStateOf(false) }

    Scaffold(
        topBar = {
            TopAppBar(
                title = { Text("Contribute MCQ", fontWeight = FontWeight.Bold) },
                navigationIcon = {
                    IconButton(onClick = { viewModel.navigateBack() }) {
                        Icon(imageVector = Icons.AutoMirrored.Default.ArrowBack, contentDescription = "Back")
                    }
                },
                colors = TopAppBarDefaults.topAppBarColors(
                    containerColor = if (isDark) Color(0xFF121212) else MaterialTheme.colorScheme.surface
                )
            )
        }
    ) { paddingValues ->
        Column(
            modifier = Modifier
                .fillMaxSize()
                .padding(paddingValues)
                .background(if (isDark) Color(0xFF121212) else MaterialTheme.colorScheme.background)
                .verticalScroll(rememberScrollState())
                .padding(16.dp),
            verticalArrangement = Arrangement.spacedBy(16.dp)
        ) {
            Text(
                text = "Submit a Question",
                style = MaterialTheme.typography.headlineSmall,
                fontWeight = FontWeight.Bold,
                color = MaterialTheme.colorScheme.primary
            )
            
            Text(
                text = "Help other students by contributing authentic practice questions. Once submitted, our subject administrators will review your question for approval.",
                style = MaterialTheme.typography.bodyMedium,
                color = MaterialTheme.colorScheme.onSurfaceVariant
            )

            // Contribution stats banner for the user
            PremiumStyleContainer(
                style = activeStyle,
                modifier = Modifier.fillMaxWidth(),
                containerColor = if (isDark) Color(0xFF1E1E1E) else MaterialTheme.colorScheme.surfaceVariant.copy(alpha = 0.4f)
            ) {
                Row(
                    modifier = Modifier.padding(12.dp).fillMaxWidth(),
                    horizontalArrangement = Arrangement.SpaceAround,
                    verticalAlignment = Alignment.CenterVertically
                ) {
                    Column(horizontalAlignment = Alignment.CenterHorizontally) {
                        Text(
                            text = "${loggedInUser?.approvedMcqs ?: 0}",
                            style = MaterialTheme.typography.titleLarge,
                            fontWeight = FontWeight.Bold,
                            color = Color(0xFF4CAF50)
                        )
                        Text(
                            text = "Approved MCQs",
                            style = MaterialTheme.typography.bodySmall,
                            color = MaterialTheme.colorScheme.onSurfaceVariant
                        )
                    }
                    Box(
                        modifier = Modifier
                            .width(1.dp)
                            .height(30.dp)
                            .background(MaterialTheme.colorScheme.outlineVariant)
                    )
                    Column(horizontalAlignment = Alignment.CenterHorizontally) {
                        Text(
                            text = "${loggedInUser?.rejectedMcqs ?: 0}",
                            style = MaterialTheme.typography.titleLarge,
                            fontWeight = FontWeight.Bold,
                            color = MaterialTheme.colorScheme.error
                        )
                        Text(
                            text = "Rejected MCQs",
                            style = MaterialTheme.typography.bodySmall,
                            color = MaterialTheme.colorScheme.onSurfaceVariant
                        )
                    }
                }
            }

            // --- 1. QUESTION TEXT ---
            OutlinedTextField(
                value = questionText,
                onValueChange = { questionText = it },
                label = { Text("Question *") },
                modifier = Modifier.fillMaxWidth().testTag("add_mcq_question"),
                maxLines = 4,
                colors = OutlinedTextFieldDefaults.colors()
            )

            // --- 2. OPTION A ---
            OutlinedTextField(
                value = optA,
                onValueChange = { optA = it },
                label = { Text("Option A *") },
                modifier = Modifier.fillMaxWidth().testTag("add_mcq_opt_a")
            )

            // --- 3. OPTION B ---
            OutlinedTextField(
                value = optB,
                onValueChange = { optB = it },
                label = { Text("Option B *") },
                modifier = Modifier.fillMaxWidth().testTag("add_mcq_opt_b")
            )

            // --- 4. OPTION C ---
            OutlinedTextField(
                value = optC,
                onValueChange = { optC = it },
                label = { Text("Option C *") },
                modifier = Modifier.fillMaxWidth().testTag("add_mcq_opt_c")
            )

            // --- 5. OPTION D ---
            OutlinedTextField(
                value = optD,
                onValueChange = { optD = it },
                label = { Text("Option D *") },
                modifier = Modifier.fillMaxWidth().testTag("add_mcq_opt_d")
            )

            // --- 6. LOGICAL EXPLANATION ---
            OutlinedTextField(
                value = explanation,
                onValueChange = { explanation = it },
                label = { Text("Logical Explanation *") },
                modifier = Modifier.fillMaxWidth().testTag("add_mcq_explanation"),
                maxLines = 3
            )

            // --- SELECT CORRECT OPTION ---
            Text("Select Correct Option:", fontWeight = FontWeight.Bold, style = MaterialTheme.typography.bodyMedium)
            Row(
                modifier = Modifier.fillMaxWidth(),
                horizontalArrangement = Arrangement.spacedBy(12.dp)
            ) {
                listOf("A", "B", "C", "D").forEach { option ->
                    val isSelected = correctOpt == option
                    FilterChip(
                        selected = isSelected,
                        onClick = { correctOpt = option },
                        label = { Text("Option $option", fontWeight = FontWeight.Bold) },
                        modifier = Modifier.weight(1f).testTag("chip_correct_$option")
                    )
                }
            }

            Divider()

            // --- SELECT DIFFICULTY ---
            Text("Select Difficulty Level:", fontWeight = FontWeight.Bold, style = MaterialTheme.typography.bodyMedium)
            Row(
                modifier = Modifier.fillMaxWidth(),
                horizontalArrangement = Arrangement.spacedBy(12.dp)
            ) {
                listOf("EASY", "MEDIUM", "HARD").forEach { diff ->
                    val isSelected = selectedDifficulty == diff
                    FilterChip(
                        selected = isSelected,
                        onClick = { selectedDifficulty = diff },
                        label = { Text(diff, fontWeight = FontWeight.Bold) },
                        modifier = Modifier.weight(1f).testTag("chip_difficulty_$diff")
                    )
                }
            }

            Divider()

            // --- 7. SELECT BOOK / SUBJECT ---
            Text("Select Subject / Book:", fontWeight = FontWeight.Bold, style = MaterialTheme.typography.bodyMedium)
            Box(modifier = Modifier.fillMaxWidth()) {
                PremiumStyleContainer(
                    style = activeStyle,
                    onClick = { subjectDropdownExpanded = true },
                    modifier = Modifier.fillMaxWidth()
                ) {
                    Row(
                        modifier = Modifier.padding(16.dp),
                        horizontalArrangement = Arrangement.SpaceBetween,
                        verticalAlignment = Alignment.CenterVertically
                    ) {
                        Text(
                            text = selectedSubject?.name ?: "Tap to choose Book / Subject",
                            style = MaterialTheme.typography.bodyMedium,
                            fontWeight = if (selectedSubject != null) FontWeight.SemiBold else FontWeight.Normal
                        )
                        Icon(imageVector = Icons.Default.ArrowDropDown, contentDescription = null)
                    }
                }
                DropdownMenu(
                    expanded = subjectDropdownExpanded,
                    onDismissRequest = { subjectDropdownExpanded = false },
                    modifier = Modifier.fillMaxWidth(0.9f)
                ) {
                    subjects.forEach { subj ->
                        DropdownMenuItem(
                            text = { Text(subj.name) },
                            onClick = {
                                selectedSubject = subj
                                selectedTopic = null // Reset topic on subject change
                                subjectDropdownExpanded = false
                            }
                        )
                    }
                }
            }

            // --- 8. SELECT TOPIC ---
            Text("Select Topic:", fontWeight = FontWeight.Bold, style = MaterialTheme.typography.bodyMedium)
            Box(modifier = Modifier.fillMaxWidth()) {
                PremiumStyleContainer(
                    style = activeStyle,
                    onClick = {
                        if (selectedSubject == null) {
                            viewModel.feedbackMessage.value = "Please select a Subject first."
                        } else {
                            topicDropdownExpanded = true
                        }
                    },
                    modifier = Modifier.fillMaxWidth()
                ) {
                    Row(
                        modifier = Modifier.padding(16.dp),
                        horizontalArrangement = Arrangement.SpaceBetween,
                        verticalAlignment = Alignment.CenterVertically
                    ) {
                        Text(
                            text = selectedTopic?.name ?: "Tap to choose Topic",
                            style = MaterialTheme.typography.bodyMedium,
                            fontWeight = if (selectedTopic != null) FontWeight.SemiBold else FontWeight.Normal
                        )
                        Icon(imageVector = Icons.Default.ArrowDropDown, contentDescription = null)
                    }
                }
                DropdownMenu(
                    expanded = topicDropdownExpanded,
                    onDismissRequest = { topicDropdownExpanded = false },
                    modifier = Modifier.fillMaxWidth(0.9f)
                ) {
                    filteredTopics.forEach { topic ->
                        DropdownMenuItem(
                            text = { Text(topic.name) },
                            onClick = {
                                selectedTopic = topic
                                topicDropdownExpanded = false
                            }
                        )
                    }
                }
            }

            Spacer(modifier = Modifier.height(10.dp))

            // --- SUBMIT BUTTON ---
            Button(
                onClick = {
                    if (questionText.trim().isEmpty() || optA.trim().isEmpty() || optB.trim().isEmpty() ||
                        optC.trim().isEmpty() || optD.trim().isEmpty() || explanation.trim().isEmpty()
                    ) {
                        viewModel.feedbackMessage.value = "Please fill in all question and option fields."
                        return@Button
                    }
                    if (selectedSubject == null) {
                        viewModel.feedbackMessage.value = "Please select a Book / Subject."
                        return@Button
                    }
                    if (selectedTopic == null) {
                        viewModel.feedbackMessage.value = "Please select a Topic."
                        return@Button
                    }

                    isSubmitting = true
                    viewModel.insertPendingMcq(
                        subjectId = selectedSubject!!.id,
                        topicId = selectedTopic!!.id,
                        question = questionText,
                        optionA = optA,
                        optionB = optB,
                        optionC = optC,
                        optionD = optD,
                        correctOption = correctOpt,
                        detailedExplanation = explanation,
                        difficulty = selectedDifficulty,
                        onComplete = { success ->
                            isSubmitting = false
                            if (success) {
                                viewModel.navigateBack()
                            }
                        }
                    )
                },
                modifier = Modifier
                    .fillMaxWidth()
                    .height(54.dp)
                    .testTag("submit_mcq_button"),
                shape = RoundedCornerShape(14.dp),
                enabled = !isSubmitting
            ) {
                if (isSubmitting) {
                    CircularProgressIndicator(modifier = Modifier.size(24.dp), color = Color.White, strokeWidth = 2.dp)
                } else {
                    Icon(imageVector = Icons.Default.Check, contentDescription = null)
                    Spacer(modifier = Modifier.width(8.dp))
                    Text("Submit MCQ for Review", fontWeight = FontWeight.Bold, fontSize = 16.sp)
                }
            }
        }
    }
}

// ==================== SCREEN: ADMIN MCQ CONTRIBUTIONS & USER STATS ====================
@OptIn(ExperimentalMaterial3Api::class)
@Composable
fun AdminContributedMcqsScreen(viewModel: MainViewModel) {
    val pendingMcqs by viewModel.allPendingMcqs.collectAsState()
    val subjects by viewModel.allSubjects.collectAsState()
    val topics by viewModel.allTopics.collectAsState()
    val allUsers by viewModel.allUsers.collectAsState()
    val announcements by viewModel.allAnnouncements.collectAsState()
    val isDark = isSystemInDarkTheme()

    var searchQuery by remember { mutableStateOf("") }
    var selectedTab by remember { mutableStateOf(0) } // 0: Pending MCQs, 1: Contributor Stats, 2: Announcements, 3: SQL Helper

    var rejectingMcq by remember { mutableStateOf<PendingMcq?>(null) }
    var rejectionReason by remember { mutableStateOf("") }

    // Announcement form states
    var annMessage by remember { mutableStateOf("") }
    var annImageUrl by remember { mutableStateOf("") }
    var annDuration by remember { mutableStateOf(5) }
    var annIsCloseable by remember { mutableStateOf(true) }
    var annTargetAll by remember { mutableStateOf(true) }
    val selectedUserIds = remember { mutableStateMapOf<Int, Boolean>() }
    var userSearchQuery by remember { mutableStateOf("") }

    Scaffold(
        topBar = {
            TopAppBar(
                title = { Text("Contributor & Message Hub", fontWeight = FontWeight.Bold) },
                navigationIcon = {
                    IconButton(onClick = { viewModel.navigateTo(Screen.AdminDashboard) }) {
                        Icon(Icons.Filled.ArrowBack, contentDescription = "Back")
                    }
                },
                colors = TopAppBarDefaults.topAppBarColors(
                    containerColor = if (isDark) Color(0xFF121212) else MaterialTheme.colorScheme.surface
                )
            )
        },
        containerColor = if (isDark) Color(0xFF121212) else MaterialTheme.colorScheme.background
    ) { paddingValues ->
        Column(
            modifier = Modifier
                .fillMaxSize()
                .padding(paddingValues)
                .padding(horizontal = 16.dp)
        ) {
            // Tab Header Row coded with clean custom cards (highly compatible, visually beautiful)
            Row(
                modifier = Modifier
                    .fillMaxWidth()
                    .padding(vertical = 8.dp),
                horizontalArrangement = Arrangement.spacedBy(4.dp)
            ) {
                listOf(
                    "Pending (${pendingMcqs.size})",
                    "Stats"
                ).forEachIndexed { index, title ->
                    val isSelected = selectedTab == index
                    Card(
                        modifier = Modifier
                            .weight(1f)
                            .clickable { selectedTab = index },
                        colors = CardDefaults.cardColors(
                            containerColor = if (isSelected) {
                                if (isDark) MaterialTheme.colorScheme.primaryContainer else MaterialTheme.colorScheme.primary
                            } else {
                                if (isDark) Color(0xFF1E1E1E) else MaterialTheme.colorScheme.surfaceVariant.copy(alpha = 0.5f)
                            }
                        ),
                        shape = RoundedCornerShape(10.dp),
                        border = BorderStroke(
                            1.dp,
                            if (isSelected) MaterialTheme.colorScheme.primary else MaterialTheme.colorScheme.outlineVariant.copy(alpha = 0.5f)
                        )
                    ) {
                        Text(
                            text = title,
                            modifier = Modifier
                                .fillMaxWidth()
                                .padding(vertical = 10.dp),
                            textAlign = TextAlign.Center,
                            fontWeight = FontWeight.Bold,
                            fontSize = 10.sp,
                            color = if (isSelected) {
                                if (isDark) MaterialTheme.colorScheme.onPrimaryContainer else Color.White
                            } else {
                                MaterialTheme.colorScheme.onSurfaceVariant
                            }
                        )
                    }
                }
            }

            Spacer(modifier = Modifier.height(8.dp))

            when (selectedTab) {
                0 -> {
                    // TAB 0: Pending MCQs
                    if (pendingMcqs.isEmpty()) {
                        Box(
                            modifier = Modifier.fillMaxSize().padding(24.dp),
                            contentAlignment = Alignment.Center
                        ) {
                            Column(
                                horizontalAlignment = Alignment.CenterHorizontally,
                                verticalArrangement = Arrangement.spacedBy(8.dp)
                            ) {
                                Text("👍", fontSize = 48.sp)
                                Text(
                                    text = "No Pending Submissions",
                                    fontWeight = FontWeight.Bold,
                                    fontSize = 16.sp,
                                    color = MaterialTheme.colorScheme.onSurfaceVariant
                                )
                                Text(
                                    text = "All contributed MCQs have been reviewed and resolved.",
                                    fontSize = 12.sp,
                                    color = MaterialTheme.colorScheme.onSurfaceVariant.copy(alpha = 0.7f),
                                    textAlign = TextAlign.Center
                                )
                            }
                        }
                    } else {
                        LazyColumn(
                            verticalArrangement = Arrangement.spacedBy(12.dp),
                            modifier = Modifier.fillMaxSize()
                        ) {
                            items(pendingMcqs) { mcq ->
                                val subjName = subjects.find { it.id == mcq.subjectId }?.name ?: "Unknown Subject"
                                val topicName = topics.find { it.id == mcq.topicId }?.name ?: "Unknown Topic"

                                Card(
                                    modifier = Modifier.fillMaxWidth(),
                                    shape = RoundedCornerShape(12.dp),
                                    colors = CardDefaults.cardColors(containerColor = MaterialTheme.colorScheme.surface),
                                    border = BorderStroke(1.dp, MaterialTheme.colorScheme.outlineVariant)
                                ) {
                                    Column(
                                        modifier = Modifier.padding(16.dp),
                                        verticalArrangement = Arrangement.spacedBy(8.dp)
                                    ) {
                                        Row(
                                            modifier = Modifier.fillMaxWidth(),
                                            horizontalArrangement = Arrangement.SpaceBetween,
                                            verticalAlignment = Alignment.CenterVertically
                                        ) {
                                            Card(
                                                colors = CardDefaults.cardColors(containerColor = MaterialTheme.colorScheme.primaryContainer),
                                                shape = RoundedCornerShape(6.dp)
                                            ) {
                                                Text(
                                                    text = subjName,
                                                    fontSize = 10.sp,
                                                    fontWeight = FontWeight.Bold,
                                                    color = MaterialTheme.colorScheme.onPrimaryContainer,
                                                    modifier = Modifier.padding(horizontal = 8.dp, vertical = 2.dp)
                                                )
                                            }
                                            Text(
                                                text = "@${mcq.username} (ID: #${mcq.userId})",
                                                fontSize = 11.sp,
                                                fontWeight = FontWeight.SemiBold,
                                                color = MaterialTheme.colorScheme.primary
                                            )
                                        }

                                        Text(
                                            text = "Topic: $topicName",
                                            fontSize = 11.sp,
                                            color = MaterialTheme.colorScheme.onSurfaceVariant,
                                            fontWeight = FontWeight.Medium
                                        )

                                        Divider(color = MaterialTheme.colorScheme.outlineVariant.copy(alpha = 0.5f))

                                        Text(
                                            text = mcq.question,
                                            fontWeight = FontWeight.Bold,
                                            fontSize = 13.sp
                                        )

                                        Column(verticalArrangement = Arrangement.spacedBy(2.dp)) {
                                            Text("A) ${mcq.optionA}", fontSize = 12.sp)
                                            Text("B) ${mcq.optionB}", fontSize = 12.sp)
                                            Text("C) ${mcq.optionC}", fontSize = 12.sp)
                                            Text("D) ${mcq.optionD}", fontSize = 12.sp)
                                        }

                                        Row(
                                            horizontalArrangement = Arrangement.spacedBy(6.dp),
                                            verticalAlignment = Alignment.CenterVertically
                                        ) {
                                            Text("Correct Option:", fontWeight = FontWeight.SemiBold, fontSize = 11.sp)
                                            Card(
                                                colors = CardDefaults.cardColors(containerColor = Color(0xFF4CAF50)),
                                                shape = RoundedCornerShape(4.dp)
                                            ) {
                                                Text(
                                                    text = "Option ${mcq.correctOption}",
                                                    fontWeight = FontWeight.Bold,
                                                    color = Color.White,
                                                    fontSize = 10.sp,
                                                    modifier = Modifier.padding(horizontal = 6.dp, vertical = 2.dp)
                                                )
                                            }
                                        }

                                        if (mcq.detailedExplanation.isNotEmpty()) {
                                            Text(
                                                text = "Explanation: ${mcq.detailedExplanation}",
                                                fontSize = 11.sp,
                                                fontStyle = FontStyle.Italic,
                                                color = MaterialTheme.colorScheme.onSurfaceVariant
                                            )
                                        }

                                        Row(
                                            modifier = Modifier.fillMaxWidth().padding(top = 8.dp),
                                            horizontalArrangement = Arrangement.spacedBy(8.dp)
                                        ) {
                                            Button(
                                                onClick = { rejectingMcq = mcq },
                                                colors = ButtonDefaults.buttonColors(containerColor = MaterialTheme.colorScheme.error),
                                                shape = RoundedCornerShape(8.dp),
                                                modifier = Modifier.weight(1f).height(40.dp)
                                            ) {
                                                Icon(Icons.Default.Close, contentDescription = null, modifier = Modifier.size(14.dp))
                                                Spacer(modifier = Modifier.width(4.dp))
                                                Text("Reject", fontSize = 12.sp, fontWeight = FontWeight.Bold)
                                            }

                                            Button(
                                                onClick = { viewModel.approvePendingMcq(mcq) },
                                                colors = ButtonDefaults.buttonColors(containerColor = Color(0xFF2E7D32)),
                                                shape = RoundedCornerShape(8.dp),
                                                modifier = Modifier.weight(1f).height(40.dp)
                                            ) {
                                                Icon(Icons.Default.Check, contentDescription = null, modifier = Modifier.size(14.dp))
                                                Spacer(modifier = Modifier.width(4.dp))
                                                Text("Approve", fontSize = 12.sp, fontWeight = FontWeight.Bold)
                                            }
                                        }
                                    }
                                }
                            }
                        }
                    }
                }
                1 -> {
                    // TAB 1: Search Contributor Stats
                    Column(
                        modifier = Modifier.fillMaxSize(),
                        verticalArrangement = Arrangement.spacedBy(10.dp)
                    ) {
                        OutlinedTextField(
                            value = searchQuery,
                            onValueChange = { searchQuery = it },
                            label = { Text("Search by name, ID, or username...") },
                            leadingIcon = { Icon(Icons.Filled.Search, null) },
                            singleLine = true,
                            modifier = Modifier.fillMaxWidth()
                        )

                        val regularUsers = allUsers.filter { it.role == "USER" }
                        val filteredUsers = regularUsers.filter { u ->
                            u.fullName.contains(searchQuery, ignoreCase = true) ||
                            u.username.contains(searchQuery, ignoreCase = true) ||
                            u.id.toString() == searchQuery.trim()
                        }

                        Text(
                            text = "Matching Contributors: ${filteredUsers.size}",
                            fontSize = 11.sp,
                            fontWeight = FontWeight.Bold,
                            color = MaterialTheme.colorScheme.primary
                        )

                        if (filteredUsers.isEmpty()) {
                            Box(
                                modifier = Modifier.fillMaxWidth().weight(1f),
                                contentAlignment = Alignment.Center
                            ) {
                                Text("No contributors found", color = MaterialTheme.colorScheme.onSurfaceVariant)
                            }
                        } else {
                            LazyColumn(
                                verticalArrangement = Arrangement.spacedBy(8.dp),
                                modifier = Modifier.weight(1f)
                            ) {
                                items(filteredUsers) { user ->
                                    Card(
                                        modifier = Modifier.fillMaxWidth(),
                                        shape = RoundedCornerShape(10.dp),
                                        colors = CardDefaults.cardColors(containerColor = MaterialTheme.colorScheme.surface),
                                        border = BorderStroke(1.dp, MaterialTheme.colorScheme.outlineVariant.copy(alpha = 0.5f))
                                    ) {
                                        Row(
                                            modifier = Modifier.padding(12.dp).fillMaxWidth(),
                                            horizontalArrangement = Arrangement.spacedBy(12.dp),
                                            verticalAlignment = Alignment.CenterVertically
                                        ) {
                                            // Circular Letter Avatar
                                            Box(
                                                modifier = Modifier
                                                    .size(40.dp)
                                                    .clip(CircleShape)
                                                    .background(Color(if (user.avatarColor != 0) user.avatarColor else 0xFFD6E3FF.toInt())),
                                                contentAlignment = Alignment.Center
                                            ) {
                                                Text(
                                                    text = user.fullName.firstOrNull()?.uppercase() ?: user.username.firstOrNull()?.uppercase() ?: "U",
                                                    fontWeight = FontWeight.Bold,
                                                    color = Color.White,
                                                    fontSize = 16.sp
                                                )
                                            }

                                            Column(modifier = Modifier.weight(1f)) {
                                                Text(
                                                    text = user.fullName.ifEmpty { "Student" },
                                                    fontWeight = FontWeight.Bold,
                                                    fontSize = 14.sp
                                                )
                                                Text(
                                                    text = "@${user.username} (ID: #${user.id})",
                                                    fontSize = 12.sp,
                                                    color = MaterialTheme.colorScheme.onSurfaceVariant
                                                )
                                                
                                                Row(
                                                    modifier = Modifier.padding(top = 4.dp),
                                                    horizontalArrangement = Arrangement.spacedBy(16.dp)
                                                ) {
                                                    Row(verticalAlignment = Alignment.CenterVertically, horizontalArrangement = Arrangement.spacedBy(4.dp)) {
                                                        Box(modifier = Modifier.size(6.dp).clip(CircleShape).background(Color(0xFF4CAF50)))
                                                        Text("Approved: ${user.approvedMcqs}", fontSize = 11.sp, fontWeight = FontWeight.Bold, color = Color(0xFF2E7D32))
                                                    }
                                                    Row(verticalAlignment = Alignment.CenterVertically, horizontalArrangement = Arrangement.spacedBy(4.dp)) {
                                                        Box(modifier = Modifier.size(6.dp).clip(CircleShape).background(MaterialTheme.colorScheme.error))
                                                        Text("Rejected: ${user.rejectedMcqs}", fontSize = 11.sp, fontWeight = FontWeight.Bold, color = MaterialTheme.colorScheme.error)
                                                    }
                                                }
                                            }
                                        }
                                    }
                                }
                            }
                        }
                    }
                }
                2 -> {
                    // TAB 2: Announcement Manager (Send popups & manage history)
                    LazyColumn(
                        modifier = Modifier.fillMaxSize(),
                        verticalArrangement = Arrangement.spacedBy(12.dp)
                    ) {
                        item {
                            Card(
                                shape = RoundedCornerShape(12.dp),
                                border = BorderStroke(1.dp, MaterialTheme.colorScheme.outlineVariant),
                                colors = CardDefaults.cardColors(containerColor = MaterialTheme.colorScheme.surface)
                            ) {
                                Column(
                                    modifier = Modifier.padding(14.dp),
                                    verticalArrangement = Arrangement.spacedBy(10.dp)
                                ) {
                                    Text(
                                        text = "📢 Create New Pop-up Announcement",
                                        fontWeight = FontWeight.Bold,
                                        fontSize = 14.sp,
                                        color = MaterialTheme.colorScheme.primary
                                    )

                                    OutlinedTextField(
                                        value = annMessage,
                                        onValueChange = { annMessage = it },
                                        label = { Text("Message details (Urdu/English)") },
                                        placeholder = { Text("Write important announcement here...") },
                                        modifier = Modifier.fillMaxWidth(),
                                        maxLines = 4
                                    )

                                    OutlinedTextField(
                                        value = annImageUrl,
                                        onValueChange = { annImageUrl = it },
                                        label = { Text("Image URL (Optional)") },
                                        placeholder = { Text("https://example.com/image.png") },
                                        singleLine = true,
                                        modifier = Modifier.fillMaxWidth()
                                    )

                                    // Quick visual asset templates (adds premium developer polish)
                                    Row(horizontalArrangement = Arrangement.spacedBy(6.dp)) {
                                        listOf(
                                            "Clear" to "",
                                            "Trophy" to "https://images.unsplash.com/photo-1578269174936-2709b5a5e023?w=500&q=80",
                                            "Notice" to "https://images.unsplash.com/photo-1427504494785-3a9ca7044f45?w=500&q=80"
                                        ).forEach { (label, url) ->
                                            Card(
                                                shape = RoundedCornerShape(6.dp),
                                                colors = CardDefaults.cardColors(containerColor = MaterialTheme.colorScheme.secondaryContainer.copy(alpha = 0.5f)),
                                                modifier = Modifier.clickable { annImageUrl = url }
                                            ) {
                                                Text(
                                                    text = label,
                                                    fontSize = 11.sp,
                                                    color = MaterialTheme.colorScheme.onSecondaryContainer,
                                                    modifier = Modifier.padding(horizontal = 8.dp, vertical = 4.dp)
                                                )
                                            }
                                        }
                                    }

                                    Divider(color = MaterialTheme.colorScheme.outlineVariant.copy(alpha = 0.5f))

                                    // Duration slider/row
                                    Text("Display Duration: $annDuration seconds", fontWeight = FontWeight.Bold, fontSize = 12.sp)
                                    Row(horizontalArrangement = Arrangement.spacedBy(6.dp)) {
                                        listOf(5, 10, 15, 30).forEach { secs ->
                                            val isSel = annDuration == secs
                                            Card(
                                                shape = RoundedCornerShape(8.dp),
                                                colors = CardDefaults.cardColors(
                                                    containerColor = if (isSel) MaterialTheme.colorScheme.primaryContainer else MaterialTheme.colorScheme.surfaceVariant.copy(alpha = 0.5f)
                                                ),
                                                border = BorderStroke(1.dp, if (isSel) MaterialTheme.colorScheme.primary else Color.Transparent),
                                                modifier = Modifier
                                                    .weight(1f)
                                                    .clickable { annDuration = secs }
                                            ) {
                                                Text(
                                                    text = "$secs sec",
                                                    modifier = Modifier.padding(vertical = 8.dp).fillMaxWidth(),
                                                    textAlign = TextAlign.Center,
                                                    fontWeight = FontWeight.Bold,
                                                    fontSize = 11.sp,
                                                    color = if (isSel) MaterialTheme.colorScheme.onPrimaryContainer else MaterialTheme.colorScheme.onSurfaceVariant
                                                )
                                            }
                                        }
                                    }

                                    // Dismiss behavior Segment toggle
                                    Row(
                                        modifier = Modifier.fillMaxWidth(),
                                        horizontalArrangement = Arrangement.SpaceBetween,
                                        verticalAlignment = Alignment.CenterVertically
                                    ) {
                                        Column {
                                            Text("Closeable popup", fontWeight = FontWeight.Bold, fontSize = 12.sp)
                                            Text(
                                                text = if (annIsCloseable) "User can close anytime" else "Locked modal (must complete timer)",
                                                fontSize = 10.sp,
                                                color = MaterialTheme.colorScheme.onSurfaceVariant.copy(alpha = 0.7f)
                                            )
                                        }
                                        Switch(
                                            checked = annIsCloseable,
                                            onCheckedChange = { annIsCloseable = it }
                                        )
                                    }

                                    Divider(color = MaterialTheme.colorScheme.outlineVariant.copy(alpha = 0.5f))

                                    // Targets setting
                                    Text("Target Receivers:", fontWeight = FontWeight.Bold, fontSize = 12.sp)
                                    Row(horizontalArrangement = Arrangement.spacedBy(10.dp)) {
                                        Row(verticalAlignment = Alignment.CenterVertically, modifier = Modifier.clickable { annTargetAll = true }) {
                                            RadioButton(selected = annTargetAll, onClick = { annTargetAll = true })
                                            Text("All Users", fontSize = 12.sp)
                                        }
                                        Row(verticalAlignment = Alignment.CenterVertically, modifier = Modifier.clickable { annTargetAll = false }) {
                                            RadioButton(selected = !annTargetAll, onClick = { annTargetAll = false })
                                            Text("Specific Users", fontSize = 12.sp)
                                        }
                                    }

                                    // Specific user multi selection picker with search bar
                                    if (!annTargetAll) {
                                        OutlinedTextField(
                                            value = userSearchQuery,
                                            onValueChange = { userSearchQuery = it },
                                            placeholder = { Text("Filter users to select...") },
                                            singleLine = true,
                                            modifier = Modifier.fillMaxWidth(),
                                            leadingIcon = { Icon(Icons.Filled.Search, null, modifier = Modifier.size(16.dp)) }
                                        )

                                        val regularUsers = allUsers.filter { it.role == "USER" }
                                        val filterQuery = regularUsers.filter { u ->
                                            u.fullName.contains(userSearchQuery, ignoreCase = true) ||
                                            u.username.contains(userSearchQuery, ignoreCase = true) ||
                                            u.id.toString() == userSearchQuery.trim()
                                        }

                                        Card(
                                            colors = CardDefaults.cardColors(containerColor = MaterialTheme.colorScheme.surfaceVariant.copy(alpha = 0.2f)),
                                            border = BorderStroke(1.dp, MaterialTheme.colorScheme.outlineVariant),
                                            modifier = Modifier
                                                .fillMaxWidth()
                                                .heightIn(max = 140.dp)
                                        ) {
                                            LazyColumn(
                                                modifier = Modifier.padding(6.dp),
                                                verticalArrangement = Arrangement.spacedBy(4.dp)
                                            ) {
                                                items(filterQuery) { u ->
                                                    val isSelected = selectedUserIds[u.id] ?: false
                                                    Row(
                                                        modifier = Modifier
                                                            .fillMaxWidth()
                                                            .clickable { selectedUserIds[u.id] = !isSelected }
                                                            .padding(horizontal = 6.dp, vertical = 2.dp),
                                                        verticalAlignment = Alignment.CenterVertically,
                                                        horizontalArrangement = Arrangement.SpaceBetween
                                                    ) {
                                                        Text("@${u.username} (${u.fullName})", fontSize = 11.sp, fontWeight = FontWeight.Medium)
                                                        Checkbox(
                                                            checked = isSelected,
                                                            onCheckedChange = { selectedUserIds[u.id] = it }
                                                        )
                                                    }
                                                }
                                            }
                                        }
                                        
                                        val selectedCount = selectedUserIds.filter { it.value }.size
                                        Text("Targeting: $selectedCount users", fontSize = 10.sp, fontWeight = FontWeight.Bold, color = MaterialTheme.colorScheme.primary)
                                    }

                                    Button(
                                        onClick = {
                                            if (annMessage.trim().isEmpty()) {
                                                viewModel.feedbackMessage.value = "Announcement message cannot be empty."
                                                return@Button
                                            }
                                            val targetString = if (annTargetAll) {
                                                "all"
                                            } else {
                                                val idsList = selectedUserIds.filter { it.value }.keys.toList()
                                                if (idsList.isEmpty()) {
                                                    viewModel.feedbackMessage.value = "Please select at least 1 targeted user."
                                                    return@Button
                                                }
                                                idsList.joinToString(",")
                                            }

                                            viewModel.sendAnnouncement(
                                                imageUrl = annImageUrl.trim(),
                                                message = annMessage.trim(),
                                                targetUserIds = targetString,
                                                displayDuration = annDuration,
                                                isCloseable = annIsCloseable,
                                                onComplete = {
                                                    annMessage = ""
                                                    annImageUrl = ""
                                                    selectedUserIds.clear()
                                                }
                                            )
                                        },
                                        shape = RoundedCornerShape(8.dp),
                                        modifier = Modifier.fillMaxWidth()
                                    ) {
                                        Icon(Icons.Filled.Check, null)
                                        Spacer(modifier = Modifier.width(6.dp))
                                        Text("Publish Announcement", fontWeight = FontWeight.Bold)
                                    }
                                }
                            }
                        }

                        // Sent Announcements History Title
                        item {
                            Text(
                                text = "Sent Announcements Feed (${announcements.size})",
                                fontWeight = FontWeight.Bold,
                                fontSize = 13.sp,
                                modifier = Modifier.padding(top = 10.dp),
                                color = MaterialTheme.colorScheme.primary
                            )
                        }

                        if (announcements.isEmpty()) {
                            item {
                                Card(
                                    modifier = Modifier.fillMaxWidth(),
                                    colors = CardDefaults.cardColors(containerColor = MaterialTheme.colorScheme.surfaceVariant.copy(alpha = 0.3f))
                                ) {
                                    Column(
                                        modifier = Modifier.padding(18.dp).fillMaxWidth(),
                                        horizontalAlignment = Alignment.CenterHorizontally
                                    ) {
                                        Text("✏️", fontSize = 24.sp)
                                        Text("No Sent Announcements", fontSize = 12.sp, fontWeight = FontWeight.Bold, color = MaterialTheme.colorScheme.onSurfaceVariant)
                                    }
                                }
                            }
                        } else {
                            items(announcements) { ann ->
                                Card(
                                    modifier = Modifier.fillMaxWidth(),
                                    shape = RoundedCornerShape(10.dp),
                                    colors = CardDefaults.cardColors(containerColor = MaterialTheme.colorScheme.surface),
                                    border = BorderStroke(1.dp, MaterialTheme.colorScheme.outlineVariant)
                                ) {
                                    Column(
                                        modifier = Modifier.padding(12.dp),
                                        verticalArrangement = Arrangement.spacedBy(6.dp)
                                    ) {
                                        Row(
                                            modifier = Modifier.fillMaxWidth(),
                                            horizontalArrangement = Arrangement.SpaceBetween,
                                            verticalAlignment = Alignment.CenterVertically
                                        ) {
                                            Row(horizontalArrangement = Arrangement.spacedBy(6.dp)) {
                                                Card(
                                                    colors = CardDefaults.cardColors(
                                                        containerColor = if (ann.isCloseable) Color(0xFFE8F5E9) else Color(0xFFFFEBEE)
                                                    )
                                                ) {
                                                    Text(
                                                        text = if (ann.isCloseable) "Closeable" else "Forced Modal",
                                                        fontSize = 9.sp,
                                                        fontWeight = FontWeight.Bold,
                                                        color = if (ann.isCloseable) Color(0xFF2E7D32) else Color(0xFFC62828),
                                                        modifier = Modifier.padding(horizontal = 6.dp, vertical = 2.dp)
                                                    )
                                                }
                                                Card(
                                                    colors = CardDefaults.cardColors(containerColor = MaterialTheme.colorScheme.secondaryContainer)
                                                ) {
                                                    Text(
                                                        text = "${ann.displayDuration} Secs",
                                                        fontSize = 9.sp,
                                                        fontWeight = FontWeight.Bold,
                                                        color = MaterialTheme.colorScheme.onSecondaryContainer,
                                                        modifier = Modifier.padding(horizontal = 6.dp, vertical = 2.dp)
                                                    )
                                                }
                                            }

                                            IconButton(
                                                onClick = { viewModel.deleteAnnouncement(ann) },
                                                modifier = Modifier.size(24.dp)
                                            ) {
                                                Icon(
                                                    imageVector = Icons.Default.Delete,
                                                    contentDescription = "Delete",
                                                    tint = MaterialTheme.colorScheme.error,
                                                    modifier = Modifier.size(16.dp)
                                                )
                                            }
                                        }

                                        Text(text = ann.message, fontSize = 12.sp, fontWeight = FontWeight.Medium)

                                        if (ann.imageUrl.isNotEmpty()) {
                                            Text(
                                                text = "Image attachment: ${ann.imageUrl.take(35)}...",
                                                fontSize = 10.sp,
                                                fontStyle = FontStyle.Italic,
                                                color = MaterialTheme.colorScheme.onSurfaceVariant
                                            )
                                        }

                                        Divider(color = MaterialTheme.colorScheme.outlineVariant.copy(alpha = 0.3f))

                                        Row(
                                            horizontalArrangement = Arrangement.spacedBy(4.dp),
                                            verticalAlignment = Alignment.CenterVertically
                                        ) {
                                            Icon(Icons.Filled.AccountBox, null, modifier = Modifier.size(12.dp), tint = MaterialTheme.colorScheme.onSurfaceVariant)
                                            Text(
                                                text = "Receivers: " + if (ann.targetUserIds == "all") "All Users" else "IDs [${ann.targetUserIds}]",
                                                fontSize = 10.sp,
                                                color = MaterialTheme.colorScheme.onSurfaceVariant,
                                                fontWeight = FontWeight.SemiBold
                                            )
                                        }
                                    }
                                }
                            }
                        }
                    }
                }
                3 -> {
                    // TAB 3: SQL Helper instructions
                    Column(
                        modifier = Modifier
                            .fillMaxSize()
                            .verticalScroll(rememberScrollState()),
                        verticalArrangement = Arrangement.spacedBy(12.dp)
                    ) {
                        Card(
                            colors = CardDefaults.cardColors(
                                containerColor = MaterialTheme.colorScheme.primaryContainer.copy(alpha = 0.4f)
                            ),
                            shape = RoundedCornerShape(12.dp),
                            modifier = Modifier.fillMaxWidth()
                        ) {
                            Column(modifier = Modifier.padding(14.dp), verticalArrangement = Arrangement.spacedBy(6.dp)) {
                                Text(
                                    text = "Supabase API Sync Tables",
                                    fontWeight = FontWeight.Bold,
                                    fontSize = 15.sp,
                                    color = MaterialTheme.colorScheme.primary
                                )
                                Text(
                                    text = "To ensure contributor credentials AND announcements operate smoothly on remote Supabase APIs, copy and execute the PostgreSQL ALTER & CREATE table setup code in your Supabase project's SQL Editor.",
                                    fontSize = 12.sp,
                                    lineHeight = 18.sp,
                                    color = MaterialTheme.colorScheme.onPrimaryContainer
                                )
                            }
                        }

                        Text("Run the following PostgreSQL queries:", fontWeight = FontWeight.Bold, fontSize = 13.sp)

                        // SQL Box
                        Card(
                            colors = CardDefaults.cardColors(containerColor = if (isDark) Color(0xFF1E1E2E) else Color(0xFFF1F5F9)),
                            shape = RoundedCornerShape(8.dp),
                            border = BorderStroke(1.dp, MaterialTheme.colorScheme.outlineVariant),
                            modifier = Modifier.fillMaxWidth()
                        ) {
                            Column(modifier = Modifier.padding(14.dp)) {
                                Text(
                                    text = "-- 1. Add MCQ stat trackers to users table\n" +
                                            "ALTER TABLE users ADD COLUMN IF NOT EXISTS approved_mcqs integer DEFAULT 0;\n" +
                                            "ALTER TABLE users ADD COLUMN IF NOT EXISTS rejected_mcqs integer DEFAULT 0;\n\n" +
                                            "-- 2. Build/Configure Announcements Table\n" +
                                            "CREATE TABLE IF NOT EXISTS announcements (\n" +
                                            "    id bigint PRIMARY KEY GENERATED BY DEFAULT AS IDENTITY,\n" +
                                            "    \"imageUrl\" text DEFAULT '',\n" +
                                            "    message text NOT NULL,\n" +
                                            "    \"targetUserIds\" text NOT NULL,\n" +
                                            "    \"displayDuration\" integer NOT NULL DEFAULT 5,\n" +
                                            "    \"isCloseable\" boolean NOT NULL DEFAULT true,\n" +
                                            "    timestamp bigint NOT NULL\n" +
                                            ");\n\n" +
                                            "-- 3. Delete old pending_mcqs table (No longer needed)\n" +
                                            "DROP TABLE IF EXISTS pending_mcqs CASCADE;\n\n" +
                                            "-- 4. Build/Configure unified MCQs Table with status field\n" +
                                            "CREATE TABLE IF NOT EXISTS mcqs (\n" +
                                            "    id bigint PRIMARY KEY GENERATED BY DEFAULT AS IDENTITY,\n" +
                                            "    subject_id integer NOT NULL,\n" +
                                            "    topic_id integer NOT NULL,\n" +
                                            "    question text NOT NULL,\n" +
                                            "    option_a text NOT NULL,\n" +
                                            "    option_b text NOT NULL,\n" +
                                            "    option_c text NOT NULL,\n" +
                                            "    option_d text NOT NULL,\n" +
                                            "    correct_option text NOT NULL,\n" +
                                            "    detailed_explanation text DEFAULT '',\n" +
                                            "    difficulty text NOT NULL DEFAULT 'MEDIUM',\n" +
                                            "    status text NOT NULL DEFAULT 'APPROVED',\n" +
                                            "    user_id integer NOT NULL DEFAULT 0,\n" +
                                            "    text_username text NOT NULL DEFAULT '',\n" +
                                            "    created_at bigint DEFAULT 0,\n" +
                                            "    subject_name text NOT NULL DEFAULT '',\n" +
                                            "    topic_name text NOT NULL DEFAULT ''\n" +
                                            ");\n" +
                                            "ALTER TABLE mcqs RENAME COLUMN username TO text_username;\n" +
                                            "ALTER TABLE mcqs ADD COLUMN IF NOT EXISTS detailed_explanation text DEFAULT '';\n" +
                                            "ALTER TABLE mcqs ADD COLUMN IF NOT EXISTS difficulty text NOT NULL DEFAULT 'MEDIUM';\n" +
                                            "ALTER TABLE mcqs ADD COLUMN IF NOT EXISTS status text NOT NULL DEFAULT 'APPROVED';\n" +
                                            "ALTER TABLE mcqs ADD COLUMN IF NOT EXISTS user_id integer NOT NULL DEFAULT 0;\n" +
                                            "ALTER TABLE mcqs ADD COLUMN IF NOT EXISTS text_username text NOT NULL DEFAULT '';\n" +
                                            "ALTER TABLE mcqs ADD COLUMN IF NOT EXISTS created_at bigint DEFAULT 0;\n" +
                                            "ALTER TABLE mcqs ADD COLUMN IF NOT EXISTS subject_name text NOT NULL DEFAULT '';\n" +
                                            "ALTER TABLE mcqs ADD COLUMN IF NOT EXISTS topic_name text NOT NULL DEFAULT '';\n\n" +
                                            "-- NOTE: If you have existing tables and see sequence or ID constraint faults, run this first:\n" +
                                            "-- DROP TABLE IF EXISTS announcements, pending_mcqs, mcqs CASCADE;",
                                    fontFamily = androidx.compose.ui.text.font.FontFamily.Monospace,
                                    fontSize = 10.sp,
                                    color = if (isDark) Color(0xFF00FFC4) else Color(0xFF0F172A),
                                    lineHeight = 15.sp
                                )
                            }
                        }

                        Text(
                            text = "💡 Note: High-precision column casing mapping is mandatory to correspond perfectly with Retrofit/Moshi serializations without disrupting core DB structure operations.",
                            fontSize = 11.sp,
                            lineHeight = 16.sp,
                            color = MaterialTheme.colorScheme.onSurfaceVariant.copy(alpha = 0.8f)
                        )
                    }
                }
            }
        }
    }

    // Rejection reason dialog
    if (rejectingMcq != null) {
        AlertDialog(
            onDismissRequest = { rejectingMcq = null },
            title = { Text("Reject Submission", fontWeight = FontWeight.Bold) },
            text = {
                Column(verticalArrangement = Arrangement.spacedBy(10.dp)) {
                    Text("Please write a Roman Urdu rejection reason to send to @${rejectingMcq!!.username} as a push notification:")
                    OutlinedTextField(
                        value = rejectionReason,
                        onValueChange = { rejectionReason = it },
                        label = { Text("Reason (in Roman Urdu)") },
                        modifier = Modifier.fillMaxWidth(),
                        maxLines = 3
                    )
                }
            },
            confirmButton = {
                Button(
                    onClick = {
                        if (rejectionReason.trim().isEmpty()) {
                            viewModel.feedbackMessage.value = "Please write a reason."
                        } else {
                            viewModel.rejectPendingMcq(rejectingMcq!!, rejectionReason.trim())
                            rejectingMcq = null
                            rejectionReason = ""
                        }
                    },
                    colors = ButtonDefaults.buttonColors(containerColor = MaterialTheme.colorScheme.error)
                ) {
                    Text("Confirm Rejection", fontWeight = FontWeight.Bold)
                }
            },
            dismissButton = {
                TextButton(onClick = { rejectingMcq = null }) {
                    Text("Cancel")
                }
            },
            shape = RoundedCornerShape(16.dp)
        )
    }
}

// ==================== SCREEN: STANDALONE ADMIN ANNOUNCEMENTS MANAGER ====================
@OptIn(ExperimentalMaterial3Api::class)
@Composable
fun AdminAnnouncementsScreen(viewModel: MainViewModel) {
    val announcements by viewModel.allAnnouncements.collectAsState()
    val allUsers by viewModel.allUsers.collectAsState()
    val isDark = isSystemInDarkTheme()
    val context = androidx.compose.ui.platform.LocalContext.current
    val coroutineScope = rememberCoroutineScope()

    var selectedTab by remember { mutableStateOf(0) } // 0: Form & Active Feed, 1: DB Migration Helper

    // Forms state
    var annMessage by remember { mutableStateOf("") }
    var annImageUrl by remember { mutableStateOf("") }
    var annDuration by remember { mutableStateOf(5) }
    var annIsCloseable by remember { mutableStateOf(true) }
    var annTargetAll by remember { mutableStateOf(true) }
    val selectedUserIds = remember { mutableStateMapOf<Int, Boolean>() }
    var userSearchQuery by remember { mutableStateOf("") }
    var isUploadingImage by remember { mutableStateOf(false) }

    val imagePickerLauncher = androidx.activity.compose.rememberLauncherForActivityResult(
        contract = androidx.activity.result.contract.ActivityResultContracts.GetContent()
    ) { uri: android.net.Uri? ->
        uri?.let {
            coroutineScope.launch {
                isUploadingImage = true
                var savedPath = viewModel.uploadFileToSimulatedStorage(context, it, "announcements")
                var isFallback = false
                if (savedPath == null) {
                    try {
                        val resolver = context.contentResolver
                        val bytes = resolver.openInputStream(it)?.use { stream -> stream.readBytes() }
                        if (bytes != null) {
                            val localFile = java.io.File(context.cacheDir, "announcement_${System.currentTimeMillis()}.jpg")
                            localFile.writeBytes(bytes)
                            savedPath = localFile.absolutePath
                            isFallback = true
                        }
                    } catch (e: Exception) {
                        e.printStackTrace()
                    }
                }
                if (savedPath != null) {
                    annImageUrl = savedPath
                    viewModel.feedbackMessage.value = if (isFallback) "Announcement image attached locally (Offline Mode)!" else "Announcement image uploaded & attached successfully!"
                } else {
                    viewModel.feedbackMessage.value = "Photo upload failed. Check files permissions."
                }
                isUploadingImage = false
            }
        }
    }

    Scaffold(
        topBar = {
            TopAppBar(
                title = { Text("Publish Announcements", fontWeight = FontWeight.Bold) },
                navigationIcon = {
                    IconButton(onClick = { viewModel.navigateTo(Screen.AdminDashboard) }) {
                        Icon(Icons.Filled.ArrowBack, contentDescription = "Back")
                    }
                },
                colors = TopAppBarDefaults.topAppBarColors(
                    containerColor = if (isDark) Color(0xFF121212) else MaterialTheme.colorScheme.surface
                )
            )
        },
        containerColor = if (isDark) Color(0xFF121212) else MaterialTheme.colorScheme.background
    ) { paddingValues ->
        Column(
            modifier = Modifier
                .fillMaxSize()
                .padding(paddingValues)
                .padding(horizontal = 16.dp)
        ) {
            // Screen Level Tabs
            Row(
                modifier = Modifier
                    .fillMaxWidth()
                    .padding(vertical = 8.dp),
                horizontalArrangement = Arrangement.spacedBy(4.dp)
            ) {
                listOf(
                    "Announcements (${announcements.size})",
                    "Database Setup"
                ).forEachIndexed { index, title ->
                    val isSelected = selectedTab == index
                    Card(
                        modifier = Modifier
                            .weight(1f)
                            .clickable { selectedTab = index },
                        colors = CardDefaults.cardColors(
                            containerColor = if (isSelected) {
                                if (isDark) MaterialTheme.colorScheme.primaryContainer else MaterialTheme.colorScheme.primary
                            } else {
                                if (isDark) Color(0xFF1E1E1E) else MaterialTheme.colorScheme.surfaceVariant.copy(alpha = 0.5f)
                            }
                        ),
                        shape = RoundedCornerShape(10.dp),
                        border = BorderStroke(
                            1.dp,
                            if (isSelected) MaterialTheme.colorScheme.primary else MaterialTheme.colorScheme.outlineVariant.copy(alpha = 0.5f)
                        )
                    ) {
                        Text(
                            text = title,
                            modifier = Modifier
                                .fillMaxWidth()
                                .padding(vertical = 10.dp),
                            textAlign = TextAlign.Center,
                            fontWeight = FontWeight.Bold,
                            fontSize = 12.sp,
                            color = if (isSelected) {
                                if (isDark) MaterialTheme.colorScheme.onPrimaryContainer else Color.White
                            } else {
                                MaterialTheme.colorScheme.onSurfaceVariant
                            }
                        )
                    }
                }
            }

            Spacer(modifier = Modifier.height(8.dp))

            when (selectedTab) {
                0 -> {
                    LazyColumn(
                        modifier = Modifier.fillMaxSize(),
                        verticalArrangement = Arrangement.spacedBy(16.dp)
                    ) {
                        item {
                            Card(
                                shape = RoundedCornerShape(12.dp),
                                border = BorderStroke(1.dp, MaterialTheme.colorScheme.outlineVariant),
                                colors = CardDefaults.cardColors(containerColor = MaterialTheme.colorScheme.surface)
                            ) {
                                Column(
                                    modifier = Modifier.padding(14.dp),
                                    verticalArrangement = Arrangement.spacedBy(12.dp)
                                ) {
                                    Text(
                                        text = "📢 Create New Pop-up Announcement",
                                        fontWeight = FontWeight.Bold,
                                        fontSize = 14.sp,
                                        color = MaterialTheme.colorScheme.primary
                                    )

                                    OutlinedTextField(
                                        value = annMessage,
                                        onValueChange = { annMessage = it },
                                        label = { Text("Message details (Urdu/English)") },
                                        placeholder = { Text("Write important announcement here...") },
                                        modifier = Modifier.fillMaxWidth().testTag("announcement_text_message"),
                                        maxLines = 4
                                    )

                                    Column(verticalArrangement = Arrangement.spacedBy(4.dp)) {
                                        Text("Announcement Image Attachment:", fontWeight = FontWeight.SemiBold, fontSize = 11.sp)
                                        Row(
                                            modifier = Modifier.fillMaxWidth(),
                                            horizontalArrangement = Arrangement.spacedBy(8.dp),
                                            verticalAlignment = Alignment.CenterVertically
                                        ) {
                                            OutlinedTextField(
                                                value = annImageUrl,
                                                onValueChange = { annImageUrl = it },
                                                label = { Text("Image URL or Attached Path") },
                                                placeholder = { Text("No image selected") },
                                                modifier = Modifier.weight(1f),
                                                singleLine = true
                                            )
                                            Button(
                                                onClick = { imagePickerLauncher.launch("image/*") },
                                                shape = RoundedCornerShape(8.dp),
                                                modifier = Modifier.height(56.dp).testTag("select_announcement_photo_button")
                                            ) {
                                                if (isUploadingImage) {
                                                    CircularProgressIndicator(modifier = Modifier.size(18.dp), color = MaterialTheme.colorScheme.onPrimary, strokeWidth = 2.dp)
                                                } else {
                                                    Icon(Icons.Default.PhotoLibrary, "Pick")
                                                    Spacer(modifier = Modifier.width(4.dp))
                                                    Text("Pick File")
                                                }
                                            }
                                        }
                                    }

                                    // Quick visual templates
                                    Row(horizontalArrangement = Arrangement.spacedBy(6.dp)) {
                                        listOf(
                                            "Clear" to "",
                                            "Trophy" to "https://images.unsplash.com/photo-1578269174936-2709b5a5e023?w=500&q=80",
                                            "Notice" to "https://images.unsplash.com/photo-1427504494785-3a9ca7044f45?w=500&q=80"
                                        ).forEach { (label, url) ->
                                            Card(
                                                shape = RoundedCornerShape(6.dp),
                                                colors = CardDefaults.cardColors(containerColor = MaterialTheme.colorScheme.secondaryContainer.copy(alpha = 0.5f)),
                                                modifier = Modifier.clickable { annImageUrl = url }
                                            ) {
                                                Text(
                                                    text = label,
                                                    fontSize = 11.sp,
                                                    color = MaterialTheme.colorScheme.onSecondaryContainer,
                                                    modifier = Modifier.padding(horizontal = 8.dp, vertical = 4.dp)
                                                )
                                            }
                                        }
                                    }

                                    Divider(color = MaterialTheme.colorScheme.outlineVariant.copy(alpha = 0.5f))

                                    // Duration slider/row
                                    Text("Display Duration: $annDuration seconds", fontWeight = FontWeight.Bold, fontSize = 12.sp)
                                    Row(horizontalArrangement = Arrangement.spacedBy(6.dp)) {
                                        listOf(5, 10, 15, 30).forEach { secs ->
                                            val isSel = annDuration == secs
                                            Card(
                                                shape = RoundedCornerShape(8.dp),
                                                colors = CardDefaults.cardColors(
                                                    containerColor = if (isSel) MaterialTheme.colorScheme.primaryContainer else MaterialTheme.colorScheme.surfaceVariant.copy(alpha = 0.5f)
                                                ),
                                                border = BorderStroke(1.dp, if (isSel) MaterialTheme.colorScheme.primary else Color.Transparent),
                                                modifier = Modifier
                                                    .weight(1f)
                                                    .clickable { annDuration = secs }
                                            ) {
                                                Text(
                                                    text = "$secs sec",
                                                    modifier = Modifier.padding(vertical = 8.dp).fillMaxWidth(),
                                                    textAlign = TextAlign.Center,
                                                    fontWeight = FontWeight.Bold,
                                                    fontSize = 11.sp,
                                                    color = if (isSel) MaterialTheme.colorScheme.onPrimaryContainer else MaterialTheme.colorScheme.onSurfaceVariant
                                                )
                                            }
                                        }
                                    }

                                    // Dismiss behavior Segment toggle
                                    Row(
                                        modifier = Modifier.fillMaxWidth(),
                                        horizontalArrangement = Arrangement.SpaceBetween,
                                        verticalAlignment = Alignment.CenterVertically
                                    ) {
                                        Column {
                                            Text("Closeable popup", fontWeight = FontWeight.Bold, fontSize = 12.sp)
                                            Text(
                                                text = if (annIsCloseable) "User can close anytime" else "Locked modal (must complete timer)",
                                                fontSize = 10.sp,
                                                color = MaterialTheme.colorScheme.onSurfaceVariant.copy(alpha = 0.7f)
                                            )
                                        }
                                        Switch(
                                            checked = annIsCloseable,
                                            onCheckedChange = { annIsCloseable = it }
                                        )
                                    }

                                    Divider(color = MaterialTheme.colorScheme.outlineVariant.copy(alpha = 0.5f))

                                    // Targets setting
                                    Text("Target Receivers:", fontWeight = FontWeight.Bold, fontSize = 12.sp)
                                    Row(horizontalArrangement = Arrangement.spacedBy(10.dp)) {
                                        Row(verticalAlignment = Alignment.CenterVertically, modifier = Modifier.clickable { annTargetAll = true }) {
                                            RadioButton(selected = annTargetAll, onClick = { annTargetAll = true })
                                            Text("All Users", fontSize = 12.sp)
                                        }
                                        Row(verticalAlignment = Alignment.CenterVertically, modifier = Modifier.clickable { annTargetAll = false }) {
                                            RadioButton(selected = !annTargetAll, onClick = { annTargetAll = false })
                                            Text("Specific Users", fontSize = 12.sp)
                                        }
                                    }

                                    // Specific user multi selection picker with search bar
                                    if (!annTargetAll) {
                                        OutlinedTextField(
                                            value = userSearchQuery,
                                            onValueChange = { userSearchQuery = it },
                                            placeholder = { Text("Filter users to select...") },
                                            singleLine = true,
                                            modifier = Modifier.fillMaxWidth(),
                                            leadingIcon = { Icon(Icons.Filled.Search, null, modifier = Modifier.size(16.dp)) }
                                        )

                                        val regularUsers = allUsers.filter { it.role == "USER" }
                                        val filterQuery = regularUsers.filter { u ->
                                            u.fullName.contains(userSearchQuery, ignoreCase = true) ||
                                            u.username.contains(userSearchQuery, ignoreCase = true) ||
                                            u.id.toString() == userSearchQuery.trim()
                                        }

                                        Card(
                                            colors = CardDefaults.cardColors(containerColor = MaterialTheme.colorScheme.surfaceVariant.copy(alpha = 0.2f)),
                                            border = BorderStroke(1.dp, MaterialTheme.colorScheme.outlineVariant),
                                            modifier = Modifier
                                                .fillMaxWidth()
                                                .heightIn(max = 140.dp)
                                        ) {
                                            LazyColumn(
                                                modifier = Modifier.padding(6.dp),
                                                verticalArrangement = Arrangement.spacedBy(4.dp)
                                            ) {
                                                items(filterQuery) { u ->
                                                    val isSelected = selectedUserIds[u.id] ?: false
                                                    Row(
                                                        modifier = Modifier
                                                            .fillMaxWidth()
                                                            .clickable { selectedUserIds[u.id] = !isSelected }
                                                            .padding(horizontal = 6.dp, vertical = 2.dp),
                                                        verticalAlignment = Alignment.CenterVertically,
                                                        horizontalArrangement = Arrangement.SpaceBetween
                                                    ) {
                                                        Text("@${u.username} (${u.fullName})", fontSize = 11.sp, fontWeight = FontWeight.Medium)
                                                        Checkbox(
                                                            checked = isSelected,
                                                            onCheckedChange = { selectedUserIds[u.id] = it }
                                                        )
                                                    }
                                                }
                                            }
                                        }

                                        val selectedCount = selectedUserIds.filter { it.value }.size
                                        Text("Targeting: $selectedCount users", fontSize = 10.sp, fontWeight = FontWeight.Bold, color = MaterialTheme.colorScheme.primary)
                                    }

                                    ByButtonRow(
                                        viewModel = viewModel,
                                        annMessage = { annMessage },
                                        annImageUrl = { annImageUrl },
                                        annDuration = { annDuration },
                                        annIsCloseable = { annIsCloseable },
                                        annTargetAll = { annTargetAll },
                                        selectedUserIds = selectedUserIds,
                                        onPublishSuccess = {
                                            annMessage = ""
                                            annImageUrl = ""
                                            selectedUserIds.clear()
                                        }
                                    )
                                }
                            }
                        }

                        // Sent Announcements History Title
                        item {
                            Text(
                                text = "Sent Announcements History (${announcements.size})",
                                fontWeight = FontWeight.Bold,
                                fontSize = 14.sp,
                                color = MaterialTheme.colorScheme.primary
                            )
                        }

                        if (announcements.isEmpty()) {
                            item {
                                Card(
                                    modifier = Modifier.fillMaxWidth(),
                                    colors = CardDefaults.cardColors(containerColor = MaterialTheme.colorScheme.surfaceVariant.copy(alpha = 0.3f))
                                ) {
                                    Column(
                                        modifier = Modifier.padding(24.dp).fillMaxWidth(),
                                        horizontalAlignment = Alignment.CenterHorizontally
                                    ) {
                                        Text("✏️", fontSize = 32.sp)
                                        Text("No Sent Announcements Yet", fontSize = 13.sp, fontWeight = FontWeight.Bold, color = MaterialTheme.colorScheme.onSurfaceVariant)
                                        Text("When you publish announcements, active logs will display right here.", fontSize = 11.sp, color = MaterialTheme.colorScheme.onSurfaceVariant.copy(alpha = 0.7f), textAlign = TextAlign.Center)
                                    }
                                }
                            }
                        } else {
                            items(announcements) { ann ->
                                Card(
                                    modifier = Modifier.fillMaxWidth(),
                                    shape = RoundedCornerShape(10.dp),
                                    colors = CardDefaults.cardColors(containerColor = MaterialTheme.colorScheme.surface),
                                    border = BorderStroke(1.dp, MaterialTheme.colorScheme.outlineVariant)
                                ) {
                                    Column(
                                        modifier = Modifier.padding(12.dp),
                                        verticalArrangement = Arrangement.spacedBy(6.dp)
                                    ) {
                                        Row(
                                            modifier = Modifier.fillMaxWidth(),
                                            horizontalArrangement = Arrangement.SpaceBetween,
                                            verticalAlignment = Alignment.CenterVertically
                                        ) {
                                            Row(horizontalArrangement = Arrangement.spacedBy(6.dp)) {
                                                Card(
                                                    colors = CardDefaults.cardColors(
                                                        containerColor = if (ann.isCloseable) Color(0xFFE8F5E9) else Color(0xFFFFEBEE)
                                                    )
                                                ) {
                                                    Text(
                                                        text = if (ann.isCloseable) "Closeable" else "Forced Modal",
                                                        fontSize = 9.sp,
                                                        fontWeight = FontWeight.Bold,
                                                        color = if (ann.isCloseable) Color(0xFF2E7D32) else Color(0xFFC62828),
                                                        modifier = Modifier.padding(horizontal = 6.dp, vertical = 2.dp)
                                                    )
                                                }
                                                Card(
                                                    colors = CardDefaults.cardColors(containerColor = MaterialTheme.colorScheme.secondaryContainer)
                                                ) {
                                                    Text(
                                                        text = "${ann.displayDuration} Secs",
                                                        fontSize = 9.sp,
                                                        fontWeight = FontWeight.Bold,
                                                        color = MaterialTheme.colorScheme.onSecondaryContainer,
                                                        modifier = Modifier.padding(horizontal = 6.dp, vertical = 2.dp)
                                                    )
                                                }
                                            }

                                            IconButton(
                                                onClick = { viewModel.deleteAnnouncement(ann) },
                                                modifier = Modifier.size(24.dp)
                                            ) {
                                                Icon(
                                                    imageVector = Icons.Default.Delete,
                                                    contentDescription = "Delete",
                                                    tint = MaterialTheme.colorScheme.error,
                                                    modifier = Modifier.size(16.dp)
                                                )
                                            }
                                        }

                                        Text(text = ann.message, fontSize = 13.sp, fontWeight = FontWeight.Medium)

                                        if (ann.imageUrl.isNotEmpty()) {
                                            Row(
                                                verticalAlignment = Alignment.CenterVertically,
                                                horizontalArrangement = Arrangement.spacedBy(6.dp),
                                                modifier = Modifier.padding(top = 4.dp)
                                            ) {
                                                Icon(Icons.Filled.Photo, null, modifier = Modifier.size(14.dp), tint = MaterialTheme.colorScheme.primary)
                                                Text(
                                                    text = "Image attached: ${ann.imageUrl.take(35)}...",
                                                    fontSize = 11.sp,
                                                    fontStyle = FontStyle.Italic,
                                                    color = MaterialTheme.colorScheme.onSurfaceVariant
                                                )
                                            }
                                        }

                                        Divider(color = MaterialTheme.colorScheme.outlineVariant.copy(alpha = 0.3f))

                                        Row(
                                            horizontalArrangement = Arrangement.spacedBy(4.dp),
                                            verticalAlignment = Alignment.CenterVertically
                                        ) {
                                            Icon(Icons.Filled.AccountBox, null, modifier = Modifier.size(12.dp), tint = MaterialTheme.colorScheme.onSurfaceVariant)
                                            Text(
                                                text = "Receivers: " + if (ann.targetUserIds == "all") "All Users" else "IDs [${ann.targetUserIds}]",
                                                fontSize = 10.sp,
                                                color = MaterialTheme.colorScheme.onSurfaceVariant,
                                                fontWeight = FontWeight.SemiBold
                                            )
                                        }
                                    }
                                }
                            }
                        }
                    }
                }
                1 -> {
                    // STANDALONE DATABASE MIGRATION SCRIPT
                    Column(
                        modifier = Modifier
                            .fillMaxSize()
                            .verticalScroll(rememberScrollState()),
                        verticalArrangement = Arrangement.spacedBy(16.dp)
                    ) {
                        Card(
                            colors = CardDefaults.cardColors(
                                containerColor = MaterialTheme.colorScheme.primaryContainer.copy(alpha = 0.4f)
                            ),
                            shape = RoundedCornerShape(12.dp),
                            modifier = Modifier.fillMaxWidth()
                        ) {
                            Column(modifier = Modifier.padding(14.dp), verticalArrangement = Arrangement.spacedBy(6.dp)) {
                                Text(
                                    text = "PostgreSQL Table Setup Guidance",
                                    fontWeight = FontWeight.Bold,
                                    fontSize = 15.sp,
                                    color = MaterialTheme.colorScheme.primary
                                )
                                Text(
                                    text = "To sync and save published announcements securely with your live Supabase remote storage backend without key sequence collisions, run these queries inside your Supabase project SQL Editor.",
                                    fontSize = 12.sp,
                                    lineHeight = 18.sp,
                                    color = MaterialTheme.colorScheme.onPrimaryContainer
                                )
                            }
                        }

                        Text("Run the following PostgreSQL queries on Supabase:", fontWeight = FontWeight.Bold, fontSize = 13.sp)

                        Card(
                            colors = CardDefaults.cardColors(containerColor = if (isDark) Color(0xFF1E1E2E) else Color(0xFFF1F5F9)),
                            shape = RoundedCornerShape(8.dp),
                            border = BorderStroke(1.dp, MaterialTheme.colorScheme.outlineVariant),
                            modifier = Modifier.fillMaxWidth()
                        ) {
                            Column(modifier = Modifier.padding(14.dp)) {
                                Text(
                                    text = "-- 1. Add MCQ stat trackers to users table\n" +
                                            "ALTER TABLE users ADD COLUMN IF NOT EXISTS approved_mcqs integer DEFAULT 0;\n" +
                                            "ALTER TABLE users ADD COLUMN IF NOT EXISTS rejected_mcqs integer DEFAULT 0;\n\n" +
                                            "-- 2. Build/Configure Announcements Table\n" +
                                            "CREATE TABLE IF NOT EXISTS announcements (\n" +
                                            "    id bigint PRIMARY KEY GENERATED BY DEFAULT AS IDENTITY,\n" +
                                            "    \"imageUrl\" text DEFAULT '',\n" +
                                            "    message text NOT NULL,\n" +
                                            "    \"targetUserIds\" text NOT NULL,\n" +
                                            "    \"displayDuration\" integer NOT NULL DEFAULT 5,\n" +
                                            "    \"isCloseable\" boolean NOT NULL DEFAULT true,\n" +
                                            "    timestamp bigint NOT NULL\n" +
                                            ");\n\n" +
                                            "-- 3. Delete old pending_mcqs table (No longer needed)\n" +
                                            "DROP TABLE IF EXISTS pending_mcqs CASCADE;\n\n" +
                                            "-- 4. Build/Configure unified MCQs Table with status field\n" +
                                            "CREATE TABLE IF NOT EXISTS mcqs (\n" +
                                            "    id bigint PRIMARY KEY GENERATED BY DEFAULT AS IDENTITY,\n" +
                                            "    subject_id integer NOT NULL,\n" +
                                            "    topic_id integer NOT NULL,\n" +
                                            "    question text NOT NULL,\n" +
                                            "    option_a text NOT NULL,\n" +
                                            "    option_b text NOT NULL,\n" +
                                            "    option_c text NOT NULL,\n" +
                                            "    option_d text NOT NULL,\n" +
                                            "    correct_option text NOT NULL,\n" +
                                            "    detailed_explanation text DEFAULT '',\n" +
                                            "    difficulty text NOT NULL DEFAULT 'MEDIUM',\n" +
                                            "    status text NOT NULL DEFAULT 'APPROVED',\n" +
                                            "    user_id integer NOT NULL DEFAULT 0,\n" +
                                            "    text_username text NOT NULL DEFAULT '',\n" +
                                            "    created_at bigint DEFAULT 0,\n" +
                                            "    subject_name text NOT NULL DEFAULT '',\n" +
                                            "    topic_name text NOT NULL DEFAULT ''\n" +
                                            ");\n" +
                                            "ALTER TABLE mcqs RENAME COLUMN username TO text_username;\n" +
                                            "ALTER TABLE mcqs ADD COLUMN IF NOT EXISTS detailed_explanation text DEFAULT '';\n" +
                                            "ALTER TABLE mcqs ADD COLUMN IF NOT EXISTS difficulty text NOT NULL DEFAULT 'MEDIUM';\n" +
                                            "ALTER TABLE mcqs ADD COLUMN IF NOT EXISTS status text NOT NULL DEFAULT 'APPROVED';\n" +
                                            "ALTER TABLE mcqs ADD COLUMN IF NOT EXISTS user_id integer NOT NULL DEFAULT 0;\n" +
                                            "ALTER TABLE mcqs ADD COLUMN IF NOT EXISTS text_username text NOT NULL DEFAULT '';\n" +
                                            "ALTER TABLE mcqs ADD COLUMN IF NOT EXISTS created_at bigint DEFAULT 0;\n" +
                                            "ALTER TABLE mcqs ADD COLUMN IF NOT EXISTS subject_name text NOT NULL DEFAULT '';\n" +
                                            "ALTER TABLE mcqs ADD COLUMN IF NOT EXISTS topic_name text NOT NULL DEFAULT '';\n\n" +
                                            "-- NOTE: If you have existing tables and see sequence or ID constraint faults, run this first:\n" +
                                            "-- DROP TABLE IF EXISTS announcements, pending_mcqs, mcqs CASCADE;",
                                    fontFamily = androidx.compose.ui.text.font.FontFamily.Monospace,
                                    fontSize = 10.sp,
                                    color = if (isDark) Color(0xFF00FFC4) else Color(0xFF0F172A),
                                    lineHeight = 15.sp
                                )
                            }
                        }

                        Text(
                            text = "💡 Note: High-precision casings correspond perfectly with retrofit/Moshi JSON serializations to ensure offline logs map properly with remote tables.",
                            fontSize = 11.sp,
                            lineHeight = 16.sp,
                            color = MaterialTheme.colorScheme.onSurfaceVariant.copy(alpha = 0.8f)
                        )
                    }
                }
            }
        }
    }
}

@Composable
fun ByButtonRow(
    viewModel: MainViewModel,
    annMessage: () -> String,
    annImageUrl: () -> String,
    annDuration: () -> Int,
    annIsCloseable: () -> Boolean,
    annTargetAll: () -> Boolean,
    selectedUserIds: Map<Int, Boolean>,
    onPublishSuccess: () -> Unit
) {
    Button(
        onClick = {
            if (annMessage().trim().isEmpty()) {
                viewModel.feedbackMessage.value = "Announcement message cannot be empty."
                return@Button
            }
            val targetString = if (annTargetAll()) {
                "all"
            } else {
                val idsList = selectedUserIds.filter { it.value }.keys.toList()
                if (idsList.isEmpty()) {
                    viewModel.feedbackMessage.value = "Please select at least 1 targeted user."
                    return@Button
                }
                idsList.joinToString(",")
            }

            viewModel.sendAnnouncement(
                imageUrl = annImageUrl().trim(),
                message = annMessage().trim(),
                targetUserIds = targetString,
                displayDuration = annDuration(),
                isCloseable = annIsCloseable(),
                onComplete = onPublishSuccess
            )
        },
        shape = RoundedCornerShape(8.dp),
        modifier = Modifier.fillMaxWidth().testTag("publish_announcement_action_button")
    ) {
        Icon(Icons.Filled.Campaign, null)
        Spacer(modifier = Modifier.width(6.dp))
        Text("Publish Announcement", fontWeight = FontWeight.Bold)
    }
}

@OptIn(ExperimentalMaterial3Api::class)
@Composable
fun AskAiScreen(viewModel: MainViewModel) {
    val messages by viewModel.aiChatMessages.collectAsState()
    val isThinking by viewModel.isAiThinking.collectAsState()
    val loggedInUser by viewModel.loggedInUser.collectAsState()
    val isAiEnabled = viewModel.isAiEnabledForUser(loggedInUser)

    Scaffold(
        topBar = {
            TopAppBar(
                title = {
                    Row(verticalAlignment = Alignment.CenterVertically) {
                        Icon(Icons.Filled.AutoAwesome, "Ask AI", tint = MaterialTheme.colorScheme.primary)
                        Spacer(modifier = Modifier.width(8.dp))
                        Text("Ask AI Study Desk", fontWeight = FontWeight.Bold)
                    }
                },
                navigationIcon = {
                    IconButton(onClick = { 
                        if (loggedInUser?.role == "ADMIN") {
                            viewModel.navigateTo(Screen.AdminDashboard)
                        } else {
                            viewModel.navigateTo(Screen.UserDashboard)
                        }
                    }) {
                        Icon(Icons.AutoMirrored.Filled.ArrowBack, "Back")
                    }
                },
                actions = {
                    if (isAiEnabled && messages.isNotEmpty()) {
                        IconButton(onClick = { viewModel.clearAiChat() }) {
                            Icon(Icons.Filled.DeleteSweep, "Clear Chat", tint = MaterialTheme.colorScheme.error)
                        }
                    }
                }
            )
        }
    ) { paddingValues ->
        if (!isAiEnabled) {
            Box(
                modifier = Modifier
                    .fillMaxSize()
                    .padding(paddingValues)
                    .padding(24.dp),
                contentAlignment = Alignment.Center
            ) {
                Card(
                    modifier = Modifier.fillMaxWidth().widthIn(max = 480.dp),
                    colors = CardDefaults.cardColors(containerColor = MaterialTheme.colorScheme.errorContainer.copy(alpha = 0.2f)),
                    border = androidx.compose.foundation.BorderStroke(1.dp, MaterialTheme.colorScheme.error.copy(alpha = 0.3f))
                ) {
                    Column(
                        modifier = Modifier.padding(24.dp),
                        horizontalAlignment = Alignment.CenterHorizontally,
                        verticalArrangement = Arrangement.spacedBy(16.dp)
                    ) {
                        Box(
                            modifier = Modifier
                                .size(64.dp)
                                .clip(RoundedCornerShape(32.dp))
                                .background(MaterialTheme.colorScheme.error.copy(alpha = 0.1f)),
                            contentAlignment = Alignment.Center
                        ) {
                            Icon(
                                imageVector = Icons.Filled.Lock,
                                contentDescription = null,
                                tint = MaterialTheme.colorScheme.error,
                                modifier = Modifier.size(32.dp)
                            )
                        }
                        Text(
                            "AI Assistant Restricted",
                            fontWeight = FontWeight.Bold,
                            style = MaterialTheme.typography.titleMedium,
                            color = MaterialTheme.colorScheme.onErrorContainer
                        )
                        Text(
                            "The administrator has currently deactivated the Ask AI assistant desk for your account. Please consult the admin desk for subscription or access updates.",
                            fontSize = 14.sp,
                            textAlign = TextAlign.Center,
                            color = MaterialTheme.colorScheme.onSurfaceVariant,
                            lineHeight = 20.sp
                        )
                        Button(
                            onClick = { viewModel.navigateTo(Screen.UserDashboard) },
                            colors = ButtonDefaults.buttonColors(containerColor = MaterialTheme.colorScheme.error)
                        ) {
                            Text("Return to Dashboard")
                        }
                    }
                }
            }
        } else {
            Column(
                modifier = Modifier
                    .fillMaxSize()
                    .padding(paddingValues)
                    .background(MaterialTheme.colorScheme.background)
            ) {
                val lazyListState = rememberLazyListState()
                
                LaunchedEffect(messages.size, isThinking) {
                    if (messages.isNotEmpty()) {
                        lazyListState.animateScrollToItem(messages.size - 1)
                    }
                }

                Box(
                    modifier = Modifier
                        .weight(1f)
                        .fillMaxWidth()
                ) {
                    if (messages.isEmpty()) {
                        Column(
                            modifier = Modifier
                                .fillMaxSize()
                                .verticalScroll(rememberScrollState())
                                .padding(24.dp),
                            horizontalAlignment = Alignment.CenterHorizontally,
                            verticalArrangement = Arrangement.Center
                        ) {
                            Box(
                                modifier = Modifier
                                    .size(80.dp)
                                    .clip(RoundedCornerShape(40.dp))
                                    .background(MaterialTheme.colorScheme.primaryContainer),
                                contentAlignment = Alignment.Center
                            ) {
                                Icon(
                                    imageVector = Icons.Filled.AutoAwesome,
                                    contentDescription = null,
                                    tint = MaterialTheme.colorScheme.primary,
                                    modifier = Modifier.size(40.dp)
                                )
                            }
                            Spacer(modifier = Modifier.height(16.dp))
                            Text(
                                "Ask NayaRasta AI",
                                fontWeight = FontWeight.Bold,
                                style = MaterialTheme.typography.titleLarge
                            )
                            Spacer(modifier = Modifier.height(8.dp))
                            Text(
                                "Your smart exam helper. Ask any questions about syllabus, topics, calculations, or explanations!",
                                fontSize = 14.sp,
                                color = MaterialTheme.colorScheme.onSurfaceVariant,
                                textAlign = TextAlign.Center,
                                lineHeight = 20.sp,
                                modifier = Modifier.padding(horizontal = 16.dp)
                            )
                            Spacer(modifier = Modifier.height(24.dp))
                            Text(
                                "TRY ASKING:",
                                fontWeight = FontWeight.Bold,
                                fontSize = 11.sp,
                                color = MaterialTheme.colorScheme.primary,
                                letterSpacing = 1.sp
                            )
                            Spacer(modifier = Modifier.height(12.dp))
                            
                            val suggestions = listOf(
                                "Explain photosynthesis in simple 3 points",
                                "Provide steps to solve quadratic equations",
                                "Explain the difference between mitosis & meiosis",
                                "Give me study tips to memorize MDCAT words"
                            )

                            suggestions.forEach { sug ->
                                Card(
                                    modifier = Modifier
                                        .fillMaxWidth()
                                        .padding(vertical = 4.dp)
                                        .clickable { viewModel.sendAiMessage(sug) },
                                    colors = CardDefaults.cardColors(containerColor = MaterialTheme.colorScheme.surfaceVariant.copy(alpha = 0.5f))
                                ) {
                                    Row(
                                        modifier = Modifier.padding(16.dp),
                                        verticalAlignment = Alignment.CenterVertically
                                    ) {
                                        Icon(Icons.Filled.ChevronRight, null, tint = MaterialTheme.colorScheme.primary, modifier = Modifier.size(18.dp))
                                        Spacer(modifier = Modifier.width(8.dp))
                                        Text(sug, fontSize = 13.sp, fontWeight = FontWeight.Medium)
                                    }
                                }
                            }
                        }
                    } else {
                        LazyColumn(
                            state = lazyListState,
                            modifier = Modifier.fillMaxSize(),
                            contentPadding = PaddingValues(16.dp),
                            verticalArrangement = Arrangement.spacedBy(12.dp)
                        ) {
                            items(messages) { msg ->
                                val isUser = msg.sender == "USER"
                                Row(
                                    modifier = Modifier.fillMaxWidth(),
                                    horizontalArrangement = if (isUser) Arrangement.End else Arrangement.Start
                                ) {
                                    Card(
                                        shape = RoundedCornerShape(
                                            topStart = 16.dp,
                                            topEnd = 16.dp,
                                            bottomStart = if (isUser) 16.dp else 2.dp,
                                            bottomEnd = if (isUser) 2.dp else 16.dp
                                        ),
                                        colors = CardDefaults.cardColors(
                                            containerColor = if (isUser) MaterialTheme.colorScheme.primary else MaterialTheme.colorScheme.surfaceVariant
                                        ),
                                        modifier = Modifier.widthIn(max = 290.dp)
                                    ) {
                                        Column(modifier = Modifier.padding(12.dp), verticalArrangement = Arrangement.spacedBy(4.dp)) {
                                            Text(
                                                text = msg.text,
                                                fontSize = 14.sp,
                                                lineHeight = 20.sp,
                                                color = if (isUser) MaterialTheme.colorScheme.onPrimary else MaterialTheme.colorScheme.onSurfaceVariant
                                            )
                                            Text(
                                                text = SimpleDateFormat("hh:mm a", Locale.getDefault()).format(Date(msg.timestamp)),
                                                fontSize = 9.sp,
                                                color = (if (isUser) MaterialTheme.colorScheme.onPrimary else MaterialTheme.colorScheme.onSurfaceVariant).copy(alpha = 0.6f),
                                                modifier = Modifier.align(Alignment.End)
                                            )
                                        }
                                    }
                                }
                            }
                            
                            if (isThinking) {
                                item {
                                    Row(
                                        modifier = Modifier.fillMaxWidth(),
                                        horizontalArrangement = Arrangement.Start
                                    ) {
                                        Card(
                                            shape = RoundedCornerShape(topStart = 16.dp, topEnd = 16.dp, bottomStart = 2.dp, bottomEnd = 16.dp),
                                            colors = CardDefaults.cardColors(containerColor = MaterialTheme.colorScheme.surfaceVariant),
                                            modifier = Modifier.widthIn(max = 160.dp)
                                        ) {
                                            Row(
                                                modifier = Modifier.padding(12.dp),
                                                verticalAlignment = Alignment.CenterVertically,
                                                horizontalArrangement = Arrangement.spacedBy(6.dp)
                                            ) {
                                                CircularProgressIndicator(modifier = Modifier.size(16.dp), strokeWidth = 2.dp)
                                                Text("AI typing...", fontSize = 12.sp, color = MaterialTheme.colorScheme.onSurfaceVariant)
                                            }
                                        }
                                    }
                                }
                            }
                        }
                    }
                }

                var textValue by remember { mutableStateOf("") }
                Surface(
                    tonalElevation = 4.dp,
                    modifier = Modifier.fillMaxWidth()
                ) {
                    Row(
                        modifier = Modifier
                            .fillMaxWidth()
                            .padding(horizontal = 12.dp, vertical = 8.dp),
                        verticalAlignment = Alignment.CenterVertically,
                        horizontalArrangement = Arrangement.spacedBy(8.dp)
                    ) {
                        OutlinedTextField(
                            value = textValue,
                            onValueChange = { textValue = it },
                            placeholder = { Text("Ask any question...", fontSize = 14.sp) },
                            modifier = Modifier
                                .weight(1f)
                                .testTag("ask_ai_input_field"),
                            maxLines = 4,
                            shape = RoundedCornerShape(24.dp),
                            colors = OutlinedTextFieldDefaults.colors(
                                focusedContainerColor = MaterialTheme.colorScheme.surface,
                                unfocusedContainerColor = MaterialTheme.colorScheme.surface
                            )
                        )
                        IconButton(
                            onClick = {
                                if (textValue.trim().isNotEmpty()) {
                                    viewModel.sendAiMessage(textValue.trim())
                                    textValue = ""
                                }
                            },
                            enabled = !isThinking && textValue.trim().isNotEmpty(),
                            modifier = Modifier
                                .size(48.dp)
                                .background(
                                    if (textValue.trim().isEmpty() || isThinking) {
                                        MaterialTheme.colorScheme.surfaceVariant
                                    } else {
                                        MaterialTheme.colorScheme.primary
                                    },
                                    CircleShape
                                )
                                .testTag("ask_ai_send_button")
                        ) {
                            Icon(
                                imageVector = Icons.Filled.Send,
                                contentDescription = "Send",
                                tint = if (textValue.trim().isEmpty() || isThinking) {
                                    MaterialTheme.colorScheme.onSurfaceVariant.copy(alpha = 0.5f)
                                } else {
                                    MaterialTheme.colorScheme.onPrimary
                                }
                            )
                        }
                    }
                }
            }
        }
    }
}

@OptIn(ExperimentalMaterial3Api::class)
@Composable
fun AdminAskAiSettingsScreen(viewModel: MainViewModel) {
    val globalEnabled by viewModel.aiGloballyEnabled.collectAsState()
    val systemPrompt by viewModel.aiSystemPrompt.collectAsState()
    val allowedUserIds by viewModel.aiAllowedUserIds.collectAsState()
    val blockedUserIds by viewModel.aiBlockedUserIds.collectAsState()
    val allUsers by viewModel.allUsers.collectAsState()

    var tempPrompt by remember(systemPrompt) { mutableStateOf(systemPrompt) }
    var userSearchQuery by remember { mutableStateOf("") }

    Scaffold(
        topBar = {
            TopAppBar(
                title = {
                    Row(verticalAlignment = Alignment.CenterVertically) {
                        Icon(Icons.Filled.Settings, null, tint = MaterialTheme.colorScheme.primary)
                        Spacer(modifier = Modifier.width(8.dp))
                        Text("Ask AI Control Desk", fontWeight = FontWeight.Bold)
                    }
                },
                navigationIcon = {
                    IconButton(onClick = { viewModel.navigateTo(Screen.AdminDashboard) }) {
                        Icon(Icons.AutoMirrored.Filled.ArrowBack, "Back")
                    }
                }
            )
        }
    ) { paddingValues ->
        LazyColumn(
            modifier = Modifier
                .fillMaxSize()
                .padding(paddingValues)
                .background(MaterialTheme.colorScheme.background),
            contentPadding = PaddingValues(16.dp),
            verticalArrangement = Arrangement.spacedBy(16.dp)
        ) {
            item {
                Card(
                    modifier = Modifier.fillMaxWidth(),
                    shape = RoundedCornerShape(12.dp)
                ) {
                    Column(
                        modifier = Modifier.padding(16.dp),
                        verticalArrangement = Arrangement.spacedBy(12.dp)
                    ) {
                        Text(
                            "AI ACCESS MANAGEMENT",
                            fontWeight = FontWeight.Bold,
                            fontSize = 12.sp,
                            color = MaterialTheme.colorScheme.primary,
                            letterSpacing = 1.sp
                        )
                        Row(
                            modifier = Modifier.fillMaxWidth(),
                            verticalAlignment = Alignment.CenterVertically,
                            horizontalArrangement = Arrangement.SpaceBetween
                        ) {
                            Column(modifier = Modifier.weight(1f)) {
                                Text("Global AI Access", fontWeight = FontWeight.Bold, fontSize = 15.sp)
                                Text(
                                    if (globalEnabled) "All users have access to Ask AI features." else "Only explicitly selected users have AI access.",
                                    fontSize = 12.sp,
                                    color = MaterialTheme.colorScheme.onSurfaceVariant
                                )
                            }
                            Switch(
                                checked = globalEnabled,
                                onCheckedChange = { isChecked ->
                                    viewModel.saveAiSettings(isChecked, tempPrompt, allowedUserIds)
                                    viewModel.feedbackMessage.value = "AI Global status updated!"
                                },
                                modifier = Modifier.testTag("admin_ai_global_switch")
                            )
                        }
                    }
                }
            }

            item {
                Card(
                    modifier = Modifier.fillMaxWidth(),
                    shape = RoundedCornerShape(12.dp)
                ) {
                    Column(
                        modifier = Modifier.padding(16.dp),
                        verticalArrangement = Arrangement.spacedBy(12.dp)
                    ) {
                        Text(
                            "AI INSTRUCTIONS & BEHAVIOR",
                            fontWeight = FontWeight.Bold,
                            fontSize = 12.sp,
                            color = MaterialTheme.colorScheme.primary,
                            letterSpacing = 1.sp
                        )
                        Text(
                            "Give AI guidelines on response constraints (e.g., limit output lines, tone of speech, language constraints). Keep instructions under 3 lines for clean responses.",
                            fontSize = 12.sp,
                            color = MaterialTheme.colorScheme.onSurfaceVariant
                        )
                        OutlinedTextField(
                            value = tempPrompt,
                            onValueChange = { tempPrompt = it },
                            modifier = Modifier.fillMaxWidth().testTag("admin_ai_prompt_input"),
                            label = { Text("System Instruction Prompt") },
                            maxLines = 6,
                            minLines = 2
                        )
                        Button(
                            onClick = {
                                viewModel.saveAiSettings(globalEnabled, tempPrompt, allowedUserIds)
                                viewModel.feedbackMessage.value = "AI system instruction prompt saved successfully!"
                            },
                            modifier = Modifier.align(Alignment.End).testTag("save_ai_prompt_button")
                        ) {
                            Text("Save Prompt")
                        }
                    }
                }
            }

            item {
                Column(verticalArrangement = Arrangement.spacedBy(8.dp)) {
                    Text(
                        "MANAGE SELECTED USER ACCESS",
                        fontWeight = FontWeight.Bold,
                        fontSize = 12.sp,
                        color = MaterialTheme.colorScheme.primary,
                        letterSpacing = 1.sp
                    )
                    Text(
                        "If Global AI access is active, uncheck a student to BLOCK / disable their AI desk. If Global AI access is inactive, check a student to ALLOW / enable their AI desk.",
                        fontSize = 12.sp,
                        color = MaterialTheme.colorScheme.onSurfaceVariant
                    )
                    OutlinedTextField(
                        value = userSearchQuery,
                        onValueChange = { userSearchQuery = it },
                        modifier = Modifier.fillMaxWidth().padding(vertical = 4.dp),
                        placeholder = { Text("Search users by name...") },
                        leadingIcon = { Icon(Icons.Filled.Search, null) },
                        singleLine = true,
                        shape = RoundedCornerShape(24.dp)
                    )
                }
            }

            val filteredUsers = allUsers.filter {
                (it.fullName.contains(userSearchQuery, ignoreCase = true) || it.username.contains(userSearchQuery, ignoreCase = true)) &&
                        it.role != "ADMIN"
            }

            if (filteredUsers.isEmpty()) {
                item {
                    Box(modifier = Modifier.fillMaxWidth().padding(32.dp), contentAlignment = Alignment.Center) {
                        Text("No regular users found matching search.", color = MaterialTheme.colorScheme.onSurfaceVariant)
                    }
                }
            } else {
                items(filteredUsers) { user ->
                    val isChecked = viewModel.isAiEnabledForUser(user)
                    Row(
                        modifier = Modifier
                            .fillMaxWidth()
                            .clip(RoundedCornerShape(8.dp))
                            .background(MaterialTheme.colorScheme.surfaceVariant.copy(alpha = 0.3f))
                            .clickable {
                                val currentAllowed = allowedUserIds.toMutableSet()
                                val currentBlocked = blockedUserIds.toMutableSet()
                                val newChecked = !isChecked

                                if (newChecked) {
                                    currentAllowed.add(user.id)
                                    currentBlocked.remove(user.id)
                                } else {
                                    currentAllowed.remove(user.id)
                                    currentBlocked.add(user.id)
                                }
                                viewModel.saveAiSettings(globalEnabled, tempPrompt, currentAllowed, currentBlocked)
                            }
                            .padding(12.dp),
                        verticalAlignment = Alignment.CenterVertically,
                        horizontalArrangement = Arrangement.SpaceBetween
                    ) {
                        Row(verticalAlignment = Alignment.CenterVertically) {
                            val initial = user.fullName.firstOrNull()?.uppercase() ?: user.username.firstOrNull()?.uppercase() ?: "S"
                            Box(
                                modifier = Modifier
                                    .size(36.dp)
                                    .clip(CircleShape)
                                    .background(Color(if (user.avatarColor != 0) user.avatarColor else 0xFFD6E3FF.toInt())),
                                contentAlignment = Alignment.Center
                            ) {
                                Text(initial, color = Color.White, fontWeight = FontWeight.Bold, fontSize = 14.sp)
                            }
                            Spacer(modifier = Modifier.width(12.dp))
                            Column {
                                Row(verticalAlignment = Alignment.CenterVertically) {
                                    Text(
                                        text = if (user.fullName.isNotEmpty()) user.fullName else user.username,
                                        fontWeight = FontWeight.SemiBold,
                                        fontSize = 14.sp
                                    )
                                    if (!isChecked) {
                                        Spacer(modifier = Modifier.width(8.dp))
                                        Surface(
                                            color = MaterialTheme.colorScheme.errorContainer,
                                            shape = RoundedCornerShape(4.dp)
                                        ) {
                                            Text(
                                                text = "BLOCKED",
                                                color = MaterialTheme.colorScheme.onErrorContainer,
                                                fontSize = 9.sp,
                                                fontWeight = FontWeight.Bold,
                                                modifier = Modifier.padding(horizontal = 4.dp, vertical = 2.dp)
                                            )
                                        }
                                    }
                                }
                                Text(
                                    text = "@${user.username} • id: ${user.id}",
                                    fontSize = 11.sp,
                                    color = MaterialTheme.colorScheme.onSurfaceVariant
                                )
                            }
                        }
                        Checkbox(
                            checked = isChecked,
                            onCheckedChange = { isCheckedNow ->
                                val currentAllowed = allowedUserIds.toMutableSet()
                                val currentBlocked = blockedUserIds.toMutableSet()

                                if (isCheckedNow) {
                                    currentAllowed.add(user.id)
                                    currentBlocked.remove(user.id)
                                } else {
                                    currentAllowed.remove(user.id)
                                    currentBlocked.add(user.id)
                                }
                                viewModel.saveAiSettings(globalEnabled, tempPrompt, currentAllowed, currentBlocked)
                            },
                            modifier = Modifier.testTag("user_ai_checkbox_${user.id}")
                        )
                    }
                }
            }
        }
    }
}

@OptIn(ExperimentalMaterial3Api::class)
@Composable
fun MdcatCountdownDetailScreen(viewModel: MainViewModel) {
    val isDark = isSystemInDarkTheme()
    val mdcatCountdownStateVal by viewModel.mdcatCountdownState.collectAsState()
    val activeStyle by viewModel.activeDesignStyle.collectAsState()

    var sysTime by remember { mutableStateOf(System.currentTimeMillis()) }
    var activeQuoteIndex by remember { mutableStateOf(0) }

    // Start live-ticking clock
    androidx.compose.runtime.LaunchedEffect(Unit) {
        while (true) {
            kotlinx.coroutines.delay(1000L)
            sysTime = System.currentTimeMillis()
        }
    }

    fun parseIsoDate(isoString: String): Long {
        return try {
            val sdf = java.text.SimpleDateFormat("yyyy-MM-dd'T'HH:mm:ss'Z'", java.util.Locale.US)
            sdf.timeZone = java.util.TimeZone.getTimeZone("UTC")
            sdf.parse(isoString)?.time ?: 0L
        } catch (e: Exception) {
            try {
                val sdf = java.text.SimpleDateFormat("yyyy-MM-dd'T'HH:mm:ss", java.util.Locale.US)
                val clean = isoString.replace("Z", "")
                sdf.parse(clean)?.time ?: 0L
            } catch (e2: Exception) {
                try {
                    val sdf = java.text.SimpleDateFormat("yyyy-MM-dd HH:mm:ss", java.util.Locale.US)
                    sdf.parse(isoString)?.time ?: 0L
                } catch (e3: Exception) {
                    0L
                }
            }
        }
    }

    val targetMs = if (mdcatCountdownStateVal != null) parseIsoDate(mdcatCountdownStateVal!!.testDate) else 0L
    val diffMs = targetMs - sysTime

    val secondsTotal = (diffMs / 1000L).coerceAtLeast(0L)
    val days = secondsTotal / 86400L
    val hours = (secondsTotal % 86400L) / 3600L
    val minutes = (secondsTotal % 3600L) / 60L
    val seconds = secondsTotal % 60L

    // Quotes logic
    val quotesList = remember(mdcatCountdownStateVal) {
        mdcatCountdownStateVal?.quotes?.split("|")?.filter { it.isNotBlank() } ?: emptyList()
    }
    
    val activeQuote = if (quotesList.isNotEmpty()) {
        quotesList[activeQuoteIndex % quotesList.size]
    } else ""

    Scaffold(
        topBar = {
            TopAppBar(
                title = { Text("MDCAT Mission Control", fontWeight = FontWeight.Bold) },
                navigationIcon = {
                    IconButton(onClick = { viewModel.navigateBack() }) {
                        Icon(imageVector = Icons.AutoMirrored.Filled.ArrowBack, contentDescription = "Back")
                    }
                },
                colors = TopAppBarDefaults.topAppBarColors(
                    containerColor = if (isDark) Color(0xFF121212) else MaterialTheme.colorScheme.surface
                )
            )
        }
    ) { paddingValues ->
        Column(
            modifier = Modifier
                .fillMaxSize()
                .padding(paddingValues)
                .background(if (isDark) Color(0xFF0F0E13) else Color(0xFFF9F9FC))
                .verticalScroll(rememberScrollState())
                .padding(20.dp),
            verticalArrangement = Arrangement.spacedBy(20.dp),
            horizontalAlignment = Alignment.CenterHorizontally
        ) {
            // 1. MOTIVATION BANNER ON TOP OF PAGE
            val quoteBg = viewModel.getCountdownQuoteImage()
            if (quoteBg.isNotBlank()) {
                Box(
                    modifier = Modifier
                        .fillMaxWidth()
                        .height(140.dp)
                        .clip(RoundedCornerShape(24.dp))
                ) {
                    androidx.compose.foundation.Image(
                        painter = coil.compose.rememberAsyncImagePainter(model = quoteBg),
                        contentDescription = "Inspirational Backdrop",
                        modifier = Modifier.fillMaxSize(),
                        contentScale = androidx.compose.ui.layout.ContentScale.Crop
                    )
                    Box(
                        modifier = Modifier
                            .fillMaxSize()
                            .background(
                                Brush.verticalGradient(
                                    colors = listOf(Color.Transparent, Color.Black.copy(alpha = 0.7f))
                                )
                            )
                    )
                    Text(
                        text = "Fuel your MDCAT ambition daily",
                        color = Color.White,
                        fontSize = 14.sp,
                        fontWeight = FontWeight.Bold,
                        modifier = Modifier
                            .align(Alignment.BottomStart)
                            .padding(16.dp)
                    )
                }
            }

            PremiumStyleContainer(
                style = activeStyle,
                modifier = Modifier.fillMaxWidth().testTag("countdown_motivation_card"),
                containerColor = if (isDark) MaterialTheme.colorScheme.surfaceVariant else Color(0xFFEFF6FF)
            ) {
                Column(
                    modifier = Modifier.padding(20.dp),
                    horizontalAlignment = Alignment.CenterHorizontally,
                    verticalArrangement = Arrangement.spacedBy(16.dp)
                ) {
                    Box(
                        modifier = Modifier
                            .clip(RoundedCornerShape(12.dp))
                            .background(MaterialTheme.colorScheme.secondary.copy(alpha = 0.12f))
                            .padding(horizontal = 12.dp, vertical = 6.dp)
                    ) {
                        Row(
                            verticalAlignment = Alignment.CenterVertically,
                            horizontalArrangement = Arrangement.spacedBy(6.dp)
                        ) {
                            Icon(
                                imageVector = Icons.Filled.AutoAwesome,
                                contentDescription = "Sparkle",
                                tint = MaterialTheme.colorScheme.secondary,
                                modifier = Modifier.size(16.dp)
                            )
                            Text(
                                text = "DAILY INSPIRATION",
                                fontSize = 10.sp,
                                fontWeight = FontWeight.Bold,
                                color = MaterialTheme.colorScheme.secondary,
                                letterSpacing = 1.sp
                            )
                        }
                    }

                    Text(
                        text = if (activeQuote.isNotEmpty()) "\"$activeQuote\"" else "No motivational quotes configured by Admin yet.",
                        fontSize = 16.sp,
                        fontWeight = FontWeight.Medium,
                        fontStyle = androidx.compose.ui.text.font.FontStyle.Italic,
                        color = if (isDark) Color(0xFFE8E0EC) else MaterialTheme.colorScheme.onSurface,
                        textAlign = androidx.compose.ui.text.style.TextAlign.Center,
                        modifier = Modifier.padding(horizontal = 8.dp),
                        lineHeight = 24.sp
                    )

                    if (quotesList.size > 1) {
                        Button(
                            onClick = {
                                activeQuoteIndex++
                            },
                            colors = ButtonDefaults.buttonColors(
                                containerColor = if (isDark) MaterialTheme.colorScheme.secondary.copy(alpha = 0.15f) else MaterialTheme.colorScheme.secondaryContainer,
                                contentColor = if (isDark) MaterialTheme.colorScheme.secondary else MaterialTheme.colorScheme.onSecondaryContainer
                            ),
                            shape = RoundedCornerShape(14.dp),
                            elevation = ButtonDefaults.buttonElevation(defaultElevation = 0.dp),
                            modifier = Modifier.testTag("next_motivation_button")
                        ) {
                            Row(
                                verticalAlignment = Alignment.CenterVertically,
                                horizontalArrangement = Arrangement.spacedBy(6.dp)
                            ) {
                                Icon(
                                    imageVector = Icons.Filled.ChevronRight,
                                    contentDescription = "Next",
                                    modifier = Modifier.size(18.dp)
                                )
                                Text(
                                    text = "Next Motivation",
                                    fontSize = 12.sp,
                                    fontWeight = FontWeight.Bold
                                )
                            }
                        }
                    }
                }
            }

            // 2. REAL-TIME WORKING TICKING HUD & STATUS
            PremiumStyleContainer(
                style = activeStyle,
                modifier = Modifier.fillMaxWidth(),
                containerColor = if (isDark) Color(0xFF151518) else Color(0xFFFFFFFF)
            ) {
                Column(
                    modifier = Modifier.padding(20.dp),
                    horizontalAlignment = Alignment.CenterHorizontally,
                    verticalArrangement = Arrangement.spacedBy(16.dp)
                ) {
                    Text(
                        text = "LIVE TEST COUNTDOWN",
                        fontSize = 11.sp,
                        fontWeight = FontWeight.Bold,
                        color = MaterialTheme.colorScheme.primary,
                        letterSpacing = 1.sp
                    )

                    if (diffMs > 0) {
                        // Four Column Live Circular Dials
                        Row(
                            modifier = Modifier.fillMaxWidth(),
                            horizontalArrangement = Arrangement.SpaceEvenly
                        ) {
                            // DAYS DIAL
                            TimeCircularDial(
                                value = days.toInt(),
                                maxValue = 100, // standard MDCAT session ceiling
                                label = "Days",
                                color = MaterialTheme.colorScheme.secondary,
                                isDark = isDark
                            )

                            // HOURS DIAL
                            TimeCircularDial(
                                value = hours.toInt(),
                                maxValue = 24,
                                label = "Hours",
                                color = MaterialTheme.colorScheme.primary,
                                isDark = isDark
                            )

                            // MINUTES DIAL
                            TimeCircularDial(
                                value = minutes.toInt(),
                                maxValue = 60,
                                label = "Mins",
                                color = MaterialTheme.colorScheme.tertiary,
                                isDark = isDark
                            )

                            // SECONDS DIAL
                            TimeCircularDial(
                                value = seconds.toInt(),
                                maxValue = 60,
                                label = "Secs",
                                color = MaterialTheme.colorScheme.secondary.copy(alpha = 0.7f),
                                isDark = isDark
                            )
                        }

                        // Grid of Linear Progress Bars
                        Column(
                            modifier = Modifier
                                .fillMaxWidth()
                                .padding(top = 8.dp),
                            verticalArrangement = Arrangement.spacedBy(12.dp)
                        ) {
                            Text(
                                text = "PROPORTIONAL COMPLETION STATUS",
                                fontSize = 10.sp,
                                fontWeight = FontWeight.Bold,
                                color = MaterialTheme.colorScheme.onSurfaceVariant.copy(alpha = 0.8f),
                                letterSpacing = 0.5.sp,
                                modifier = Modifier.align(Alignment.Start)
                            )

                            TimeProgressBar(
                                label = "Days Preparation Progress",
                                current = days.toInt(),
                                max = 100,
                                color = MaterialTheme.colorScheme.secondary,
                                suffix = " days remaining"
                            )

                            TimeProgressBar(
                                label = "Current Day Hour Progress",
                                current = hours.toInt(),
                                max = 24,
                                color = MaterialTheme.colorScheme.primary,
                                suffix = " hours remaining"
                            )

                            TimeProgressBar(
                                label = "Current Hour Minute Progress",
                                current = minutes.toInt(),
                                max = 60,
                                color = MaterialTheme.colorScheme.tertiary,
                                suffix = " mins remaining"
                            )

                            TimeProgressBar(
                                label = "Current Minute Seconds Progress",
                                current = seconds.toInt(),
                                max = 60,
                                color = MaterialTheme.colorScheme.secondary.copy(alpha = 0.7f),
                                suffix = " secs remaining"
                            )
                        }
                    } else {
                        // Countdown finished
                        Column(
                            horizontalAlignment = Alignment.CenterHorizontally,
                            verticalArrangement = Arrangement.spacedBy(8.dp),
                            modifier = Modifier.padding(vertical = 16.dp)
                        ) {
                            Icon(
                                imageVector = Icons.Filled.CheckCircle,
                                contentDescription = "Finished",
                                tint = Color(0xFF4CAF50),
                                modifier = Modifier.size(64.dp)
                            )
                            Text(
                                text = "MDCAT TEST HAS BEGUN!",
                                fontSize = 18.sp,
                                fontWeight = FontWeight.Bold,
                                color = Color(0xFF4CAF50)
                            )
                            Text(
                                text = "Stay calm, trust your preparation, and give it your absolute best effort!",
                                fontSize = 13.sp,
                                color = MaterialTheme.colorScheme.onSurfaceVariant,
                                textAlign = androidx.compose.ui.text.style.TextAlign.Center,
                                modifier = Modifier.padding(horizontal = 16.dp)
                            )
                        }
                    }
                }
            }

            // 3. ADVICE & STATS CARD
            PremiumStyleContainer(
                style = activeStyle,
                modifier = Modifier.fillMaxWidth(),
                containerColor = if (isDark) Color(0xFF1E1E24) else Color(0xFFF0F4FF)
            ) {
                Row(
                    modifier = Modifier.padding(16.dp),
                    horizontalArrangement = Arrangement.spacedBy(12.dp),
                    verticalAlignment = Alignment.CenterVertically
                ) {
                    Icon(
                        imageVector = Icons.Filled.Info,
                        contentDescription = "Tips Icon",
                        tint = MaterialTheme.colorScheme.primary,
                        modifier = Modifier.size(24.dp)
                    )
                    Column {
                        Text(
                            text = "Aesthetic Preparation Graph Rule",
                            fontSize = 12.sp,
                            fontWeight = FontWeight.Bold,
                            color = MaterialTheme.colorScheme.primary
                        )
                        Text(
                            text = "Dials show real-time percentage loops. High preparative values correlate with systematic study schedules. Track daily to maximize retention.",
                            fontSize = 11.sp,
                            color = MaterialTheme.colorScheme.onSurfaceVariant
                        )
                    }
                }
            }
        }
    }
}

@Composable
fun TimeCircularDial(
    value: Int,
    maxValue: Int,
    label: String,
    color: Color,
    isDark: Boolean
) {
    val sweepProgress = if (maxValue > 0) (value.toFloat() / maxValue.toFloat()).coerceIn(0f, 1f) else 0f

    Column(
        horizontalAlignment = Alignment.CenterHorizontally,
        verticalArrangement = Arrangement.spacedBy(6.dp)
    ) {
        Box(
            contentAlignment = Alignment.Center,
            modifier = Modifier.size(64.dp)
        ) {
            // Background track
            CircularProgressIndicator(
                progress = { 1f },
                modifier = Modifier.fillMaxSize(),
                color = if (isDark) Color(0xFF2E2E33) else Color(0xFFEEEEEE),
                strokeWidth = 5.dp
            )
            // Live progress
            CircularProgressIndicator(
                progress = { sweepProgress },
                modifier = Modifier.fillMaxSize(),
                color = color,
                strokeWidth = 5.dp
            )
            // Value
            Text(
                text = String.format("%02d", value),
                fontSize = 16.sp,
                fontWeight = FontWeight.Bold,
                fontFamily = FontFamily.Monospace,
                color = if (isDark) Color.White else Color.Black
            )
        }
        Text(
            text = label,
            fontSize = 10.sp,
            fontWeight = FontWeight.Bold,
            color = color
        )
    }
}

@Composable
fun TimeProgressBar(
    label: String,
    current: Int,
    max: Int,
    color: Color,
    suffix: String
) {
    val fraction = if (max > 0) (current.toFloat() / max.toFloat()).coerceIn(0f, 1f) else 0f
    
    Column(
        verticalArrangement = Arrangement.spacedBy(4.dp),
        modifier = Modifier.fillMaxWidth()
    ) {
        Row(
            modifier = Modifier.fillMaxWidth(),
            horizontalArrangement = Arrangement.SpaceBetween,
            verticalAlignment = Alignment.CenterVertically
        ) {
            Text(
                text = label,
                fontSize = 10.sp,
                fontWeight = FontWeight.SemiBold,
                color = MaterialTheme.colorScheme.onSurfaceVariant
            )
            Text(
                text = "$current/$max$suffix",
                fontSize = 10.sp,
                fontFamily = FontFamily.Monospace,
                fontWeight = FontWeight.Bold,
                color = color
            )
        }
        LinearProgressIndicator(
            progress = { fraction },
            modifier = Modifier
                .fillMaxWidth()
                .height(6.dp)
                .clip(RoundedCornerShape(3.dp)),
            color = color,
            trackColor = color.copy(alpha = 0.15f)
        )
    }
}

@OptIn(ExperimentalMaterial3Api::class)
@Composable
fun GetRewardScreen(viewModel: MainViewModel) {
    val loggedInUser by viewModel.loggedInUser.collectAsState()
    val allOffers by viewModel.allRewardOffers.collectAsState()
    val claimedRewards by viewModel.userClaimedRewards.collectAsState()
    val pendingMcqs by viewModel.allPendingMcqs.collectAsState()
    val notes by viewModel.allNotes.collectAsState()

    val context = LocalContext.current
    val isDark = isSystemInDarkTheme()

    Scaffold(
        topBar = {
            TopAppBar(
                title = { Text("Rewards Program 🎁", fontWeight = FontWeight.Bold) },
                navigationIcon = {
                    IconButton(onClick = { viewModel.navigateBack() }) {
                        Icon(Icons.AutoMirrored.Filled.ArrowBack, "Back")
                    }
                },
                colors = TopAppBarDefaults.topAppBarColors(containerColor = MaterialTheme.colorScheme.surface)
            )
        }
    ) { innerPadding ->
        val user = loggedInUser
        if (user == null) {
            Box(
                modifier = Modifier.fillMaxSize().padding(innerPadding),
                contentAlignment = Alignment.Center
            ) {
                Text("Please log in to view rewards.", style = MaterialTheme.typography.bodyLarge)
            }
            return@Scaffold
        }

        val isAdmin = user.role == "ADMIN"

        LazyColumn(
            modifier = Modifier
                .fillMaxSize()
                .padding(innerPadding)
                .padding(16.dp),
            verticalArrangement = Arrangement.spacedBy(16.dp)
        ) {
            if (!isAdmin) {
                // --- USER REWARDS DASHBOARD ---
                val userPendingCount = pendingMcqs.count { it.userId == user.id }
                val approvedCount = user.approvedMcqs
                val rejectedCount = user.rejectedMcqs
                val totalSubmitted = approvedCount + userPendingCount + rejectedCount

                val claimedCost = claimedRewards.sumOf { c -> allOffers.find { it.id == c.offerId }?.requiredMcqs ?: 0 }
                val leftMcqs = (approvedCount - claimedCost).coerceAtLeast(0)

                item {
                    Card(
                        shape = RoundedCornerShape(24.dp),
                        colors = CardDefaults.cardColors(
                            containerColor = if (isDark) MaterialTheme.colorScheme.surfaceVariant else MaterialTheme.colorScheme.primaryContainer
                        ),
                        border = BorderStroke(1.5.dp, MaterialTheme.colorScheme.primary.copy(alpha = 0.3f)),
                        modifier = Modifier.fillMaxWidth()
                    ) {
                        Column(
                            modifier = Modifier.padding(20.dp),
                            verticalArrangement = Arrangement.spacedBy(16.dp)
                        ) {
                            Text(
                                "My Contribution Progress 📈",
                                fontSize = 18.sp,
                                fontWeight = FontWeight.Bold,
                                color = MaterialTheme.colorScheme.primary
                            )

                            Row(
                                modifier = Modifier
                                    .fillMaxWidth()
                                    .background(
                                        if (isDark) MaterialTheme.colorScheme.primaryContainer.copy(alpha = 0.3f) else MaterialTheme.colorScheme.secondaryContainer,
                                        RoundedCornerShape(12.dp)
                                    )
                                    .padding(horizontal = 16.dp, vertical = 10.dp),
                                horizontalArrangement = Arrangement.SpaceBetween,
                                verticalAlignment = Alignment.CenterVertically
                            ) {
                                Text(
                                    "Available MCQ Points:",
                                    fontWeight = FontWeight.Bold,
                                    fontSize = 14.sp,
                                    color = MaterialTheme.colorScheme.primary
                                )
                                Text(
                                    "$leftMcqs Left to Claim",
                                    fontWeight = FontWeight.ExtraBold,
                                    fontSize = 16.sp,
                                    color = if (leftMcqs > 0) MaterialTheme.colorScheme.secondary else Color.Gray
                                )
                            }

                            // Numerical Stats row
                            Row(
                                modifier = Modifier.fillMaxWidth(),
                                horizontalArrangement = Arrangement.SpaceBetween
                            ) {
                                Column(horizontalAlignment = Alignment.CenterHorizontally) {
                                    Text("Approved", fontSize = 12.sp, color = Color.Gray)
                                    Text("$approvedCount", fontSize = 22.sp, fontWeight = FontWeight.Bold, color = Color(0xFF4CAF50))
                                }
                                Column(horizontalAlignment = Alignment.CenterHorizontally) {
                                    Text("Pending", fontSize = 12.sp, color = Color.Gray)
                                    Text("$userPendingCount", fontSize = 22.sp, fontWeight = FontWeight.Bold, color = Color(0xFFFF9800))
                                }
                                Column(horizontalAlignment = Alignment.CenterHorizontally) {
                                    Text("Rejected", fontSize = 12.sp, color = Color.Gray)
                                    Text("$rejectedCount", fontSize = 22.sp, fontWeight = FontWeight.Bold, color = Color(0xFFF44336))
                                }
                                Column(horizontalAlignment = Alignment.CenterHorizontally) {
                                    Text("Total Added", fontSize = 12.sp, color = Color.Gray)
                                    Text("$totalSubmitted", fontSize = 22.sp, fontWeight = FontWeight.Bold, color = MaterialTheme.colorScheme.primary)
                                }
                            }

                            // --- BAR CHART GRAPHIC ---
                            if (totalSubmitted > 0) {
                                Column(verticalArrangement = Arrangement.spacedBy(4.dp)) {
                                    Row(
                                        modifier = Modifier
                                            .fillMaxWidth()
                                            .height(24.dp)
                                            .clip(RoundedCornerShape(12.dp))
                                    ) {
                                        if (approvedCount > 0) {
                                            Box(
                                                modifier = Modifier
                                                    .weight(approvedCount.toFloat())
                                                    .fillMaxHeight()
                                                    .background(Color(0xFF4CAF50)),
                                                contentAlignment = Alignment.Center
                                            ) {
                                                Text("${(approvedCount * 100 / totalSubmitted)}%", color = Color.White, fontSize = 10.sp, fontWeight = FontWeight.Bold)
                                            }
                                        }
                                        if (userPendingCount > 0) {
                                            Box(
                                                modifier = Modifier
                                                    .weight(userPendingCount.toFloat())
                                                    .fillMaxHeight()
                                                    .background(Color(0xFFFF9800)),
                                                contentAlignment = Alignment.Center
                                            ) {
                                                Text("${(userPendingCount * 100 / totalSubmitted)}%", color = Color.White, fontSize = 10.sp, fontWeight = FontWeight.Bold)
                                            }
                                        }
                                        if (rejectedCount > 0) {
                                            Box(
                                                modifier = Modifier
                                                    .weight(rejectedCount.toFloat())
                                                    .fillMaxHeight()
                                                    .background(Color(0xFFF44336)),
                                                contentAlignment = Alignment.Center
                                            ) {
                                                Text("${(rejectedCount * 100 / totalSubmitted)}%", color = Color.White, fontSize = 10.sp, fontWeight = FontWeight.Bold)
                                            }
                                        }
                                    }

                                    // Chart Legend
                                    Row(
                                        modifier = Modifier.fillMaxWidth(),
                                        horizontalArrangement = Arrangement.spacedBy(12.dp, Alignment.CenterHorizontally),
                                        verticalAlignment = Alignment.CenterVertically
                                    ) {
                                        Row(verticalAlignment = Alignment.CenterVertically) {
                                            Box(modifier = Modifier.size(10.dp).clip(CircleShape).background(Color(0xFF4CAF50)))
                                            Spacer(modifier = Modifier.width(4.dp))
                                            Text("Approved", fontSize = 10.sp, color = MaterialTheme.colorScheme.onSurfaceVariant)
                                        }
                                        Row(verticalAlignment = Alignment.CenterVertically) {
                                            Box(modifier = Modifier.size(10.dp).clip(CircleShape).background(Color(0xFFFF9800)))
                                            Spacer(modifier = Modifier.width(4.dp))
                                            Text("Pending", fontSize = 10.sp, color = MaterialTheme.colorScheme.onSurfaceVariant)
                                        }
                                        Row(verticalAlignment = Alignment.CenterVertically) {
                                            Box(modifier = Modifier.size(10.dp).clip(CircleShape).background(Color(0xFFF44336)))
                                            Spacer(modifier = Modifier.width(4.dp))
                                            Text("Rejected", fontSize = 10.sp, color = MaterialTheme.colorScheme.onSurfaceVariant)
                                        }
                                    }
                                }
                            } else {
                                Box(
                                    modifier = Modifier
                                        .fillMaxWidth()
                                        .height(48.dp)
                                        .background(MaterialTheme.colorScheme.surfaceVariant.copy(alpha = 0.5f), RoundedCornerShape(12.dp)),
                                    contentAlignment = Alignment.Center
                                ) {
                                    Text("No MCQ contributions submitted yet. Start contributing to get rewards!", fontSize = 12.sp, color = Color.Gray, modifier = Modifier.padding(8.dp))
                                }
                            }
                        }
                    }
                }

                item {
                    Text(
                        "Available Reward Offers 🎁",
                        fontSize = 16.sp,
                        fontWeight = FontWeight.Bold,
                        color = MaterialTheme.colorScheme.onBackground,
                        modifier = Modifier.padding(top = 8.dp)
                    )
                }

                if (allOffers.isEmpty()) {
                    item {
                        Card(
                            modifier = Modifier.fillMaxWidth(),
                            colors = CardDefaults.cardColors(containerColor = MaterialTheme.colorScheme.surfaceVariant.copy(alpha = 0.5f))
                        ) {
                            Box(modifier = Modifier.padding(16.dp), contentAlignment = Alignment.Center) {
                                Text("No rewards offers configured by admin yet.", color = Color.Gray, fontSize = 14.sp)
                            }
                        }
                    }
                } else {
                    items(allOffers) { offer ->
                        val isClaimed = claimedRewards.any { it.offerId == offer.id }
                        val progressFraction = if (offer.requiredMcqs > 0) (leftMcqs.toFloat() / offer.requiredMcqs.toFloat()).coerceIn(0f, 1f) else 1f
                        val isEligible = leftMcqs >= offer.requiredMcqs

                        Card(
                            shape = RoundedCornerShape(16.dp),
                            border = BorderStroke(1.dp, MaterialTheme.colorScheme.outlineVariant),
                            colors = CardDefaults.cardColors(containerColor = MaterialTheme.colorScheme.surface),
                            modifier = Modifier.fillMaxWidth()
                        ) {
                            Column(
                                modifier = Modifier.padding(16.dp),
                                verticalArrangement = Arrangement.spacedBy(12.dp)
                            ) {
                                Row(
                                    modifier = Modifier.fillMaxWidth(),
                                    horizontalArrangement = Arrangement.SpaceBetween,
                                    verticalAlignment = Alignment.Top
                                ) {
                                    Column(modifier = Modifier.weight(1f)) {
                                        Text(
                                            offer.description,
                                            fontWeight = FontWeight.Bold,
                                            fontSize = 16.sp,
                                            color = MaterialTheme.colorScheme.primary
                                        )
                                        Spacer(modifier = Modifier.height(4.dp))
                                        Text(
                                            "Requires ${offer.requiredMcqs} Approved MCQs",
                                            fontSize = 12.sp,
                                            color = MaterialTheme.colorScheme.onSurfaceVariant
                                        )
                                    }

                                    // Display Icon depending on Type
                                    Icon(
                                        imageVector = when (offer.rewardType) {
                                            "SUBSCRIPTION" -> Icons.Filled.Stars
                                            "NOTES" -> Icons.Filled.LibraryBooks
                                            else -> Icons.Filled.Payments
                                        },
                                        contentDescription = "Reward Type Icon",
                                        tint = when (offer.rewardType) {
                                            "SUBSCRIPTION" -> Color(0xFFFFB300)
                                            "NOTES" -> Color(0xFF00ACC1)
                                            else -> Color(0xFF43A047)
                                        },
                                        modifier = Modifier.size(32.dp)
                                    )
                                }

                                // Details if Notes reward
                                if (offer.rewardType == "NOTES") {
                                    val noteIdsList = offer.notesIds.split(",").mapNotNull { it.trim().toIntOrNull() }
                                    val matchedNotesNames = notes.filter { noteIdsList.contains(it.id) }.map { it.title }
                                    if (matchedNotesNames.isNotEmpty()) {
                                        Text(
                                            "Included Notes: ${matchedNotesNames.joinToString(", ")}",
                                            fontSize = 12.sp,
                                            fontStyle = FontStyle.Italic,
                                            color = MaterialTheme.colorScheme.secondary
                                        )
                                    }
                                }

                                // Linear Progress bar towards this reward
                                Column(verticalArrangement = Arrangement.spacedBy(4.dp)) {
                                    Row(
                                        modifier = Modifier.fillMaxWidth(),
                                        horizontalArrangement = Arrangement.SpaceBetween
                                    ) {
                                        Text(
                                            text = "Claim Progress",
                                            fontSize = 11.sp,
                                            color = MaterialTheme.colorScheme.onSurfaceVariant
                                        )
                                        Text(
                                            text = "$leftMcqs / ${offer.requiredMcqs} MCQs (${(progressFraction * 100).toInt()}%)",
                                            fontSize = 11.sp,
                                            fontWeight = FontWeight.Bold,
                                            color = if (isEligible) Color(0xFF4CAF50) else MaterialTheme.colorScheme.primary
                                        )
                                    }
                                    LinearProgressIndicator(
                                        progress = { progressFraction },
                                        modifier = Modifier.fillMaxWidth().height(6.dp).clip(RoundedCornerShape(3.dp)),
                                        color = if (isEligible) Color(0xFF4CAF50) else MaterialTheme.colorScheme.primary,
                                        trackColor = MaterialTheme.colorScheme.outlineVariant.copy(alpha = 0.5f)
                                    )
                                }

                                Row(
                                    modifier = Modifier.fillMaxWidth(),
                                    horizontalArrangement = Arrangement.End
                                ) {
                                    if (isClaimed) {
                                        Button(
                                            onClick = {},
                                            enabled = false,
                                            colors = ButtonDefaults.buttonColors(
                                                disabledContainerColor = Color(0xFF4CAF50).copy(alpha = 0.2f),
                                                disabledContentColor = Color(0xFF4CAF50)
                                            )
                                        ) {
                                            Icon(Icons.Filled.Check, "Claimed")
                                            Spacer(modifier = Modifier.width(4.dp))
                                            Text("Already Claimed")
                                        }
                                    } else {
                                        Button(
                                            onClick = {
                                                viewModel.claimReward(offer) { success, msg, waUrl ->
                                                    android.widget.Toast.makeText(context, msg, android.widget.Toast.LENGTH_LONG).show()
                                                    if (success && waUrl != null) {
                                                        try {
                                                            val intent = Intent(Intent.ACTION_VIEW).apply {
                                                                data = Uri.parse(waUrl)
                                                            }
                                                            context.startActivity(intent)
                                                        } catch (e: Exception) {
                                                            android.widget.Toast.makeText(context, "Redirect failed. Please manually message admin.", android.widget.Toast.LENGTH_SHORT).show()
                                                        }
                                                    }
                                                }
                                            },
                                            enabled = isEligible,
                                            colors = ButtonDefaults.buttonColors(
                                                containerColor = MaterialTheme.colorScheme.secondary,
                                                contentColor = Color.White
                                            ),
                                            modifier = Modifier.testTag("claim_reward_btn_${offer.id}")
                                        ) {
                                            if (isEligible) {
                                                Icon(Icons.Filled.Redeem, "Unlock")
                                                Spacer(modifier = Modifier.width(6.dp))
                                                Text("Claim Reward!")
                                            } else {
                                                Icon(Icons.Filled.Lock, "Locked")
                                                Spacer(modifier = Modifier.width(6.dp))
                                                Text("Locked (Needs ${offer.requiredMcqs - leftMcqs} more)")
                                            }
                                        }
                                    }
                                }
                            }
                        }
                    }
                }
            } else {
                // --- ADMIN REWARDS MANAGER PANEL ---
                item {
                    Text(
                        "Configure New Reward Offer 🛠️",
                        fontSize = 18.sp,
                        fontWeight = FontWeight.Bold,
                        color = MaterialTheme.colorScheme.primary
                    )
                }

                item {
                    var reqMcqsInput by remember { mutableStateOf("100") }
                    var selectedRewardTypeIndex by remember { mutableStateOf(0) } // 0: Subscription, 1: Notes, 2: Cash
                    val rewardTypes = listOf("SUBSCRIPTION", "NOTES", "CASH")

                    // Multi-select state for notes
                    val selectedNotesIds = remember { mutableStateListOf<Int>() }

                    var cashAmountInput by remember { mutableStateOf("1000") }
                    var customDescriptionInput by remember { mutableStateOf("") }

                    var typeDropdownExpanded by remember { mutableStateOf(false) }

                    Card(
                        shape = RoundedCornerShape(20.dp),
                        elevation = CardDefaults.cardElevation(defaultElevation = 2.dp),
                        colors = CardDefaults.cardColors(containerColor = MaterialTheme.colorScheme.surface),
                        border = BorderStroke(1.dp, MaterialTheme.colorScheme.outlineVariant),
                        modifier = Modifier.fillMaxWidth()
                    ) {
                        Column(
                            modifier = Modifier.padding(16.dp),
                            verticalArrangement = Arrangement.spacedBy(14.dp)
                        ) {
                            // MCQ count requirement input
                            OutlinedTextField(
                                value = reqMcqsInput,
                                onValueChange = { reqMcqsInput = it.filter { c -> c.isDigit() } },
                                label = { Text("Required Approved MCQs") },
                                keyboardOptions = androidx.compose.foundation.text.KeyboardOptions(
                                    keyboardType = androidx.compose.ui.text.input.KeyboardType.Number
                                ),
                                leadingIcon = { Icon(Icons.Filled.Numbers, null) },
                                modifier = Modifier.fillMaxWidth()
                            )

                            // Dropdown for Type Selection
                            Box(modifier = Modifier.fillMaxWidth()) {
                                OutlinedTextField(
                                    value = when (rewardTypes[selectedRewardTypeIndex]) {
                                        "SUBSCRIPTION" -> "1 Month Free Subscription"
                                        "NOTES" -> "Academic Notes Package"
                                        else -> "Cash Reward Payment"
                                    },
                                    onValueChange = {},
                                    readOnly = true,
                                    label = { Text("Reward Benefit Type") },
                                    leadingIcon = { Icon(Icons.Filled.Redeem, null) },
                                    trailingIcon = {
                                        IconButton(onClick = { typeDropdownExpanded = !typeDropdownExpanded }) {
                                            Icon(Icons.Filled.ArrowDropDown, "Open Dropdown")
                                        }
                                    },
                                    modifier = Modifier.fillMaxWidth().clickable { typeDropdownExpanded = true }
                                )
                                DropdownMenu(
                                    expanded = typeDropdownExpanded,
                                    onDismissRequest = { typeDropdownExpanded = false },
                                    modifier = Modifier.fillMaxWidth(0.9f)
                                ) {
                                    DropdownMenuItem(
                                        text = { Text("1 Month Free Subscription ⭐️") },
                                        onClick = {
                                            selectedRewardTypeIndex = 0
                                            typeDropdownExpanded = false
                                        }
                                    )
                                    DropdownMenuItem(
                                        text = { Text("Specific Notes Unlock 📚") },
                                        onClick = {
                                            selectedRewardTypeIndex = 1
                                            typeDropdownExpanded = false
                                        }
                                    )
                                    DropdownMenuItem(
                                        text = { Text("Cash Reward 💵") },
                                        onClick = {
                                            selectedRewardTypeIndex = 2
                                            typeDropdownExpanded = false
                                        }
                                    )
                                }
                            }

                            // Dynamic panel depending on reward selection
                            when (rewardTypes[selectedRewardTypeIndex]) {
                                "NOTES" -> {
                                    Text(
                                        "Select Notes to Unlock (Multiple Selection):",
                                        fontSize = 13.sp,
                                        fontWeight = FontWeight.Bold,
                                        color = MaterialTheme.colorScheme.onSurfaceVariant
                                    )
                                    if (notes.isEmpty()) {
                                        Text("No academic notes exist. Create notes first under Notes tab.", fontSize = 12.sp, color = Color.Red)
                                    } else {
                                        Card(
                                            modifier = Modifier
                                                .fillMaxWidth()
                                                .heightIn(max = 180.dp),
                                            colors = CardDefaults.cardColors(containerColor = MaterialTheme.colorScheme.surfaceVariant.copy(alpha = 0.3f)),
                                            border = BorderStroke(1.dp, MaterialTheme.colorScheme.outlineVariant)
                                        ) {
                                            LazyColumn(
                                                modifier = Modifier.padding(6.dp),
                                                verticalArrangement = Arrangement.spacedBy(4.dp)
                                            ) {
                                                items(notes) { note ->
                                                    val isSelected = selectedNotesIds.contains(note.id)
                                                    Row(
                                                        modifier = Modifier
                                                            .fillMaxWidth()
                                                            .clickable {
                                                                if (isSelected) selectedNotesIds.remove(note.id)
                                                                else selectedNotesIds.add(note.id)
                                                            }
                                                            .padding(vertical = 4.dp, horizontal = 8.dp),
                                                        verticalAlignment = Alignment.CenterVertically
                                                    ) {
                                                        Checkbox(
                                                            checked = isSelected,
                                                            onCheckedChange = { checked ->
                                                                if (checked == true) selectedNotesIds.add(note.id)
                                                                else selectedNotesIds.remove(note.id)
                                                            }
                                                        )
                                                        Spacer(modifier = Modifier.width(8.dp))
                                                        Text(note.title, fontSize = 14.sp)
                                                    }
                                                }
                                            }
                                        }
                                    }
                                }
                                "CASH" -> {
                                    OutlinedTextField(
                                        value = cashAmountInput,
                                        onValueChange = { cashAmountInput = it.filter { c -> c.isDigit() } },
                                        label = { Text("Cash Amount (Rs.)") },
                                        keyboardOptions = androidx.compose.foundation.text.KeyboardOptions(
                                            keyboardType = androidx.compose.ui.text.input.KeyboardType.Number
                                        ),
                                        leadingIcon = { Icon(Icons.Filled.Payments, null) },
                                        modifier = Modifier.fillMaxWidth()
                                    )
                                }
                            }

                            // Custom offer title/description text field
                            OutlinedTextField(
                                value = customDescriptionInput,
                                onValueChange = { customDescriptionInput = it },
                                label = { Text("Custom Description (Optional)") },
                                placeholder = { Text("e.g. Free Biotech Premium Access") },
                                leadingIcon = { Icon(Icons.Filled.Edit, null) },
                                modifier = Modifier.fillMaxWidth()
                            )

                            // Save Offer button
                            Button(
                                onClick = {
                                    val reqMcqVal = reqMcqsInput.toIntOrNull() ?: 100
                                    val rType = rewardTypes[selectedRewardTypeIndex]
                                    val finalDesc = if (customDescriptionInput.trim().isNotEmpty()) {
                                        customDescriptionInput.trim()
                                    } else {
                                        when (rType) {
                                            "SUBSCRIPTION" -> "1 Month Free Subscription"
                                            "NOTES" -> {
                                                val count = selectedNotesIds.size
                                                "Unlock $count Premium Study Notes Package"
                                            }
                                            else -> "Rs. ${cashAmountInput.toDoubleOrNull() ?: 0.0} Cash Payout Reward"
                                        }
                                    }

                                    val notesIdsStr = selectedNotesIds.joinToString(",")
                                    val cashAmountVal = if (rType == "CASH") (cashAmountInput.toDoubleOrNull() ?: 0.0) else 0.0

                                    viewModel.createRewardOffer(
                                        requiredMcqs = reqMcqVal,
                                        rewardType = rType,
                                        notesIds = notesIdsStr,
                                        cashAmount = cashAmountVal,
                                        description = finalDesc
                                    )
                                    // Reset fields
                                    customDescriptionInput = ""
                                    selectedNotesIds.clear()
                                    android.widget.Toast.makeText(context, "Offer Created successfully!", android.widget.Toast.LENGTH_SHORT).show()
                                },
                                modifier = Modifier.fillMaxWidth().testTag("create_reward_offer_btn"),
                                colors = ButtonDefaults.buttonColors(containerColor = MaterialTheme.colorScheme.primary)
                            ) {
                                Icon(Icons.Filled.Add, "Create")
                                Spacer(modifier = Modifier.width(6.dp))
                                Text("Create Reward Offer", fontWeight = FontWeight.Bold)
                            }
                        }
                    }
                }

                item {
                    Text(
                        "Active Reward Offers 📋",
                        fontSize = 16.sp,
                        fontWeight = FontWeight.Bold,
                        modifier = Modifier.padding(top = 8.dp)
                    )
                }

                if (allOffers.isEmpty()) {
                    item {
                        Card(
                            modifier = Modifier.fillMaxWidth(),
                            colors = CardDefaults.cardColors(containerColor = MaterialTheme.colorScheme.surfaceVariant.copy(alpha = 0.5f))
                        ) {
                            Box(modifier = Modifier.padding(16.dp), contentAlignment = Alignment.Center) {
                                Text("No active offers. Use form above to add your first offer.", color = Color.Gray, fontSize = 14.sp)
                            }
                        }
                    }
                } else {
                    items(allOffers) { offer ->
                        Card(
                            modifier = Modifier.fillMaxWidth(),
                            border = BorderStroke(1.dp, MaterialTheme.colorScheme.outlineVariant),
                            colors = CardDefaults.cardColors(containerColor = MaterialTheme.colorScheme.surface)
                        ) {
                            Row(
                                modifier = Modifier.padding(16.dp),
                                verticalAlignment = Alignment.CenterVertically,
                                horizontalArrangement = Arrangement.SpaceBetween
                            ) {
                                Column(modifier = Modifier.weight(1f)) {
                                    Text(offer.description, fontWeight = FontWeight.Bold, fontSize = 15.sp)
                                    Spacer(modifier = Modifier.height(2.dp))
                                    Text("Type: ${offer.rewardType} | Needs ${offer.requiredMcqs} Approved MCQs", fontSize = 12.sp, color = Color.Gray)
                                    if (offer.rewardType == "NOTES" && offer.notesIds.isNotEmpty()) {
                                        Text("Unlocked Note IDs: ${offer.notesIds}", fontSize = 11.sp, color = MaterialTheme.colorScheme.secondary)
                                    }
                                }

                                IconButton(
                                    onClick = { viewModel.deleteRewardOffer(offer) },
                                    colors = IconButtonDefaults.iconButtonColors(contentColor = Color.Red),
                                    modifier = Modifier.testTag("delete_reward_offer_${offer.id}")
                                ) {
                                    Icon(Icons.Filled.Delete, "Delete Offer")
                                }
                            }
                        }
                    }
                }
            }
        }
    }
}

// ==================== SCREEN: APP BRANDING AND CONFIGURATION SETTINGS ====================
@OptIn(androidx.compose.material3.ExperimentalMaterial3Api::class)
@Composable
fun AdminAppSettingsScreen(viewModel: MainViewModel) {
    val loggedInUserVal by viewModel.loggedInUser.collectAsState()
    
    if (loggedInUserVal?.role != "ADMIN") {
        Box(
            modifier = Modifier.fillMaxSize().background(MaterialTheme.colorScheme.background),
            contentAlignment = Alignment.Center
        ) {
            Text(
                text = "Permission Denied. Only Admins can access this page.",
                color = MaterialTheme.colorScheme.error,
                fontWeight = FontWeight.Bold,
                fontSize = 16.sp
            )
        }
        return
    }

    val appSettingsVal by viewModel.appSettings.collectAsState()

    var nameInput by remember(appSettingsVal) {
        mutableStateOf(appSettingsVal["app_name"] ?: "NayaRasta")
    }
    var logoInput by remember(appSettingsVal) {
        mutableStateOf(appSettingsVal["app_logo_url"] ?: "")
    }
    var iconInput by remember(appSettingsVal) {
        mutableStateOf(appSettingsVal["app_icon_url"] ?: "🎓")
    }
    var splashInput by remember(appSettingsVal) {
        mutableStateOf(appSettingsVal["splash_screen_url"] ?: "")
    }
    var landingInput by remember(appSettingsVal) {
        mutableStateOf(appSettingsVal["landing_hero_banner"] ?: "")
    }
    var aboutUsInput by remember(appSettingsVal) {
        mutableStateOf(appSettingsVal["about_us_image"] ?: "")
    }
    var countdownInput by remember(appSettingsVal) {
        mutableStateOf(appSettingsVal["countdown_quote_image"] ?: "")
    }
    var helplineInput by remember(appSettingsVal) {
        mutableStateOf(appSettingsVal["helpline_number"] ?: "03328335332")
    }

    var themePrimaryInput by remember(appSettingsVal) {
        mutableStateOf(appSettingsVal["theme_primary_color"] ?: "#1D4ED8")
    }
    var themeSecondaryInput by remember(appSettingsVal) {
        mutableStateOf(appSettingsVal["theme_secondary_color"] ?: "#EA580C")
    }

    val context = androidx.compose.ui.platform.LocalContext.current

    val logoPickerLauncher = androidx.activity.compose.rememberLauncherForActivityResult(
        contract = androidx.activity.result.contract.ActivityResultContracts.GetContent()
    ) { uri: android.net.Uri? ->
        if (uri != null) {
            val localPath = viewModel.copyUriToLocalStorage(context, uri, "app_logo")
            if (localPath != null) {
                logoInput = localPath
            }
        }
    }

    val iconPickerLauncher = androidx.activity.compose.rememberLauncherForActivityResult(
        contract = androidx.activity.result.contract.ActivityResultContracts.GetContent()
    ) { uri: android.net.Uri? ->
        if (uri != null) {
            val localPath = viewModel.copyUriToLocalStorage(context, uri, "app_icon")
            if (localPath != null) {
                iconInput = localPath
            }
        }
    }

    val splashPickerLauncher = androidx.activity.compose.rememberLauncherForActivityResult(
        contract = androidx.activity.result.contract.ActivityResultContracts.GetContent()
    ) { uri: android.net.Uri? ->
        if (uri != null) {
            val localPath = viewModel.copyUriToLocalStorage(context, uri, "splash_screen")
            if (localPath != null) {
                splashInput = localPath
            }
        }
    }

    val landingPickerLauncher = androidx.activity.compose.rememberLauncherForActivityResult(
        contract = androidx.activity.result.contract.ActivityResultContracts.GetContent()
    ) { uri: android.net.Uri? ->
        if (uri != null) {
            val localPath = viewModel.copyUriToLocalStorage(context, uri, "landing_hero")
            if (localPath != null) {
                landingInput = localPath
            }
        }
    }

    val aboutUsPickerLauncher = androidx.activity.compose.rememberLauncherForActivityResult(
        contract = androidx.activity.result.contract.ActivityResultContracts.GetContent()
    ) { uri: android.net.Uri? ->
        if (uri != null) {
            val localPath = viewModel.copyUriToLocalStorage(context, uri, "about_us_image")
            if (localPath != null) {
                aboutUsInput = localPath
            }
        }
    }

    val countdownPickerLauncher = androidx.activity.compose.rememberLauncherForActivityResult(
        contract = androidx.activity.result.contract.ActivityResultContracts.GetContent()
    ) { uri: android.net.Uri? ->
        if (uri != null) {
            val localPath = viewModel.copyUriToLocalStorage(context, uri, "countdown_quote")
            if (localPath != null) {
                countdownInput = localPath
            }
        }
    }

    var showToast by remember { mutableStateOf(false) }
    var toastMessage by remember { mutableStateOf("") }

    Scaffold(
        topBar = {
            TopAppBar(
                title = {
                    Row(verticalAlignment = Alignment.CenterVertically) {
                        Icon(
                            imageVector = Icons.Filled.Palette,
                            contentDescription = null,
                            tint = MaterialTheme.colorScheme.primary
                        )
                        Spacer(modifier = Modifier.width(8.dp))
                        Text("App Settings & Branding", fontWeight = FontWeight.Bold)
                    }
                },
                navigationIcon = {
                    IconButton(onClick = { viewModel.navigateTo(Screen.AdminDashboard) }) {
                        Icon(imageVector = Icons.AutoMirrored.Filled.ArrowBack, contentDescription = "Back")
                    }
                }
            )
        }
    ) { paddingValues ->
        Box(
            modifier = Modifier
                .fillMaxSize()
                .padding(paddingValues)
                .background(MaterialTheme.colorScheme.background)
        ) {
            LazyColumn(
                modifier = Modifier.fillMaxSize(),
                contentPadding = PaddingValues(16.dp),
                verticalArrangement = Arrangement.spacedBy(16.dp)
            ) {
                // Header / Overview card
                item {
                    Card(
                        colors = CardDefaults.cardColors(
                            containerColor = MaterialTheme.colorScheme.primaryContainer.copy(alpha = 0.4f)
                        ),
                        modifier = Modifier.fillMaxWidth()
                    ) {
                        Column(modifier = Modifier.padding(16.dp)) {
                            Text(
                                text = "Dynamic Brand Desk",
                                fontWeight = FontWeight.Bold,
                                fontSize = 16.sp,
                                color = MaterialTheme.colorScheme.primary
                            )
                            Spacer(modifier = Modifier.height(4.dp))
                            Text(
                                text = "Modify the app branding in real time. Changes are stored in the local SQLite/Supabase backend database and refresh immediately throughout all views.",
                                fontSize = 12.sp,
                                color = MaterialTheme.colorScheme.onSurfaceVariant
                            )
                        }
                    }
                }

                // Section 1: Core Branding
                item {
                    Card(
                        modifier = Modifier.fillMaxWidth(),
                        border = BorderStroke(1.dp, MaterialTheme.colorScheme.outlineVariant)
                    ) {
                        Column(
                            modifier = Modifier.padding(16.dp),
                            verticalArrangement = Arrangement.spacedBy(12.dp)
                        ) {
                            Text(
                                text = "CORE BRANDING",
                                fontWeight = FontWeight.ExtraBold,
                                fontSize = 11.sp,
                                color = MaterialTheme.colorScheme.primary,
                                letterSpacing = 1.sp
                            )

                            // App Name
                            OutlinedTextField(
                                value = nameInput,
                                onValueChange = { nameInput = it },
                                label = { Text("App Name") },
                                modifier = Modifier.fillMaxWidth().testTag("app_name_input"),
                                singleLine = true,
                                leadingIcon = {
                                    Icon(Icons.Filled.Title, null)
                                }
                            )

                            // WhatsApp / Helpline Number
                            OutlinedTextField(
                                value = helplineInput,
                                onValueChange = { helplineInput = it },
                                label = { Text("WhatsApp / Helpline Number") },
                                placeholder = { Text("e.g. 03328335332") },
                                modifier = Modifier.fillMaxWidth().testTag("app_helpline_input"),
                                singleLine = true,
                                leadingIcon = {
                                    Icon(Icons.Filled.Phone, null)
                                }
                            )

                            // App Icon / Emoji
                            Row(
                                modifier = Modifier.fillMaxWidth(),
                                verticalAlignment = Alignment.CenterVertically,
                                horizontalArrangement = Arrangement.spacedBy(8.dp)
                            ) {
                                OutlinedTextField(
                                    value = iconInput,
                                    onValueChange = { iconInput = it },
                                    label = { Text("App Icon Character / Path") },
                                    placeholder = { Text("🎓 or Local Path") },
                                    modifier = Modifier.weight(1f).testTag("app_icon_input"),
                                    singleLine = true,
                                    leadingIcon = {
                                        Icon(Icons.Filled.EmojiEmotions, null)
                                    }
                                )
                                Button(
                                    onClick = { iconPickerLauncher.launch("image/*") },
                                    shape = RoundedCornerShape(8.dp),
                                    contentPadding = PaddingValues(horizontal = 8.dp),
                                    modifier = Modifier.height(56.dp)
                                ) {
                                    Icon(Icons.Filled.PhotoLibrary, contentDescription = "Pick Icon")
                                }
                            }
                        }
                    }
                }

                // Section 2: Logo and Splash Screen
                item {
                    Card(
                        modifier = Modifier.fillMaxWidth(),
                        border = BorderStroke(1.dp, MaterialTheme.colorScheme.outlineVariant)
                    ) {
                        Column(
                            modifier = Modifier.padding(16.dp),
                            verticalArrangement = Arrangement.spacedBy(12.dp)
                        ) {
                            Text(
                                text = "ASSETS & IMAGES",
                                fontWeight = FontWeight.ExtraBold,
                                fontSize = 11.sp,
                                color = MaterialTheme.colorScheme.primary,
                                letterSpacing = 1.sp
                            )

                            // App Logo
                            Row(
                                modifier = Modifier.fillMaxWidth(),
                                verticalAlignment = Alignment.CenterVertically,
                                horizontalArrangement = Arrangement.spacedBy(8.dp)
                            ) {
                                OutlinedTextField(
                                    value = logoInput,
                                    onValueChange = { logoInput = it },
                                    label = { Text("App Logo Image URL / Path") },
                                    placeholder = { Text("Leave blank for default resource") },
                                    modifier = Modifier.weight(1f).testTag("app_logo_input"),
                                    leadingIcon = {
                                        Icon(Icons.Filled.Image, null)
                                    }
                                )
                                Button(
                                    onClick = { logoPickerLauncher.launch("image/*") },
                                    shape = RoundedCornerShape(8.dp),
                                    contentPadding = PaddingValues(horizontal = 8.dp),
                                    modifier = Modifier.height(56.dp)
                                ) {
                                    Icon(Icons.Filled.PhotoLibrary, contentDescription = "Pick Logo")
                                }
                            }
                            if (logoInput.isNotBlank()) {
                                Box(
                                    modifier = Modifier
                                        .size(60.dp)
                                        .align(Alignment.CenterHorizontally)
                                        .clip(RoundedCornerShape(8.dp))
                                        .background(Color.White)
                                        .padding(4.dp),
                                    contentAlignment = Alignment.Center
                                ) {
                                    androidx.compose.foundation.Image(
                                        painter = coil.compose.rememberAsyncImagePainter(model = logoInput),
                                        contentDescription = "Logo Preview",
                                        modifier = Modifier.fillMaxSize(),
                                        contentScale = androidx.compose.ui.layout.ContentScale.Fit
                                    )
                                }
                            }

                            // Splash Screen Image
                            Row(
                                modifier = Modifier.fillMaxWidth(),
