// ==================== SCREEN: USER SEARCH ====================
@OptIn(androidx.compose.material3.ExperimentalMaterial3Api::class)
@Composable
fun UserSearchScreen(viewModel: MainViewModel) {
    val allUsers by viewModel.allUsers.collectAsState()
    val onlineUsers by viewModel.onlineSearchResults.collectAsState()
    val isSearchingOnline by viewModel.isSearchingOnline.collectAsState()
    val loggedInUser by viewModel.loggedInUser.collectAsState()
    val activeStyle by viewModel.activeDesignStyle.collectAsState()
    
    var searchQuery by remember { mutableStateOf("") }
    
    // Live direct online search from Supabase database
    LaunchedEffect(searchQuery) {
        viewModel.searchUsersOnline(searchQuery)
    }
    
    val filteredUsers = remember(allUsers, onlineUsers, searchQuery, loggedInUser) {
        val query = searchQuery.trim().lowercase()
        val isAdmin = loggedInUser?.role == "ADMIN"
        
        // Prefer live online database results; fallback to locally cached users if online is empty and we are offline/idle
        val baseUsers = if (onlineUsers.isNotEmpty() || query.isNotEmpty()) {
            onlineUsers
        } else {
            allUsers
        }
        
        baseUsers.filter { user ->
            user.id != loggedInUser?.id &&
            (isAdmin || user.role != "ADMIN") &&
            (query.isEmpty() || 
             user.username.lowercase().contains(query) ||
             user.fullName.lowercase().contains(query) ||
             user.phoneNumber.contains(query)) &&
            (isAdmin || viewModel.getPrivacySettings(user.id).isProfilePublic)
        }
    }
    
    Scaffold(
        topBar = {
            TopAppBar(
                title = { Text("Search Students", fontWeight = FontWeight.Bold, fontSize = 20.sp) },
                navigationIcon = {
                    IconButton(onClick = { viewModel.navigateBack() }) {
                        Icon(Icons.Filled.ArrowBack, "Back")
                    }
                },
                colors = TopAppBarDefaults.topAppBarColors(
                    containerColor = MaterialTheme.colorScheme.primaryContainer,
                    titleContentColor = MaterialTheme.colorScheme.onPrimaryContainer
                )
            )
        }
    ) { paddingValues ->
        Column(
            modifier = Modifier
                .fillMaxSize()
                .padding(paddingValues)
                .padding(16.dp),
            verticalArrangement = Arrangement.spacedBy(16.dp)
        ) {
            OutlinedTextField(
                value = searchQuery,
                onValueChange = { searchQuery = it },
                label = { Text("Search by name, username, or phone") },
                placeholder = { Text("Enter student name or phone...") },
                leadingIcon = { Icon(Icons.Filled.Search, "Search Icon") },
                trailingIcon = {
                    if (isSearchingOnline) {
                        CircularProgressIndicator(modifier = Modifier.size(20.dp), strokeWidth = 2.dp)
                    } else if (searchQuery.isNotEmpty()) {
                        IconButton(onClick = { searchQuery = "" }) {
                            Icon(Icons.Filled.Close, "Clear search")
                        }
                    }
                },
                singleLine = true,
                modifier = Modifier.fillMaxWidth(),
                shape = RoundedCornerShape(12.dp)
            )
            
            Text(
                text = if (searchQuery.isEmpty()) "All Registered Students" else "Search Results (${filteredUsers.size})",
                fontWeight = FontWeight.Bold,
                fontSize = 15.sp,
                color = MaterialTheme.colorScheme.primary
            )
            
            if (filteredUsers.isEmpty()) {
                Box(
                    modifier = Modifier.fillMaxSize().weight(1f),
                    contentAlignment = Alignment.Center
                ) {
                    Column(
                        horizontalAlignment = Alignment.CenterHorizontally,
                        verticalArrangement = Arrangement.spacedBy(8.dp)
                    ) {
                        Icon(
                            imageVector = Icons.Filled.People,
                            contentDescription = "No students",
                            tint = MaterialTheme.colorScheme.outline,
                            modifier = Modifier.size(64.dp)
                        )
                        Text(
                            text = if (searchQuery.isEmpty()) "No students registered yet." else "No students match your query.",
                            color = MaterialTheme.colorScheme.outline,
                            fontSize = 14.sp
                        )
                    }
                }
            } else {
                LazyColumn(
                    modifier = Modifier.fillMaxSize().weight(1f),
                    verticalArrangement = Arrangement.spacedBy(10.dp)
                ) {
                    items(filteredUsers) { user ->
                        val privacy = viewModel.getPrivacySettings(user.id)
                        val displayName = if (privacy.hideFullName && loggedInUser?.role != "ADMIN") {
                            "@${user.username}"
                        } else {
                            user.fullName.ifEmpty { "@${user.username}" }
                        }
                        
                        Card(
                            modifier = Modifier
                                .fillMaxWidth()
                                .clickable { viewModel.navigateTo(Screen.ViewUserProfile(user.id)) },
                            colors = CardDefaults.cardColors(containerColor = MaterialTheme.colorScheme.surface),
                            border = BorderStroke(1.dp, MaterialTheme.colorScheme.outlineVariant)
                        ) {
                            Row(
                                modifier = Modifier
                                    .fillMaxWidth()
                                    .padding(12.dp),
                                verticalAlignment = Alignment.CenterVertically
                            ) {
                                Box(
                                    modifier = Modifier
                                        .size(48.dp)
                                        .clip(CircleShape)
                                        .background(Color(if (user.avatarColor != 0) user.avatarColor else 0xFF005FB0.toInt())),
                                    contentAlignment = Alignment.Center
                                ) {
                                    val hideImage = privacy.hideProfileImage && loggedInUser?.role != "ADMIN"
                                    if (!user.profileImageUri.isNullOrEmpty() && !hideImage) {
                                        androidx.compose.foundation.Image(
                                            painter = coil.compose.rememberAsyncImagePainter(model = user.profileImageUri),
                                            contentDescription = "User profile picture",
                                            modifier = Modifier.fillMaxSize(),
                                            contentScale = androidx.compose.ui.layout.ContentScale.Crop
                                        )
                                    } else {
                                        val initial = user.username.firstOrNull()?.uppercase() ?: "S"
                                        Text(
                                            text = initial,
                                            color = Color.White,
                                            fontWeight = FontWeight.Bold,
                                            fontSize = 18.sp
                                        )
                                    }
                                }
                                
                                Spacer(modifier = Modifier.width(12.dp))
                                
                                Column(modifier = Modifier.weight(1f)) {
                                    Text(
                                        text = displayName,
                                        fontWeight = FontWeight.Bold,
                                        fontSize = 15.sp,
                                        color = MaterialTheme.colorScheme.onSurface
                                    )
                                    Text(
                                        text = "@${user.username} • ${user.studentType.ifEmpty { "Fresher" }}",
                                        fontSize = 12.sp,
                                        color = MaterialTheme.colorScheme.onSurfaceVariant
                                    )
                                }
                                
                                Icon(
                                    imageVector = Icons.Filled.ChevronRight,
                                    contentDescription = "View Profile",
                                    tint = MaterialTheme.colorScheme.outline
                                )
                            }
                        }
                    }
                }
            }
        }
    }
}

// ==================== SCREEN: VIEW USER PROFILE ====================
@OptIn(androidx.compose.material3.ExperimentalMaterial3Api::class)
@Composable
fun ViewUserProfileScreen(viewModel: MainViewModel, userId: Int) {
    val allUsers by viewModel.allUsers.collectAsState()
    val loggedInUser by viewModel.loggedInUser.collectAsState()
    val activeStyle by viewModel.activeDesignStyle.collectAsState()
    val isDark = androidx.compose.foundation.isSystemInDarkTheme()
    
    val user = remember(allUsers, userId) { allUsers.find { it.id == userId } }
    val userTests by viewModel.getTestResultsForUser(userId).collectAsState(initial = emptyList())
    val allResults by viewModel.allTestResults.collectAsState()
    
    val privacy = remember(userId, allUsers) { viewModel.getPrivacySettings(userId) }
    
    val isAdmin = loggedInUser?.role == "ADMIN"
    val last5Tests = remember(userTests) { userTests.take(5) }
    
    Scaffold(
        topBar = {
            TopAppBar(
                title = { Text(if (user != null) (if (privacy.hideFullName && !isAdmin) "@${user.username}" else user.fullName.ifEmpty { "@${user.username}" }) else "Student Profile", fontWeight = FontWeight.Bold, fontSize = 18.sp) },
                navigationIcon = {
                    IconButton(onClick = { viewModel.navigateBack() }) {
                        Icon(Icons.Filled.ArrowBack, "Back")
                    }
                },
                colors = TopAppBarDefaults.topAppBarColors(
                    containerColor = MaterialTheme.colorScheme.primaryContainer,
                    titleContentColor = MaterialTheme.colorScheme.onPrimaryContainer
                )
            )
        }
    ) { paddingValues ->
        if (user == null) {
            Box(
                modifier = Modifier
                    .fillMaxSize()
                    .padding(paddingValues),
                contentAlignment = Alignment.Center
            ) {
                Text("Error: Selected profile could not be found.", color = MaterialTheme.colorScheme.error)
            }
        } else {
            LazyColumn(
                modifier = Modifier
                    .fillMaxSize()
                    .padding(paddingValues)
                    .padding(16.dp),
                verticalArrangement = Arrangement.spacedBy(14.dp)
            ) {
                item {
                    PremiumStyleContainer(
                        style = activeStyle,
                        modifier = Modifier.fillMaxWidth(),
                        containerColor = MaterialTheme.colorScheme.surface
                    ) {
                        Row(
                            modifier = Modifier
                                .fillMaxWidth()
                                .padding(16.dp),
                            verticalAlignment = Alignment.CenterVertically
                        ) {
                            Box(
                                modifier = Modifier
                                    .size(64.dp)
                                    .clip(CircleShape)
                                    .background(Color(if (user.avatarColor != 0) user.avatarColor else 0xFF005FB0.toInt())),
                                contentAlignment = Alignment.Center
                            ) {
                                val hideImage = privacy.hideProfileImage && !isAdmin
                                if (!user.profileImageUri.isNullOrEmpty() && !hideImage) {
                                    androidx.compose.foundation.Image(
                                        painter = coil.compose.rememberAsyncImagePainter(model = user.profileImageUri),
                                        contentDescription = "User profile picture",
                                        modifier = Modifier.fillMaxSize(),
                                        contentScale = androidx.compose.ui.layout.ContentScale.Crop
                                    )
                                } else {
                                    val initials = if (user.fullName.isNotEmpty() && (!privacy.hideFullName || isAdmin)) {
                                        user.fullName.take(2).uppercase()
                                    } else {
                                        user.username.take(2).uppercase()
                                    }
                                    Text(
                                        text = initials,
                                        color = Color.White,
                                        fontWeight = FontWeight.Bold,
                                        fontSize = 20.sp
                                    )
                                }
                            }
                            
                            Spacer(modifier = Modifier.width(16.dp))
                            
                            Column(modifier = Modifier.weight(1f)) {
                                val hideName = privacy.hideFullName && !isAdmin
                                Text(
                                    text = if (hideName) "@${user.username}" else user.fullName.ifEmpty { "@${user.username}" },
                                    fontSize = 18.sp,
                                    fontWeight = FontWeight.Bold,
                                    color = MaterialTheme.colorScheme.onSurface
                                )
                                Text(
                                    text = "@${user.username} • ${user.studentType.ifEmpty { "Fresher" }}",
                                    fontSize = 13.sp,
                                    color = MaterialTheme.colorScheme.onSurfaceVariant
                                )
                            }
                        }
                    }
                }
                
                if (isAdmin) {
                    item {
                        Card(
                            colors = CardDefaults.cardColors(containerColor = MaterialTheme.colorScheme.primaryContainer.copy(alpha = 0.3f))
                        ) {
                            Column(
                                modifier = Modifier
                                    .fillMaxWidth()
                                    .padding(14.dp),
                                verticalArrangement = Arrangement.spacedBy(8.dp),
                                horizontalAlignment = Alignment.CenterHorizontally
                            ) {
                                Row(
                                    verticalAlignment = Alignment.CenterVertically,
                                    horizontalArrangement = Arrangement.spacedBy(6.dp)
                                ) {
                                    Icon(Icons.Filled.Security, contentDescription = "Admin view", tint = MaterialTheme.colorScheme.primary, modifier = Modifier.size(16.dp))
                                    Text("Administrator Controls", fontWeight = FontWeight.Bold, fontSize = 13.sp, color = MaterialTheme.colorScheme.primary)
                                }
                                Text("As an administrator, you have permission to view this student's full data record and download a PDF report.", fontSize = 11.sp, color = MaterialTheme.colorScheme.onSurfaceVariant, textAlign = androidx.compose.ui.text.style.TextAlign.Center)
                                
                                Button(
                                    onClick = { viewModel.activeReportTask.value = ReportTask.StudentProgress(user, userTests) },
                                    modifier = Modifier.fillMaxWidth().padding(top = 4.dp),
