fun calculateUserLeaderboardRank(userId: Int, users: List<com.example.data.model.User>, allResults: List<com.example.data.model.TestResult>): Int {
    val rankedList = users.filter { it.role == "USER" }.map { user ->
        val userResults = allResults.filter { it.userId == user.id }
        val correctCount = userResults.sumOf { it.correctAnswers }
        val totalQuestions = userResults.sumOf { it.totalQuestions }
        val successRate = if (totalQuestions > 0) {
            (correctCount.toFloat() / totalQuestions * 100f).toInt()
        } else 0
        val totalScore = userResults.sumOf { it.scorePercentage.toInt() }
        Pair(user.id, Pair(totalScore, successRate))
    }.sortedWith(compareByDescending<Pair<Int, Pair<Int, Int>>> { it.second.first }.thenByDescending { it.second.second })

    val index = rankedList.indexOfFirst { it.first == userId }
    return if (index != -1) index + 1 else rankedList.size + 1
}

val JameelNooriFontFamily: FontFamily
    @Composable
    get() {
        val context = LocalContext.current
        return remember(context) {
            try {
                val typeface = androidx.core.content.res.ResourcesCompat.getFont(context, com.example.R.font.jameel_noori)
                if (typeface != null) {
                    FontFamily(typeface)
                } else {
                    FontFamily.SansSerif
                }
            } catch (e: Exception) {
                android.util.Log.e("FontLoading", "Failed to load jameel_noori font from resources, falling back to SansSerif", e)
                FontFamily.SansSerif
            }
        }
    }

