@Composable
fun rememberSupabaseImagePainter(model: String?): androidx.compose.ui.graphics.painter.Painter {
    val context = androidx.compose.ui.platform.LocalContext.current
    return if (model.isNullOrEmpty()) {
        coil.compose.rememberAsyncImagePainter(model = null)
    } else if (model.startsWith("http") && model.contains("supabase")) {
        val request = coil.request.ImageRequest.Builder(context)
            .data(model)
            .addHeader("apikey", com.example.BuildConfig.SUPABASE_KEY)
            .addHeader("Authorization", "Bearer ${com.example.BuildConfig.SUPABASE_KEY}")
            .crossfade(true)
            .build()
        coil.compose.rememberAsyncImagePainter(model = request)
    } else {
        coil.compose.rememberAsyncImagePainter(model = model)
    }
}

